INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41289, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「読書を〜していたら」の「を」で、する対象を示す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示し、「読書にしていたら」では動作の目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「読書へしていたら」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「読書よりしていたら」では文の意味が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「読書を〜していたら」の「を」で、する対象を示す。正解。", "に": "「に」は相手や場所を示し、「読書にしていたら」では動作の目的語にならない。", "へ": "「へ」は方向を示し、「読書へしていたら」は成り立たない。", "より": "「より」は比較を表し、「読書よりしていたら」では文の意味が崩れる。"}, "error_tags": {"に": "相手・場所の「に」は動作の目的語にならない", "へ": "方向の「へ」は動作の目的語にならない", "より": "比較の「より」は動作の目的語にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41289, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「読書を通して」の「を」で、通す手段や過程を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すもので、「読書が通して」では「通す」と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「読書で通して」では「通す」と結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「読書から通して」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「読書を通して」の「を」で、通す手段や過程を示す。正解。", "が": "「が」は主語を示すもので、「読書が通して」では「通す」と結びつかない。", "で": "「で」は手段や場所を示すが、「読書で通して」では「通す」と結びつかない。", "から": "「から」は起点を示し、「読書から通して」は意味が通らない。"}, "error_tags": {"が": "主語の「が」は「通す」の対象にならない", "で": "手段の「で」は「通す」と結びつかない", "から": "起点の「から」は「通す」と結びつかない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41289, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "本を読むこと。読書という行為。", "primary_collocate": null, "pronunciation": "どくしょ", "ipa": "dokɯɕo", "syllable_count": 3, "sentences": [{"text": "毎朝三十分の読書を続けています。", "target_word": "読書", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]三十分[さんじゅっぷん]の読書[どくしょ]を続[つづ]けています。", "sentence_source": "generated"}, {"text": "読書をしていたら、いつの間にか夜になりました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]をしていたら、いつの間[ま]にか夜[よる]になりました。", "sentence_source": "generated"}, {"text": "この公園は読書にぴったりの場所です。", "target_word": "読書", "complexity_tier": "T3", "furigana": "この公園[こうえん]は読書[どくしょ]にぴったりの場所[ばしょ]です。", "sentence_source": "generated"}, {"text": "学校では、朝の十分間を読書の時間にしています。", "target_word": "読書", "complexity_tier": "T3", "furigana": "学校[がっこう]では、朝[あさ]の十分間[じゅっぷんかん]を読書[どくしょ]の時間[じかん]にしています。", "sentence_source": "generated"}, {"text": "読書が苦手なので、短い話から始めました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]が苦手[にがて]なので、短[みじか]い話[はなし]から始[はじ]めました。", "sentence_source": "generated"}, {"text": "秋は涼しいので、読書に向いている季節です。", "target_word": "読書", "complexity_tier": "T3", "furigana": "秋[あき]は涼[すず]しいので、読書[どくしょ]に向[む]いている季節[きせつ]です。", "sentence_source": "generated"}, {"text": "読書をしている間、彼は電話が鳴っても気づきません。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]をしている間[あいだ]、彼[かれ]は電話[でんわ]が鳴[な]っても気[き]づきません。", "sentence_source": "generated"}, {"text": "読書を通して、遠い国のことを知りました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]を通[とお]して、遠[とお]い国[くに]のことを知[し]りました。", "sentence_source": "generated"}, {"text": "目が疲れたので、読書をやめて休みました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "目[め]が疲[つか]れたので、読書[どくしょ]をやめて休[やす]みました。", "sentence_source": "generated"}, {"text": "読書のあとで、感想をノートに書きました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]のあとで、感想[かんそう]をノートに書[か]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "読書", "label": "基本形"}, {"form": "読書する", "label": "サ変動詞"}, {"form": "読書した", "label": "過去形"}], "register": "中立（丁寧体）", "sense_fingerprint": "本を読むという行為そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41289, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "読書", "is_correct": true, "explanation": "「毎朝三十分の」の後、「を続けています」で続く行為名詞。正解。"}, {"text": "読ま", "is_correct": false, "explanation": "未然形の語幹。「の」の後の名詞の位置に入らず、文が成り立たない。"}, {"text": "読め", "is_correct": false, "explanation": "命令形。「毎朝三十分の」の後には置けない。"}, {"text": "読んだ", "is_correct": false, "explanation": "過去形の動詞。名詞の位置に入らず、「を続けています」とつながらない。"}], "explanations": {"読書": "「毎朝三十分の」の後、「を続けています」で続く行為名詞。正解。", "読ま": "未然形の語幹。「の」の後の名詞の位置に入らず、文が成り立たない。", "読め": "命令形。「毎朝三十分の」の後には置けない。", "読んだ": "過去形の動詞。名詞の位置に入らず、「を続けています」とつながらない。"}, "sentence_index": 0, "correct_answer": "読書"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レジで商品のバーコードを読書して、値段を表示します。", "explanation": "ここは〈読み取り〉の意味。機器で記号を読み取ることを指し、本を読む読書とは違うので合わない。"}, {"text": "夜空の星を一つずつ読書して、位置を記録しました。", "explanation": "ここは〈観察〉の意味。よく見て状態を調べることを指し、文字を読む読書とは違うので合わない。"}, {"text": "ドアの鍵を読書して、家に入りました。", "explanation": "ここは〈解錠〉の意味。鍵を開ける動作を指し、本を読む読書とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41289, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "読書", "is_correct": true, "explanation": "「をしている間」の前に入る行為名詞。正解。"}, {"text": "読もう", "is_correct": false, "explanation": "意向形の動詞。「をしている間」の前には置けない。"}, {"text": "読める", "is_correct": false, "explanation": "可能形の動詞。名詞の位置に入らず、「をしている」とつながらない。"}, {"text": "読ませ", "is_correct": false, "explanation": "使役形の語幹。「をしている間」の前では文が成り立たない。"}], "explanations": {"読書": "「をしている間」の前に入る行為名詞。正解。", "読もう": "意向形の動詞。「をしている間」の前には置けない。", "読める": "可能形の動詞。名詞の位置に入らず、「をしている」とつながらない。", "読ませ": "使役形の語幹。「をしている間」の前では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "読書"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書館で目的の本を読書して探しました。", "explanation": "ここは〈検索〉の意味。本を探す作業を指し、本を読む行為の読書とは違う。"}, {"text": "動画の読書を一時間しました。", "explanation": "ここは〈視聴〉の意味。映像を見たり聞いたりすることを指し、文字の本を読む読書には当たらない。"}, {"text": "毎朝、体重計で体重を読書して記録しています。", "explanation": "ここは〈計測〉の意味。体重計などで数値を量ることを指し、文字を読む読書とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41289, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、読書を続けるます。", "corrected_sentence": "毎朝、読書を続けます。", "error_description": "「続ける」の丁寧形は「続けます」。辞書形の「る」を残したまま「ます」を付けたのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41289, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "読書を集中すると、時間を忘れます。", "corrected_sentence": "読書に集中すると、時間を忘れます。", "error_description": "「集中する」は助詞「に」を取る。「読書を集中」は誤りで、正しくは「読書に集中」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41290, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雨の音を聞く」の「を」は、聞く対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は人に尋ねる形になり、「雨の音に聞く」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「雨の音と聞いて」は文の流れが成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「雨の音へ聞く」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「雨の音を聞く」の「を」は、聞く対象を示す。", "に": "「に」は人に尋ねる形になり、「雨の音に聞く」は成り立たない。", "と": "「雨の音と聞いて」は文の流れが成り立たない。", "へ": "「へ」は方向を表すので、「雨の音へ聞く」は不自然。"}, "error_tags": {"に": "尋ねる相手", "と": "引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
