INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41290, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "耳で音を感じ取ること。", "primary_collocate": null, "pronunciation": "きく", "ipa": "kikɯ", "syllable_count": 2, "sentences": [{"text": "朝、庭で鳥の鳴き声を聞くと、元気が出る。", "target_word": "聞く", "complexity_tier": "T3", "furigana": "あさ、にわでとりのなきごえをきくと、げんきがでる。", "sentence_source": "generated"}, {"text": "夜中に雨の音を聞いて、目が覚めた。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "よなかにあめのおとをきいて、めがさめた。", "sentence_source": "generated"}, {"text": "駅のホームで、電車が近づく音を聞いた。", "target_word": "聞いた", "complexity_tier": "T3", "furigana": "えきのほーむで、でんしゃがちかづくおとをきいた。", "sentence_source": "generated"}, {"text": "静かな森で、風が木をゆらす音を聞いた。", "target_word": "聞いた", "complexity_tier": "T3", "furigana": "しずかなもりで、かぜがきをゆらすおとをきいた。", "sentence_source": "generated"}, {"text": "海辺で波の音を聞きながら、ゆっくり歩いた。", "target_word": "聞き", "complexity_tier": "T3", "furigana": "うみべでなみのおとをききながら、ゆっくりあるいた。", "sentence_source": "generated"}, {"text": "花火の大きな音を聞いて、犬が驚いた。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "はなびのおおきなおとをきいて、いぬがおどろいた。", "sentence_source": "generated"}, {"text": "祖父は耳が遠いので、小さな音を聞くのが難しい。", "target_word": "聞く", "complexity_tier": "T3", "furigana": "そふはみみがとおいので、ちいさなおとをきくのがむずかしい。", "sentence_source": "generated"}, {"text": "子どものころ、遠くで汽笛を聞くのが好きだった。", "target_word": "聞く", "complexity_tier": "T3", "furigana": "こどものころ、とおくできてきをきくのがすきだった。", "sentence_source": "generated"}, {"text": "外でサイレンを聞いて、窓の外を見た。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "そとでさいれんをきいて、まどのそとをみた。", "sentence_source": "generated"}, {"text": "雷の音を聞いた直後、停電になった。", "target_word": "聞いた", "complexity_tier": "T3", "furigana": "かみなりのおとをきいたちょくご、ていでんになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聞く", "label": "基本形"}, {"form": "聞かない", "label": "否定形"}, {"form": "聞いた", "label": "過去形"}, {"form": "聞いて", "label": "て形"}, {"form": "聞けば", "label": "仮定形"}, {"form": "聞こう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "耳で音や声を聞く、聴覚で受け取る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ゆらす (Zipf 1.93)']::text[], '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41290, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聞く", "is_correct": true, "explanation": "鳴き声は耳で受け取るものなので、「聞くと」が合う。"}, {"text": "見る", "is_correct": false, "explanation": "見るのは目で捉える動作で、鳴き声には合わない。"}, {"text": "触る", "is_correct": false, "explanation": "触るのは手で触れる動作で、鳴き声には使わない。"}, {"text": "嗅ぐ", "is_correct": false, "explanation": "嗅ぐのは匂いを確かめる動作で、鳴き声には使わない。"}], "explanations": {"聞く": "鳴き声は耳で受け取るものなので、「聞くと」が合う。", "見る": "見るのは目で捉える動作で、鳴き声には合わない。", "触る": "触るのは手で触れる動作で、鳴き声には使わない。", "嗅ぐ": "嗅ぐのは匂いを確かめる動作で、鳴き声には使わない。"}, "sentence_index": 0, "correct_answer": "聞く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝の海を聞きながら、ゆっくり散歩した。", "explanation": "ここは〈見る〉の意味。聞くは音を耳で感じ取る動詞なので、景色を目で見ることには使わない。"}, {"text": "庭の花の香りを聞いた。", "explanation": "ここは〈かぐ〉の意味。聞くは音や話を耳で感じ取る動詞なので、においをかぐ場面には使わない。"}, {"text": "猫のふわふわの毛を聞いた。", "explanation": "ここは〈触る〉の意味。聞くは耳で音を受け取る動詞なので、手で毛の感触を確かめる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41290, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聞く", "is_correct": true, "explanation": "「小さな音を聞くのが難しい」の「聞く」が、耳で音を捉える意味で合う。"}, {"text": "眺める", "is_correct": false, "explanation": "眺めるのは目で見て楽しむ動作で、音には使わない。"}, {"text": "撫でる", "is_correct": false, "explanation": "撫でるのは手で触れる動作で、音には使わない。"}, {"text": "摘む", "is_correct": false, "explanation": "摘むのは手で取る動作で、音には使わない。"}], "explanations": {"聞く": "「小さな音を聞くのが難しい」の「聞く」が、耳で音を捉える意味で合う。", "眺める": "眺めるのは目で見て楽しむ動作で、音には使わない。", "撫でる": "撫でるのは手で触れる動作で、音には使わない。", "摘む": "摘むのは手で取る動作で、音には使わない。"}, "sentence_index": 6, "correct_answer": "聞く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝ごはんのパンを聞いた。", "explanation": "ここは〈食べる〉の意味。聞くは耳で音を感じ取る動詞なので、食べ物を口に入れる場面には使わない。"}, {"text": "分厚い小説の表紙を聞いた。", "explanation": "ここは〈読む〉の意味。聞くは耳で音を感じ取る動詞なので、文字を目で追う場面には使わない。"}, {"text": "友だちに手紙を聞いた。", "explanation": "ここは〈書く〉の意味。聞くは耳で音を感じ取る動詞なので、紙に文字を書く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41290, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の静けさの中で、遠くの汽笛が聞いた。", "corrected_sentence": "夜の静けさの中で、遠くの汽笛を聞いた。", "error_description": "「聞く」の目的語には「を」を使う。「汽笛が聞いた」は主語と目的語を取り違えている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "聞いて", "is_correct": true, "explanation": "「雨の音を聞いて、目が覚めた」と、動作の順序を表す「て形」。"}, {"text": "聞く", "is_correct": false, "explanation": "基本形は「〜て、目が覚めた」の前に置けない。"}, {"text": "聞かない", "is_correct": false, "explanation": "否定形は、目が覚めた出来事につながらない。"}, {"text": "聞こう", "is_correct": false, "explanation": "意志形は「聞こう、目が覚めた」となり、後の出来事に続けられない。"}], "correct_form": "聞いて", "base_form": "聞く", "form_label": "て形", "sentence_index": 1, "explanations": {"聞いて": "「雨の音を聞いて、目が覚めた」と、動作の順序を表す「て形」。", "聞く": "基本形は「〜て、目が覚めた」の前に置けない。", "聞かない": "否定形は、目が覚めた出来事につながらない。", "聞こう": "意志形は「聞こう、目が覚めた」となり、後の出来事に続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41290, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠くの汽笛を聞いると、なぜか故郷を思い出す。", "corrected_sentence": "遠くの汽笛を聞くと、なぜか故郷を思い出す。", "error_description": "「聞く」に「と」を続けるときは「聞くと」。「聞いると」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "聞く", "is_correct": true, "explanation": "「汽笛を聞くのが好きだった」の「〜のが」の前には基本形が入る。"}, {"text": "聞けば", "is_correct": false, "explanation": "仮定形は「〜のが」の前に置けない。"}, {"text": "聞こう", "is_correct": false, "explanation": "意志形は「〜のが」の前に置けない。"}, {"text": "聞いて", "is_correct": false, "explanation": "て形は「〜のが」の前に置けない。"}], "correct_form": "聞く", "base_form": "聞く", "form_label": "基本形", "sentence_index": 7, "explanations": {"聞く": "「汽笛を聞くのが好きだった」の「〜のが」の前には基本形が入る。", "聞けば": "仮定形は「〜のが」の前に置けない。", "聞こう": "意志形は「〜のが」の前に置けない。", "聞いて": "て形は「〜のが」の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41291, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「話を聞いた」の「を」は、聞く対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「話が聞いた」は、話が聞く側になり意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「話の聞いた」は名詞をつなぐ形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「話へ聞いた」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「話を聞いた」の「を」は、聞く対象を示す。", "が": "「話が聞いた」は、話が聞く側になり意味が通らない。", "の": "「話の聞いた」は名詞をつなぐ形として成り立たない。", "へ": "「へ」は方向を表すので、「話へ聞いた」は不自然。"}, "error_tags": {"が": "主語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41291, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41291, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "音や声を耳で感じ取る。特に、相手の話に注意を向けて聴くこと。", "primary_collocate": null, "pronunciation": "きく", "ipa": "kikɯ", "syllable_count": 2, "sentences": [{"text": "先生の話をよく聞いて、メモを取った。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "せんせいのはなしをよくきいて、めもをとった。", "sentence_source": "generated"}, {"text": "友だちが悩んでいたので、最後まで話を聞いた。", "target_word": "聞いた", "complexity_tier": "T3", "furigana": "ともだちがなやんでいたので、さいごまではなしをきいた。", "sentence_source": "generated"}, {"text": "授業中は、先生の説明を静かに聞くことになっている。", "target_word": "聞く", "complexity_tier": "T3", "furigana": "じゅぎょうちゅうは、せんせいのせつめいをしずかにきくことになっている。", "sentence_source": "generated"}, {"text": "彼は人の話を最後まで聞く人だ。", "target_word": "聞く", "complexity_tier": "T3", "furigana": "かれはひとのはなしをさいごまできくひとだ。", "sentence_source": "generated"}, {"text": "母は私の話を聞いて、うなずいてくれた。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "はははわたしのはなしをきいて、うなずいてくれた。", "sentence_source": "generated"}, {"text": "会議では、まず全員の報告を聞いてから、意見を言う。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "かいぎでは、まずぜんいんのほうこくをきいてから、いけんをいう。", "sentence_source": "generated"}, {"text": "大事な説明なので、集中して聞いてください。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "だいじなせつめいなので、しゅうちゅうしてきいてください。", "sentence_source": "generated"}, {"text": "祖父は昔の話を、いつも楽しそうに聞いている。", "target_word": "聞いて", "complexity_tier": "T3", "furigana": "そふはむかしのはなしを、いつもたのしそうにきいている。", "sentence_source": "generated"}, {"text": "説明を聞かなかったので、使い方が分からなかった。", "target_word": "聞かなかった", "complexity_tier": "T3", "furigana": "せつめいをきかなかったので、つかいかたがわからなかった。", "sentence_source": "generated"}, {"text": "校長先生のあいさつを、生徒たちは体育館で聞いた。", "target_word": "聞いた", "complexity_tier": "T3", "furigana": "こうちょうせんせいのあいさつを、せいとたちはたいいくかんできいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聞く", "label": "基本形"}, {"form": "聞かない", "label": "否定形"}, {"form": "聞いた", "label": "過去形"}, {"form": "聞いて", "label": "て形"}, {"form": "聞けば", "label": "仮定形"}, {"form": "聞こう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "相手の話に注意を向けて耳を傾ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41291, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聞いて", "is_correct": true, "explanation": "「先生の話をよく聞いて、メモを取った」の「聞いて」は、注意して耳を傾ける意味で合う。"}, {"text": "見て", "is_correct": false, "explanation": "「話をよく見て」は目で見る意味になり、話には合わない。"}, {"text": "嗅いで", "is_correct": false, "explanation": "嗅ぐのは匂いを確かめる動作で、話には使わない。"}, {"text": "描いて", "is_correct": false, "explanation": "描くのは絵や文字をかく動作で、話には使わない。"}], "explanations": {"聞いて": "「先生の話をよく聞いて、メモを取った」の「聞いて」は、注意して耳を傾ける意味で合う。", "見て": "「話をよく見て」は目で見る意味になり、話には合わない。", "嗅いで": "嗅ぐのは匂いを確かめる動作で、話には使わない。", "描いて": "描くのは絵や文字をかく動作で、話には使わない。"}, "sentence_index": 0, "correct_answer": "聞いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "展望台で夕焼けの景色を聞いた。", "explanation": "ここは〈見る〉の意味。聞くは音や話を耳で感じ取る動詞なので、景色を目で見ることには使わない。"}, {"text": "分厚い本のページを聞いた。", "explanation": "ここは〈読む〉の意味。聞くは音や話を耳で感じ取る動詞なので、ページの文字を目で追う場面には使わない。"}, {"text": "紙に猫の絵を聞いた。", "explanation": "ここは〈描く〉の意味。聞くは音や話を耳で感じ取る動詞なので、紙に絵をかく場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41291, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聞いて", "is_correct": true, "explanation": "「集中して聞いてください」の「聞いて」は、注意して耳を傾ける意味で合う。"}, {"text": "忘れて", "is_correct": false, "explanation": "「集中して忘れてください」は意味が逆になり、説明を聞く場面に合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "「集中して眠ってください」は意味が通らない。"}, {"text": "捨てて", "is_correct": false, "explanation": "「集中して捨ててください」は説明を受ける場面に合わない。"}], "explanations": {"聞いて": "「集中して聞いてください」の「聞いて」は、注意して耳を傾ける意味で合う。", "忘れて": "「集中して忘れてください」は意味が逆になり、説明を聞く場面に合わない。", "眠って": "「集中して眠ってください」は意味が通らない。", "捨てて": "「集中して捨ててください」は説明を受ける場面に合わない。"}, "sentence_index": 6, "correct_answer": "聞いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、牛乳を聞いた。", "explanation": "ここは〈飲む〉の意味。聞くは音や話を耳で感じ取る動詞なので、液体を口に入れる場面には使わない。"}, {"text": "おやつのクッキーを聞いた。", "explanation": "ここは〈食べる〉の意味。聞くは音や話を耳で感じ取る動詞なので、お菓子を口に入れる場面には使わない。"}, {"text": "出かける前に、父は革靴を聞いた。", "explanation": "ここは〈磨く〉の意味。聞くは音や話を耳で感じ取る動詞なので、靴を手入れする場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41291, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちの相談が、最後まで聞いてあげた。", "corrected_sentence": "友だちの相談を、最後まで聞いてあげた。", "error_description": "「聞く」の目的語には「を」を使う。「相談が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "聞いた", "is_correct": true, "explanation": "「最後まで話を聞いた」の過去形が、文の流れに合う。"}, {"text": "聞いて", "is_correct": false, "explanation": "て形は文を言い切れず、「〜ので、話を聞いて。」は意味が通らない。"}, {"text": "聞く", "is_correct": false, "explanation": "基本形の現在形では、「悩んでいたので」の流れに合わない。"}, {"text": "聞けば", "is_correct": false, "explanation": "仮定形は文を言い切れず、「〜ので、話を聞けば。」は成り立たない。"}], "correct_form": "聞いた", "base_form": "聞く", "form_label": "過去形", "sentence_index": 1, "explanations": {"聞いた": "「最後まで話を聞いた」の過去形が、文の流れに合う。", "聞いて": "て形は文を言い切れず、「〜ので、話を聞いて。」は意味が通らない。", "聞く": "基本形の現在形では、「悩んでいたので」の流れに合わない。", "聞けば": "仮定形は文を言い切れず、「〜ので、話を聞けば。」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41291, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "授業の内容を聞くてから、質問しよう。", "corrected_sentence": "授業の内容を聞いてから、質問しよう。", "error_description": "「聞く」のて形は「聞いて」。「聞くて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "聞いて", "is_correct": true, "explanation": "「聞いている」の一部で、て形が「いる」に続く形として正しい。"}, {"text": "聞こう", "is_correct": false, "explanation": "意志形。「聞こうている」は「いる」に続かず、「聞いている」の形にならない。"}, {"text": "聞かない", "is_correct": false, "explanation": "否定形は「聞かないいる」となり、「聞いている」の形にならない。"}, {"text": "聞きます", "is_correct": false, "explanation": "丁寧形。「聞きますいる」は成り立たず、「聞いている」の形にならない。"}], "correct_form": "聞いて", "base_form": "聞く", "form_label": "て形", "sentence_index": 7, "explanations": {"聞いて": "「聞いている」の一部で、て形が「いる」に続く形として正しい。", "聞こう": "意志形。「聞こうている」は「いる」に続かず、「聞いている」の形にならない。", "聞かない": "否定形は「聞かないいる」となり、「聞いている」の形にならない。", "聞きます": "丁寧形。「聞きますいる」は成り立たず、「聞いている」の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
