INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41292, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "心から強く、ひたすら願うさまを表す。手紙などで用いる。", "primary_collocate": null, "pronunciation": "せつ", "ipa": "setsɯ", "syllable_count": 2, "sentences": [{"text": "皆様のご健康を切にお祈り申し上げます。", "target_word": "切に", "complexity_tier": "T3", "furigana": "皆様[みなさま]のご健康[けんこう]を切[せつ]にお祈[いの]り申[もう]し上[あ]げます。", "sentence_source": "generated"}, {"text": "一日も早いご回復を切に願っております。", "target_word": "切に", "complexity_tier": "T3", "furigana": "一日[いちにち]も早[はや]いご回復[かいふく]を切[せつ]に願[ねが]っております。", "sentence_source": "generated"}, {"text": "ご理解を賜りますよう、切にお願い申し上げます。", "target_word": "切に", "complexity_tier": "T3", "furigana": "ご理解[りかい]を賜[たまわ]りますよう、切[せつ]にお願[ねが]い申[もう]し上[あ]げます。", "sentence_source": "generated"}, {"text": "世界の平和が続くことを切に望んでいます。", "target_word": "切に", "complexity_tier": "T3", "furigana": "世界[せかい]の平和[へいわ]が続[つづ]くことを切[せつ]に望[のぞ]んでいます。", "sentence_source": "generated"}, {"text": "先生の今後のご活躍を切に祈っております。", "target_word": "切に", "complexity_tier": "T3", "furigana": "先生[せんせい]の今後[こんご]のご活躍[かつやく]を切[せつ]に祈[いの]っております。", "sentence_source": "generated"}, {"text": "ご返事を切にお待ちしております。", "target_word": "切に", "complexity_tier": "T3", "furigana": "ご返事[へんじ]を切[せつ]にお待[ま]ちしております。", "sentence_source": "generated"}, {"text": "皆さまのご協力を切にお願いいたします。", "target_word": "切に", "complexity_tier": "T3", "furigana": "皆[みな]さまのご協力[きょうりょく]を切[せつ]にお願[ねが]いいたします。", "sentence_source": "generated"}, {"text": "無事に帰ってくることを、家族は切に願っていた。", "target_word": "切に", "complexity_tier": "T3", "furigana": "無事[ぶじ]に帰[かえ]ってくることを、家族[かぞく]は切[せつ]に願[ねが]っていた。", "sentence_source": "generated"}, {"text": "今後のご発展を切にお祈りいたします。", "target_word": "切に", "complexity_tier": "T3", "furigana": "今後[こんご]のご発展[はってん]を切[せつ]にお祈[いの]りいたします。", "sentence_source": "generated"}, {"text": "切なる願いが届き、母は涙を流した。", "target_word": "切なる", "complexity_tier": "T3", "furigana": "切[せつ]なる願[ねが]いが届[とど]き、母[はは]は涙[なみだ]を流[なが]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切に", "label": "連用形"}, {"form": "切なる", "label": "連体形（文語）"}], "register": "文章語（手紙・あらたまった場面）", "sense_fingerprint": "心から強く願う、手紙の丁寧な言い方（切に）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41292, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切に", "is_correct": true, "explanation": "「心から強く」の意味の副詞で、「お祈り申し上げます」を自然に修飾する。"}, {"text": "切れ", "is_correct": false, "explanation": "命令形。「ご健康を切れお祈り」は文中に置けず、文として成り立たない。"}, {"text": "切って", "is_correct": false, "explanation": "「切る」のて形。「ご健康を切ってお祈り」では文として成り立たない。"}, {"text": "切る", "is_correct": false, "explanation": "動詞の辞書形。「ご健康を切る」は意味が通らず、空所に入らない。"}], "explanations": {"切に": "「心から強く」の意味の副詞で、「お祈り申し上げます」を自然に修飾する。", "切れ": "命令形。「ご健康を切れお祈り」は文中に置けず、文として成り立たない。", "切って": "「切る」のて形。「ご健康を切ってお祈り」では文として成り立たない。", "切る": "動詞の辞書形。「ご健康を切る」は意味が通らず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "切に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の勢いが切に増してきた。", "explanation": "ここは〈強く〉の意味。切には心からの強い願いを表す副詞で、雨の勢いには合わない。"}, {"text": "この傷は切に深い。", "explanation": "ここは〈深く〉の意味。切には願いの強さに使い、傷の深さのような物の状態には使わない。"}, {"text": "風が切に吹いていた。", "explanation": "ここは〈しきりに〉の意味。しきりには同じ動作が絶え間なく続く様子を表し、切には心からの願いを表すので、吹く風には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41292, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切に", "is_correct": true, "explanation": "副詞として「ご協力をお願い」の気持ちの強さを表し、文に自然に入る。"}, {"text": "切れ", "is_correct": false, "explanation": "命令形。「ご協力を切れ」は「お願い」に続かず、不自然になる。"}, {"text": "切らず", "is_correct": false, "explanation": "否定の連用形。「切らずにお願い」は意味が通らない。"}, {"text": "切った", "is_correct": false, "explanation": "過去形。「ご協力を切った」と「お願い」が結びつかない。"}], "explanations": {"切に": "副詞として「ご協力をお願い」の気持ちの強さを表し、文に自然に入る。", "切れ": "命令形。「ご協力を切れ」は「お願い」に続かず、不自然になる。", "切らず": "否定の連用形。「切らずにお願い」は意味が通らない。", "切った": "過去形。「ご協力を切った」と「お願い」が結びつかない。"}, "sentence_index": 6, "correct_answer": "切に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "激しい雨が切なる勢いで降り続いた。", "explanation": "ここは〈強い〉の意味。切なるは心からの願いを表す語で、雨の勢いには合わない。"}, {"text": "大きな地震が切なる揺れを起こした。", "explanation": "ここは〈激しい〉の意味。切なるは願いに使う語で、地震の揺れの激しさには使わない。"}, {"text": "切なる湯気が鍋から上がった。", "explanation": "ここは〈熱い〉の意味。湯気の熱さは熱いで表し、切なるは心からの願いを表す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41292, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ご参加を切でお待ちしています。", "corrected_sentence": "ご参加を切にお待ちしています。", "error_description": "副詞「切に」は語尾が「に」。「切で」は「で」に誤っており、「切に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "切に", "is_correct": true, "explanation": "副詞の形で、「願っております」を修飾して心からの強い願いを表す。ここでは正しい形。"}, {"text": "切だ", "is_correct": false, "explanation": "終止形で、「願っております」を直接修飾できず、文が成り立たない。"}, {"text": "切な", "is_correct": false, "explanation": "連体形で名詞の前に置く形。ここでは後ろに名詞がなく、「願う」を修飾できない。"}, {"text": "切なる", "is_correct": false, "explanation": "文語の連体形で名詞の前に置く。「願っております」を修飾できず、文語的すぎて文と合わない。"}], "correct_form": "切に", "base_form": "切", "form_label": "連用形", "sentence_index": 1, "explanations": {"切に": "副詞の形で、「願っております」を修飾して心からの強い願いを表す。ここでは正しい形。", "切だ": "終止形で、「願っております」を直接修飾できず、文が成り立たない。", "切な": "連体形で名詞の前に置く形。ここでは後ろに名詞がなく、「願う」を修飾できない。", "切なる": "文語の連体形で名詞の前に置く。「願っております」を修飾できず、文語的すぎて文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41292, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "切なに願いを胸に、新しい道へ進んだ。", "corrected_sentence": "切なる願いを胸に、新しい道へ進んだ。", "error_description": "「願い」を修飾する連体形は「切なる」。「切なに」は形が誤りで、連体形の「切なる」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "切に", "is_correct": true, "explanation": "副詞の形で、「家族は」の後の「願っていた」を強く修飾する。ここでは正しい形。"}, {"text": "切なり", "is_correct": false, "explanation": "文語の終止形で、「願っていた」を修飾できず、現代の文章では使わない。"}, {"text": "切である", "is_correct": false, "explanation": "断定の形で、「願っていた」の修飾にはならず、文が不自然になる。"}, {"text": "切だった", "is_correct": false, "explanation": "過去の断定形で、「願っていた」を修飾できず、文が成り立たない。"}], "correct_form": "切に", "base_form": "切", "form_label": "連用形", "sentence_index": 7, "explanations": {"切に": "副詞の形で、「家族は」の後の「願っていた」を強く修飾する。ここでは正しい形。", "切なり": "文語の終止形で、「願っていた」を修飾できず、現代の文章では使わない。", "切である": "断定の形で、「願っていた」の修飾にはならず、文が不自然になる。", "切だった": "過去の断定形で、「願っていた」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41294, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『書きます』の対象を示す格助詞。『手紙を書きます』として成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す語で、『手紙が書きます』では手紙が書く主体になり意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ語で、『手紙の書きます』と動詞に直接続けられない。"}, {"text": "と", "is_correct": false, "explanation": "並列・引用を表す語で、「手紙と書きます」では書く対象として文が完結しない。"}], "correct_answer": "を", "explanations": {"を": "『書きます』の対象を示す格助詞。『手紙を書きます』として成り立つ。", "が": "主語を示す語で、『手紙が書きます』では手紙が書く主体になり意味が通らない。", "の": "名詞をつなぐ語で、『手紙の書きます』と動詞に直接続けられない。", "と": "並列・引用を表す語で、「手紙と書きます」では書く対象として文が完結しない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41294, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "帰着の対象を示す格助詞。『手紙に、きょうの出来事を書きました』として成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す語で、『手紙へ』は書く場所として不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ語だが、「手紙の、きょう…」と読点で切れ、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「手紙が、きょう…を書きました」では手紙が書く主体になり意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "帰着の対象を示す格助詞。『手紙に、きょうの出来事を書きました』として成り立つ。", "へ": "方向を表す語で、『手紙へ』は書く場所として不自然。", "の": "名詞をつなぐ語だが、「手紙の、きょう…」と読点で切れ、文が成り立たない。", "が": "主語を示すため、「手紙が、きょう…を書きました」では手紙が書く主体になり意味が通らない。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41294, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "てがみは、ともだちにあててかくものです。", "primary_collocate": null, "pronunciation": "てがみ", "ipa": "teɡami", "syllable_count": 3, "sentences": [{"text": "ともだちに手紙を書きました。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "ともだちに手紙[てがみ]を書[か]きました。", "sentence_source": "generated"}, {"text": "誕生日のお礼に、友だちへ手紙を書きます。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]のお礼[れい]に、友[とも]だちへ手紙[てがみ]を書[か]きます。", "sentence_source": "generated"}, {"text": "手紙を書いたら、ポストに入れます。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "手紙[てがみ]を書[か]いたら、ポストに入[い]れます。", "sentence_source": "generated"}, {"text": "転校した友だちから、手紙がきました。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "転校[てんこう]した友[とも]だちから、手紙[てがみ]がきました。", "sentence_source": "generated"}, {"text": "手紙の中に、かわいいシールが入っていました。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "手紙[てがみ]の中[なか]に、かわいいシールが入[はい]っていました。", "sentence_source": "generated"}, {"text": "母は、わたしの手紙を読んで笑いました。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "母[はは]は、わたしの手紙[てがみ]を読[よ]んで笑[わら]いました。", "sentence_source": "generated"}, {"text": "手紙のへんじを、毎日待っています。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "手紙[てがみ]のへんじを、毎日[まいにち]待[ま]っています。", "sentence_source": "generated"}, {"text": "手紙に、きょうの出来事を書きました。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "手紙[てがみ]に、きょうの出来事[できごと]を書[か]きました。", "sentence_source": "generated"}, {"text": "切手をはって、手紙をポストに出しました。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "切手[きって]をはって、手紙[てがみ]をポストに出[だ]しました。", "sentence_source": "generated"}, {"text": "夏休みは会えないので、手紙でやりとりします。", "target_word": "手紙", "complexity_tier": "T3", "furigana": "夏休[なつやす]みは会[あ]えないので、手紙[てがみ]でやりとりします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手紙", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ともだちなど身近な人にあてて書く手紙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: へんじ (Zipf 2.15)']::text[], 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手紙", "is_correct": true, "explanation": "友だちに送る文書の『手紙』で、『ともだちに手紙を書きました』として成り立つ。"}, {"text": "切手", "is_correct": false, "explanation": "郵便料金の証票で、書く対象にはならない。"}, {"text": "電話", "is_correct": false, "explanation": "通話の道具で、『ともだちに電話を書きました』とは言えない。"}, {"text": "荷物", "is_correct": false, "explanation": "送る品物で、書く対象にはならない。"}], "explanations": {"手紙": "友だちに送る文書の『手紙』で、『ともだちに手紙を書きました』として成り立つ。", "切手": "郵便料金の証票で、書く対象にはならない。", "電話": "通話の道具で、『ともだちに電話を書きました』とは言えない。", "荷物": "送る品物で、書く対象にはならない。"}, "sentence_index": 0, "correct_answer": "手紙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "英語の授業で、Bという手紙を覚えた。", "explanation": "ここは〈文字〉の意味。アルファベットの一字は『手紙』ではなく『文字』と言うので合わない。"}, {"text": "ともだちの声を聞けなくて、手紙を聞いた。", "explanation": "ここは〈話し声・音声〉の意味。手紙は読むもので、音として受け取ることはできないので合わない。"}, {"text": "ともだちに手紙を描いて、送った。", "explanation": "ここは〈絵〉の意味。描くのは絵で、手紙は描かないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手紙", "is_correct": true, "explanation": "返事を待つ対象の『手紙』で、『手紙のへんじを待っています』として成り立つ。"}, {"text": "封筒", "is_correct": false, "explanation": "手紙を入れる容器で、『封筒のへんじ』とは言えない。"}, {"text": "小包", "is_correct": false, "explanation": "送る荷物で、『小包のへんじ』とは言えない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券などで、『切符のへんじ』は成り立たない。"}], "explanations": {"手紙": "返事を待つ対象の『手紙』で、『手紙のへんじを待っています』として成り立つ。", "封筒": "手紙を入れる容器で、『封筒のへんじ』とは言えない。", "小包": "送る荷物で、『小包のへんじ』とは言えない。", "切符": "乗車券などで、『切符のへんじ』は成り立たない。"}, "sentence_index": 6, "correct_answer": "手紙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みは会えないので、手紙を弾いて聞かせます。", "explanation": "ここは〈楽器〉の意味。手紙は楽器ではなく、音を奏でることはできないので合わない。"}, {"text": "夏休みは会えないので、手紙を撮って送ります。", "explanation": "ここは〈写真〉の意味。撮るのは写真で、手紙は撮れないので合わない。"}, {"text": "夏休みは会えないので、手紙を歌って送ります。", "explanation": "ここは〈音楽・楽曲〉の意味。手紙は楽曲にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引っ越しの前に、ともだちへ手紙が書いた。", "corrected_sentence": "引っ越しの前に、ともだちへ手紙を書いた。", "error_description": "正しくは『手紙を書いた』。『書く』の対象は『を』で示すので、『手紙が』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母に手紙を送るら、すぐ返事が来た。", "corrected_sentence": "祖母に手紙を送ったら、すぐ返事が来た。", "error_description": "正しくは『送ったら』。完了の『た』が必要で、『送るら』は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41296, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ノンフィクション", "is_correct": true, "explanation": "実際にあった事実にもとづく作品を指し、フィクション（作り話）の対義語。"}, {"text": "小説", "is_correct": false, "explanation": "作り話の代表的なジャンルで、対義語ではなく同じ側に入る。"}, {"text": "詩", "is_correct": false, "explanation": "言葉の表現形式で、作り話かどうかの対義語ではない。"}, {"text": "漫画", "is_correct": false, "explanation": "表現の形式で、事実か作り話かという分け方の対義語ではない。"}], "correct_answer": "ノンフィクション", "explanations": {"ノンフィクション": "実際にあった事実にもとづく作品を指し、フィクション（作り話）の対義語。", "小説": "作り話の代表的なジャンルで、対義語ではなく同じ側に入る。", "詩": "言葉の表現形式で、作り話かどうかの対義語ではない。", "漫画": "表現の形式で、事実か作り話かという分け方の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41296, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ノンフィクション", "is_correct": true, "explanation": "事実にもとづく作品を指し、フィクション（作り話）の対義語。"}, {"text": "靴", "is_correct": false, "explanation": "身につける品物で、作り話かどうかの対義語ではない。"}, {"text": "時計", "is_correct": false, "explanation": "時間を知らせる道具で、フィクションの対義語ではない。"}, {"text": "地図", "is_correct": false, "explanation": "場所を表す図で、フィクションの対義語ではない。"}], "correct_answer": "ノンフィクション", "explanations": {"ノンフィクション": "事実にもとづく作品を指し、フィクション（作り話）の対義語。", "靴": "身につける品物で、作り話かどうかの対義語ではない。", "時計": "時間を知らせる道具で、フィクションの対義語ではない。", "地図": "場所を表す図で、フィクションの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41296, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "うそのおはなしのこと。", "primary_collocate": null, "pronunciation": "ふぃくしょん", "ipa": "ɸikɯɕoɴ", "syllable_count": 4, "sentences": [{"text": "この本はフィクションですから、本当の話ではありません。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "この本[ほん]はフィクションですから、本当[ほんとう]の話[はなし]ではありません。", "sentence_source": "generated"}, {"text": "私は本当の話より、フィクションのほうが好きです。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "私[わたし]は本当[ほんとう]の話[はなし]より、フィクションのほうが好[す]きです。", "sentence_source": "generated"}, {"text": "この映画はフィクションなので、登場する人は実在しません。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "この映画[えいが]はフィクションなので、登場[とうじょう]する人[ひと]は実在[じつざい]しません。", "sentence_source": "generated"}, {"text": "弟はフィクションを読むのが好きで、毎晩物語を読みます。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "弟[おとうと]はフィクションを読[よ]むのが好[す]きで、毎晩[まいばん]物語[ものがたり]を読[よ]みます。", "sentence_source": "generated"}, {"text": "ドラマの最初に「これはフィクションです」と出ました。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "ドラマの最初[さいしょ]に「これはフィクションです」と出[で]ました。", "sentence_source": "generated"}, {"text": "魔法を使う話はフィクションです。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "魔法[まほう]を使[つか]う話[はなし]はフィクションです。", "sentence_source": "generated"}, {"text": "先生はフィクションを書くための授業を始めました。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "先生[せんせい]はフィクションを書[か]くための授業[じゅぎょう]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "事件に似た話ですが、全部フィクションです。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "事件[じけん]に似[に]た話[はなし]ですが、全部[ぜんぶ]フィクションです。", "sentence_source": "generated"}, {"text": "この小説は昔の町が舞台のフィクションです。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は昔[むかし]の町[まち]が舞台[ぶたい]のフィクションです。", "sentence_source": "generated"}, {"text": "子どもはフィクションの世界に夢中になります。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "子[こ]どもはフィクションの世界[せかい]に夢中[むちゅう]になります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フィクション", "label": "基本形"}], "register": "polite", "sense_fingerprint": "本当ではない、作られたおはなし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41296, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フィクション", "is_correct": true, "explanation": "作り話という意味で、後半の「本当の話ではありません」と文脈が合う。"}, {"text": "ノンフィクション", "is_correct": false, "explanation": "事実にもとづく本のことで、「本当の話ではありません」と矛盾する。"}, {"text": "年表", "is_correct": false, "explanation": "事実を年代順に並べた表で、「本当の話ではない」と続く文脈に合わない。"}, {"text": "辞典", "is_correct": false, "explanation": "言葉を説明する本で、作り話かどうかという話題に合わない。"}], "explanations": {"フィクション": "作り話という意味で、後半の「本当の話ではありません」と文脈が合う。", "ノンフィクション": "事実にもとづく本のことで、「本当の話ではありません」と矛盾する。", "年表": "事実を年代順に並べた表で、「本当の話ではない」と続く文脈に合わない。", "辞典": "言葉を説明する本で、作り話かどうかという話題に合わない。"}, "sentence_index": 0, "correct_answer": "フィクション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちにフィクションをついてしまいました。", "explanation": "ここは〈ウソ〉の意味。フィクションは作り話で、相手をだますウソの意味では使わず、「つく」とは言わないので合わない。"}, {"text": "来週は雨になるというフィクションが出ました。", "explanation": "ここは〈予想〉の意味。フィクションは作り話で、これから起きることを推し量る予想の意味では使わないので合わない。"}, {"text": "彼はフィクションが豊かで、新しい話をどんどん思いつきます。", "explanation": "ここは〈想像力〉の意味。作り話そのものを「豊か」と言うのは不自然で、この語はそこに合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41296, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フィクション", "is_correct": true, "explanation": "書く対象として文が成り立ち、「書くための授業」の内容と合う。"}, {"text": "池", "is_correct": false, "explanation": "池は書く対象にならず、「池を書く」は不自然。"}, {"text": "駅", "is_correct": false, "explanation": "駅は書くものではなく、「駅を書く」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は書く対象にならず、文の意味に合わない。"}], "explanations": {"フィクション": "書く対象として文が成り立ち、「書くための授業」の内容と合う。", "池": "池は書く対象にならず、「池を書く」は不自然。", "駅": "駅は書くものではなく、「駅を書く」は成り立たない。", "窓": "窓は書く対象にならず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "フィクション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はフィクションにふけって、授業を聞いていませんでした。", "explanation": "ここは〈空想〉の意味。「〜にふける」で思いにふける状態を表す語で、作り話という意味のこの語とは合わない。"}, {"text": "偉人のフィクションは、実在した人の人生を記録しています。", "explanation": "ここは〈伝記〉の意味。作り話は実在した人の人生を記録しないので、矛盾して合わない。"}, {"text": "試合のフィクションを、ラジオで聞きました。", "explanation": "ここは〈実況〉の意味。その場で起きた試合を伝える語で、作り話のこの語は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41296, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はフィクションを作家として有名です。", "corrected_sentence": "彼女はフィクションの作家として有名です。", "error_description": "「フィクションの作家」は名詞を「の」でつなぐ形。「を」にすると動詞の目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41296, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女はフィクションに書いています。", "corrected_sentence": "彼女はフィクションを書いています。", "error_description": "「書く」の目的語は「を」で示す。「に」にすると文が成り立たないので、「フィクションを書く」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41297, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ノンフィクション", "is_correct": true, "explanation": "実際にあった事実にもとづく作品で、フィクション（作り話）の対義語。"}, {"text": "詩", "is_correct": false, "explanation": "言葉の表現形式で、作り話かどうかの対義語ではない。"}, {"text": "漫画", "is_correct": false, "explanation": "表現の形式で、事実か作り話かという分け方の対義語ではない。"}, {"text": "映画", "is_correct": false, "explanation": "作品の形式で、フィクションの対義語ではない。"}], "correct_answer": "ノンフィクション", "explanations": {"ノンフィクション": "実際にあった事実にもとづく作品で、フィクション（作り話）の対義語。", "詩": "言葉の表現形式で、作り話かどうかの対義語ではない。", "漫画": "表現の形式で、事実か作り話かという分け方の対義語ではない。", "映画": "作品の形式で、フィクションの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41297, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「フィクション」と「世界」をつなぐ「の」。作品の世界を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「世界を」とすると目的語が二つになり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "方向や位置の「に」。「世界」につながらず不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「フィクションが世界を楽しむ」となり、主語として意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「フィクション」と「世界」をつなぐ「の」。作品の世界を示す。", "を": "目的語の「を」。「世界を」とすると目的語が二つになり、文が成り立たない。", "に": "方向や位置の「に」。「世界」につながらず不自然。", "が": "主語の「が」。「フィクションが世界を楽しむ」となり、主語として意味が通らない。"}, "error_tags": {"を": "対格", "に": "着点・位置", "が": "主格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ノンフィクション", "is_correct": true, "explanation": "事実にもとづく作品で、フィクション（作り話）の対義語。"}, {"text": "年表", "is_correct": false, "explanation": "事実を年代順に並べた表で、対義語にはならない。"}, {"text": "辞典", "is_correct": false, "explanation": "言葉を説明する本で、対義語ではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書くための道具で、フィクションの対義語ではない。"}], "correct_answer": "ノンフィクション", "explanations": {"ノンフィクション": "事実にもとづく作品で、フィクション（作り話）の対義語。", "年表": "事実を年代順に並べた表で、対義語にはならない。", "辞典": "言葉を説明する本で、対義語ではない。", "鉛筆": "書くための道具で、フィクションの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41297, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際にないことや、想像で作られた話。", "primary_collocate": null, "pronunciation": "ふぃくしょん", "ipa": "ɸikɯɕoɴ", "syllable_count": 4, "sentences": [{"text": "この作家は、想像だけでフィクションを書きました。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "この作家[さっか]は、想像[そうぞう]だけでフィクションを書[か]きました。", "sentence_source": "generated"}, {"text": "実際にあった話ではなく、完全なフィクションです。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "実際[じっさい]にあった話[はなし]ではなく、完全[かんぜん]なフィクションです。", "sentence_source": "generated"}, {"text": "宇宙旅行を描いたフィクションが、書店で人気です。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]旅行[りょこう]を描[えが]いたフィクションが、書店[しょてん]で人気[にんき]です。", "sentence_source": "generated"}, {"text": "フィクションなので、登場人物の名前も本物ではありません。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "フィクションなので、登場人物[とうじょうじんぶつ]の名前[なまえ]も本物[ほんもの]ではありません。", "sentence_source": "generated"}, {"text": "この小説は実話に見えますが、実はフィクションです。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は実話[じつわ]に見[み]えますが、実[じつ]はフィクションです。", "sentence_source": "generated"}, {"text": "兄は未来の町を舞台にしたフィクションを集めています。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "兄[あに]は未来[みらい]の町[まち]を舞台[ぶたい]にしたフィクションを集[あつ]めています。", "sentence_source": "generated"}, {"text": "ニュースと違って、フィクションは作り手が自由に考えた話です。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "ニュースと違[ちが]って、フィクションは作[つく]り手[て]が自由[じゆう]に考[かんが]えた話[はなし]です。", "sentence_source": "generated"}, {"text": "彼は現実を離れて、フィクションの世界を楽しみます。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "彼[かれ]は現実[げんじつ]を離[はな]れて、フィクションの世界[せかい]を楽[たの]しみます。", "sentence_source": "generated"}, {"text": "この話は実際の事件に似ていますが、フィクションと書いてあります。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "この話[はなし]は実際[じっさい]の事件[じけん]に似[に]ていますが、フィクションと書[か]いてあります。", "sentence_source": "generated"}, {"text": "学生たちは、自分で考えたフィクションを発表しました。", "target_word": "フィクション", "complexity_tier": "T3", "furigana": "学生[がくせい]たちは、自分[じぶん]で考[かんが]えたフィクションを発表[はっぴょう]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フィクション", "label": "基本形"}], "register": "polite", "sense_fingerprint": "現実にはない、想像によって作られた物語や作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41297, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フィクション", "is_correct": true, "explanation": "想像で作られた話を書くという意味で、「想像だけで」と文脈が合う。"}, {"text": "夕食", "is_correct": false, "explanation": "料理であり、「書く」という動詞と結びつかない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける器で、書く対象にならない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "家電製品で、書く対象にならないので文が成り立たない。"}], "explanations": {"フィクション": "想像で作られた話を書くという意味で、「想像だけで」と文脈が合う。", "夕食": "料理であり、「書く」という動詞と結びつかない。", "花瓶": "花を生ける器で、書く対象にならない。", "洗濯機": "家電製品で、書く対象にならないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "フィクション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵はフィクションだと判明しました。", "explanation": "ここは〈偽物〉の意味。フィクションは作り話の意味で、絵が偽物だったという意味では使わないので合わない。"}, {"text": "このフィクションは、実際に起きた出来事を正確に残したものです。", "explanation": "ここは〈記録〉の意味。作り話は実際の出来事を正確に残すものではないので合わない。"}, {"text": "このフィクションは、国中の人の回答をまとめたものです。", "explanation": "ここは〈統計〉の意味。実際の回答を集めた統計は作り話ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41297, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フィクション", "is_correct": true, "explanation": "作り手が自由に考えた話で、ニュースと対比される。文脈に合う。"}, {"text": "時刻表", "is_correct": false, "explanation": "列車の時刻を示す表で、作り手が自由に考えた話とは合わない。"}, {"text": "天気予報", "is_correct": false, "explanation": "実際の天気を伝えるもので、作り手が自由に考えた話とは対比できない。"}, {"text": "献立", "is_correct": false, "explanation": "料理の予定表で、物語の話ではないので文に合わない。"}], "explanations": {"フィクション": "作り手が自由に考えた話で、ニュースと対比される。文脈に合う。", "時刻表": "列車の時刻を示す表で、作り手が自由に考えた話とは合わない。", "天気予報": "実際の天気を伝えるもので、作り手が自由に考えた話とは対比できない。", "献立": "料理の予定表で、物語の話ではないので文に合わない。"}, "sentence_index": 6, "correct_answer": "フィクション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はフィクションを広げて、道を確かめました。", "explanation": "ここは〈地図〉の意味。フィクションは作り話で、広げて道を確かめる地図の意味では使えないので合わない。"}, {"text": "彼はフィクションを一枚ずつ撮って、本にまとめました。", "explanation": "ここは〈写真〉の意味。フィクションは作り話で、一枚ずつ撮って残すものではないので合わない。"}, {"text": "ホームでフィクションの時刻を確認しました。", "explanation": "ここは〈時刻〉の意味。フィクションは作り話で、列車の時刻を確かめる対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41297, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はフィクションを好きです。", "corrected_sentence": "私はフィクションが好きです。", "error_description": "「好き」は「〜が好き」と使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41297, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女はフィクションを得意な作家です。", "corrected_sentence": "彼女はフィクションが得意な作家です。", "error_description": "「得意」は「〜が得意」と使う。「を」にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41298, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈嘘〉は〈つく〉の目的語になるので〈を〉が正しい。"}, {"text": "が", "is_correct": false, "explanation": "〈嘘〉を主語にすると「嘘がついて」となり、文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、「嘘でついて」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を表すが、「嘘とついて」では文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "〈嘘〉は〈つく〉の目的語になるので〈を〉が正しい。", "が": "〈嘘〉を主語にすると「嘘がついて」となり、文が成立しない。", "で": "手段や場所を表すが、「嘘でついて」では意味が通らない。", "と": "相手や引用を表すが、「嘘とついて」では文が成立しない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
