INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41298, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "うそは、ほんとうではないことをいうことです。", "primary_collocate": null, "pronunciation": "うそ", "ipa": "ɯso", "syllable_count": 2, "sentences": [{"text": "「宿題は終わった」と言ったが、それは嘘だった。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "「宿題[しゅくだい]は終[お]わった」と言[い]ったが、それは嘘[うそ]だった。", "sentence_source": "generated"}, {"text": "弟は嘘をついて、母に叱られた。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "弟[おとうと]は嘘[うそ]をついて、母[はは]に叱[しか]られた。", "sentence_source": "generated"}, {"text": "嘘を言うと、友だちに信じてもらえなくなる。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "嘘[うそ]を言[い]うと、友[とも]だちに信[しん]じてもらえなくなる。", "sentence_source": "generated"}, {"text": "先生は「本当のことを言いなさい。嘘はだめですよ」と言った。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "先生[せんせい]は「本当[ほんとう]のことを言[い]いなさい。嘘[うそ]はだめですよ」と言[い]った。", "sentence_source": "generated"}, {"text": "私は風邪をひいていないのに、嘘の理由で学校を休んだ。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "私[わたし]は風邪[かぜ]をひいていないのに、嘘[うそ]の理由[りゆう]で学校[がっこう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "彼の話は嘘ばかりなので、だれも信じない。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は嘘[うそ]ばかりなので、だれも信[しん]じない。", "sentence_source": "generated"}, {"text": "ケーキを食べていないという子どもの嘘は、口のまわりのクリームですぐわかった。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "ケーキを食[た]べていないという子[こ]どもの嘘[うそ]は、口[くち]のまわりのクリームですぐわかった。", "sentence_source": "generated"}, {"text": "嘘をつかないで、正直に話してください。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "嘘[うそ]をつかないで、正直[しょうじき]に話[はな]してください。", "sentence_source": "generated"}, {"text": "「雪が降った」なんて嘘でしょう。ここは真夏よ。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "「雪[ゆき]が降[ふ]った」なんて嘘[うそ]でしょう。ここは真夏[まなつ]よ。", "sentence_source": "generated"}, {"text": "小さな嘘でも、重なると大きな問題になる。", "target_word": "嘘", "complexity_tier": "T3", "furigana": "小[ちい]さな嘘[うそ]でも、重[かさ]なると大[おお]きな問題[もんだい]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘘", "label": "基本形"}, {"form": "嘘の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "本当ではないことを言うこと（子ども向けの基本義）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41298, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘘", "is_correct": true, "explanation": "「それは…だった」で、事実ではない言葉の内容を指す名詞。"}, {"text": "積み木", "is_correct": false, "explanation": "遊び道具の名で、言った内容としては当てはまらない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠さを表す語で、言ったことの内容として不自然。"}, {"text": "台風", "is_correct": false, "explanation": "天候の現象で、言った内容としては当てはまらない。"}], "explanations": {"嘘": "「それは…だった」で、事実ではない言葉の内容を指す名詞。", "積み木": "遊び道具の名で、言った内容としては当てはまらない。", "眠気": "眠さを表す語で、言ったことの内容として不自然。", "台風": "天候の現象で、言った内容としては当てはまらない。"}, "sentence_index": 0, "correct_answer": "嘘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は計算に嘘があったと気づかず、そのまま提出した。", "explanation": "〈嘘〉は意図して偽ること。うっかりした誤りには〈誤り〉を使うので、〈嘘〉と混同している。"}, {"text": "この薬は嘘の効き目で、すぐに症状が治まった。", "explanation": "〈嘘〉は偽りの言葉を指す。効き目を表すのに〈嘘〉を使うのは誤りで、〈効果〉の意味と混同している。"}, {"text": "雨の日の空は嘘の重さで、低く垂れこめていた。", "explanation": "〈嘘〉は偽りの言葉を指す。空の重苦しさを表すのに〈嘘〉を使うのは誤りで、〈重苦しい〉の意味と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41298, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘘", "is_correct": true, "explanation": "「食べていない」と言う偽りの主張を指す名詞。文の主語として合う。"}, {"text": "遠足", "is_correct": false, "explanation": "学校行事の名前で、主張の内容とは関係しない。"}, {"text": "雷", "is_correct": false, "explanation": "天候の現象で、子どもの主張の内容としては当てはまらない。"}, {"text": "給食", "is_correct": false, "explanation": "食事の時間を指す語で、ケーキを食べていないという主張とは結びつかない。"}], "explanations": {"嘘": "「食べていない」と言う偽りの主張を指す名詞。文の主語として合う。", "遠足": "学校行事の名前で、主張の内容とは関係しない。", "雷": "天候の現象で、子どもの主張の内容としては当てはまらない。", "給食": "食事の時間を指す語で、ケーキを食べていないという主張とは結びつかない。"}, "sentence_index": 6, "correct_answer": "嘘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は約束の時間を嘘で守った。", "explanation": "〈嘘〉は偽りの言葉を指す。偽りを手段に時間を守る使い方は不自然で、〈言い訳〉の意味と混同している。"}, {"text": "寝坊した弟は、嘘で遅刻を取り戻した。", "explanation": "〈嘘〉は偽りの言葉を指す。遅刻の挽回に使うのは誤りで、〈埋め合わせ〉の意味と混同している。"}, {"text": "この絵は嘘の色で美しく描かれている。", "explanation": "〈嘘〉は言葉の偽り。色を表すのに〈嘘〉を使うのは誤りで、〈偽物〉の意味と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
