INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41299, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "事実と異なることを言うこと。また、その言葉。真実を偽って伝えること。", "primary_collocate": null, "pronunciation": "うそ", "ipa": "ɯso", "syllable_count": 2, "sentences": [{"text": "容疑者は警察に嘘の証言をして、捜査を混乱させた。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "容疑者[ようぎしゃ]は警察[けいさつ]に嘘[うそ]の証言[しょうげん]をして、捜査[そうさ]を混乱[こんらん]させた。", "sentence_source": "generated"}, {"text": "履歴書に嘘を書くと、採用が取り消されることがある。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "履歴書[りれきしょ]に嘘[うそ]を書[か]くと、採用[さいよう]が取[と]り消[け]されることがある。", "sentence_source": "generated"}, {"text": "彼女の言葉が嘘だと分かったとき、信頼は一瞬で崩れた。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の言葉[ことば]が嘘[うそ]だと分[わ]かったとき、信頼[しんらい]は一瞬[いっしゅん]で崩[くず]れた。", "sentence_source": "generated"}, {"text": "商品の広告に嘘があれば、消費者は買う前に判断できない。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "商品[しょうひん]の広告[こうこく]に嘘[うそ]があれば、消費者[しょうひしゃ]は買[か]う前[まえ]に判断[はんだん]できない。", "sentence_source": "generated"}, {"text": "部長は事実を隠し、会議で嘘の報告をしていた。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "部長[ぶちょう]は事実[じじつ]を隠[かく]し、会議[かいぎ]で嘘[うそ]の報告[ほうこく]をしていた。", "sentence_source": "generated"}, {"text": "嘘を重ねるほど、あとで説明するのが苦しくなる。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "嘘[うそ]を重[かさ]ねるほど、あとで説明[せつめい]するのが苦[くる]しくなる。", "sentence_source": "generated"}, {"text": "嘘を見抜くために、記者は何度も資料を確かめた。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "嘘[うそ]を見抜[みぬ]くために、記者[きしゃ]は何度[なんど]も資料[しりょう]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "彼は嘘をついていないと言い張ったが、記録がそれを否定した。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "彼[かれ]は嘘[うそ]をついていないと言[い]い張[は]ったが、記録[きろく]がそれを否定[ひてい]した。", "sentence_source": "generated"}, {"text": "彼女は相手を傷つけないための嘘を、悪いこととは思っていない。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は相手[あいて]を傷[きず]つけないための嘘[うそ]を、悪[わる]いこととは思[おも]っていない。", "sentence_source": "generated"}, {"text": "偽の領収書を出すのは、会社に対する嘘になる。", "target_word": "嘘", "complexity_tier": "T4", "furigana": "偽[にせ]の領収書[りょうしゅうしょ]を出[だ]すのは、会社[かいしゃ]に対[たい]する嘘[うそ]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘘", "label": "基本形"}, {"form": "嘘の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "事実と違うことを偽って伝えること、またその言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41299, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘘", "is_correct": true, "explanation": "「嘘の証言」で、偽りの証言を表す。警察に対して行った証言の内容として合う。"}, {"text": "天気", "is_correct": false, "explanation": "天候を表す語で、証言の内容として成り立たない。"}, {"text": "試験", "is_correct": false, "explanation": "学力を測る行事で、証言とは結びつかない。"}, {"text": "帽子", "is_correct": false, "explanation": "身につける物で、証言の修飾語として不自然。"}], "explanations": {"嘘": "「嘘の証言」で、偽りの証言を表す。警察に対して行った証言の内容として合う。", "天気": "天候を表す語で、証言の内容として成り立たない。", "試験": "学力を測る行事で、証言とは結びつかない。", "帽子": "身につける物で、証言の修飾語として不自然。"}, "sentence_index": 0, "correct_answer": "嘘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "見積書の金額に嘘の計算ミスがあったので、書き直した。", "explanation": "〈嘘〉は意図的な偽り。うっかりした計算ミスには〈誤り〉を使うので、〈嘘〉とは合わない。"}, {"text": "新商品は嘘で作られたため、すぐに製造が止まった。", "explanation": "〈嘘〉は言葉の偽り。物の材料には使えず、〈偽造〉の意味と混同している。"}, {"text": "市場に嘘の商品が並んでいる。", "explanation": "〈嘘〉は言葉や説明の偽り。商品そのものには〈偽物〉を使うので、〈嘘〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41299, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘘", "is_correct": true, "explanation": "偽りを見抜くという意味で、記者が資料を確かめた目的として合う。"}, {"text": "靴", "is_correct": false, "explanation": "物を指す語で、見抜く対象としては不自然。"}, {"text": "窓", "is_correct": false, "explanation": "物を指す語で、見抜く対象として成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "物を指す語で、見抜くという動作の対象として不自然。"}], "explanations": {"嘘": "偽りを見抜くという意味で、記者が資料を確かめた目的として合う。", "靴": "物を指す語で、見抜く対象としては不自然。", "窓": "物を指す語で、見抜く対象として成り立たない。", "冷蔵庫": "物を指す語で、見抜くという動作の対象として不自然。"}, "sentence_index": 6, "correct_answer": "嘘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は取り返しのつかない嘘を犯してしまった。", "explanation": "〈嘘〉は偽りを言うこと。〈犯す〉とは言わず、〈過ち〉と混同した使い方になる。"}, {"text": "この企画は嘘に終わった。", "explanation": "〈嘘〉は偽りの話。企画の結果には〈失敗〉を使うので、〈嘘〉とは合わない。"}, {"text": "この店は嘘の味で、毎日多くの客が並んでいる。", "explanation": "〈嘘〉は言葉の偽り。味を表すのに〈嘘〉を使うのは誤りで、〈おいしさ〉の意味とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41299, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "記者は嘘が見抜くために、資料を確かめた。", "corrected_sentence": "記者は嘘を見抜くために、資料を確かめた。", "error_description": "〈見抜く〉の目的語は格助詞〈を〉。〈が〉を付けると〈嘘〉が主語になり、文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41299, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は嘘な報告をしたので、会議で責められた。", "corrected_sentence": "彼女は嘘の報告をしたので、会議で責められた。", "error_description": "〈嘘〉は名詞なので名詞修飾には格助詞〈の〉を使う。〈な〉は付けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41304, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「あります」の主語になる「が」で、存在するものを示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「ある」は目的語をとらないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表す「と」だが、「ピアノと」で文が続かず、ここでは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、存在を示す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「あります」の主語になる「が」で、存在するものを示す。", "を": "目的語の「を」。「ある」は目的語をとらないので合わない。", "と": "並列を表す「と」だが、「ピアノと」で文が続かず、ここでは合わない。", "へ": "方向を示す「へ」で、存在を示す文には合わない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41304, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ピアノの先生」の修飾を示す「の」。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「ピアノから先生で」では先生を修飾できず合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。比べる対象がないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置や帰着を示す「に」で、ここでは「先生」を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「ピアノの先生」の修飾を示す「の」。", "から": "起点の「から」。「ピアノから先生で」では先生を修飾できず合わない。", "より": "比較の「より」。比べる対象がないので合わない。", "に": "位置や帰着を示す「に」で、ここでは「先生」を修飾できない。"}, "error_tags": {"から": "起点", "より": "比較", "に": "位置・帰着"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41304, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ピアノは、おとをだすがっきです。", "primary_collocate": null, "pronunciation": "ぴあの", "ipa": "pjano", "syllable_count": 3, "sentences": [{"text": "姉は毎日、学校から帰るとピアノを弾きます。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "姉[あね]は毎日[まいにち]、学校[がっこう]から帰[かえ]るとピアノを弾[ひ]きます。", "sentence_source": "generated"}, {"text": "私の家には古いピアノがあります。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]には古[ふる]いピアノがあります。", "sentence_source": "generated"}, {"text": "ピアノの音が聞こえるので、隣の部屋をのぞきました。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "ピアノの音[おと]が聞[き]こえるので、隣[となり]の部屋[へや]をのぞきました。", "sentence_source": "generated"}, {"text": "弟はピアノを習っているので、楽譜が読めます。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "弟[おとうと]はピアノを習[なら]っているので、楽譜[がくふ]が読[よ]めます。", "sentence_source": "generated"}, {"text": "音楽室にピアノがあって、先生が歌の伴奏をしてくれた。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "音楽室[おんがくしつ]にピアノがあって、先生[せんせい]が歌[うた]の伴奏[ばんそう]をしてくれた。", "sentence_source": "generated"}, {"text": "このピアノは大きいので、二階へ運ぶのが大変だった。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "このピアノは大[おお]きいので、二階[にかい]へ運[はこ]ぶのが大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "夜はピアノを弾くと近所に迷惑なので、昼間に練習します。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "夜[よる]はピアノを弾[ひ]くと近所[きんじょ]に迷惑[めいわく]なので、昼間[ひるま]に練習[れんしゅう]します。", "sentence_source": "generated"}, {"text": "母はピアノの先生で、毎週土曜日に子どもたちに教えている。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "母[はは]はピアノの先生[せんせい]で、毎週[まいしゅう]土曜日[どようび]に子[こ]どもたちに教[おし]えている。", "sentence_source": "generated"}, {"text": "ピアノの前に座ると、少し緊張します。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "ピアノの前[まえ]に座[すわ]ると、少[すこ]し緊張[きんちょう]します。", "sentence_source": "generated"}, {"text": "私はギターよりピアノのほうが好きです。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "私[わたし]はギターよりピアノのほうが好[す]きです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ピアノ", "label": "基本形"}], "register": "標準", "sense_fingerprint": "音を出す楽器のピアノ。日常の場面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41304, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ピアノ", "is_correct": true, "explanation": "「ピアノを弾く」は演奏での定番の組み合わせで、ここに入る唯一の語。"}, {"text": "太鼓", "is_correct": false, "explanation": "打楽器で、「叩く」と言うので「弾きます」とは合わない。"}, {"text": "ラッパ", "is_correct": false, "explanation": "管楽器で「吹く」と言うので、「弾きます」とは合わない。"}, {"text": "笛", "is_correct": false, "explanation": "「吹く」楽器なので、「弾きます」とは合わない。"}], "explanations": {"ピアノ": "「ピアノを弾く」は演奏での定番の組み合わせで、ここに入る唯一の語。", "太鼓": "打楽器で、「叩く」と言うので「弾きます」とは合わない。", "ラッパ": "管楽器で「吹く」と言うので、「弾きます」とは合わない。", "笛": "「吹く」楽器なので、「弾きます」とは合わない。"}, "sentence_index": 0, "correct_answer": "ピアノ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "荷物をピアノで縛ると、ほどけにくくて安心だ。", "explanation": "ここは楽器の意味ではない。楽器のピアノで荷物は縛れず、縛るのはピアノ線などの針金。"}, {"text": "ピアノは息を吹き込んで、ポケットに入る小さな音を出す。", "explanation": "ここは〈ハーモニカ〉の仕組み。息を吹き込んで音を出すのはハーモニカで、ピアノは弦を打つ。"}, {"text": "ピアノは硬いばちで、並べた板を順に叩いて旋律を奏でる。", "explanation": "ここは〈木琴〉の用法。ばちで板を叩いて音を出すのは木琴で、ピアノは鍵盤で弦を打つ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41304, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ピアノ", "is_correct": true, "explanation": "「ピアノを弾くと」と演奏を言う場面に合う、ここに入る唯一の語。"}, {"text": "ドラム", "is_correct": false, "explanation": "叩いて鳴らす楽器なので、「弾く」とは言わない。"}, {"text": "鐘", "is_correct": false, "explanation": "打って鳴らす楽器なので、「弾く」とは合わない。"}, {"text": "ホルン", "is_correct": false, "explanation": "吹いて鳴らす楽器なので、「弾く」とは合わない。"}], "explanations": {"ピアノ": "「ピアノを弾くと」と演奏を言う場面に合う、ここに入る唯一の語。", "ドラム": "叩いて鳴らす楽器なので、「弾く」とは言わない。", "鐘": "打って鳴らす楽器なので、「弾く」とは合わない。", "ホルン": "吹いて鳴らす楽器なので、「弾く」とは合わない。"}, "sentence_index": 6, "correct_answer": "ピアノ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアノは弓で弦をこすって、伸びやかな音を出す。", "explanation": "ここは〈バイオリン〉の仕組み。弓で弦をこすって音を出すのはバイオリンで、ピアノは弦を打つ。"}, {"text": "ピアノは指で弦を押さえて、その位置で音の高さを決める。", "explanation": "ここは〈ギター〉の用法。弦を指で押さえて音の高さを決めるのはギターで、ピアノは鍵盤で音を出す。"}, {"text": "ピアノは指で糸を一本ずつはじいて、やわらかな音を出す。", "explanation": "ここは〈ハープ〉の用法。指で糸をはじくのはハープで、ピアノは鍵盤で弦を打つ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41304, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父の家には古いピアノをあります。", "corrected_sentence": "祖父の家には古いピアノがあります。", "error_description": "誤りは「を」。「ある」は存在を表し、存在するものは「が」で示す。正しくは「ピアノが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41304, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は毎晩ピアノを読んでいる。", "corrected_sentence": "妹は毎晩ピアノを弾いている。", "error_description": "誤りは「読んで」。正しくは「弾いて」。ピアノは「弾く」で演奏するもので、「読む」は楽譜などに使う語なので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41305, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。ピアノについて説明する文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「ピアノを鍵盤を」と目的語が重なり、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「ピアノへ」では説明の主題にならず合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「ピアノから」では説明の主題にならず合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。ピアノについて説明する文の主題になる。", "を": "目的語の「を」。「ピアノを鍵盤を」と目的語が重なり、文が成立しない。", "へ": "方向の「へ」。「ピアノへ」では説明の主題にならず合わない。", "から": "起点の「から」。「ピアノから」では説明の主題にならず合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41305, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ピアノの演奏家」の所属・修飾を示す「の」。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」だが、「ピアノと演奏家になる」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「ピアノを演奏家になる」では「なる」が「に」を取るため成立しない。"}, {"text": "に", "is_correct": false, "explanation": "位置や帰着を示す「に」だが、「ピアノに演奏家」では修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「ピアノの演奏家」の所属・修飾を示す「の」。", "と": "並列を示す「と」だが、「ピアノと演奏家になる」では意味が通らない。", "を": "目的語の「を」。「ピアノを演奏家になる」では「なる」が「に」を取るため成立しない。", "に": "位置や帰着を示す「に」だが、「ピアノに演奏家」では修飾にならない。"}, "error_tags": {"と": "並列・相手", "に": "位置・帰着", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41305, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ピアノは、鍵盤を押して音を出す楽器です。クラシック音楽などでよく使われます。", "primary_collocate": null, "pronunciation": "ぴあの", "ipa": "pjano", "syllable_count": 3, "sentences": [{"text": "彼女はピアノでショパンの曲を演奏した。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はピアノでショパンの曲[きょく]を演奏[えんそう]した。", "sentence_source": "generated"}, {"text": "ピアノは鍵盤を押すと、中のハンマーが弦を打って音が出る。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "ピアノは鍵盤[けんばん]を押[お]すと、中[なか]のハンマーが弦[げん]を打[う]って音[おと]が出[で]る。", "sentence_source": "generated"}, {"text": "コンサートでは、ピアノとバイオリンが美しい二重奏を奏でた。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "コンサートでは、ピアノとバイオリンが美[うつく]しい二重奏[にじゅうそう]を奏[かな]でた。", "sentence_source": "generated"}, {"text": "調律師が来て、狂っていたピアノの音を直してくれた。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "調律師[ちょうりつし]が来[き]て、狂[くる]っていたピアノの音[おと]を直[なお]してくれた。", "sentence_source": "generated"}, {"text": "彼はクラシックが好きで、ピアノの独奏会によく行く。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "彼[かれ]はクラシックが好[す]きで、ピアノの独奏会[どくそうかい]によく行[い]く。", "sentence_source": "generated"}, {"text": "発表会に向けて、ピアノの練習を毎日二時間続けている。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "発表会[はっぴょうかい]に向[む]けて、ピアノの練習[れんしゅう]を毎日[まいにち]二時間[にじかん]続[つづ]けている。", "sentence_source": "generated"}, {"text": "ピアノの鍵盤は白と黒があり、黒い鍵盤は半音を出す。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "ピアノの鍵盤[けんばん]は白[しろ]と黒[くろ]があり、黒[くろ]い鍵盤[けんばん]は半音[はんおん]を出[だ]す。", "sentence_source": "generated"}, {"text": "祖母は若いころ、ピアノの演奏家になるのが夢だった。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は若[わか]いころ、ピアノの演奏家[えんそうか]になるのが夢[ゆめ]だった。", "sentence_source": "generated"}, {"text": "音大に入るため、彼は子どものころからピアノを習った。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "音大[おんだい]に入[はい]るため、彼[かれ]は子[こ]どものころからピアノを習[なら]った。", "sentence_source": "generated"}, {"text": "楽譜どおりにピアノを弾くだけでなく、自分の気持ちも音にのせたい。", "target_word": "ピアノ", "complexity_tier": "T3", "furigana": "楽譜[がくふ]どおりにピアノを弾[ひ]くだけでなく、自分[じぶん]の気持[きも]ちも音[おと]にのせたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ピアノ", "label": "基本形"}], "register": "標準", "sense_fingerprint": "鍵盤楽器のピアノ。演奏やクラシック音楽の場面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 二重奏 (Zipf 2.1)']::text[], 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41305, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ピアノ", "is_correct": true, "explanation": "「ピアノでショパンの曲を演奏した」の手段を示す語で、ここに入る唯一の語。"}, {"text": "ハンマー", "is_correct": false, "explanation": "鍵盤を押すと動く内部の部品で、演奏の手段にはならない。"}, {"text": "弦", "is_correct": false, "explanation": "音を出す部品で、それ自体を使って演奏はできない。"}, {"text": "ペダル", "is_correct": false, "explanation": "音を伸ばす踏み板で、演奏の道具にはならない。"}], "explanations": {"ピアノ": "「ピアノでショパンの曲を演奏した」の手段を示す語で、ここに入る唯一の語。", "ハンマー": "鍵盤を押すと動く内部の部品で、演奏の手段にはならない。", "弦": "音を出す部品で、それ自体を使って演奏はできない。", "ペダル": "音を伸ばす踏み板で、演奏の道具にはならない。"}, "sentence_index": 0, "correct_answer": "ピアノ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ピアノは足元のふいごで空気を送り、その風で音を出す。", "explanation": "ここは〈オルガン〉の仕組み。風を送って鳴らすのはオルガンで、ピアノは弦を打って音を出す。"}, {"text": "ピアノは両手で打ち合わせて、乾いた音を鳴らす。", "explanation": "ここは〈カスタネット〉の用法。打ち合わせて鳴らすのはカスタネットで、ピアノには合わない。"}, {"text": "ピアノはばちで皮を叩いて、ずしんと響く音を出す。", "explanation": "ここは〈ドラム〉の用法。皮を叩いて鳴らすのはドラムで、ピアノは鍵盤で弦を打つ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41305, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ピアノ", "is_correct": true, "explanation": "「ピアノの鍵盤」と、鍵盤を持つ楽器そのものを指す語で、ここに入る唯一の語。"}, {"text": "ダンパー", "is_correct": false, "explanation": "弦の振動を止める部品で、鍵盤を持つものではない。"}, {"text": "響板", "is_correct": false, "explanation": "音を響かせる板で、鍵盤を持たない。"}, {"text": "譜面台", "is_correct": false, "explanation": "楽譜を置く台で、鍵盤はない。"}], "explanations": {"ピアノ": "「ピアノの鍵盤」と、鍵盤を持つ楽器そのものを指す語で、ここに入る唯一の語。", "ダンパー": "弦の振動を止める部品で、鍵盤を持つものではない。", "響板": "音を響かせる板で、鍵盤を持たない。", "譜面台": "楽譜を置く台で、鍵盤はない。"}, "sentence_index": 6, "correct_answer": "ピアノ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアノは弓で弦をこすりながら、息の長い音を出す。", "explanation": "ここは〈バイオリン〉の仕組み。弓で弦をこするのはバイオリンで、ピアノは弦を打って音を出す。"}, {"text": "ピアノは弦を指で押さえて、音の高さを変えながら弾く。", "explanation": "ここは〈ギター〉の用法。弦を指で押さえて音程を変えるのはギターで、ピアノは鍵盤で音程を決める。"}, {"text": "ピアノは指で糸を一本ずつはじき、澄んだ音を重ねる。", "explanation": "ここは〈ハープ〉の用法。糸を指ではじくのはハープで、ピアノは鍵盤を押して弦を打つ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41305, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉はピアノをモーツァルトの曲を演奏した。", "corrected_sentence": "姉はピアノでモーツァルトの曲を演奏した。", "error_description": "誤りは「ピアノを」の「を」。ピアノは演奏の手段なので「で」が正しい。「を」のままだと「曲を」と目的語が二つ重なり、一つの動詞に目的語が二つ立って不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41305, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は毎朝、ピアノを吹いてから学校へ行く。", "corrected_sentence": "妹は毎朝、ピアノを弾いてから学校へ行く。", "error_description": "誤りは「吹いて」。ピアノは「弾く」で演奏するもので、「吹く」は管楽器に使う語なので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
