INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41306, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「お米を研いだ」で、研ぐ動作の対象を示す目的語の助詞。"}, {"text": "の", "is_correct": false, "explanation": "所有の関係を示す。研いだ動作の対象は示せず、「お米の研いだ水」は別の意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す。米を研ぐ対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、研ぐ対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「お米を研いだ」で、研ぐ動作の対象を示す目的語の助詞。", "の": "所有の関係を示す。研いだ動作の対象は示せず、「お米の研いだ水」は別の意味になる。", "へ": "方向を表す。米を研ぐ対象にはならない。", "より": "比較の助詞で、研ぐ対象を示せない。"}, "error_tags": {"の": "所有・連体", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41306, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、こすったり、みがいたりして、きれいにする。", "primary_collocate": null, "pronunciation": "とぐ", "ipa": "toɡɯ", "syllable_count": 2, "sentences": [{"text": "母は夕食の前に米を研いでいる。", "target_word": "研いで", "complexity_tier": "T3", "furigana": "母[はは]は夕食[ゆうしょく]の前[まえ]に米[こめ]を研[と]いでいる。", "sentence_source": "generated"}, {"text": "ご飯を炊く前に、米を三回ていねいに研ぐ。", "target_word": "研ぐ", "complexity_tier": "T3", "furigana": "ご飯[はん]を炊[た]く前[まえ]に、米[こめ]を三回[さんかい]ていねいに研[と]ぐ。", "sentence_source": "generated"}, {"text": "水がにごらなくなるまで、米を研いだ。", "target_word": "研いだ", "complexity_tier": "T3", "furigana": "水[みず]がにごらなくなるまで、米[こめ]を研[と]いだ。", "sentence_source": "generated"}, {"text": "朝早く起きて、お米を研ぐのが祖母の日課だ。", "target_word": "研ぐ", "complexity_tier": "T3", "furigana": "朝[あさ]早[はや]く起[お]きて、お米[こめ]を研[と]ぐのが祖母[そぼ]の日課[にっか]だ。", "sentence_source": "generated"}, {"text": "米を研ぐときは、冷たい水を使うとよい。", "target_word": "研ぐ", "complexity_tier": "T3", "furigana": "米[こめ]を研[と]ぐときは、冷[つめ]たい水[みず]を使[つか]うとよい。", "sentence_source": "generated"}, {"text": "キャンプ場で、飯ごうに入れる米を研いだ。", "target_word": "研いだ", "complexity_tier": "T3", "furigana": "キャンプ場[じょう]で、飯[はん]ごうに入[い]れる米[こめ]を研[と]いだ。", "sentence_source": "generated"}, {"text": "彼は炊飯器に入れる前に、米をもう一度研いだ。", "target_word": "研いだ", "complexity_tier": "T3", "furigana": "彼[かれ]は炊飯器[すいはんき]に入[い]れる前[まえ]に、米[こめ]をもう一度[いちど]研[と]いだ。", "sentence_source": "generated"}, {"text": "お米を研いだ水は、植物にあげるといいらしい。", "target_word": "研いだ", "complexity_tier": "T3", "furigana": "お米[こめ]を研[と]いだ水[みず]は、植物[しょくぶつ]にあげるといいらしい。", "sentence_source": "generated"}, {"text": "おいしいご飯のために、米を研ぐ時間を大切にしている。", "target_word": "研ぐ", "complexity_tier": "T3", "furigana": "おいしいご飯[はん]のために、米[こめ]を研[と]ぐ時間[じかん]を大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "祖父は朝の米を手早く研いだ。", "target_word": "研いだ", "complexity_tier": "T3", "furigana": "祖父[そふ]は朝[あさ]の米[こめ]を手早[てばや]く研[と]いだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "研ぐ", "label": "辞書形"}, {"form": "研いで", "label": "て形"}, {"form": "研いだ", "label": "た形"}, {"form": "研ぎ", "label": "連用形"}, {"form": "研がない", "label": "ない形"}], "register": "標準（日常語）", "sense_fingerprint": "米などをこすってきれいにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41306, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研いで", "is_correct": true, "explanation": "て形で「研いでいる」と続き、米を研いでいる状態を表す。"}, {"text": "研ぐ", "is_correct": false, "explanation": "辞書形に「いる」を付けると不自然で、空所に入らない。"}, {"text": "研ぎ", "is_correct": false, "explanation": "連用形に「いる」を続けた形は文として成立しない。"}, {"text": "研がない", "is_correct": false, "explanation": "否定形に「いる」は続かず、「研がないいる」は不自然になる。"}], "explanations": {"研いで": "て形で「研いでいる」と続き、米を研いでいる状態を表す。", "研ぐ": "辞書形に「いる」を付けると不自然で、空所に入らない。", "研ぎ": "連用形に「いる」を続けた形は文として成立しない。", "研がない": "否定形に「いる」は続かず、「研がないいる」は不自然になる。"}, "sentence_index": 0, "correct_answer": "研いで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お皿を研ぐのが祖母の日課だ。", "explanation": "ここは〈洗う〉の意味。皿の汚れは洗うを使い、研ぐは米や刃物を対象とするので合わない。"}, {"text": "庭のごみを研ぐのが祖母の日課だ。", "explanation": "ここは〈掃く〉の意味。ごみは掃いて集めるもので、研ぐは米や刃物を対象とする語なので合わない。"}, {"text": "祖母は毎朝、髪を研ぐのが日課だ。", "explanation": "ここは〈とかす〉の意味。髪は櫛でとかすと言い、研ぐは米や刃物に使う語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41306, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研いだ", "is_correct": true, "explanation": "た形で「もう一度研いだ」と過去の動作を述べ、文末として自然。"}, {"text": "研いで", "is_correct": false, "explanation": "て形のため、文末に置くと「研いで。」と言い切れず不自然。"}, {"text": "研げ", "is_correct": false, "explanation": "命令形で、「もう一度研げ」は文脈に合わない。"}, {"text": "研がず", "is_correct": false, "explanation": "否定の連用形で、「もう一度研がず」は「もう一度」の意味と矛盾する。"}], "explanations": {"研いだ": "た形で「もう一度研いだ」と過去の動作を述べ、文末として自然。", "研いで": "て形のため、文末に置くと「研いで。」と言い切れず不自然。", "研げ": "命令形で、「もう一度研げ」は文脈に合わない。", "研がず": "否定の連用形で、「もう一度研がず」は「もう一度」の意味と矛盾する。"}, "sentence_index": 6, "correct_answer": "研いだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テーブルを研いで、きれいにした。", "explanation": "ここは〈拭く〉の意味。テーブルの汚れは拭くで取り、研ぐは刃物や米に使う語なので合わない。"}, {"text": "木材を研いで、形を整えた。", "explanation": "ここは〈削る〉の意味。木材の形を整えるなら削るを使い、研ぐは刃物を鋭くする動作に使う。"}, {"text": "論文を研いで発表した。", "explanation": "ここは〈研究する〉の意味。学問や調査は研究するを使い、研ぐは物をこすって磨く意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41306, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "米に三回ていねいに研いでから炊く。", "corrected_sentence": "米を三回ていねいに研いでから炊く。", "error_description": "「研ぐ」は対象を「を」で示す。「に」は誤りで、「米を研いで」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "研ぐ", "is_correct": true, "explanation": "辞書形で、「米を三回ていねいに研ぐ」と言い切りの動作を表す。"}, {"text": "研いで", "is_correct": false, "explanation": "て形のため、文末の「研ぐ。」の位置には置けない。"}, {"text": "研がない", "is_correct": false, "explanation": "否定形で、「三回ていねいに研ぐ」という肯定の動作と矛盾する。"}, {"text": "研ぎ", "is_correct": false, "explanation": "連用形で文を言い切れず、「米を三回ていねいに研ぎ。」は成り立たない。"}], "correct_form": "研ぐ", "base_form": "研ぐ", "form_label": "辞書形", "sentence_index": 1, "explanations": {"研ぐ": "辞書形で、「米を三回ていねいに研ぐ」と言い切りの動作を表す。", "研いで": "て形のため、文末の「研ぐ。」の位置には置けない。", "研がない": "否定形で、「三回ていねいに研ぐ」という肯定の動作と矛盾する。", "研ぎ": "連用形で文を言い切れず、「米を三回ていねいに研ぎ。」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41306, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "米を研ぎて、ふやかした。", "corrected_sentence": "米を研いで、ふやかした。", "error_description": "「研ぐ」のて形は音便で「研いで」になる。「研ぎて」は形が誤りで、「研いで」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "研いだ", "is_correct": true, "explanation": "た形。「お米を研いだ水」と名詞の「水」を修飾する。"}, {"text": "研ぎ", "is_correct": false, "explanation": "連用形のため、名詞「水」を直接修飾できない。"}, {"text": "研ごう", "is_correct": false, "explanation": "意志形のため、名詞を修飾できず文が成り立たない。"}, {"text": "研がず", "is_correct": false, "explanation": "否定の連用形で、名詞を修飾できず意味も反転する。"}], "correct_form": "研いだ", "base_form": "研ぐ", "form_label": "た形", "sentence_index": 7, "explanations": {"研いだ": "た形。「お米を研いだ水」と名詞の「水」を修飾する。", "研ぎ": "連用形のため、名詞「水」を直接修飾できない。", "研ごう": "意志形のため、名詞を修飾できず文が成り立たない。", "研がず": "否定の連用形で、名詞を修飾できず意味も反転する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41307, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「砥石で」の「で」は道具・手段を表し、砥石を使って研ぐという意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "「砥石に研いでいる」は不自然。研ぐ動作の道具は「で」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表す。砥石を移動先とする文は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表す。ここでは比較の文脈がなく、意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "正解。「砥石で」の「で」は道具・手段を表し、砥石を使って研ぐという意味に合う。", "に": "「砥石に研いでいる」は不自然。研ぐ動作の道具は「で」で示す。", "へ": "「へ」は移動の方向を表す。砥石を移動先とする文は成り立たない。", "より": "「より」は比較の基準を表す。ここでは比較の文脈がなく、意味が通らない。"}, "error_tags": {"に": "帰着・対象（〜に）", "へ": "方向（〜へ）", "より": "比較（〜より）"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41307, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「斧を研いで」の「を」は研ぐ動作の対象を示し、斧を研ぐという意味に合う。"}, {"text": "と", "is_correct": false, "explanation": "「斧と研いで」は不自然。研ぐの対象は「を」で示す。"}, {"text": "から", "is_correct": false, "explanation": "「斧から研いで」は意味が通らない。起点を表す「から」は研ぐの対象に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「斧の研いで」は文の成分として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「斧を研いで」の「を」は研ぐ動作の対象を示し、斧を研ぐという意味に合う。", "と": "「斧と研いで」は不自然。研ぐの対象は「を」で示す。", "から": "「斧から研いで」は意味が通らない。起点を表す「から」は研ぐの対象に合わない。", "の": "「斧の研いで」は文の成分として成り立たない。"}, "error_tags": {"と": "共同（〜と）", "から": "起点（〜から）", "の": "連体（〜の）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41307, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "刃物や道具の表面をこすって、切れ味や光沢を良くする。", "primary_collocate": null, "pronunciation": "とぐ", "ipa": "toɡɯ", "syllable_count": 2, "sentences": [{"text": "父は包丁を砥石で研いでいる。", "target_word": "研いで", "complexity_tier": "T3", "furigana": "父[ちち]は包丁[ほうちょう]を砥石[といし]で研[と]いでいる。", "sentence_source": "generated"}, {"text": "切れなくなったナイフを研いだら、よく切れるようになった。", "target_word": "研いだら", "complexity_tier": "T3", "furigana": "切[き]れなくなったナイフを研[と]いだら、よく切[き]れるようになった。", "sentence_source": "generated"}, {"text": "おじいさんは毎朝、かまを研いでから畑へ行く。", "target_word": "研いで", "complexity_tier": "T3", "furigana": "おじいさんは毎朝[まいあさ]、かまを研[と]いでから畑[はたけ]へ行[い]く。", "sentence_source": "generated"}, {"text": "包丁がよく切れないので、研ぐことにした。", "target_word": "研ぐ", "complexity_tier": "T3", "furigana": "包丁[ほうちょう]がよく切[き]れないので、研[と]ぐことにした。", "sentence_source": "generated"}, {"text": "大工さんがのみを丁寧に研いでいる。", "target_word": "研いで", "complexity_tier": "T3", "furigana": "大工[だいく]さんがのみを丁寧[ていねい]に研[と]いでいる。", "sentence_source": "generated"}, {"text": "刃を研ぐときは、角度を一定に保つことが大切だ。", "target_word": "研ぐ", "complexity_tier": "T3", "furigana": "刃[は]を研[と]ぐときは、角度[かくど]を一定[いってい]に保[たも]つことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "料理人は仕事の前に、必ず包丁を研ぐ。", "target_word": "研ぐ", "complexity_tier": "T3", "furigana": "料理人[りょうりにん]は仕事[しごと]の前[まえ]に、必[かなら]ず包丁[ほうちょう]を研[と]ぐ。", "sentence_source": "generated"}, {"text": "斧を研いでおかないと、薪が割りにくい。", "target_word": "研いで", "complexity_tier": "T3", "furigana": "斧[おの]を研[と]いでおかないと、薪[まき]が割[わ]りにくい。", "sentence_source": "generated"}, {"text": "母のはさみを研いでもらうために、店に持っていった。", "target_word": "研いで", "complexity_tier": "T3", "furigana": "母[はは]のはさみを研[と]いでもらうために、店[みせ]に持[も]っていった。", "sentence_source": "generated"}, {"text": "研いだばかりの刀は、光が当たると鋭く輝いた。", "target_word": "研いだ", "complexity_tier": "T3", "furigana": "研[と]いだばかりの刀[かたな]は、光[ひかり]が当[あ]たると鋭[するど]く輝[かがや]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "研ぐ", "label": "辞書形"}, {"form": "研いで", "label": "て形"}, {"form": "研いだ", "label": "た形"}, {"form": "研ぎ", "label": "連用形"}, {"form": "研げば", "label": "仮定形"}], "register": "標準（日常語）", "sense_fingerprint": "刃物を砥石でこすって切れ味を良くする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41307, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研いで", "is_correct": true, "explanation": "正解。「砥石で研いでいる」で、砥石を道具にして包丁の切れ味を良くする動作となり、文脈に合う。"}, {"text": "焼いて", "is_correct": false, "explanation": "「砥石で焼いている」は意味が成り立たない。焼くは熱を加える動作で、刃物の手入れには当てはまらない。"}, {"text": "煮て", "is_correct": false, "explanation": "「砥石で煮ている」は不自然。煮るは液体の中で加熱する動作で、砥石とは結びつかない。"}, {"text": "冷やして", "is_correct": false, "explanation": "「砥石で冷やしている」は文脈に合わない。冷やすは温度を下げる動作で、包丁の切れ味を良くする意味を持たない。"}], "explanations": {"研いで": "正解。「砥石で研いでいる」で、砥石を道具にして包丁の切れ味を良くする動作となり、文脈に合う。", "焼いて": "「砥石で焼いている」は意味が成り立たない。焼くは熱を加える動作で、刃物の手入れには当てはまらない。", "煮て": "「砥石で煮ている」は不自然。煮るは液体の中で加熱する動作で、砥石とは結びつかない。", "冷やして": "「砥石で冷やしている」は文脈に合わない。冷やすは温度を下げる動作で、包丁の切れ味を良くする意味を持たない。"}, "sentence_index": 0, "correct_answer": "研いで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日、論文を研いでいる。", "explanation": "ここは「研究」の意味。論文を調べて考察することは「研究する」で表し、刃物の切れ味を良くする「研ぐ」は合わない。"}, {"text": "ガラスの窓を研いでピカピカにした。", "explanation": "ここは「磨く」の意味で使う場面。窓ガラスを磨いて光らせる文で、「研ぐ」は刃物など道具の切れ味を良くする語なので使わない。"}, {"text": "皿が汚れたので、研いでから重ねた。", "explanation": "ここは「洗う」の意味で使う場面。汚れを落とす文で、「研ぐ」は刃物などの切れ味・光沢を良くする語なので、皿の汚れには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41307, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研ぐ", "is_correct": true, "explanation": "正解。刃物をこすって切れ味を良くする動詞で、料理人が仕事前に包丁を手入れする文に合う。"}, {"text": "茹でる", "is_correct": false, "explanation": "「包丁を茹でる」は不自然。茹でるは水の中で加熱する動作で、刃物の手入れとは結びつかない。"}, {"text": "編む", "is_correct": false, "explanation": "「包丁を編む」は意味が成り立たない。編むは糸や紐を組み合わせる動作。"}, {"text": "凍らせる", "is_correct": false, "explanation": "「包丁を凍らせる」は手入れの動作ではなく、文脈に合わない。凍らせるは温度を下げて固める動作。"}], "explanations": {"研ぐ": "正解。刃物をこすって切れ味を良くする動詞で、料理人が仕事前に包丁を手入れする文に合う。", "茹でる": "「包丁を茹でる」は不自然。茹でるは水の中で加熱する動作で、刃物の手入れとは結びつかない。", "編む": "「包丁を編む」は意味が成り立たない。編むは糸や紐を組み合わせる動作。", "凍らせる": "「包丁を凍らせる」は手入れの動作ではなく、文脈に合わない。凍らせるは温度を下げて固める動作。"}, "sentence_index": 6, "correct_answer": "研ぐ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末は工事現場で研いで、旅行の費用にした。", "explanation": "ここは「稼ぐ」の意味で使う場面。お金を得る文で、「研ぐ」は道具の切れ味・光沢を良くする語なので収入の意味にはならない。"}, {"text": "机の角を研いで、丸くした。", "explanation": "ここは「削る」の意味で使う場面。角を取り除いて丸くする文で、「研ぐ」は道具の切れ味を良くする語なので、机の表面を削る意味はない。"}, {"text": "テーブルを研いで、きれいにした。", "explanation": "ここは「拭く」の意味で使う場面。汚れを拭き取る文で、「研ぐ」は刃物など道具の切れ味・光沢を良くする語なので、テーブルには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41307, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は包丁を研ぎて、料理を始めた。", "corrected_sentence": "母は包丁を研いで、料理を始めた。", "error_description": "「研ぐ」のて形は「研いで」（イ音便）。「研ぎて」は誤りで、連用形の「研ぎ」に「て」を付けた形は使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "研いだら", "is_correct": true, "explanation": "正解。「研いだ」に「ら」を付けた条件の形で、研いだ後によく切れるようになったという流れに合う。"}, {"text": "研ぐ", "is_correct": false, "explanation": "辞書形「研ぐ」は「ら」と続かない。「研ぐ、よく切れるようになった」では文が成り立たない。"}, {"text": "研がない", "is_correct": false, "explanation": "否定形「研がない」は切れ味が戻った流れと逆の意味になり、「ら」も続かないため文に合わない。"}, {"text": "研げ", "is_correct": false, "explanation": "命令形「研げ」は相手への命令になり、過去の経過を述べる文に合わない。"}], "correct_form": "研いだら", "base_form": "研ぐ", "form_label": "た形＋ら（条件）", "sentence_index": 1, "explanations": {"研いだら": "正解。「研いだ」に「ら」を付けた条件の形で、研いだ後によく切れるようになったという流れに合う。", "研ぐ": "辞書形「研ぐ」は「ら」と続かない。「研ぐ、よく切れるようになった」では文が成り立たない。", "研がない": "否定形「研がない」は切れ味が戻った流れと逆の意味になり、「ら」も続かないため文に合わない。", "研げ": "命令形「研げ」は相手への命令になり、過去の経過を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41307, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "包丁を研ぐば、よく切れるようになる。", "corrected_sentence": "包丁を研げば、よく切れるようになる。", "error_description": "仮定形は「研げば」。「研ぐば」は誤りで、語幹末の「ぐ」を「げ」に変えた形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "研いで", "is_correct": true, "explanation": "正解。て形で、「研いでおかないと」と続けて、前もって研いでおく意味に合う。"}, {"text": "研げば", "is_correct": false, "explanation": "仮定形「研げば」は条件の意味になり、「〜ておかないと」と続く文の形に合わない。"}, {"text": "研いだ", "is_correct": false, "explanation": "た形「研いだ」は完了の意味になり、「〜ておかないと」と続かないため文が崩れる。"}, {"text": "研いでいた", "is_correct": false, "explanation": "「研いでいた」は過去の継続を表し、「〜ておかないと」の条件文にはならない。"}], "correct_form": "研いで", "base_form": "研ぐ", "form_label": "て形", "sentence_index": 7, "explanations": {"研いで": "正解。て形で、「研いでおかないと」と続けて、前もって研いでおく意味に合う。", "研げば": "仮定形「研げば」は条件の意味になり、「〜ておかないと」と続く文の形に合わない。", "研いだ": "た形「研いだ」は完了の意味になり、「〜ておかないと」と続かないため文が崩れる。", "研いでいた": "「研いでいた」は過去の継続を表し、「〜ておかないと」の条件文にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41308, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「先輩に倣い」の形で、倣う相手を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "倣うは対象を「に」で示すため、「先輩を倣い」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す。「先輩で倣い」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す。手本を示す相手には使わないため不自然。"}], "correct_answer": "に", "explanations": {"に": "「先輩に倣い」の形で、倣う相手を示す格助詞。", "を": "倣うは対象を「に」で示すため、「先輩を倣い」は不自然。", "で": "手段や場所を表す。「先輩で倣い」は意味が通らない。", "へ": "方向を表す。手本を示す相手には使わないため不自然。"}, "error_tags": {"を": "目的語の格", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41308, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「隣の人に倣って」で、手本とする相手を示す格助詞。"}, {"text": "の", "is_correct": false, "explanation": "連体の助詞。「隣の人の倣って」は文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す。「隣の人より倣って」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を表す。手本を示す文の代わりにはならない。"}], "correct_answer": "に", "explanations": {"に": "「隣の人に倣って」で、手本とする相手を示す格助詞。", "の": "連体の助詞。「隣の人の倣って」は文として成り立たない。", "より": "比較を表す。「隣の人より倣って」は意味が通らない。", "と": "共同の相手を表す。手本を示す文の代わりにはならない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "と": "共同の相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41308, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人がすることを同じようにする。", "primary_collocate": null, "pronunciation": "ならう", "ipa": "naɾaɯ", "syllable_count": 3, "sentences": [{"text": "弟は兄に倣って、毎朝早く起きるようにした。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "弟[おとうと]は兄[あに]に倣[なら]って、毎朝[まいあさ]早[はや]く起[お]きるようにした。", "sentence_source": "generated"}, {"text": "新入社員は先輩に倣い、あいさつを大きな声でした。", "target_word": "倣い", "complexity_tier": "T3", "furigana": "新入[しんにゅう]社員[しゃいん]は先輩[せんぱい]に倣[なら]い、あいさつを大[おお]きな声[こえ]でした。", "sentence_source": "generated"}, {"text": "先生の話し方に倣って、ゆっくり説明してみた。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はな]し方[かた]に倣[なら]って、ゆっくり説明[せつめい]してみた。", "sentence_source": "generated"}, {"text": "父に倣って、わたしも庭の花に毎日水をやっている。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "父[ちち]に倣[なら]って、わたしも庭[にわ]の花[はな]に毎日[まいにち]水[みず]をやっている。", "sentence_source": "generated"}, {"text": "みんなが並ぶのを見て、私もそれに倣った。", "target_word": "倣った", "complexity_tier": "T3", "furigana": "みんなが並[なら]ぶのを見[み]て、私[わたし]もそれに倣[なら]った。", "sentence_source": "generated"}, {"text": "兄の行動に倣うのはいいが、無理はしないでね。", "target_word": "倣う", "complexity_tier": "T3", "furigana": "兄[あに]の行動[こうどう]に倣[なら]うのはいいが、無理[むり]はしないでね。", "sentence_source": "generated"}, {"text": "姉に倣ってピアノを始めたが、なかなか上手にならない。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "姉[あね]に倣[なら]ってピアノを始[はじ]めたが、なかなか上手[じょうず]にならない。", "sentence_source": "generated"}, {"text": "隣の人に倣って、くつをぬいで中に入った。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]に倣[なら]って、くつをぬいで中[なか]に入[はい]った。", "sentence_source": "generated"}, {"text": "子どもは親のすることに倣うものだ。", "target_word": "倣う", "complexity_tier": "T3", "furigana": "子[こ]どもは親[おや]のすることに倣[なら]うものだ。", "sentence_source": "generated"}, {"text": "先に帰った友だちに倣い、私も早めに席を立った。", "target_word": "倣い", "complexity_tier": "T3", "furigana": "先[さき]に帰[かえ]った友[とも]だちに倣[なら]い、私[わたし]も早[はや]めに席[せき]を立[た]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "倣う", "label": "辞書形"}, {"form": "倣って", "label": "て形"}, {"form": "倣った", "label": "た形"}, {"form": "倣い", "label": "連用形"}, {"form": "倣わない", "label": "ない形"}], "register": "標準（やや硬め）", "sense_fingerprint": "人の行動を手本にして同じようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41308, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倣って", "is_correct": true, "explanation": "「兄に倣って」で手本を示し、後の「毎朝早く起きるようにした」へ自然に続く。"}, {"text": "倣う", "is_correct": false, "explanation": "終止形のため、読点で続く文に連結できない。"}, {"text": "倣った", "is_correct": false, "explanation": "過去形で、「倣った、毎朝早く起きる」と後続の文が結びつかない。"}, {"text": "倣え", "is_correct": false, "explanation": "命令形で、後の「〜ようにした」と意味が合わない。"}], "explanations": {"倣って": "「兄に倣って」で手本を示し、後の「毎朝早く起きるようにした」へ自然に続く。", "倣う": "終止形のため、読点で続く文に連結できない。", "倣った": "過去形で、「倣った、毎朝早く起きる」と後続の文が結びつかない。", "倣え": "命令形で、後の「〜ようにした」と意味が合わない。"}, "sentence_index": 0, "correct_answer": "倣って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生の指示に倣って、教室を出た。", "explanation": "ここは〈従う〉の意味。指示には従うを使い、倣うは手本をまねる意味なので合わない。"}, {"text": "校則に倣って、髪を染めた。", "explanation": "ここは〈逆らう〉の意味。校則に対しては逆らうを使い、倣うは手本をまねる行為なのでこの文には合わない。"}, {"text": "先生にピアノを倣っている。", "explanation": "ここは〈習う〉の意味。稽古事を教わる場合は習うを使い、倣うは人の行動をまねる意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41308, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倣って", "is_correct": true, "explanation": "「姉に倣って」で手本を示し、ピアノを始めた理由として続く。"}, {"text": "倣え", "is_correct": false, "explanation": "命令形で「倣えピアノを始めた」と続かず、文が成り立たない。"}, {"text": "倣おう", "is_correct": false, "explanation": "意志形で、「始めたが」と続かず不自然になる。"}, {"text": "倣える", "is_correct": false, "explanation": "可能形で、「姉に倣えてピアノ」は意味が成り立たない。"}], "explanations": {"倣って": "「姉に倣って」で手本を示し、ピアノを始めた理由として続く。", "倣え": "命令形で「倣えピアノを始めた」と続かず、文が成り立たない。", "倣おう": "意志形で、「始めたが」と続かず不自然になる。", "倣える": "可能形で、「姉に倣えてピアノ」は意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "倣って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人混みに倣って、裏道を通った。", "explanation": "ここは〈避ける〉の意味。人混みは避けるもので、倣うは人の行動を手本にする意味なので合わない。"}, {"text": "誘いに倣って、早めに帰った。", "explanation": "ここは〈断る〉の意味。誘いは断る・受けるもので、倣うは手本をまねる意味で合わない。"}, {"text": "友だちの名前に倣い、私も席を立った。", "explanation": "ここは〈呼ぶ〉の意味。名前を呼ぶには呼ぶを使い、倣うは人の行動やのやり方を手本にする語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41308, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩を倣って、大きな声であいさつをした。", "corrected_sentence": "先輩に倣って、大きな声であいさつをした。", "error_description": "「倣う」は「〜に倣う」と「に」を取る。「を」は誤りで、「先輩に倣って」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "倣い", "is_correct": true, "explanation": "連用形。読点で文を続け、並列の動作を表す。"}, {"text": "倣う", "is_correct": false, "explanation": "終止形のため、読点の前で文が切れてしまい続かない。"}, {"text": "倣った", "is_correct": false, "explanation": "過去形のため、「、あいさつを大きな声でした」と続く形にならない。"}, {"text": "倣わない", "is_correct": false, "explanation": "否定の終止形で意味が反転し、読点で続く文に連結できない。"}], "correct_form": "倣い", "base_form": "倣う", "form_label": "連用形", "sentence_index": 1, "explanations": {"倣い": "連用形。読点で文を続け、並列の動作を表す。", "倣う": "終止形のため、読点の前で文が切れてしまい続かない。", "倣った": "過去形のため、「、あいさつを大きな声でした」と続く形にならない。", "倣わない": "否定の終止形で意味が反転し、読点で続く文に連結できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41308, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩の行動に倣う、練習を続けた。", "corrected_sentence": "先輩の行動に倣って、練習を続けた。", "error_description": "「倣う」は読点の前で連用形「倣って」にする必要がある。終止形のままでは文が続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "倣って", "is_correct": true, "explanation": "て形。「隣の人に倣って」で手本を示し、後の行動へ続く。"}, {"text": "倣います", "is_correct": false, "explanation": "丁寧形は文中の読点の前に置けず、不自然になる。"}, {"text": "倣え", "is_correct": false, "explanation": "命令形のため、「、」で続く文として成立しない。"}, {"text": "倣おう", "is_correct": false, "explanation": "意志形のため、「、くつをぬいで」と続く過去の文に連結できない。"}], "correct_form": "倣って", "base_form": "倣う", "form_label": "て形", "sentence_index": 7, "explanations": {"倣って": "て形。「隣の人に倣って」で手本を示し、後の行動へ続く。", "倣います": "丁寧形は文中の読点の前に置けず、不自然になる。", "倣え": "命令形のため、「、」で続く文として成立しない。", "倣おう": "意志形のため、「、くつをぬいで」と続く過去の文に連結できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41309, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「昔のやり方に倣えば」で、手本とする対象を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "倣うは「に」で対象を取るため、「を」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す。やり方を手本とする対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を表す。「やり方と倣えば」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「昔のやり方に倣えば」で、手本とする対象を示す格助詞。", "を": "倣うは「に」で対象を取るため、「を」は不自然。", "で": "手段を表す。やり方を手本とする対象にはならない。", "と": "共同の相手を表す。「やり方と倣えば」は不自然。"}, "error_tags": {"を": "目的語の格", "で": "手段・場所", "と": "共同の相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41309, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「彼の生き方に倣う」で、手本とする対象を示す格助詞。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、手本の対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体の助詞。「生き方の倣う若者」は文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「生き方が倣う若者」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「彼の生き方に倣う」で、手本とする対象を示す格助詞。", "より": "比較の助詞で、手本の対象を示せない。", "の": "連体の助詞。「生き方の倣う若者」は文が成り立たない。", "が": "主語を示す。「生き方が倣う若者」では意味が通らない。"}, "error_tags": {"より": "比較", "の": "連体修飾", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41309, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "他の人のやり方や考え方、行動などをまねて、同じようにすること。", "primary_collocate": null, "pronunciation": "ならう", "ipa": "naɾaɯ", "syllable_count": 3, "sentences": [{"text": "この会社は海外の成功例に倣って、新しい制度を作った。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は海外[かいがい]の成功例[せいこうれい]に倣[なら]って、新[あたら]しい制度[せいど]を作[つく]った。", "sentence_source": "generated"}, {"text": "昔のやり方に倣えば、問題はすぐに解決する。", "target_word": "倣えば", "complexity_tier": "T3", "furigana": "昔[むかし]のやり方[かた]に倣[なら]えば、問題[もんだい]はすぐに解決[かいけつ]する。", "sentence_source": "generated"}, {"text": "先人の考え方に倣い、謙虚に学び続けたい。", "target_word": "倣い", "complexity_tier": "T3", "furigana": "先人[せんじん]の考[かんが]え方[かた]に倣[なら]い、謙虚[けんきょ]に学[まな]び続[つづ]けたい。", "sentence_source": "generated"}, {"text": "前例に倣って、今年も同じ手順で式を行う。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "前例[ぜんれい]に倣[なら]って、今年[ことし]も同[おな]じ手順[てじゅん]で式[しき]を行[おこな]う。", "sentence_source": "generated"}, {"text": "町は隣の市の取り組みに倣い、ごみの分別を始めた。", "target_word": "倣い", "complexity_tier": "T3", "furigana": "町[まち]は隣[となり]の市[し]の取[と]り組[く]みに倣[なら]い、ごみの分別[ぶんべつ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "欧米の制度に倣った法律が、明治時代に作られた。", "target_word": "倣った", "complexity_tier": "T3", "furigana": "欧米[おうべい]の制度[せいど]に倣[なら]った法律[ほうりつ]が、明治[めいじ]時代[じだい]に作[つく]られた。", "sentence_source": "generated"}, {"text": "師匠の教えに倣って、毎日の稽古を欠かさない。", "target_word": "倣って", "complexity_tier": "T3", "furigana": "師匠[ししょう]の教[おし]えに倣[なら]って、毎日[まいにち]の稽古[けいこ]を欠[か]かさない。", "sentence_source": "generated"}, {"text": "彼の生き方に倣う若者が少しずつ増えている。", "target_word": "倣う", "complexity_tier": "T3", "furigana": "彼[かれ]の生[い]き方[かた]に倣[なら]う若者[わかもの]が少[すこ]しずつ増[ふ]えている。", "sentence_source": "generated"}, {"text": "他校の成功に倣い、うちの学校も朝の読書を取り入れた。", "target_word": "倣い", "complexity_tier": "T3", "furigana": "他校[たこう]の成功[せいこう]に倣[なら]い、うちの学校[がっこう]も朝[あさ]の読書[どくしょ]を取[と]り入[い]れた。", "sentence_source": "generated"}, {"text": "伝統に倣いつつ、新しい工夫も加えた。", "target_word": "倣い", "complexity_tier": "T3", "furigana": "伝統[でんとう]に倣[なら]いつつ、新[あたら]しい工夫[くふう]も加[くわ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "倣う", "label": "辞書形"}, {"form": "倣って", "label": "て形"}, {"form": "倣った", "label": "た形"}, {"form": "倣い", "label": "連用形"}, {"form": "倣えば", "label": "仮定形"}], "register": "標準（やや硬め・文章寄り）", "sense_fingerprint": "他者のやり方・考え方・前例をまねる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41309, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倣って", "is_correct": true, "explanation": "手本を示す「〜に倣って」で、新しい制度を作った理由として続く。"}, {"text": "倣う", "is_correct": false, "explanation": "終止形のため、「成功例に倣う、新しい制度を作った」と続かない。"}, {"text": "倣った", "is_correct": false, "explanation": "過去形の終止で、後の「作った」と文が結びつかない。"}, {"text": "倣え", "is_correct": false, "explanation": "命令形で、文の意味が合わない。"}], "explanations": {"倣って": "手本を示す「〜に倣って」で、新しい制度を作った理由として続く。", "倣う": "終止形のため、「成功例に倣う、新しい制度を作った」と続かない。", "倣った": "過去形の終止で、後の「作った」と文が結びつかない。", "倣え": "命令形で、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "倣って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "忠告に倣って、夜更かしした。", "explanation": "ここは〈従う〉の場面。忠告に従ったのに夜更かしするのは矛盾し、倣うは手本をまねる意味で合わない。"}, {"text": "約束に倣って、遅刻した。", "explanation": "ここは〈守る〉の場面。約束は守るもので、遅刻と組むと矛盾し、倣うは手本をまねる意味で合わない。"}, {"text": "川に倣って歩いた。", "explanation": "ここは〈沿う〉の意味。川や道に添って進むときは沿うを使い、倣うは手本をまねる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41309, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倣って", "is_correct": true, "explanation": "「師匠の教えに倣って」で手本を示し、稽古を欠かさない文に続く。"}, {"text": "倣います", "is_correct": false, "explanation": "丁寧形は文中の読点の前に置けず、不自然になる。"}, {"text": "倣おう", "is_correct": false, "explanation": "意志形のため、「欠かさない」と続かず意味が合わない。"}, {"text": "倣った", "is_correct": false, "explanation": "過去形の終止で、読点の前では文が続かず不自然になる。"}], "explanations": {"倣って": "「師匠の教えに倣って」で手本を示し、稽古を欠かさない文に続く。", "倣います": "丁寧形は文中の読点の前に置けず、不自然になる。", "倣おう": "意志形のため、「欠かさない」と続かず意味が合わない。", "倣った": "過去形の終止で、読点の前では文が続かず不自然になる。"}, "sentence_index": 6, "correct_answer": "倣って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "時計の時間に倣って、宿題を出した。", "explanation": "ここは〈合わせる〉の意味。時間には合わせるを使い、倣うは人の行動や方法を手本にする意味で合わない。"}, {"text": "提案に倣って、もとの方法を守った。", "explanation": "ここは〈従う〉の意味。提案には従うを使い、倣うは手本をまねる意味で、ここでは合わない。"}, {"text": "線路に倣いつつ、町を歩いた。", "explanation": "ここは〈沿う〉の場面。線路には沿うを使い、倣うは手本をまねる意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41309, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地域の取り組みを倣って、ごみを減らす計画を立てた。", "corrected_sentence": "地域の取り組みに倣って、ごみを減らす計画を立てた。", "error_description": "「倣う」は「〜に倣う」と「に」を取る。「を」は誤りで、「取り組みに倣って」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "倣えば", "is_correct": true, "explanation": "仮定形。「倣えば、問題は解決する」と条件を示す。"}, {"text": "倣う", "is_correct": false, "explanation": "終止形のため、読点の前で条件節が成立せず続かない。"}, {"text": "倣った", "is_correct": false, "explanation": "過去形のため、条件の意味にならず「解決する」と時制が合わない。"}, {"text": "倣え", "is_correct": false, "explanation": "命令形で、「問題はすぐに解決する」と続かない。"}], "correct_form": "倣えば", "base_form": "倣う", "form_label": "仮定形", "sentence_index": 1, "explanations": {"倣えば": "仮定形。「倣えば、問題は解決する」と条件を示す。", "倣う": "終止形のため、読点の前で条件節が成立せず続かない。", "倣った": "過去形のため、条件の意味にならず「解決する」と時制が合わない。", "倣え": "命令形で、「問題はすぐに解決する」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41309, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先人の知恵に倣う、新しい道を開いた。", "corrected_sentence": "先人の知恵に倣って、新しい道を開いた。", "error_description": "「倣う」は読点の前で連用形「倣って」にする必要がある。終止形のままでは文が続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "倣う", "is_correct": true, "explanation": "辞書形。「倣う若者」と名詞を修飾し、手本にする人々を表す。"}, {"text": "倣い", "is_correct": false, "explanation": "連用形のため、名詞「若者」を直接修飾できない。"}, {"text": "倣って", "is_correct": false, "explanation": "て形のため、名詞を修飾できず文の流れが合わない。"}, {"text": "倣わず", "is_correct": false, "explanation": "否定の連用形で、名詞を修飾できず意味も反転する。"}], "correct_form": "倣う", "base_form": "倣う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"倣う": "辞書形。「倣う若者」と名詞を修飾し、手本にする人々を表す。", "倣い": "連用形のため、名詞「若者」を直接修飾できない。", "倣って": "て形のため、名詞を修飾できず文の流れが合わない。", "倣わず": "否定の連用形で、名詞を修飾できず意味も反転する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41310, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「練習を続ける」の「を」で、続ける対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「練習が続けた」では続ける主体も目的語もなく成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「練習で続ける」は続ける対象を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「練習と続けた」では文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「練習を続ける」の「を」で、続ける対象を示す。正解。", "が": "「が」は主語を示すが、「練習が続けた」では続ける主体も目的語もなく成り立たない。", "で": "「で」は手段を示すが、「練習で続ける」は続ける対象を示せず不自然。", "と": "「と」は相手や並列を示すが、「練習と続けた」では文の意味が通らない。"}, "error_tags": {"が": "主語", "で": "手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41310, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「公園で練習した」の「で」で、練習が行われる場所を示す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「に」は存在や到達を示すが、「公園に練習した」は行為の場所を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、公園は練習の対象ではないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、練習は方向を指さないので合わない。"}], "correct_answer": "で", "explanations": {"で": "「公園で練習した」の「で」で、練習が行われる場所を示す。正解。", "に": "「に」は存在や到達を示すが、「公園に練習した」は行為の場所を表せない。", "を": "「を」は動作の対象を示すが、公園は練習の対象ではないので合わない。", "へ": "「へ」は方向を示すが、練習は方向を指さないので合わない。"}, "error_tags": {"に": "存在・到達", "を": "対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41310, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何度も同じことをやって、うまくできるようになること。", "primary_collocate": null, "pronunciation": "れんしゅう", "ipa": "ɾeɴɕɯː", "syllable_count": 4, "sentences": [{"text": "毎日三十分、ピアノの練習をしています。", "target_word": "練習", "complexity_tier": "T3", "furigana": "毎日[まいにち]三十分[さんじゅっぷん]、ピアノの練習[れんしゅう]をしています。", "sentence_source": "generated"}, {"text": "試合に勝ちたいので、放課後も練習を続けた。", "target_word": "練習", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]ちたいので、放課後[ほうかご]も練習[れんしゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "九九を覚えるまで、何度も練習した。", "target_word": "練習", "complexity_tier": "T3", "furigana": "九九[くく]を覚[おぼ]えるまで、何度[なんど]も練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "兄は自転車に乗る練習を手伝ってくれた。", "target_word": "練習", "complexity_tier": "T3", "furigana": "兄[あに]は自転車[じてんしゃ]に乗[の]る練習[れんしゅう]を手伝[てつだ]ってくれた。", "sentence_source": "generated"}, {"text": "発表の前に、家族の前で練習してみた。", "target_word": "練習", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の前[まえ]に、家族[かぞく]の前[まえ]で練習[れんしゅう]してみた。", "sentence_source": "generated"}, {"text": "練習をしないと、上手にならない。", "target_word": "練習", "complexity_tier": "T3", "furigana": "練習[れんしゅう]をしないと、上手[じょうず]にならない。", "sentence_source": "generated"}, {"text": "先生に漢字の練習を毎晩するように言われた。", "target_word": "練習", "complexity_tier": "T3", "furigana": "先生[せんせい]に漢字[かんじ]の練習[れんしゅう]を毎晩[まいばん]するように言[い]われた。", "sentence_source": "generated"}, {"text": "逆上がりができるまで、毎日公園で練習した。", "target_word": "練習", "complexity_tier": "T3", "furigana": "逆上[さかあ]がりができるまで、毎日[まいにち]公園[こうえん]で練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "今日は雨なので、サッカーの練習は休みです。", "target_word": "練習", "complexity_tier": "T3", "furigana": "今日[きょう]は雨[あめ]なので、サッカーの練習[れんしゅう]は休[やす]みです。", "sentence_source": "generated"}, {"text": "練習すれば、泳げるようになるよ。", "target_word": "練習", "complexity_tier": "T3", "furigana": "練習[れんしゅう]すれば、泳[およ]げるようになるよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "練習する", "label": "基本形"}, {"form": "練習した", "label": "過去形"}, {"form": "練習して", "label": "テ形"}], "register": "標準", "sense_fingerprint": "何度も繰り返してうまくなろうとすること（身近な基本義）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41310, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "練習", "is_correct": true, "explanation": "「ピアノの練習をしています」で、繰り返し弾いて上達を目指す意味。正解。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は文章を別の言語に移す行為で、ピアノの活動には合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行は各地を回ることで、ピアノを対象にして「をしている」とは言えない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は衣類などを洗う家事で、楽器の活動には使えない。"}], "explanations": {"練習": "「ピアノの練習をしています」で、繰り返し弾いて上達を目指す意味。正解。", "翻訳": "翻訳は文章を別の言語に移す行為で、ピアノの活動には合わない。", "旅行": "旅行は各地を回ることで、ピアノを対象にして「をしている」とは言えない。", "洗濯": "洗濯は衣類などを洗う家事で、楽器の活動には使えない。"}, "sentence_index": 0, "correct_answer": "練習"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "提出する前に、書類の日付をもう一度練習した。", "explanation": "ここは〈確認〉の意味。練習は同じ動作を繰り返して上達させることで、日付を見直す行為には使わない。"}, {"text": "エンジンの調子を、整備士に練習してもらった。", "explanation": "ここは〈調整〉の意味。練習は本人が上達のために行うことで、機械の状態を整える意味では使わない。"}, {"text": "研究員は、顕微鏡で細胞の変化を練習した。", "explanation": "ここは〈観察〉の意味。練習は技能を身につける行為で、細胞の変化を見て記録する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41310, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "練習", "is_correct": true, "explanation": "「漢字の練習を毎晩する」で、書いて覚えるための繰り返しを指す。正解。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作る行為で、漢字の学習には使えない。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は場所をきれいにすることで、漢字を対象にはしない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は外を歩いて回ることで、漢字には使えない。"}], "explanations": {"練習": "「漢字の練習を毎晩する」で、書いて覚えるための繰り返しを指す。正解。", "料理": "料理は食べ物を作る行為で、漢字の学習には使えない。", "掃除": "掃除は場所をきれいにすることで、漢字を対象にはしない。", "散歩": "散歩は外を歩いて回ることで、漢字には使えない。"}, "sentence_index": 6, "correct_answer": "練習"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は答案を一枚ずつ練習した。", "explanation": "ここは〈採点〉の意味。練習は上達のための繰り返しで、答案に点数をつける意味では使わない。"}, {"text": "新型の車は、発売前に長い距離を練習した。", "explanation": "ここは〈試運転〉の意味。練習は人が上達を目指す行為で、車の性能を確かめる走行には使わない。"}, {"text": "アンケートの回答を練習して、結果をまとめた。", "explanation": "ここは〈集計〉の意味。練習は技能を高める繰り返しで、回答を数え上げる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41310, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日一時間、ピアノに練習をしている。", "corrected_sentence": "毎日一時間、ピアノの練習をしている。", "error_description": "「ピアノの練習」は「の」で名詞をつなぐ形が正しい。「に」は場所や相手を表すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
