INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41311, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「英会話の練習」の「の」で、練習の内容を名詞でつなぐ。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「英会話が練習を続けた」では動作の主体が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、英会話と練習の関係を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示すが、「英会話に練習」では成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「英会話の練習」の「の」で、練習の内容を名詞でつなぐ。正解。", "が": "「が」は主語を示すが、「英会話が練習を続けた」では動作の主体が合わない。", "へ": "「へ」は方向を示すが、英会話と練習の関係を表せない。", "に": "「に」は到達点や相手を示すが、「英会話に練習」では成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "に": "到達・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
