INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41311, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "技術や芸能などを、上達するために繰り返し行うこと。", "primary_collocate": null, "pronunciation": "れんしゅう", "ipa": "ɾeɴɕɯː", "syllable_count": 4, "sentences": [{"text": "楽団は来月の演奏会に向けて、週に四回練習している。", "target_word": "練習", "complexity_tier": "T4", "furigana": "楽団[がくだん]は来月[らいげつ]の演奏会[えんそうかい]に向[む]けて、週[しゅう]に四回[よんかい]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "英会話の練習を続けた結果、旅行先で困らなくなった。", "target_word": "練習", "complexity_tier": "T4", "furigana": "英会話[えいかいわ]の練習[れんしゅう]を続[つづ]けた結果[けっか]、旅行先[りょこうさき]で困[こま]らなくなった。", "sentence_source": "generated"}, {"text": "書道の練習は、基本の線を繰り返し書くことから始まる。", "target_word": "練習", "complexity_tier": "T4", "furigana": "書道[しょどう]の練習[れんしゅう]は、基本[きほん]の線[せん]を繰[く]り返[かえ]し書[か]くことから始[はじ]まる。", "sentence_source": "generated"}, {"text": "彼は毎朝ランニングで体力をつけ、夜はフォームの練習に時間を使う。", "target_word": "練習", "complexity_tier": "T4", "furigana": "彼[かれ]は毎朝[まいあさ]ランニングで体力[たいりょく]をつけ、夜[よる]はフォームの練習[れんしゅう]に時間[じかん]を使[つか]う。", "sentence_source": "generated"}, {"text": "面接の練習を何度もしたので、本番では落ち着いて話せた。", "target_word": "練習", "complexity_tier": "T4", "furigana": "面接[めんせつ]の練習[れんしゅう]を何度[なんど]もしたので、本番[ほんばん]では落[お]ち着[つ]いて話[はな]せた。", "sentence_source": "generated"}, {"text": "練習の成果が出て、ようやく曲を最後まで弾けるようになった。", "target_word": "練習", "complexity_tier": "T4", "furigana": "練習[れんしゅう]の成果[せいか]が出[で]て、ようやく曲[きょく]を最後[さいご]まで弾[ひ]けるようになった。", "sentence_source": "generated"}, {"text": "劇団員たちは、稽古場で台詞回しを練習していた。", "target_word": "練習", "complexity_tier": "T4", "furigana": "劇団員[げきだんいん]たちは、稽古場[けいこば]で台詞回[せりふまわ]しを練習[れんしゅう]していた。", "sentence_source": "generated"}, {"text": "十分な練習を積まずに大会に出るのは危険だ。", "target_word": "練習", "complexity_tier": "T4", "furigana": "十分[じゅうぶん]な練習[れんしゅう]を積[つ]まずに大会[たいかい]に出[で]るのは危険[きけん]だ。", "sentence_source": "generated"}, {"text": "料理の腕を上げるには、同じ料理を繰り返し練習するのがよい。", "target_word": "練習", "complexity_tier": "T4", "furigana": "料理[りょうり]の腕[うで]を上[あ]げるには、同[おな]じ料理[りょうり]を繰[く]り返[かえ]し練習[れんしゅう]するのがよい。", "sentence_source": "generated"}, {"text": "彼女は発音の練習のために、毎日ニュースを声に出して読んでいる。", "target_word": "練習", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は発音[はつおん]の練習[れんしゅう]のために、毎日[まいにち]ニュースを声[こえ]に出[だ]して読[よ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "練習する", "label": "基本形"}, {"form": "練習した", "label": "過去形"}, {"form": "練習して", "label": "テ形"}], "register": "標準", "sense_fingerprint": "技術や芸能の上達のために繰り返し行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 台詞回し (Zipf 2.3)']::text[], '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41311, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "練習", "is_correct": true, "explanation": "「週に四回練習している」で、演奏に向けて技術を繰り返し磨く意味。正解。"}, {"text": "沸騰", "is_correct": false, "explanation": "沸騰は液体が煮えたつ現象で、楽団の活動には使えない。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は雇用を打ち切ることで、週ごとの繰り返しを表す文脈に合わない。"}, {"text": "膨張", "is_correct": false, "explanation": "膨張は体積が大きくなる現象で、人の活動には使えない。"}], "explanations": {"練習": "「週に四回練習している」で、演奏に向けて技術を繰り返し磨く意味。正解。", "沸騰": "沸騰は液体が煮えたつ現象で、楽団の活動には使えない。", "解雇": "解雇は雇用を打ち切ることで、週ごとの繰り返しを表す文脈に合わない。", "膨張": "膨張は体積が大きくなる現象で、人の活動には使えない。"}, "sentence_index": 0, "correct_answer": "練習"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人は三か月の練習の後に、経費を一円ずつ精算した。", "explanation": "ここは〈精算〉の意味。練習は技能を身につける繰り返しで、金額を計算して清算する意味では使わない。"}, {"text": "コーチは選手の技術を丁寧に練習した。", "explanation": "ここは〈指導〉の意味。練習は本人が繰り返す行為で、選手に教える意味では使わない。"}, {"text": "新しい案を練習してから、決定する。", "explanation": "ここは〈検討〉の意味。練習は技能を身につける繰り返しで、案を考え比べる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41311, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "練習", "is_correct": true, "explanation": "「台詞回しを練習していた」で、稽古の中で繰り返し技術を磨く意味。正解。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は場所をきれいにすることで、台詞回しを対象にはしない。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は設備などを取り除くことで、台詞回しには使えない。"}, {"text": "注射", "is_correct": false, "explanation": "注射は薬などを体に入れることで、台詞回しには合わない。"}], "explanations": {"練習": "「台詞回しを練習していた」で、稽古の中で繰り返し技術を磨く意味。正解。", "掃除": "掃除は場所をきれいにすることで、台詞回しを対象にはしない。", "撤去": "撤去は設備などを取り除くことで、台詞回しには使えない。", "注射": "注射は薬などを体に入れることで、台詞回しには合わない。"}, "sentence_index": 6, "correct_answer": "練習"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新商品を全国の店で練習した。", "explanation": "ここは〈販売〉の意味。練習は技能を高める行為で、商品を売る意味では使わない。"}, {"text": "体温を一日三回練習する。", "explanation": "ここは〈測定〉の意味。練習は繰り返して上達させる行為で、数値を量る意味では使わない。"}, {"text": "お客様に新しいチラシを練習した。", "explanation": "ここは〈配る〉の意味。練習は上達のための繰り返しで、チラシを手渡して回る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41311, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "楽団は来月の演奏会に向けて、毎週土曜に練習にしている。", "corrected_sentence": "楽団は来月の演奏会に向けて、毎週土曜に練習をしている。", "error_description": "「練習」の後には動作の対象を示す「を」を置く。「に」は誤りで、「練習をしている」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41311, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は十分な練習を積むずに大会に出た。", "corrected_sentence": "彼は十分な練習を積まずに大会に出た。", "error_description": "「練習を積む」の否定形は「積まず」。「積むず」は活用の誤りで、「積まずに」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41313, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「熟練の職人」と、熟練が職人を修飾する名詞連結を作る「の」。"}, {"text": "が", "is_correct": false, "explanation": "「熟練が職人は」では熟練が主語になれず、文の構造が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「熟練を職人」は目的語にならず、名詞同士をつなげられない。"}, {"text": "で", "is_correct": false, "explanation": "「熟練で職人」は手段の意味にならず、職人を修飾する形にもならない。"}], "correct_answer": "の", "explanations": {"の": "「熟練の職人」と、熟練が職人を修飾する名詞連結を作る「の」。", "が": "「熟練が職人は」では熟練が主語になれず、文の構造が成り立たない。", "を": "「熟練を職人」は目的語にならず、名詞同士をつなげられない。", "で": "「熟練で職人」は手段の意味にならず、職人を修飾する形にもならない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未熟", "is_correct": true, "explanation": "「熟練」の対義語。技能が身についていない様子で、「新人には任せられない」に合う。"}, {"text": "練習", "is_correct": false, "explanation": "練習は技能を身につける過程で、熟練の対義語ではない。"}, {"text": "経験", "is_correct": false, "explanation": "経験は積み重ねた事柄を指し、熟練の反対語ではない。"}, {"text": "技術", "is_correct": false, "explanation": "技術は技の仕組みや方法を指し、熟練の対義語ではない。"}], "correct_answer": "未熟", "explanations": {"未熟": "「熟練」の対義語。技能が身についていない様子で、「新人には任せられない」に合う。", "練習": "練習は技能を身につける過程で、熟練の対義語ではない。", "経験": "経験は積み重ねた事柄を指し、熟練の反対語ではない。", "技術": "技術は技の仕組みや方法を指し、熟練の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41313, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未熟", "is_correct": true, "explanation": "「熟練」の対義語。技が未熟な様子で、「丁寧に仕上げる」職人と対比する語として合う。"}, {"text": "修業", "is_correct": false, "explanation": "修業は技を学ぶ過程で、熟練の対義語ではない。"}, {"text": "習得", "is_correct": false, "explanation": "習得は身につけることを指し、熟練の反対語ではない。"}, {"text": "手際", "is_correct": false, "explanation": "手際は作業の仕方の良さを指し、熟練の対義語ではない。"}], "correct_answer": "未熟", "explanations": {"未熟": "「熟練」の対義語。技が未熟な様子で、「丁寧に仕上げる」職人と対比する語として合う。", "修業": "修業は技を学ぶ過程で、熟練の対義語ではない。", "習得": "習得は身につけることを指し、熟練の反対語ではない。", "手際": "手際は作業の仕方の良さを指し、熟練の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41313, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "技術や技能が十分に身についていて、巧みにこなせること。", "primary_collocate": null, "pronunciation": "じゅくれん", "ipa": "dʑɯkɯɾeɴ", "syllable_count": 4, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "熟練", "complexity_tier": "T5", "furigana": "熟練(じゅくれん)したソムリエは、グラス内(ない)で展開(てんかい)される鉱物的(こうぶつてき)な輪郭(りんかく)や土壌(どじょう)由来(ゆらい)の複雑(ふくざつ)な香気(こうき)構造(こうぞう)を解読(かいどく)し、視覚(しかく)や嗅覚(きゅうかく)を超(こ)えた土地的(とちてき)コンテキストを味覚的(みかくてき)に再構成(さいこうせい)する。", "sentence_source": "mined"}, {"text": "熟練の職人は、機械では出せない薄さに木を削ることができる。", "target_word": "熟練", "complexity_tier": "T3", "furigana": "熟練(じゅくれん)の職人(しょくにん)は、機械(きかい)では出(だ)せない薄(うす)さに木(き)を削(けず)ることができる。", "sentence_source": "generated"}, {"text": "熟練した運転手のおかげで、雪道でも安全に着いた。", "target_word": "熟練", "complexity_tier": "T3", "furigana": "熟練(じゅくれん)した運転手(うんてんしゅ)のおかげで、雪道(ゆきみち)でも安全(あんぜん)に着(つ)いた。", "sentence_source": "generated"}, {"text": "この仕事には熟練が必要なので、新人には任せられない。", "target_word": "熟練", "complexity_tier": "T3", "furigana": "この仕事(しごと)には熟練(じゅくれん)が必要(ひつよう)なので、新人(しんじん)には任(まか)せられない。", "sentence_source": "generated"}, {"text": "彼女は熟練した手つきで、あっという間に魚をさばいた。", "target_word": "熟練", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は熟練(じゅくれん)した手(て)つきで、あっという間(ま)に魚(さかな)をさばいた。", "sentence_source": "generated"}, {"text": "熟練していない人が溶接すると、強度が足りなくなる。", "target_word": "熟練", "complexity_tier": "T4", "furigana": "熟練(じゅくれん)していない人(ひと)が溶接(ようせつ)すると、強度(きょうど)が足(た)りなくなる。", "sentence_source": "generated"}, {"text": "長年の経験で熟練の域に達し、父は図面なしで家具を作る。", "target_word": "熟練", "complexity_tier": "T4", "furigana": "長年(ながねん)の経験(けいけん)で熟練(じゅくれん)の域(いき)に達(たっ)し、父(ちち)は図面(ずめん)なしで家具(かぐ)を作(つく)る。", "sentence_source": "generated"}, {"text": "熟練した医師は、画像を見ただけで病気の場所を見つけた。", "target_word": "熟練", "complexity_tier": "T3", "furigana": "熟練(じゅくれん)した医師(いし)は、画像(がぞう)を見(み)ただけで病気(びょうき)の場所(ばしょ)を見(み)つけた。", "sentence_source": "generated"}, {"text": "熟練した職人が減ったため、会社は若手に技術を教える仕組みを作った。", "target_word": "熟練", "complexity_tier": "T4", "furigana": "熟練(じゅくれん)した職人(しょくにん)が減(へ)ったため、会社(かいしゃ)は若手(わかて)に技術(ぎじゅつ)を教(おし)える仕組(しく)みを作(つく)った。", "sentence_source": "generated"}, {"text": "この店の職人は、熟練の技で一枚ずつ丁寧に革靴を仕上げる。", "target_word": "熟練", "complexity_tier": "T4", "furigana": "この店(みせ)の職人(しょくにん)は、熟練(じゅくれん)の技(わざ)で一枚(いちまい)ずつ丁寧(ていねい)に革靴(かわぐつ)を仕上(しあ)げる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟練する", "label": "辞書形"}, {"form": "熟練した", "label": "過去形・連体形"}, {"form": "熟練して", "label": "て形"}, {"form": "熟練の", "label": "名詞＋の"}], "register": "neutral", "sense_fingerprint": "経験を積んで技術・技能が十分に身につき、巧みにこなせること（サ変名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): ソムリエ (Zipf 3.22), 輪郭 (Zipf 3.38), 香気 (Zipf 2.11), 嗅覚 (Zipf 3.32), コンテキスト (Zipf 2.7)']::text[], '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41313, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熟練", "is_correct": true, "explanation": "「熟練した」で、技能が十分に身につき巧みなソムリエを表し、文の意味に合う。"}, {"text": "香気", "is_correct": false, "explanation": "香気は香りを表す名詞で、「香気したソムリエ」とは続かないので空所に入らない。"}, {"text": "輪郭", "is_correct": false, "explanation": "輪郭は形の外側の線を指す名詞で、「輪郭したソムリエ」とはならない。"}, {"text": "土壌", "is_correct": false, "explanation": "土壌は地面の土を指す名詞で、「土壌したソムリエ」は成り立たない。"}], "explanations": {"熟練": "「熟練した」で、技能が十分に身につき巧みなソムリエを表し、文の意味に合う。", "香気": "香気は香りを表す名詞で、「香気したソムリエ」とは続かないので空所に入らない。", "輪郭": "輪郭は形の外側の線を指す名詞で、「輪郭したソムリエ」とはならない。", "土壌": "土壌は地面の土を指す名詞で、「土壌したソムリエ」は成り立たない。"}, "sentence_index": 0, "correct_answer": "熟練"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このワインは三年かけて熟練させた。", "explanation": "ここは〈熟成〉の意味。熟練は人の技能に使う言葉で、寝かせて味を深めるワインには使わない。"}, {"text": "二日間熟練して、結論を出した。", "explanation": "ここは〈熟慮〉の意味。熟練は技能が身につくことで、考え抜く意味にはならない。"}, {"text": "トマトは畑で熟練して、真っ赤になった。", "explanation": "ここは〈完熟〉の意味。熟練は果物の熟し具合には使わず、人の技能に限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41313, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熟練", "is_correct": true, "explanation": "「熟練の域」は技能が十分に身についた段階を表し、「長年の経験で」の文脈に合う。"}, {"text": "図面", "is_correct": false, "explanation": "図面は設計を描いた紙で、「図面の域に達し」とは言えない。"}, {"text": "家具", "is_correct": false, "explanation": "家具は完成品の道具で、「家具の域に達し」は意味をなさない。"}, {"text": "木材", "is_correct": false, "explanation": "木材は加工する材料で、「木材の域」という段階表現にはならない。"}], "explanations": {"熟練": "「熟練の域」は技能が十分に身についた段階を表し、「長年の経験で」の文脈に合う。", "図面": "図面は設計を描いた紙で、「図面の域に達し」とは言えない。", "家具": "家具は完成品の道具で、「家具の域に達し」は意味をなさない。", "木材": "木材は加工する材料で、「木材の域」という段階表現にはならない。"}, "sentence_index": 6, "correct_answer": "熟練"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの熟練の夫婦は、いつも二人で散歩している。", "explanation": "ここは〈熟年〉（中高年）の意味。熟練は技能の習熟を指すので、夫婦の年代には使わない。"}, {"text": "じっくり熟練して、引っ越し先を決めた。", "explanation": "ここは〈熟考〉の意味。熟練は技能に関して使い、よく考えることには使わない。"}, {"text": "梅の実が熟練すると、香りが強くなる。", "explanation": "ここは〈熟す〉の意味。熟練は人の技能に使い、果実が実る変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41313, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は熟練を手つきで、木製の箱を組み立てた。", "corrected_sentence": "父は熟練の手つきで、木製の箱を組み立てた。", "error_description": "「熟練」が名詞を修飾するときは「の」で続ける（熟練の手つき）。「を」は目的語を示すので、「熟練を手つき」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41313, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩は熟練されて、細かい刺繍を縫えるようになった。", "corrected_sentence": "先輩は熟練して、細かい刺繍を縫えるようになった。", "error_description": "「熟練する」は自分で習熟していく意味の動詞で、受身の「される」は付かない。正しくは連用形の「熟練して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41314, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「パンを焼く」の目的語を示す。焼く対象として自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すが、「パンで焼く」とは言わない。"}, {"text": "に", "is_correct": false, "explanation": "方向を示すが、焼く対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「パンから焼く」では文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「パンを焼く」の目的語を示す。焼く対象として自然。", "で": "手段を示すが、「パンで焼く」とは言わない。", "に": "方向を示すが、焼く対象にはならない。", "から": "起点を示すが、「パンから焼く」では文の意味が通らない。"}, "error_tags": {"で": "手段", "に": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41314, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「二枚のパンに野菜をはさむ」と、挟む先を示す。"}, {"text": "は", "is_correct": false, "explanation": "連体修飾の中では主語に「は」を使えず、「パンは野菜をはさんだ」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、目的語が二つになり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、挟む先としては不自然。"}], "correct_answer": "に", "explanations": {"に": "「二枚のパンに野菜をはさむ」と、挟む先を示す。", "は": "連体修飾の中では主語に「は」を使えず、「パンは野菜をはさんだ」は成り立たない。", "を": "目的語を示すが、目的語が二つになり文が成り立たない。", "へ": "方向を示すが、挟む先としては不自然。"}, "error_tags": {"は": "関係節の主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41314, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たべもののなまえです。こむぎこをこねてやいてつくります。", "primary_collocate": null, "pronunciation": "ぱん", "ipa": "paɴ", "syllable_count": 2, "sentences": [{"text": "毎朝、パンとコーヒーで朝ごはんにします。", "target_word": "パン", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、パンとコーヒーで朝[あさ]ごはんにします。", "sentence_source": "generated"}, {"text": "近所のお店では、朝早くからパンをやいています。", "target_word": "パン", "complexity_tier": "T3", "furigana": "近所[きんじょ]のお店[みせ]では、朝早[あさはや]くからパンをやいています。", "sentence_source": "generated"}, {"text": "このパンはやわらかくて、バターがよく合います。", "target_word": "パン", "complexity_tier": "T3", "furigana": "このパンはやわらかくて、バターがよく合[あ]います。", "sentence_source": "generated"}, {"text": "パンを作るには、小麦粉と水とイーストが必要です。", "target_word": "パン", "complexity_tier": "T3", "furigana": "パンを作[つく]るには、小麦粉[こむぎこ]と水[みず]とイーストが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "昨日買ったパンがかたくなったので、トーストにしました。", "target_word": "パン", "complexity_tier": "T3", "furigana": "昨日[きのう]買[か]ったパンがかたくなったので、トーストにしました。", "sentence_source": "generated"}, {"text": "公園でパンをちぎって、鳥にあげました。", "target_word": "パン", "complexity_tier": "T3", "furigana": "公園[こうえん]でパンをちぎって、鳥[とり]にあげました。", "sentence_source": "generated"}, {"text": "母は休みの日に、家でパンをこねます。", "target_word": "パン", "complexity_tier": "T3", "furigana": "母[はは]は休[やす]みの日[ひ]に、家[いえ]でパンをこねます。", "sentence_source": "generated"}, {"text": "サンドイッチは、二枚のパンに野菜をはさんだ食べ物です。", "target_word": "パン", "complexity_tier": "T3", "furigana": "サンドイッチは、二枚[にまい]のパンに野菜[やさい]をはさんだ食[た]べ物[もの]です。", "sentence_source": "generated"}, {"text": "パンが焼ける、いいにおいがします。", "target_word": "パン", "complexity_tier": "T3", "furigana": "パンが焼[や]ける、いいにおいがします。", "sentence_source": "generated"}, {"text": "私はごはんよりパンが好きなので、朝はいつもパンを食べます。", "target_word": "パン", "complexity_tier": "T3", "furigana": "私[わたし]はごはんよりパンが好[す]きなので、朝[あさ]はいつもパンを食[た]べます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "小麦粉をこねて焼いて作る食べ物（食べ物のパン）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41314, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パン", "is_correct": true, "explanation": "コーヒーと一緒に朝ごはんにする食べ物として、この文に自然に入る。"}, {"text": "ドライバー", "is_correct": false, "explanation": "ねじを回す工具で、朝ごはんの材料にならない。"}, {"text": "ホッチキス", "is_correct": false, "explanation": "紙をとめる文具で、食べ物として文に合わない。"}, {"text": "ブラシ", "is_correct": false, "explanation": "髪をとかしたり掃除したりする道具で、食べ物ではない。"}], "explanations": {"パン": "コーヒーと一緒に朝ごはんにする食べ物として、この文に自然に入る。", "ドライバー": "ねじを回す工具で、朝ごはんの材料にならない。", "ホッチキス": "紙をとめる文具で、食べ物として文に合わない。", "ブラシ": "髪をとかしたり掃除したりする道具で、食べ物ではない。"}, "sentence_index": 0, "correct_answer": "パン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お正月に、パンを臼でついて、おやつを作ります。", "explanation": "ここは〈餅〉と取り違えた例。臼でつくのは餅で、パンは臼でつく食べ物ではない。"}, {"text": "パンをふるって、ボウルに入れます。", "explanation": "ここは〈小麦粉〉と取り違えた例。パンは焼いた食べ物なので、ふるう粉の代わりには使わない。"}, {"text": "パンは一晩水にひたしてから炊きます。", "explanation": "ここは〈米〉と取り違えた例。炊くのは米で、焼いて作るパンには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41314, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パン", "is_correct": true, "explanation": "家でこねて作る材料として、この文の目的語に自然に入る。"}, {"text": "ハンマー", "is_correct": false, "explanation": "金づちの一種の工具で、こねる対象にならない。"}, {"text": "座布団", "is_correct": false, "explanation": "座るための布製品で、こねる対象にならない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除をする家電で、こねる対象ではない。"}], "explanations": {"パン": "家でこねて作る材料として、この文の目的語に自然に入る。", "ハンマー": "金づちの一種の工具で、こねる対象にならない。", "座布団": "座るための布製品で、こねる対象にならない。", "掃除機": "掃除をする家電で、こねる対象ではない。"}, "sentence_index": 6, "correct_answer": "パン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "たっぷりのお湯で、パンを三分ゆでてから食べます。", "explanation": "ここは〈麺〉と取り違えた例。ゆでてから食べるのは麺で、パンはゆでて食べる食べ物ではない。"}, {"text": "パンを縫って、小さなバッグを作りました。", "explanation": "ここは〈布〉と取り違えた例。縫うのは布で、焼いたパンは縫えない。"}, {"text": "パンを削って、テストに備えました。", "explanation": "ここは〈鉛筆〉と取り違えた例。削るのは鉛筆などの硬い物で、パンには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41314, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は毎朝パンが食べています。", "corrected_sentence": "妹は毎朝パンを食べています。", "error_description": "「食べる」は目的語を「を」で示す。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41314, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉はパンに焼きました。", "corrected_sentence": "姉はパンを焼きました。", "error_description": "「焼く」は目的語を「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
