INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41317, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "action", "definition": "物を作ること。特に、機械や手を使って、材料から新しい品物を作り出すこと。", "primary_collocate": null, "pronunciation": "せい", "ipa": "seː", "syllable_count": 2, "sentences": [{"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "製", "complexity_tier": "T4", "furigana": "天然酵母[てんねんこうぼ]を用[もち]いた製[せい]パンは、職人[しょくにん]の緻密[ちみつ]な管理[かんり]が不可欠[ふかけつ]な工程[こうてい]です。", "sentence_source": "mined"}, {"text": "祖父は長年、製紙の工場で働いてきました。", "target_word": "製", "complexity_tier": "T3", "furigana": "祖父[そふ]は長年[ながねん]、製紙[せいし]の工場[こうじょう]で働[はたら]いてきました。", "sentence_source": "generated"}, {"text": "この町は昔から製茶がさかんで、春になると茶摘みでにぎわう。", "target_word": "製", "complexity_tier": "T3", "furigana": "この町[まち]は昔[むかし]から製茶[せいちゃ]がさかんで、春[はる]になると茶摘[ちゃつ]みでにぎわう。", "sentence_source": "generated"}, {"text": "製鉄には大量の石炭と高い熱が必要だ。", "target_word": "製", "complexity_tier": "T3", "furigana": "製鉄[せいてつ]には大量[たいりょう]の石炭[せきたん]と高[たか]い熱[ねつ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "製菓の学校で、ケーキの作り方を学んでいます。", "target_word": "製", "complexity_tier": "T3", "furigana": "製菓[せいか]の学校[がっこう]で、ケーキの作[つく]り方[かた]を学[まな]んでいます。", "sentence_source": "generated"}, {"text": "製麺の工場では、毎朝早くからうどんを作っている。", "target_word": "製", "complexity_tier": "T3", "furigana": "製麺[せいめん]の工場[こうじょう]では、毎朝[まいあさ]早[はや]くからうどんを作[つく]っている。", "sentence_source": "generated"}, {"text": "製糸業は、明治時代の日本の経済を支えた。", "target_word": "製", "complexity_tier": "T3", "furigana": "製糸業[せいしぎょう]は、明治時代[めいじじだい]の日本[にほん]の経済[けいざい]を支[ささ]えた。", "sentence_source": "generated"}, {"text": "彼は製パンの仕事を始めて、五年になります。", "target_word": "製", "complexity_tier": "T3", "furigana": "彼[かれ]は製[せい]パンの仕事[しごと]を始[はじ]めて、五年[ごねん]になります。", "sentence_source": "generated"}, {"text": "製塩の歴史を調べると、海水から塩を作る方法がよく分かる。", "target_word": "製", "complexity_tier": "T3", "furigana": "製塩[せいえん]の歴史[れきし]を調[しら]べると、海水[かいすい]から塩[しお]を作[つく]る方法[ほうほう]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "この製薬会社は、新しい薬を作る研究に力を入れている。", "target_word": "製", "complexity_tier": "T3", "furigana": "この製薬[せいやく]会社[がいしゃ]は、新[あたら]しい薬[くすり]を作[つく]る研究[けんきゅう]に力[ちから]を入[い]れている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "製", "label": "基本形"}], "register": "標準（書き言葉）", "sense_fingerprint": "製パン・製紙・製鉄など、材料から物を作る意味で複合語の前に付く「製」（せい）。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: にぎわう (Zipf 2.48)']::text[], 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41317, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "製", "is_correct": true, "explanation": "材料から製品を作る意味の接頭辞として「製パン」になる正解。"}, {"text": "冷", "is_correct": false, "explanation": "「冷パン」は製品を作る意味の語として成立せず、接頭辞として合わない。"}, {"text": "病", "is_correct": false, "explanation": "「病パン」は意味が通らず、製品の名称の位置には入らない。"}, {"text": "画", "is_correct": false, "explanation": "「画パン」は作る意味を持つ語にならず、製の位置には合わない。"}], "explanations": {"製": "材料から製品を作る意味の接頭辞として「製パン」になる正解。", "冷": "「冷パン」は製品を作る意味の語として成立せず、接頭辞として合わない。", "病": "「病パン」は意味が通らず、製品の名称の位置には入らない。", "画": "「画パン」は作る意味を持つ語にならず、製の位置には合わない。"}, "sentence_index": 0, "correct_answer": "製"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昔話を製して、子どもたちを笑わせた。", "explanation": "ここは〈語る〉の意味。製は材料から品物を作り出す意味で、話を語る意味には使わないので合わない。"}, {"text": "この旅館は、落ち着いた雰囲気を製して、客をもてなしている。", "explanation": "ここは〈演出する〉の意味。製は材料から品物を作り出す意味で、雰囲気を作り出す意味には使わないので合わない。"}, {"text": "この店は、季節の花を製して、店先に飾っている。", "explanation": "製は材料から製品を作り出す意味で、植物を育てて咲かせる意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41317, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "製", "is_correct": true, "explanation": "「製糸業」の接頭辞として正しく、糸を作る産業を表す。"}, {"text": "猫", "is_correct": false, "explanation": "「猫糸業」は意味が通らず、産業名の接頭辞として合わない。"}, {"text": "夢", "is_correct": false, "explanation": "「夢糸業」は意味が通らず、産業名の接頭辞として合わない。"}, {"text": "氷", "is_correct": false, "explanation": "「氷糸業」は意味が通らず、糸の産業名として合わない。"}], "explanations": {"製": "「製糸業」の接頭辞として正しく、糸を作る産業を表す。", "猫": "「猫糸業」は意味が通らず、産業名の接頭辞として合わない。", "夢": "「夢糸業」は意味が通らず、産業名の接頭辞として合わない。", "氷": "「氷糸業」は意味が通らず、糸の産業名として合わない。"}, "sentence_index": 6, "correct_answer": "製"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は新しい報告書を製して、来週の会議に提出した。", "explanation": "ここは〈作成する〉の意味。製は機械や手で材料から品物を作り出す意味で、文書を書いて作る意味には使わないので合わない。"}, {"text": "彼女は新曲を製して、ライブで披露した。", "explanation": "ここは〈作曲する〉の意味。製は品物を作る意味で、音楽を作曲する意味には使わないので合わない。"}, {"text": "彼は毎年、絵を製して、展示会に出品している。", "explanation": "ここは〈描く〉の意味。製は材料から品物を作り出す意味で、絵を描く意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41317, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明治時代、製糸を日本の経済を支えた。", "corrected_sentence": "明治時代、製糸が日本の経済を支えた。", "error_description": "「製糸」は支える主体（主語）なので「が」が正しい。「を」は目的語を示すため、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41317, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は製菓を学校に通っています。", "corrected_sentence": "彼女は製菓の学校に通っています。", "error_description": "「製菓」は学校を修飾する名詞なので、「の」が正しい。「を」では「通う」の目的語になり、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
