INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41318, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても細かくて、心がこもっていること。", "primary_collocate": null, "pronunciation": "こまやか", "ipa": "komajaka", "syllable_count": 4, "sentences": [{"text": "祖母は濃やかな愛情で、孫を育てた。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "祖母[そぼ]は濃[こま]やかな愛情[あいじょう]で、孫[まご]を育[そだ]てた。", "sentence_source": "generated"}, {"text": "ホテルの人の濃やかな気づかいに感動した。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "ホテルの人[ひと]の濃[こま]やかな気[き]づかいに感動[かんどう]した。", "sentence_source": "generated"}, {"text": "彼女は濃やかに手紙の返事を書いてくれた。", "target_word": "濃やかに", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は濃[こま]やかに手紙[てがみ]の返事[へんじ]を書[か]いてくれた。", "sentence_source": "generated"}, {"text": "先生は一人ひとりに濃やかな指導をしてくれる。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "先生[せんせい]は一人[ひとり]ひとりに濃[こま]やかな指導[しどう]をしてくれる。", "sentence_source": "generated"}, {"text": "濃やかな配慮のおかげで、旅行は楽しかった。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "濃[こま]やかな配慮[はいりょ]のおかげで、旅行[りょこう]は楽[たの]しかった。", "sentence_source": "generated"}, {"text": "母の濃やかな世話で、病気はすぐによくなった。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "母[はは]の濃[こま]やかな世話[せわ]で、病気[びょうき]はすぐによくなった。", "sentence_source": "generated"}, {"text": "この店のサービスは濃やかだと評判だ。", "target_word": "濃やかだ", "complexity_tier": "T3", "furigana": "この店[みせ]のサービスは濃[こま]やかだと評判[ひょうばん]だ。", "sentence_source": "generated"}, {"text": "彼は友だちの変化に気づく、濃やかな人だ。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "彼[かれ]は友[とも]だちの変化[へんか]に気[き]づく、濃[こま]やかな人[ひと]だ。", "sentence_source": "generated"}, {"text": "看護師さんが濃やかに患者の話を聞いている。", "target_word": "濃やかに", "complexity_tier": "T3", "furigana": "看護師[かんごし]さんが濃[こま]やかに患者[かんじゃ]の話[はなし]を聞[き]いている。", "sentence_source": "generated"}, {"text": "友人の濃やかな思いやりが、何よりうれしかった。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の濃[こま]やかな思[おも]いやりが、何[なに]よりうれしかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "濃やかだ", "label": "終止形"}, {"form": "濃やかな", "label": "連体形"}, {"form": "濃やかに", "label": "連用形"}, {"form": "濃やかで", "label": "て形"}], "register": "標準（やや文章寄り）", "sense_fingerprint": "細かく心がこもっている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41318, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濃やかな", "is_correct": true, "explanation": "正解。細かく心がこもった愛情の意味で、「濃やかな愛情で、孫を育てた」に合う。"}, {"text": "賑やかな", "is_correct": false, "explanation": "「賑やかな愛情」は不自然。賑やかは人が多く活気がある様子で、愛情の細やかさとは結びつかない。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "「鮮やかな愛情」は意味が合わない。鮮やかは色や手際が際立つ様子を表す。"}, {"text": "活発な", "is_correct": false, "explanation": "「活発な愛情」は意味が合わない。活発は動きが盛んな様子を表し、心配りの細やかさは示さない。"}], "explanations": {"濃やかな": "正解。細かく心がこもった愛情の意味で、「濃やかな愛情で、孫を育てた」に合う。", "賑やかな": "「賑やかな愛情」は不自然。賑やかは人が多く活気がある様子で、愛情の細やかさとは結びつかない。", "鮮やかな": "「鮮やかな愛情」は意味が合わない。鮮やかは色や手際が際立つ様子を表す。", "活発な": "「活発な愛情」は意味が合わない。活発は動きが盛んな様子を表し、心配りの細やかさは示さない。"}, "sentence_index": 0, "correct_answer": "濃やかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の花壇に、濃やかな赤色のゼラニウムが咲いた。", "explanation": "ここは「色が濃い」という別の意味で使う場面。赤が深く濃い様子を表すため、定義の「細かく心がこもっている」には当てはまらない。"}, {"text": "細かいことを気にしない、濃やかな性格の彼と暮らしている。", "explanation": "ここは「大らか」の場面。細かいことにこだわらない人柄を指す語で、濃やかは細かく気を配る意味なので、逆の性格には使えない。"}, {"text": "週末は濃やかな商店街で買い物をした。", "explanation": "ここは「賑やか」の場面。人が多く活気のある街を指す語で、濃やかは細かく心を配る意味なので、街のにぎわいには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41318, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濃やかだ", "is_correct": true, "explanation": "正解。終止形で「濃やかだと評判だ」と続き、細かく心のこもったサービスという評判に合う。"}, {"text": "頑丈だ", "is_correct": false, "explanation": "「頑丈だと評判」はサービスには合わない。頑丈は物が壊れにくい様子を表す。"}, {"text": "寡黙だ", "is_correct": false, "explanation": "「寡黙だと評判」はサービスの評判として合わない。寡黙は言葉少ない人柄を表す語。"}, {"text": "大柄だ", "is_correct": false, "explanation": "「大柄だと評判」は不自然。大柄は体格や規模が大きい様子を表し、サービスの評判には使わない。"}], "explanations": {"濃やかだ": "正解。終止形で「濃やかだと評判だ」と続き、細かく心のこもったサービスという評判に合う。", "頑丈だ": "「頑丈だと評判」はサービスには合わない。頑丈は物が壊れにくい様子を表す。", "寡黙だ": "「寡黙だと評判」はサービスの評判として合わない。寡黙は言葉少ない人柄を表す語。", "大柄だ": "「大柄だと評判」は不自然。大柄は体格や規模が大きい様子を表し、サービスの評判には使わない。"}, "sentence_index": 6, "correct_answer": "濃やかだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は大きな声で、濃やかに笑った。", "explanation": "ここは「豪快」の場面。大きく快活に笑う様子を表す語で、濃やかは細かく心がこもっている意味なので、笑い方には合わない。"}, {"text": "引っ越しの後、部屋が濃やかで片付かない。", "explanation": "ここは「乱雑」の場面。散らかって片付かない様子を表す語で、濃やかは細やかな配慮を表すため、部屋の散らかりは示せない。"}, {"text": "この箱は濃やかで、重い物も入る。", "explanation": "ここは「頑丈」の場面。物が壊れにくく丈夫な様子を表す語で、濃やかは細かく気を配る意味なので、箱の丈夫さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41318, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は子どもたちに濃やかの愛情を注いだ。", "corrected_sentence": "父は子どもたちに濃やかな愛情を注いだ。", "error_description": "形状詞の連体形は「濃やかな」。「の」を付けた「濃やかの」は誤りで、名詞を修飾するには「な」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "濃やかな", "is_correct": true, "explanation": "正解。連体形で、「濃やかな気づかい」と名詞を修飾する形になり、文に合う。"}, {"text": "濃やかさ", "is_correct": false, "explanation": "名詞化した形で、「濃やかさ気づかい」と続けると文が成り立たない。"}, {"text": "濃やかで", "is_correct": false, "explanation": "て形で、名詞に続けると文が成り立たない。「濃やかで気づかい」は不自然。"}, {"text": "濃やかだ", "is_correct": false, "explanation": "終止形で、名詞の前に置くと文法が成り立たない。「濃やかだ気づかい」は不自然。"}], "correct_form": "濃やかな", "base_form": "濃やか", "form_label": "連体形", "sentence_index": 1, "explanations": {"濃やかな": "正解。連体形で、「濃やかな気づかい」と名詞を修飾する形になり、文に合う。", "濃やかさ": "名詞化した形で、「濃やかさ気づかい」と続けると文が成り立たない。", "濃やかで": "て形で、名詞に続けると文が成り立たない。「濃やかで気づかい」は不自然。", "濃やかだ": "終止形で、名詞の前に置くと文法が成り立たない。「濃やかだ気づかい」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41318, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅館の女将は、客に濃やかで接してくれた。", "corrected_sentence": "旅館の女将は、客に濃やかに接してくれた。", "error_description": "「接してくれた」を修飾する連用形は「濃やかに」。「濃やかで」は て形で、動詞を修飾できないため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "濃やかな", "is_correct": true, "explanation": "正解。連体形で、「濃やかな人」と名詞を修飾する形になり、文に合う。"}, {"text": "濃やかだろう", "is_correct": false, "explanation": "推量の形で、名詞を直接修飾できない。「濃やかだろう人」は文法的に成り立たない。"}, {"text": "濃やかであり", "is_correct": false, "explanation": "「であり」の連用形で、名詞を修飾できない。「濃やかであり人だ」は文が崩れる。"}, {"text": "濃やかさ", "is_correct": false, "explanation": "名詞化した形で、「濃やかさ人だ」の形では意味が通らない。"}], "correct_form": "濃やかな", "base_form": "濃やか", "form_label": "連体形", "sentence_index": 7, "explanations": {"濃やかな": "正解。連体形で、「濃やかな人」と名詞を修飾する形になり、文に合う。", "濃やかだろう": "推量の形で、名詞を直接修飾できない。「濃やかだろう人」は文法的に成り立たない。", "濃やかであり": "「であり」の連用形で、名詞を修飾できない。「濃やかであり人だ」は文が崩れる。", "濃やかさ": "名詞化した形で、「濃やかさ人だ」の形では意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
