INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41319, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細かいところまで気を配り、丁寧で思いやりのある様子。", "primary_collocate": null, "pronunciation": "こまやか", "ipa": "komajaka", "syllable_count": 4, "sentences": [{"text": "彼の濃やかな気配りが、会議を円滑に進めた。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "彼[かれ]の濃[こま]やかな気配[きくば]りが、会議[かいぎ]を円滑[えんかつ]に進[すす]めた。", "sentence_source": "generated"}, {"text": "介護の現場では、利用者への濃やかな対応が求められる。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "介護[かいご]の現場[げんば]では、利用者[りようしゃ]への濃[こま]やかな対応[たいおう]が求[もと]められる。", "sentence_source": "generated"}, {"text": "彼女は相手の気持ちに濃やかに寄り添う。", "target_word": "濃やかに", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は相手[あいて]の気持[きも]ちに濃[こま]やかに寄[よ]り添[そ]う。", "sentence_source": "generated"}, {"text": "相手に寄り添う濃やかな言葉に、心が温かくなった。", "target_word": "濃やか", "complexity_tier": "T3", "furigana": "相手[あいて]に寄[よ]り添[そ]う濃[こま]やかな言葉[ことば]に、心[こころ]が温[あたた]かくなった。", "sentence_source": "generated"}, {"text": "旅館の女将は、客の好みに合わせて濃やかに料理を変えてくれた。", "target_word": "濃やかに", "complexity_tier": "T3", "furigana": "旅館[りょかん]の女将[おかみ]は、客[きゃく]の好[この]みに合[あ]わせて濃[こま]やかに料理[りょうり]を変[か]えてくれた。", "sentence_source": "generated"}, {"text": "教師の濃やかな観察のおかげで、生徒の悩みが早く見つかった。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "教師[きょうし]の濃[こま]やかな観察[かんさつ]のおかげで、生徒[せいと]の悩[なや]みが早[はや]く見[み]つかった。", "sentence_source": "generated"}, {"text": "この国の人々は、季節への濃やかな感性を持っている。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "この国[くに]の人々[ひとびと]は、季節[きせつ]への濃[こま]やかな感性[かんせい]を持[も]っている。", "sentence_source": "generated"}, {"text": "母の濃やかな心配りは、いつも私を支えてくれた。", "target_word": "濃やかな", "complexity_tier": "T3", "furigana": "母[はは]の濃[こま]やかな心配[こころくば]りは、いつも私[わたし]を支[ささ]えてくれた。", "sentence_source": "generated"}, {"text": "面接の前に、濃やかに準備をした人が好印象を与えた。", "target_word": "濃やかに", "complexity_tier": "T3", "furigana": "面接[めんせつ]の前[まえ]に、濃[こま]やかに準備[じゅんび]をした人[ひと]が好印象[こういんしょう]を与[あた]えた。", "sentence_source": "generated"}, {"text": "彼は濃やかで、困っている人をすぐに助ける。", "target_word": "濃やかで", "complexity_tier": "T3", "furigana": "彼[かれ]は濃[こま]やかで、困[こま]っている人[ひと]をすぐに助[たす]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "濃やかだ", "label": "終止形"}, {"form": "濃やかな", "label": "連体形"}, {"form": "濃やかに", "label": "連用形"}, {"form": "濃やかで", "label": "て形"}], "register": "文章寄り（やや硬め）", "sense_fingerprint": "細部まで気を配る思いやりのある様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41319, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濃やかな", "is_correct": true, "explanation": "正解。細かいところまで行き届いた気配りという意味で、「濃やかな気配り」に合う。"}, {"text": "賑やかな", "is_correct": false, "explanation": "「賑やかな気配り」は不自然。賑やかは人や場が活気づく様子を表す。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "「鮮やかな気配り」は意味が合わない。鮮やかは色や手際が際立つ様子を表す。"}, {"text": "活発な", "is_correct": false, "explanation": "「活発な気配り」は合わない。活発は動きが盛んな様子で、気配りの行き届いた様子は表さない。"}], "explanations": {"濃やかな": "正解。細かいところまで行き届いた気配りという意味で、「濃やかな気配り」に合う。", "賑やかな": "「賑やかな気配り」は不自然。賑やかは人や場が活気づく様子を表す。", "鮮やかな": "「鮮やかな気配り」は意味が合わない。鮮やかは色や手際が際立つ様子を表す。", "活発な": "「活発な気配り」は合わない。活発は動きが盛んな様子で、気配りの行き届いた様子は表さない。"}, "sentence_index": 0, "correct_answer": "濃やかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は大きな声で、濃やかに笑い飛ばした。", "explanation": "ここは「豪快」の場面。大きく快活に笑う様子を表す語で、濃やかは細かく心を配る意味なので、笑い方には合わない。"}, {"text": "机の上が濃やかで、書類がどこにあるか分からない。", "explanation": "ここは「乱雑」の場面。散らかって整理されていない様子を表す語で、濃やかは行き届いた様子を表すため、散らかりには合わない。"}, {"text": "夕焼けの空に、濃やかな紅がにじんでいた。", "explanation": "ここは「色が濃い」という別の意味で使う場面。紅色の濃さを表すため、定義の「細かく心がこもっている」とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41319, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濃やかな", "is_correct": true, "explanation": "正解。季節の細かな移ろいに気づく細やかな感性という意味で、「濃やかな感性」に合う。"}, {"text": "頑丈な", "is_correct": false, "explanation": "「頑丈な感性」は意味が合わない。頑丈は物が壊れにくい様子を表す。"}, {"text": "寡黙な", "is_correct": false, "explanation": "「寡黙な感性」は不自然。寡黙は言葉少ない人柄を表す語。"}, {"text": "大柄な", "is_correct": false, "explanation": "「大柄な感性」は不自然。大柄は体格や規模が大きい様子を表す。"}], "explanations": {"濃やかな": "正解。季節の細かな移ろいに気づく細やかな感性という意味で、「濃やかな感性」に合う。", "頑丈な": "「頑丈な感性」は意味が合わない。頑丈は物が壊れにくい様子を表す。", "寡黙な": "「寡黙な感性」は不自然。寡黙は言葉少ない人柄を表す語。", "大柄な": "「大柄な感性」は不自然。大柄は体格や規模が大きい様子を表す。"}, "sentence_index": 6, "correct_answer": "濃やかな"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鞄は濃やかで、長い旅にも耐える。", "explanation": "ここは「頑丈」の場面。物が壊れにくく丈夫な様子を表す語で、濃やかは細かく心を配る意味なので、鞄の丈夫さには使えない。"}, {"text": "酒場には濃やかな笑い声が響いていた。", "explanation": "ここは「陽気」の場面。明るく楽しげな様子を表す語で、濃やかは細かく心がこもっている意味なので、笑い声の明るさには合わない。"}, {"text": "母は濃やかな性格で、細かいことを気にしない。", "explanation": "ここは「大らか」の場面。細かいことにこだわらない人柄を表す語で、濃やかは細かく気を配る意味なので、大らかな人柄は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41319, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒の変化に、濃やかの目を向けている。", "corrected_sentence": "先生は生徒の変化に、濃やかな目を向けている。", "error_description": "形状詞の連体形は「濃やかな」。「の」を付けた「濃やかの」は誤りで、名詞「目」を修飾するには「な」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "濃やかな", "is_correct": true, "explanation": "正解。連体形で、「濃やかな対応」と名詞を修飾する形になり、文に合う。"}, {"text": "濃やかさ", "is_correct": false, "explanation": "名詞化した形で、「濃やかさ対応」と続けると文が成り立たない。"}, {"text": "濃やかで", "is_correct": false, "explanation": "て形で、名詞に続けると文が成り立たない。「濃やかで対応」は不自然。"}, {"text": "濃やかだ", "is_correct": false, "explanation": "終止形で、名詞の前に置くと文法が成り立たない。「濃やかだ対応」は不自然。"}], "correct_form": "濃やかな", "base_form": "濃やか", "form_label": "連体形", "sentence_index": 1, "explanations": {"濃やかな": "正解。連体形で、「濃やかな対応」と名詞を修飾する形になり、文に合う。", "濃やかさ": "名詞化した形で、「濃やかさ対応」と続けると文が成り立たない。", "濃やかで": "て形で、名詞に続けると文が成り立たない。「濃やかで対応」は不自然。", "濃やかだ": "終止形で、名詞の前に置くと文法が成り立たない。「濃やかだ対応」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41319, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員は客の要望に濃やかで応えてくれた。", "corrected_sentence": "店員は客の要望に濃やかに応えてくれた。", "error_description": "「応えてくれた」を修飾する連用形は「濃やかに」。「濃やかで」は て形で、動詞を修飾できないため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "濃やかな", "is_correct": true, "explanation": "正解。連体形で、「濃やかな心配り」と名詞を修飾する形になり、文に合う。"}, {"text": "濃やかさ", "is_correct": false, "explanation": "名詞化した形で、「濃やかさ心配り」と並べると文が成り立たない。"}, {"text": "濃やかだろう", "is_correct": false, "explanation": "推量の形で、名詞の前に直接置けず、文が成り立たない。"}, {"text": "濃やかであり", "is_correct": false, "explanation": "「であり」の連用形で、名詞を修飾できず、文の形が崩れる。"}], "correct_form": "濃やかな", "base_form": "濃やか", "form_label": "連体形", "sentence_index": 7, "explanations": {"濃やかな": "正解。連体形で、「濃やかな心配り」と名詞を修飾する形になり、文に合う。", "濃やかさ": "名詞化した形で、「濃やかさ心配り」と並べると文が成り立たない。", "濃やかだろう": "推量の形で、名詞の前に直接置けず、文が成り立たない。", "濃やかであり": "「であり」の連用形で、名詞を修飾できず、文の形が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41320, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『元種が＋ある』の主語で、条件節の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "『ある』は目的語を取らないので、『を』は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『元種へあれば』は方向の意味になり、条件の文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『元種のあれば』は文法的に成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『元種が＋ある』の主語で、条件節の主語として正しい。", "を": "『ある』は目的語を取らないので、『を』は不自然。", "へ": "『元種へあれば』は方向の意味になり、条件の文として成り立たない。", "の": "『元種のあれば』は文法的に成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41320, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "『元種から』で由来・起点を表し、『生まれている』の文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は向かう先を表すので、由来を表す文脈には合わない。"}, {"text": "と", "is_correct": false, "explanation": "『元種と生まれている』は並列の意味になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『生まれる』は目的語を取らないので、『を』は不自然。"}], "correct_answer": "から", "explanations": {"から": "『元種から』で由来・起点を表し、『生まれている』の文に合う。", "へ": "『へ』は向かう先を表すので、由来を表す文脈には合わない。", "と": "『元種と生まれている』は並列の意味になり、文が成り立たない。", "を": "『生まれる』は目的語を取らないので、『を』は不自然。"}, "error_tags": {"へ": "方向", "と": "並列", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41320, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンやお酒を作るときに使う、最初の酵母のこと。", "primary_collocate": null, "pronunciation": "もとだね", "ipa": "motodane", "syllable_count": 4, "sentences": [{"text": "パン屋さんは、毎朝元種に小麦粉と水を足す。", "target_word": "元種", "complexity_tier": "T3", "furigana": "ぱんやさんは、まいあさもとだねにこむぎことみずをたす。", "sentence_source": "generated"}, {"text": "元種があれば、家でも天然酵母のパンが焼ける。", "target_word": "元種", "complexity_tier": "T3", "furigana": "もとだねがあれば、いえでもてんねんこうぼのぱんがやける。", "sentence_source": "generated"}, {"text": "友だちから元種を分けてもらった。", "target_word": "元種", "complexity_tier": "T3", "furigana": "ともだちからもとだねをわけてもらった。", "sentence_source": "generated"}, {"text": "元種を冷蔵庫に入れて、発酵をゆっくりにした。", "target_word": "元種", "complexity_tier": "T3", "furigana": "もとだねをれいぞうこにいれて、はっこうをゆっくりにした。", "sentence_source": "generated"}, {"text": "酒蔵では、元種を作ってから、大きなタンクで酒を仕込む。", "target_word": "元種", "complexity_tier": "T3", "furigana": "さかぐらでは、もとだねをつくってから、おおきなたんくでさけをしこむ。", "sentence_source": "generated"}, {"text": "元種が元気だと、パンが大きくふくらむ。", "target_word": "元種", "complexity_tier": "T3", "furigana": "もとだねがげんきだと、ぱんがおおきくふくらむ。", "sentence_source": "generated"}, {"text": "旅行に行く前に、元種の世話を弟にお願いした。", "target_word": "元種", "complexity_tier": "T3", "furigana": "りょこうにいくまえに、もとだねのせわをおとうとにおねがいした。", "sentence_source": "generated"}, {"text": "この店のパンの味は、百年続く元種から生まれている。", "target_word": "元種", "complexity_tier": "T3", "furigana": "このみせのぱんのあじは、ひゃくねんつづくもとだねからうまれている。", "sentence_source": "generated"}, {"text": "元種を作るには、果物と水を瓶に入れて数日待つ。", "target_word": "元種", "complexity_tier": "T3", "furigana": "もとだねをつくるには、くだものとみずをびんにいれてすうじつまつ。", "sentence_source": "generated"}, {"text": "元種が弱くなったので、新しく作り直した。", "target_word": "元種", "complexity_tier": "T3", "furigana": "もとだねがよわくなったので、あたらしくつくりなおした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "元種", "label": "基本形"}], "register": "標準", "sense_fingerprint": "パンやお酒作りで最初に使う酵母のもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41320, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元種", "is_correct": true, "explanation": "元種は酵母の種で、毎朝粉と水を足して育てるものなので、ここに入る。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は切る道具で、粉と水を足す相手にはならない。"}, {"text": "窯", "is_correct": false, "explanation": "窯は焼くための設備で、粉と水を足す対象ではない。"}, {"text": "蒸し器", "is_correct": false, "explanation": "蒸し器は蒸すための道具で、ここに粉と水を足す文としては不自然。"}], "explanations": {"元種": "元種は酵母の種で、毎朝粉と水を足して育てるものなので、ここに入る。", "包丁": "包丁は切る道具で、粉と水を足す相手にはならない。", "窯": "窯は焼くための設備で、粉と水を足す対象ではない。", "蒸し器": "蒸し器は蒸すための道具で、ここに粉と水を足す文としては不自然。"}, "sentence_index": 0, "correct_answer": "元種"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "元種を麺棒で薄くのばして、型で抜いた。", "explanation": "ここは〈生地〉の意味。麺棒でのばして型で抜くのは生地で、元種は酵母の培養種なので合わない。"}, {"text": "この米は元種が違うので、粒が大きい。", "explanation": "ここは〈品種〉の意味。元種は酵母のことで、米や野菜の品種には使わない。"}, {"text": "花の元種を土に植えて、毎日水をやる。", "explanation": "ここは〈苗〉（植えて育てる株や種）の意味。元種は酵母を培養した種で、植えて育てるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41320, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元種", "is_correct": true, "explanation": "元種は培養した酵母で、旅行の間に世話を頼む対象として文に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は材料で、世話をお願いする対象としては文に合わない。"}, {"text": "麦茶", "is_correct": false, "explanation": "麦茶は飲み物で、世話を頼む対象にはならない。"}, {"text": "寒天", "is_correct": false, "explanation": "寒天は材料で、『世話』を頼む文には合わない。"}], "explanations": {"元種": "元種は培養した酵母で、旅行の間に世話を頼む対象として文に合う。", "砂糖": "砂糖は材料で、世話をお願いする対象としては文に合わない。", "麦茶": "麦茶は飲み物で、世話を頼む対象にはならない。", "寒天": "寒天は材料で、『世話』を頼む文には合わない。"}, "sentence_index": 6, "correct_answer": "元種"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店を始めるために、元種を三百万円用意した。", "explanation": "ここは〈元手〉の意味。元種は酵母のことで、お金を指す〈元手〉の代わりにはならない。"}, {"text": "事故の元種は、古い配線にあった。", "explanation": "ここは〈元凶〉（悪い原因）の意味。元種は酵母のことで、事故の原因を指す語としては使わない。"}, {"text": "寝不足で元種がなくて、午後は眠かった。", "explanation": "ここは〈元気〉の意味。元種は体の調子を表す語ではないので、〈元気〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41320, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "元種が小麦粉を足して、ふたをした。", "corrected_sentence": "元種に小麦粉を足して、ふたをした。", "error_description": "『元種が』は誤り。正しくは『元種に』。元種は小麦粉を足される先なので『に』が必要。『が』だと元種が動作の主体になり、意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41320, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "元種を管理を妹に任せた。", "corrected_sentence": "元種の管理を妹に任せた。", "error_description": "『元種を』は誤り。正しくは『元種の』。『管理を』がすでに目的語なので、元種にも『を』を付けると目的語が二つになる。元種は『管理』を修飾するので『の』が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41323, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「調理の前に」と名詞をつなぐ連体修飾の「の」で、文として自然。"}, {"text": "に", "is_correct": false, "explanation": "時点を示すが、「調理に前に」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「調理で前に」は不自然で文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「調理が前に」は文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「調理の前に」と名詞をつなぐ連体修飾の「の」で、文として自然。", "に": "時点を示すが、「調理に前に」は成り立たない。", "で": "場所や手段を示すが、「調理で前に」は不自然で文が成り立たない。", "が": "主語を示すが、「調理が前に」は文として成り立たない。"}, "error_tags": {"に": "位置の誤り", "で": "場所・手段の誤り", "が": "主語の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41323, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41323, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食材を加工して食べ物を作ること。料理。", "primary_collocate": null, "pronunciation": "ちょうり", "ipa": "tɕoːɾi", "syllable_count": 3, "sentences": [{"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "調理", "complexity_tier": "T5", "furigana": "水温(すいおん)と室温(しつおん)をミリ単位(たんい)で制御(せいぎょ)し、小麦粉(こむぎこ)と水(みず)のみを混(ま)ぜ合(あ)わせる行為(こうい)は、単(たん)なる調理(ちょうり)の域(いき)を超(こ)え、微生物(びせいぶつ)の生態系(せいたいけい)を育(はぐく)む科学的(かがくてき)な実験(じっけん)とも呼応(こおう)する。", "sentence_source": "mined"}, {"text": "調理の前に、手をよく洗ってください。", "target_word": "調理", "complexity_tier": "T3", "furigana": "調理(ちょうり)の前(まえ)に、手(て)をよく洗(あら)ってください。", "sentence_source": "generated"}, {"text": "この店では、調理の様子を客席から見ることができる。", "target_word": "調理", "complexity_tier": "T3", "furigana": "この店(みせ)では、調理(ちょうり)の様子(ようす)を客席(きゃくせき)から見(み)ることができる。", "sentence_source": "generated"}, {"text": "魚の調理は難しいので、母に教えてもらった。", "target_word": "調理", "complexity_tier": "T3", "furigana": "魚(さかな)の調理(ちょうり)は難(むずか)しいので、母(はは)に教(おし)えてもらった。", "sentence_source": "generated"}, {"text": "調理に使うナイフは、毎日きちんと手入れしています。", "target_word": "調理", "complexity_tier": "T3", "furigana": "調理(ちょうり)に使(つか)うナイフは、毎日(まいにち)きちんと手入(ていれ)れしています。", "sentence_source": "generated"}, {"text": "電子レンジを使えば、調理の時間が短くなる。", "target_word": "調理", "complexity_tier": "T3", "furigana": "電子(でんし)レンジを使(つか)えば、調理(ちょうり)の時間(じかん)が短(みじか)くなる。", "sentence_source": "generated"}, {"text": "調理を担当する人は、帽子とマスクをつけます。", "target_word": "調理", "complexity_tier": "T3", "furigana": "調理(ちょうり)を担当(たんとう)する人(ひと)は、帽子(ぼうし)とマスクをつけます。", "sentence_source": "generated"}, {"text": "肉は十分に火を通して調理しないと、お腹をこわすおそれがある。", "target_word": "調理", "complexity_tier": "T3", "furigana": "肉(にく)は十分(じゅうぶん)に火(ひ)を通(とお)して調理(ちょうり)しないと、お腹(なか)をこわすおそれがある。", "sentence_source": "generated"}, {"text": "調理の方法によって、同じ野菜でも味が変わる。", "target_word": "調理", "complexity_tier": "T3", "furigana": "調理(ちょうり)の方法(ほうほう)によって、同(おな)じ野菜(やさい)でも味(あじ)が変(か)わる。", "sentence_source": "generated"}, {"text": "祖父は定年のあと、調理を習いはじめた。", "target_word": "調理", "complexity_tier": "T3", "furigana": "祖父(そふ)は定年(ていねん)のあと、調理(ちょうり)を習(なら)いはじめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "調理", "label": "基本形"}, {"form": "調理する", "label": "サ変動詞"}, {"form": "調理した", "label": "過去形"}, {"form": "調理して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "食材を切ったり加熱したりして食べ物に仕上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 水温 (Zipf 3.22), 室温 (Zipf 3.3), 混ぜ合わ (Zipf 2.89), 育む (Zipf 3.02), 呼応 (Zipf 3.02)']::text[], 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41323, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "調理", "is_correct": true, "explanation": "食材を混ぜ合わせて食べ物に仕上げる行為を指し、文の内容と合う。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は汚れを取り除く行為で、小麦粉と水を混ぜる内容と合わない。"}, {"text": "読書", "is_correct": false, "explanation": "読書は本を読むことで、食材を混ぜる行為の文脈に合わない。"}, {"text": "買い物", "is_correct": false, "explanation": "買い物は店で品物を買うことで、加工の過程を述べる文には合わない。"}], "explanations": {"調理": "食材を混ぜ合わせて食べ物に仕上げる行為を指し、文の内容と合う。", "掃除": "掃除は汚れを取り除く行為で、小麦粉と水を混ぜる内容と合わない。", "読書": "読書は本を読むことで、食材を混ぜる行為の文脈に合わない。", "買い物": "買い物は店で品物を買うことで、加工の過程を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "調理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壊れた自転車の調理を頼んだ。", "explanation": "ここは〈修理〉の意味。調理は食べ物を作ることで、機械を直す意味では使わない。"}, {"text": "部屋の調理を手伝った。", "explanation": "ここは〈整理〉の意味。調理は食べ物を作ることで、物を片づける意味では使わない。"}, {"text": "警察は事故の原因を調理している。", "explanation": "ここは〈調査〉の意味。原因を探る作業は調査で、食べ物を作る調理とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41323, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "調理", "is_correct": true, "explanation": "食べ物を作る仕事を担当する文脈に合い、帽子とマスクをつける衛生の話と合う。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲を作る仕事で、帽子とマスクをつける衛生の文脈と合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を置き換える仕事で、衛生用の帽子やマスクの話とは合わない。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は音楽を奏でることで、帽子とマスクをつける文脈には合わない。"}], "explanations": {"調理": "食べ物を作る仕事を担当する文脈に合い、帽子とマスクをつける衛生の話と合う。", "作曲": "作曲は曲を作る仕事で、帽子とマスクをつける衛生の文脈と合わない。", "翻訳": "翻訳は言葉を置き換える仕事で、衛生用の帽子やマスクの話とは合わない。", "演奏": "演奏は音楽を奏でることで、帽子とマスクをつける文脈には合わない。"}, "sentence_index": 6, "correct_answer": "調理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の発表会で、バイオリンを調理する。", "explanation": "ここは〈演奏〉の意味。音楽を奏でる意味で使い、食べ物を作る調理とは別。"}, {"text": "夏休みに、紙で動物の調理をした。", "explanation": "ここは〈工作〉の意味。紙などで物を作る作業で、食べ物には使わない。"}, {"text": "毎日三十分、英語の調理をしている。", "explanation": "ここは〈練習〉の意味。繰り返して上達を目指す行為で、食べ物を作る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41323, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母が魚の調理が教えてくれた。", "corrected_sentence": "母が魚の調理を教えてくれた。", "error_description": "「教える」の対象は「を」で示す。「調理が」は誤りで、「調理を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41323, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急いで調理を閉めた。", "corrected_sentence": "急いで調理を始めた。", "error_description": "「調理を始める」が正しい。「閉める」は戸や店などを対象とし、調理とは続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41324, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「生地に卵と牛乳を混ぜて」の「に」で、混ぜ入れる先を示す。正解。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「生地から卵と牛乳を混ぜて」では混ぜ入れる先にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「生地で卵と牛乳を混ぜて」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「生地より卵と牛乳を混ぜて」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「生地に卵と牛乳を混ぜて」の「に」で、混ぜ入れる先を示す。正解。", "から": "「から」は起点を示し、「生地から卵と牛乳を混ぜて」では混ぜ入れる先にならない。", "で": "「で」は手段や場所を示し、「生地で卵と牛乳を混ぜて」では意味が通らない。", "より": "「より」は比較を表し、「生地より卵と牛乳を混ぜて」は成り立たない。"}, "error_tags": {"から": "起点の「から」は混ぜ入れる先にならない", "で": "手段・場所の「で」は混ぜ入れる先にならない", "より": "比較の「より」は混ぜ入れる先にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41324, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「生地を冷蔵庫で冷やしました」の「を」で、冷やす対象を示す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示し、「生地に冷やしました」では冷やす対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「生地へ冷やしました」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すもので、「生地が冷やしました」では冷やす対象が示せず文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「生地を冷蔵庫で冷やしました」の「を」で、冷やす対象を示す。正解。", "に": "「に」は場所や相手を示し、「生地に冷やしました」では冷やす対象にならない。", "へ": "「へ」は方向を示し、「生地へ冷やしました」は成り立たない。", "が": "「が」は主語を示すもので、「生地が冷やしました」では冷やす対象が示せず文が崩れる。"}, "error_tags": {"に": "場所・相手の「に」は冷やす対象にならない", "へ": "方向の「へ」は冷やす対象にならない", "が": "主語の「が」は冷やす対象を示せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41324, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンやケーキを作るときに使う、粉と水を混ぜたもの。", "primary_collocate": null, "pronunciation": "きじ", "ipa": "kiʑi", "syllable_count": 2, "sentences": [{"text": "パンの生地を三十分休ませます。", "target_word": "生地", "complexity_tier": "T3", "furigana": "パンの生地[きじ]を三十分[さんじゅっぷん]休[やす]ませます。", "sentence_source": "generated"}, {"text": "生地に卵と牛乳を混ぜてください。", "target_word": "生地", "complexity_tier": "T3", "furigana": "生地[きじ]に卵[たまご]と牛乳[ぎゅうにゅう]を混[ま]ぜてください。", "sentence_source": "generated"}, {"text": "ケーキの生地を型に流して、オーブンで焼きます。", "target_word": "生地", "complexity_tier": "T3", "furigana": "ケーキの生地[きじ]を型[かた]に流[なが]して、オーブンで焼[や]きます。", "sentence_source": "generated"}, {"text": "生地がやわらかすぎて、手にくっつきました。", "target_word": "生地", "complexity_tier": "T3", "furigana": "生地[きじ]がやわらかすぎて、手[て]にくっつきました。", "sentence_source": "generated"}, {"text": "ピザの生地を薄くのばしました。", "target_word": "生地", "complexity_tier": "T3", "furigana": "ピザの生地[きじ]を薄[うす]くのばしました。", "sentence_source": "generated"}, {"text": "酵母を入れた生地は、あたたかい場所でふくらみます。", "target_word": "生地", "complexity_tier": "T3", "furigana": "酵母[こうぼ]を入[い]れた生地[きじ]は、あたたかい場所[ばしょ]でふくらみます。", "sentence_source": "generated"}, {"text": "生地をこねる仕事は、思ったより力が要ります。", "target_word": "生地", "complexity_tier": "T3", "furigana": "生地[きじ]をこねる仕事[しごと]は、思[おも]ったより力[ちから]が要[い]ります。", "sentence_source": "generated"}, {"text": "クッキーの生地を冷蔵庫で冷やしました。", "target_word": "生地", "complexity_tier": "T3", "furigana": "クッキーの生地[きじ]を冷蔵庫[れいぞうこ]で冷[ひ]やしました。", "sentence_source": "generated"}, {"text": "粉が足りなかったので、生地が水っぽくなりました。", "target_word": "生地", "complexity_tier": "T3", "furigana": "粉[こな]が足[た]りなかったので、生地[きじ]が水[みず]っぽくなりました。", "sentence_source": "generated"}, {"text": "姉は生地を丸めて、小さいパンを作りました。", "target_word": "生地", "complexity_tier": "T3", "furigana": "姉[あね]は生地[きじ]を丸[まる]めて、小[ちい]さいパンを作[つく]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生地", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "パンや菓子の材料になる、粉と水などを混ぜたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41324, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生地", "is_correct": true, "explanation": "「パンの___を三十分休ませます」の目的語として入る名詞。正解。"}, {"text": "休む", "is_correct": false, "explanation": "動詞の辞書形。「パンの」の後の名詞の位置には入らない。"}, {"text": "休んだ", "is_correct": false, "explanation": "過去形の動詞。名詞の位置に入らず、文が成り立たない。"}, {"text": "休める", "is_correct": false, "explanation": "可能形の動詞。「パンの」の後には置けない。"}], "explanations": {"生地": "「パンの___を三十分休ませます」の目的語として入る名詞。正解。", "休む": "動詞の辞書形。「パンの」の後の名詞の位置には入らない。", "休んだ": "過去形の動詞。名詞の位置に入らず、文が成り立たない。", "休める": "可能形の動詞。「パンの」の後には置けない。"}, "sentence_index": 0, "correct_answer": "生地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新聞の生地が面白かったので、最後まで読みました。", "explanation": "ここは〈記事〉の意味。新聞や雑誌の文章を指す同音の別語で、粉と水を混ぜた生地とは違うので合わない。"}, {"text": "ふとんの生地を縫い直しました。", "explanation": "ここは〈布地〉の意味。布そのものを指し、粉と水を混ぜた生地とは違うので合わない。"}, {"text": "生地をふるってダマをなくします。", "explanation": "ここは〈粉〉の意味。ふるって粉のダマを取る作業は粉に対して行い、水を混ぜた生地にはしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41324, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生地", "is_correct": true, "explanation": "「___をこねる仕事は」の目的語として入る名詞。正解。"}, {"text": "冷やし", "is_correct": false, "explanation": "連用形の語幹。名詞の位置に入らず、「をこねる」の前に置けない。"}, {"text": "冷やす", "is_correct": false, "explanation": "動詞の辞書形。名詞の位置に入らず、「をこねる仕事」とつながらない。"}, {"text": "冷める", "is_correct": false, "explanation": "自動詞。目的語にはならず、「をこねる仕事」の前では文が成り立たない。"}], "explanations": {"生地": "「___をこねる仕事は」の目的語として入る名詞。正解。", "冷やし": "連用形の語幹。名詞の位置に入らず、「をこねる」の前に置けない。", "冷やす": "動詞の辞書形。名詞の位置に入らず、「をこねる仕事」とつながらない。", "冷める": "自動詞。目的語にはならず、「をこねる仕事」の前では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "生地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "おにぎりの生地をたくさん入れて、握ります。", "explanation": "ここは〈具〉の意味。おにぎりの中に入れる材料を指し、粉と水を混ぜた生地ではないので合わない。"}, {"text": "服の生地を一メートル買いました。", "explanation": "ここは〈布地〉の意味。服を作る布を指し、粉と水を混ぜた生地とは違うので合わない。"}, {"text": "氷を生地で砕いて、グラスに入れます。", "explanation": "ここは凍って固まった水の意味。生地は粉と水を混ぜたもので、凍らせて砕く材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41324, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "生地を厚さを均一にします。", "corrected_sentence": "生地の厚さを均一にします。", "error_description": "「厚さ」は「生地の」で修飾する。「生地を厚さ」の「を」は「の」にすべき。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41324, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生地を冷やすました。", "corrected_sentence": "生地を冷やしました。", "error_description": "過去形は「冷やしました」。「冷やすました」は動詞の語幹を誤っている（「す」は「し」にすべき）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
