INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41326, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "よく見て、正しいと決めること", "primary_collocate": null, "pronunciation": "みきわめる", "ipa": "mikiwameɾɯ", "syllable_count": 5, "sentences": [{"text": "買う前に、くだものが新しいかどうか見極める。", "target_word": "見極める", "complexity_tier": "T3", "furigana": "買[か]う前[まえ]に、くだものが新[あたら]しいかどうか見極[みきわ]める。", "sentence_source": "generated"}, {"text": "先生は、どの答えが正しいか、よく見極めなさいと言った。", "target_word": "見極め", "complexity_tier": "T3", "furigana": "先生[せんせい]は、どの答[こた]えが正[ただ]しいか、よく見極[みきわ]めなさいと言[い]った。", "sentence_source": "generated"}, {"text": "魚屋さんは、いい魚をよく見極めて仕入れている。", "target_word": "見極めて", "complexity_tier": "T3", "furigana": "魚屋[さかなや]さんは、いい魚[さかな]をよく見極[みきわ]めて仕入[しい]れている。", "sentence_source": "generated"}, {"text": "本物かにせ物か、じっくり見極めてから買おう。", "target_word": "見極めて", "complexity_tier": "T3", "furigana": "本物[ほんもの]かにせ物[もの]か、じっくり見極[みきわ]めてから買[か]おう。", "sentence_source": "generated"}, {"text": "道が安全かどうか見極めてから、渡りましょう。", "target_word": "見極めて", "complexity_tier": "T3", "furigana": "道[みち]が安全[あんぜん]かどうか見極[みきわ]めてから、渡[わた]りましょう。", "sentence_source": "generated"}, {"text": "兄は雲の形を見て、明日の天気を見極めた。", "target_word": "見極めた", "complexity_tier": "T3", "furigana": "兄[あに]は雲[くも]の形[かたち]を見[み]て、明日[あした]の天気[てんき]を見極[みきわ]めた。", "sentence_source": "generated"}, {"text": "どちらが本当のことを言っているのか、私には見極められない。", "target_word": "見極められ", "complexity_tier": "T3", "furigana": "どちらが本当[ほんとう]のことを言[い]っているのか、私[わたし]には見極[みきわ]められない。", "sentence_source": "generated"}, {"text": "よく見極めないで決めたので、失敗してしまった。", "target_word": "見極め", "complexity_tier": "T3", "furigana": "よく見極[みきわ]めないで決[き]めたので、失敗[しっぱい]してしまった。", "sentence_source": "generated"}, {"text": "きのこに毒があるかどうかは、大人が見極めないと危ない。", "target_word": "見極め", "complexity_tier": "T3", "furigana": "きのこに毒[どく]があるかどうかは、大人[おとな]が見極[みきわ]めないと危[あぶ]ない。", "sentence_source": "generated"}, {"text": "どの店の味が一番か、食べ比べて見極めたい。", "target_word": "見極め", "complexity_tier": "T3", "furigana": "どの店[みせ]の味[あじ]が一番[いちばん]か、食[た]べ比[くら]べて見極[みきわ]めたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見極める", "label": "終止形"}, {"form": "見極めた", "label": "過去形"}, {"form": "見極めて", "label": "テ形"}, {"form": "見極めない", "label": "否定形"}, {"form": "見極めれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "よく見て、何が正しいか本物かを自分で判断する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41326, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見極める", "is_correct": true, "explanation": "「新しいかどうか見極める」で、よく見て正しいと判断する意味。正解。"}, {"text": "洗う", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、新しさを判断する文脈には合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは寝ることで、くだものの判断には使えない。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは表面をきれいにする動作で、新しさを判断する意味にはならない。"}], "explanations": {"見極める": "「新しいかどうか見極める」で、よく見て正しいと判断する意味。正解。", "洗う": "洗うは汚れを落とす動作で、新しさを判断する文脈には合わない。", "眠る": "眠るは寝ることで、くだものの判断には使えない。", "磨く": "磨くは表面をきれいにする動作で、新しさを判断する意味にはならない。"}, "sentence_index": 0, "correct_answer": "見極める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出かける前に、玄関を見極めた。", "explanation": "ここは〈見回す〉の意味。見極めは対象の状態を判断して決めることで、周囲をぐるりと見渡す場面では使わない。"}, {"text": "駅のホームで、旅立つ家族を見極めた。", "explanation": "ここは〈見送る〉の意味。見極めは正しいかどうか判断して決めることで、人を送り出す場面には使わない。"}, {"text": "窓辺で、子どもの寝顔を見極めた。", "explanation": "ここは〈眺める〉の意味。見極めは正しいかどうか判断して決めることで、寝顔を眺めて和む場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41326, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見極められ", "is_correct": true, "explanation": "「私には見極められない」の可能形で、判断できないという意味。正解。"}, {"text": "煮る", "is_correct": false, "explanation": "煮るは調理の動作で、「私には〜ない」の判断の文脈に合わない。"}, {"text": "焼く", "is_correct": false, "explanation": "焼くは加熱する動作で、判断の意味にはならない。"}, {"text": "叩く", "is_correct": false, "explanation": "叩くは打つ動作で、本当かどうかを判断する文脈には合わない。"}], "explanations": {"見極められ": "「私には見極められない」の可能形で、判断できないという意味。正解。", "煮る": "煮るは調理の動作で、「私には〜ない」の判断の文脈に合わない。", "焼く": "焼くは加熱する動作で、判断の意味にはならない。", "叩く": "叩くは打つ動作で、本当かどうかを判断する文脈には合わない。"}, "sentence_index": 6, "correct_answer": "見極められ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、お茶碗を見極めた。", "explanation": "ここは〈洗う〉の意味。見極めは状態を判断して決めることで、水で汚れを落とす行為には使わない。"}, {"text": "毎朝、体重を見極める。", "explanation": "ここは〈測定〉の意味。見極めは判断を伴うので、数値を量るだけの場面では使わない。"}, {"text": "なくした財布を見極めた。", "explanation": "ここは〈見つける〉の意味。見極めるは判断して決めることで、偶然見つける場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41326, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "買う前に、くだものの鮮度に見極める。", "corrected_sentence": "買う前に、くだものの鮮度を見極める。", "error_description": "「見極める」の目的語には「を」を使う。「鮮度に見極める」は「に」が誤りで、「鮮度を見極める」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見極め", "is_correct": true, "explanation": "「見極めなさい」の形で、連用形が「なさい」に続く。正解。"}, {"text": "見極めた", "is_correct": false, "explanation": "過去形で、「なさい」には続かない。"}, {"text": "見極めて", "is_correct": false, "explanation": "テ形で、「なさい」の前には入らない。"}, {"text": "見極めない", "is_correct": false, "explanation": "否定形で、命令の「なさい」とは合わない。"}], "correct_form": "見極め", "base_form": "見極める", "form_label": "連用形", "sentence_index": 1, "explanations": {"見極め": "「見極めなさい」の形で、連用形が「なさい」に続く。正解。", "見極めた": "過去形で、「なさい」には続かない。", "見極めて": "テ形で、「なさい」の前には入らない。", "見極めない": "否定形で、命令の「なさい」とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41326, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "よく見極めたないで買ったので、失敗してしまった。", "corrected_sentence": "よく見極めないで買ったので、失敗してしまった。", "error_description": "「見極め」は「ないで」に続く形のまま。「見極めたない」は「た」が余計で、「見極めないで」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見極め", "is_correct": true, "explanation": "「よく見極めないで」の未然形で、「ないで」に続く。正解。"}, {"text": "見極める", "is_correct": false, "explanation": "基本形で、「ないで」の前には入らない。"}, {"text": "見極めれば", "is_correct": false, "explanation": "仮定形で、「ないで」とは続かない。"}, {"text": "見極めよう", "is_correct": false, "explanation": "意志形で、ここでは文が成り立たない。"}], "correct_form": "見極め", "base_form": "見極める", "form_label": "未然形", "sentence_index": 7, "explanations": {"見極め": "「よく見極めないで」の未然形で、「ないで」に続く。正解。", "見極める": "基本形で、「ないで」の前には入らない。", "見極めれば": "仮定形で、「ないで」とは続かない。", "見極めよう": "意志形で、ここでは文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41327, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「価値を見極める」の「を」で、見極める対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「価値が見極める目」では文の関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達や相手を示すが、「価値に見極める」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「価値へ見極める」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「価値を見極める」の「を」で、見極める対象を示す。正解。", "が": "「が」は主語を示すが、「価値が見極める目」では文の関係が成り立たない。", "に": "「に」は到達や相手を示すが、「価値に見極める」は成り立たない。", "へ": "「へ」は方向を示すが、「価値へ見極める」は不自然。"}, "error_tags": {"が": "主語", "に": "到達・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41327, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「本質を見極めないと」の「を」で、見極める対象を示す。正解。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所有や連体を示すが、「本質の見極めないと」では成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「本質と見極めないと」では文の関係が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここでは比べる対象がなく合わない。"}], "correct_answer": "を", "explanations": {"を": "「本質を見極めないと」の「を」で、見極める対象を示す。正解。", "の": "「の」は所有や連体を示すが、「本質の見極めないと」では成り立たない。", "と": "「と」は並列や相手を示すが、「本質と見極めないと」では文の関係が崩れる。", "より": "「より」は比較を示すが、ここでは比べる対象がなく合わない。"}, "error_tags": {"の": "所有・連体", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41327, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の本質や状態を、よく観察してはっきりと見定める。また、最後まで見届ける。", "primary_collocate": null, "pronunciation": "みきわめる", "ipa": "mikiwameɾɯ", "syllable_count": 5, "sentences": [{"text": "医者は症状の原因を慎重に見極めてから、治療方針を決めた。", "target_word": "見極めて", "complexity_tier": "T4", "furigana": "医者[いしゃ]は症状[しょうじょう]の原因[げんいん]を慎重[しんちょう]に見極[みきわ]めてから、治療方針[ちりょうほうしん]を決[き]めた。", "sentence_source": "generated"}, {"text": "投資では、会社の本当の価値を見極める目が必要だ。", "target_word": "見極める", "complexity_tier": "T4", "furigana": "投資[とうし]では、会社[かいしゃ]の本当[ほんとう]の価値[かち]を見極[みきわ]める目[め]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "市場の動きを見極めたうえで、新商品の発売日を決める。", "target_word": "見極めた", "complexity_tier": "T4", "furigana": "市場[しじょう]の動[うご]きを見極[みきわ]めたうえで、新商品[しんしょうひん]の発売日[はつばいび]を決[き]める。", "sentence_source": "generated"}, {"text": "彼がどんな人物か、しばらく付き合って見極めるつもりだ。", "target_word": "見極める", "complexity_tier": "T4", "furigana": "彼[かれ]がどんな人物[じんぶつ]か、しばらく付[つ]き合[あ]って見極[みきわ]めるつもりだ。", "sentence_source": "generated"}, {"text": "職人は木の質を見極め、一本ずつ使い道を決めている。", "target_word": "見極め", "complexity_tier": "T4", "furigana": "職人[しょくにん]は木[き]の質[しつ]を見極[みきわ]め、一本[いっぽん]ずつ使[つか]い道[みち]を決[き]めている。", "sentence_source": "generated"}, {"text": "事態の行方を最後まで見極めてから、結論を出したい。", "target_word": "見極めて", "complexity_tier": "T4", "furigana": "事態[じたい]の行方[ゆくえ]を最後[さいご]まで見極[みきわ]めてから、結論[けつろん]を出[だ]したい。", "sentence_source": "generated"}, {"text": "選手の才能を見極めるのは、コーチの大切な仕事だ。", "target_word": "見極める", "complexity_tier": "T4", "furigana": "選手[せんしゅ]の才能[さいのう]を見極[みきわ]めるのは、コーチの大切[たいせつ]な仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "物事の本質を見極めないと、表面の情報に振り回される。", "target_word": "見極め", "complexity_tier": "T4", "furigana": "物事[ものごと]の本質[ほんしつ]を見極[みきわ]めないと、表面[ひょうめん]の情報[じょうほう]に振[ふ]り回[まわ]される。", "sentence_source": "generated"}, {"text": "情勢を見極めるために、大使は現地に残った。", "target_word": "見極める", "complexity_tier": "T4", "furigana": "情勢[じょうせい]を見極[みきわ]めるために、大使[たいし]は現地[げんち]に残[のこ]った。", "sentence_source": "generated"}, {"text": "本物の骨董品かどうかを見極めるには、長年の経験が欠かせない。", "target_word": "見極める", "complexity_tier": "T4", "furigana": "本物[ほんもの]の骨董品[こっとうひん]かどうかを見極[みきわ]めるには、長年[ながねん]の経験[けいけん]が欠[か]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見極める", "label": "終止形"}, {"form": "見極めた", "label": "過去形"}, {"form": "見極めて", "label": "テ形"}, {"form": "見極めない", "label": "否定形"}, {"form": "見極めれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "本質や状態を観察して見定める、または最後まで見届ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41327, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見極めて", "is_correct": true, "explanation": "「慎重に見極めてから」で、原因を観察して見定めた後に次へ進む意味。正解。"}, {"text": "叩いて", "is_correct": false, "explanation": "叩くは打つ動作で、原因を見定める文脈には合わない。"}, {"text": "砕いて", "is_correct": false, "explanation": "砕くは細かくする動作で、ここでは意味が通らない。"}, {"text": "磨いて", "is_correct": false, "explanation": "磨くは表面をきれいにする動作で、原因の判断には使えない。"}], "explanations": {"見極めて": "「慎重に見極めてから」で、原因を観察して見定めた後に次へ進む意味。正解。", "叩いて": "叩くは打つ動作で、原因を見定める文脈には合わない。", "砕いて": "砕くは細かくする動作で、ここでは意味が通らない。", "磨いて": "磨くは表面をきれいにする動作で、原因の判断には使えない。"}, "sentence_index": 0, "correct_answer": "見極めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祭りの行列を見極めた。", "explanation": "ここは〈見物〉の意味。見極めるは本質や状態を見定めることで、楽しみに眺める場面では使わない。"}, {"text": "門の前で、大声で助けを見極めた。", "explanation": "ここは〈助けを呼ぶ〉の意味。見極めは対象の本質や正体を見定めることで、声をあげて人を呼ぶ行為には使わない。"}, {"text": "会場で音楽に合わせて見極めた。", "explanation": "ここは〈踊る〉の意味。見極めは本質や状態を見定めることで、体を動かす場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41327, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見極める", "is_correct": true, "explanation": "「選手の才能を見極めるのは」で、本質を見定める意味。正解。"}, {"text": "煮る", "is_correct": false, "explanation": "煮るは調理の動作で、選手の才能には使えない。"}, {"text": "洗う", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、才能を判断する文脈に合わない。"}, {"text": "焼く", "is_correct": false, "explanation": "焼くは加熱する動作で、人の才能を対象にはしない。"}], "explanations": {"見極める": "「選手の才能を見極めるのは」で、本質を見定める意味。正解。", "煮る": "煮るは調理の動作で、選手の才能には使えない。", "洗う": "洗うは汚れを落とす動作で、才能を判断する文脈に合わない。", "焼く": "焼くは加熱する動作で、人の才能を対象にはしない。"}, "sentence_index": 6, "correct_answer": "見極める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会場の入り口で、観客にうちわを見極めた。", "explanation": "ここは〈配る〉の意味。見極めは本質や状態を判断して決めることで、うちわを手渡す場面には使わない。"}, {"text": "夕焼けを見極めた。", "explanation": "ここは〈眺める〉の意味。見極めるは対象の本質を見定めることで、景色を楽しむ場面では使わない。"}, {"text": "夏休みに、プールで見極めた。", "explanation": "ここは〈泳ぐ〉の意味。見極めは状態を見定めることで、水中で体を動かす場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41327, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カメラマンは光の具合を慎重に見極めでから、撮影を始めた。", "corrected_sentence": "カメラマンは光の具合を慎重に見極めてから、撮影を始めた。", "error_description": "テ形の誤り。「見極める」のテ形は「見極めて」で、「見極めでから」は誤り。「見極めてから」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見極める", "is_correct": true, "explanation": "連体形で、「目」を修飾して「必要だ」に続く。正解。"}, {"text": "見極めれば", "is_correct": false, "explanation": "仮定形で、名詞「目」を修飾できない。"}, {"text": "見極めて", "is_correct": false, "explanation": "テ形で、名詞「目」を修飾できない。"}, {"text": "見極めよう", "is_correct": false, "explanation": "意志形で、名詞を修飾しない。"}], "correct_form": "見極める", "base_form": "見極める", "form_label": "連体形", "sentence_index": 1, "explanations": {"見極める": "連体形で、「目」を修飾して「必要だ」に続く。正解。", "見極めれば": "仮定形で、名詞「目」を修飾できない。", "見極めて": "テ形で、名詞「目」を修飾できない。", "見極めよう": "意志形で、名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41327, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チームの選手の才能に見極めるのは、コーチの大切な仕事だ。", "corrected_sentence": "チームの選手の才能を見極めるのは、コーチの大切な仕事だ。", "error_description": "「見極める」の目的語には「を」を使う。「才能に見極める」は「に」が誤りで、「才能を見極める」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見極め", "is_correct": true, "explanation": "未然形で、「ないと」に続く。正解。"}, {"text": "見極めます", "is_correct": false, "explanation": "丁寧形で、「ないと」には続けられない。"}, {"text": "見極めず", "is_correct": false, "explanation": "文語の否定形で、「ないと」とは続かない。"}, {"text": "見極めよ", "is_correct": false, "explanation": "命令形で、ここでは文が成り立たない。"}], "correct_form": "見極め", "base_form": "見極める", "form_label": "未然形", "sentence_index": 7, "explanations": {"見極め": "未然形で、「ないと」に続く。正解。", "見極めます": "丁寧形で、「ないと」には続けられない。", "見極めず": "文語の否定形で、「ないと」とは続かない。", "見極めよ": "命令形で、ここでは文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41328, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「酵母は生き物なので」の「は」で、酵母を話題として示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語を示すもので、「酵母を生き物なので」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は目的地や相手を示し、「酵母に生き物なので」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「酵母へ生き物なので」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「酵母は生き物なので」の「は」で、酵母を話題として示す。正解。", "を": "「を」は動作の目的語を示すもので、「酵母を生き物なので」では文が成り立たない。", "に": "「に」は目的地や相手を示し、「酵母に生き物なので」は意味が通らない。", "へ": "「へ」は方向を示し、「酵母へ生き物なので」は成り立たない。"}, "error_tags": {"を": "目的語の「を」は話題の位置に入らない", "に": "相手・場所の「に」は話題の位置に入らない", "へ": "方向の「へ」は話題の位置に入らない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41328, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「酵母が糖を食べると」の「が」で、酵母を食べる動作の主語として示す。正解。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すもので、「酵母で糖を食べると」では主語の位置に入らず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「酵母から糖を食べると」では主語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、「酵母より糖を食べると」では主語の位置に入らず意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「酵母が糖を食べると」の「が」で、酵母を食べる動作の主語として示す。正解。", "で": "「で」は手段や場所を示すもので、「酵母で糖を食べると」では主語の位置に入らず不自然。", "から": "「から」は起点を示し、「酵母から糖を食べると」では主語として成り立たない。", "より": "「より」は比較を示し、「酵母より糖を食べると」では主語の位置に入らず意味が通らない。"}, "error_tags": {"で": "手段・場所の「で」は主語の位置に入らない", "から": "起点の「から」は主語の位置に入らない", "より": "比較の「より」は主語の位置に入らない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41328, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンやお酒を作るときに使う、小さな生き物です。", "primary_collocate": null, "pronunciation": "こうぼ", "ipa": "koːbo", "syllable_count": 3, "sentences": [{"text": "パンを作るときは、酵母を使います。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "パンを作[つく]るときは、酵母[こうぼ]を使[つか]います。", "sentence_source": "generated"}, {"text": "酵母は生き物なので、ぬるま湯で溶かしてから使います。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "酵母[こうぼ]は生き物[いきもの]なので、ぬるま湯[ぬるまゆ]で溶[と]かしてから使[つか]います。", "sentence_source": "generated"}, {"text": "この酵母は、お酒を作る工場で使われています。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "この酵母[こうぼ]は、お酒[さけ]を作[つく]る工場[こうじょう]で使[つか]われています。", "sentence_source": "generated"}, {"text": "酵母を入れると、生地が大きくふくらみます。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "酵母[こうぼ]を入[い]れると、生地[きじ]が大[おお]きくふくらみます。", "sentence_source": "generated"}, {"text": "酵母は目に見えないほど小さいです。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "酵母[こうぼ]は目[め]に見[み]えないほど小[ちい]さいです。", "sentence_source": "generated"}, {"text": "冷蔵庫に入れた酵母は、あまり働きません。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]に入[い]れた酵母[こうぼ]は、あまり働[はたら]きません。", "sentence_source": "generated"}, {"text": "祖母は自分で酵母を育てて、パンを焼きます。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "祖母[そぼ]は自分[じぶん]で酵母[こうぼ]を育[そだ]てて、パンを焼[や]きます。", "sentence_source": "generated"}, {"text": "酵母が糖を食べると、ガスが出ます。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "酵母[こうぼ]が糖[とう]を食[た]べると、ガスが出[で]ます。", "sentence_source": "generated"}, {"text": "古い酵母は元気がなくて、パンがふくらみませんでした。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "古[ふる]い酵母[こうぼ]は元気[げんき]がなくて、パンがふくらみませんでした。", "sentence_source": "generated"}, {"text": "ビールにも酵母が使われています。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "ビールにも酵母[こうぼ]が使[つか]われています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "酵母", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "パンやお酒を作る発酵に使う微生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41328, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酵母", "is_correct": true, "explanation": "「パンを作るときは、___を使います」の目的語として入る名詞。正解。"}, {"text": "焼く", "is_correct": false, "explanation": "動詞の辞書形。「を使います」の目的語にはならず、文が成り立たない。"}, {"text": "焼いて", "is_correct": false, "explanation": "て形の動詞。目的語の位置には入らず、文が途中で切れる。"}, {"text": "使える", "is_correct": false, "explanation": "可能形の動詞。名詞の位置に入らず、「を使います」とつながらない。"}], "explanations": {"酵母": "「パンを作るときは、___を使います」の目的語として入る名詞。正解。", "焼く": "動詞の辞書形。「を使います」の目的語にはならず、文が成り立たない。", "焼いて": "て形の動詞。目的語の位置には入らず、文が途中で切れる。", "使える": "可能形の動詞。名詞の位置に入らず、「を使います」とつながらない。"}, "sentence_index": 0, "correct_answer": "酵母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪の原因になる酵母を、手洗いで予防します。", "explanation": "ここは〈ウイルス〉の意味。風邪などを起こす病原体を指し、パンやお酒を作る微生物の酵母とは違うので合わない。"}, {"text": "まな板は熱湯で酵母を消毒して、食中毒を防ぎます。", "explanation": "ここは〈細菌〉の意味。食中毒の原因になる細菌を指し、パンやお酒を作る微生物の酵母とは違う。"}, {"text": "窓の結露に生えた酵母を、アルコールで拭き取ります。", "explanation": "ここは〈カビ〉の意味。湿気で生えて広がる菌を指し、パンをふくらませる酵母とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41328, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酵母", "is_correct": true, "explanation": "「祖母は自分で___を育てて」の目的語として入る名詞。正解。"}, {"text": "作る", "is_correct": false, "explanation": "動詞の辞書形。「を育てて」の目的語にはならず、文が崩れる。"}, {"text": "作って", "is_correct": false, "explanation": "て形の動詞。目的語の位置には入らない。"}, {"text": "焼け", "is_correct": false, "explanation": "命令形。名詞の位置に入らず、「を育てて」とつながらない。"}], "explanations": {"酵母": "「祖母は自分で___を育てて」の目的語として入る名詞。正解。", "作る": "動詞の辞書形。「を育てて」の目的語にはならず、文が崩れる。", "作って": "て形の動詞。目的語の位置には入らない。", "焼け": "命令形。名詞の位置に入らず、「を育てて」とつながらない。"}, "sentence_index": 6, "correct_answer": "酵母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お腹の中で酵母が暴れて、痛くなりました。", "explanation": "ここは〈寄生虫〉の意味。体に住みついて害を与える生き物を指し、パンやお酒を作る酵母とは違うので合わない。"}, {"text": "チーズの表面に酵母が青く生えています。", "explanation": "ここは〈カビ〉の意味。表面に青く広がる菌を指し、パンをふくらませる酵母とは違うので合わない。"}, {"text": "パンに酵母が生えてしまいました。", "explanation": "ここは〈カビ〉の意味。生えて広がるのはカビで、パンをふくらませる酵母が生える場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41328, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "酵母を量を増やすと、パンがよくふくらみます。", "corrected_sentence": "酵母の量を増やすと、パンがよくふくらみます。", "error_description": "「量」は「酵母の」で修飾する。「酵母を量」の「を」は「の」にすべき。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41328, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "酵母を使いて、パンを焼きました。", "corrected_sentence": "酵母を使って、パンを焼きました。", "error_description": "「使う」のて形は「使って」。「使いて」は活用を誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41330, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「オーブンから」は出どころを表し、「取り出す・出す」に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点を示すため、「オーブンにピザを出した」は出どころが示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先の方向を表すので、出どころを示す文には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「オーブンよりピザを出した」は意味が通らない。"}], "correct_answer": "から", "explanations": {"から": "「オーブンから」は出どころを表し、「取り出す・出す」に合う。", "に": "「に」は到着点を示すため、「オーブンにピザを出した」は出どころが示せず不自然。", "へ": "「へ」は行き先の方向を表すので、出どころを示す文には合わない。", "より": "「より」は比較を表すので、「オーブンよりピザを出した」は意味が通らない。"}, "error_tags": {"に": "帰着点", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41330, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「オーブンでじゃがいもを焼く」の「で」。焼く行為の道具・場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「オーブンをじゃがいもを焼く」は目的語が二つになり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を表すため、「オーブンとじゃがいもを焼く」は道具を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点を示すため、焼く場所を表す「で」の代わりにはならず、不自然。"}], "correct_answer": "で", "explanations": {"で": "「オーブンでじゃがいもを焼く」の「で」。焼く行為の道具・場所を表す。", "を": "「オーブンをじゃがいもを焼く」は目的語が二つになり不自然。", "と": "「と」は並列・共同を表すため、「オーブンとじゃがいもを焼く」は道具を示せない。", "に": "「に」は到着点を示すため、焼く場所を表す「で」の代わりにはならず、不自然。"}, "error_tags": {"を": "目的語", "と": "並列・共同", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41330, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物を焼いたり料理したりするための、箱形で中が熱くなる台所の道具。", "primary_collocate": null, "pronunciation": "おーぶん", "ipa": "oːbɯɴ", "syllable_count": 4, "sentences": [{"text": "オーブンでクッキーを焼きました。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "オーブンでクッキーを焼[や]きました。", "sentence_source": "generated"}, {"text": "母がオーブンからピザを出した。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "母[はは]がオーブンからピザを出[だ]した。", "sentence_source": "generated"}, {"text": "オーブンの中は、とても熱いです。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "オーブンの中[なか]は、とても熱[あつ]いです。", "sentence_source": "generated"}, {"text": "日曜日に、家のオーブンでケーキを作った。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に、家[いえ]のオーブンでケーキを作[つく]った。", "sentence_source": "generated"}, {"text": "オーブンのスイッチを入れると、中が赤く光る。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "オーブンのスイッチを入[い]れると、中[なか]が赤[あか]く光[ひか]る。", "sentence_source": "generated"}, {"text": "パンがオーブンの中でふくらんできた。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "パンがオーブンの中[なか]でふくらんできた。", "sentence_source": "generated"}, {"text": "熱いので、オーブンにさわってはいけません。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "熱[あつ]いので、オーブンにさわってはいけません。", "sentence_source": "generated"}, {"text": "姉はオーブンでじゃがいもを焼いてくれた。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "姉[あね]はオーブンでじゃがいもを焼[や]いてくれた。", "sentence_source": "generated"}, {"text": "このオーブンは小さいけれど、よく焼ける。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "このオーブンは小[ちい]さいけれど、よく焼[や]ける。", "sentence_source": "generated"}, {"text": "オーブンからいいにおいがして、おなかがすいた。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "オーブンからいいにおいがして、おなかがすいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オーブン", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "パン・ケーキ・肉などを焼くための、箱形で中が熱くなる台所の道具。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41330, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オーブン", "is_correct": true, "explanation": "「オーブンでクッキーを焼く」の形。パンやクッキーを焼く調理器具を表し、文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は物を冷やす道具で、クッキーを焼く手段としては合わない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機はごみを吸う家電で、焼く動作の道具にはならない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は衣類を洗う機械で、「でクッキーを焼きました」の道具としては成り立たない。"}], "explanations": {"オーブン": "「オーブンでクッキーを焼く」の形。パンやクッキーを焼く調理器具を表し、文脈に合う。", "冷蔵庫": "冷蔵庫は物を冷やす道具で、クッキーを焼く手段としては合わない。", "掃除機": "掃除機はごみを吸う家電で、焼く動作の道具にはならない。", "洗濯機": "洗濯機は衣類を洗う機械で、「でクッキーを焼きました」の道具としては成り立たない。"}, "sentence_index": 0, "correct_answer": "オーブン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の休みに、オーブンの中で涼みながら昼寝をした。", "explanation": "ここは〈涼む〉の場面。オーブンは熱い調理器具なので、涼む場所としては使わない。"}, {"text": "この店は、オーブンで新しいお客さんを迎えている。", "explanation": "ここは〈迎える〉の場面。オーブンは調理器具なので、人を迎える意味では使わない。"}, {"text": "雨が降ってきたので、オーブンを傘代わりにして帰った。", "explanation": "ここは〈雨具〉の場面。オーブンは調理器具なので、傘の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41330, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オーブン", "is_correct": true, "explanation": "「熱いので、オーブンにさわってはいけません」の対象。熱くなる調理器具で、理由と合う。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は本を置く家具で、「熱いので」の理由と結びつかない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は座るための布製品で、熱さの理由に合う対象ではない。"}, {"text": "体重計", "is_correct": false, "explanation": "体重計は体重を量る道具で、熱いから触ってはいけないという文脈に合わない。"}], "explanations": {"オーブン": "「熱いので、オーブンにさわってはいけません」の対象。熱くなる調理器具で、理由と合う。", "本棚": "本棚は本を置く家具で、「熱いので」の理由と結びつかない。", "座布団": "座布団は座るための布製品で、熱さの理由に合う対象ではない。", "体重計": "体重計は体重を量る道具で、熱いから触ってはいけないという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "オーブン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな音に驚いて、妹はオーブンの中に隠れた。", "explanation": "ここは〈隠れる〉の場面。オーブンは熱い調理器具なので、身を隠す場所としては使わない。"}, {"text": "妹はオーブンを抱いて、大きな声で歌った。", "explanation": "ここは〈歌う〉の場面。オーブンは調理器具なので、抱いて歌うという使い方はしない。"}, {"text": "夜道で疲れた彼は、オーブンを枕にして、ぐっすり眠った。", "explanation": "ここは〈眠る〉の場面。オーブンは調理器具なので、枕の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41330, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父がオーブンにアップルパイを取り出した。", "corrected_sentence": "祖父がオーブンからアップルパイを取り出した。", "error_description": "「取り出す」は出どころを「から」で表す。「に」は到着点を示すので誤り。正しくは「オーブンから」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41330, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母はオーブンを前で、いつも鼻歌を歌っている。", "corrected_sentence": "祖母はオーブンの前で、いつも鼻歌を歌っている。", "error_description": "「前」の場所を示すには「の」が必要。「を」は目的語になってしまい、文が成り立たない。正しくは「オーブンの前で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
