INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41331, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「オーブンで鶏肉を焼く」の「で」。手段や道具を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「オーブンへ鶏肉を焼き」では方向の「へ」が焼く手段を示せず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「オーブンから鶏肉を焼き」では起点の「から」が焼く手段に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「オーブンより鶏肉を焼き」では比較の「より」が文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "「オーブンで鶏肉を焼く」の「で」。手段や道具を示す格助詞。", "へ": "「オーブンへ鶏肉を焼き」では方向の「へ」が焼く手段を示せず、不自然。", "から": "「オーブンから鶏肉を焼き」では起点の「から」が焼く手段に合わない。", "より": "「オーブンより鶏肉を焼き」では比較の「より」が文脈に合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41331, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食材を内部の熱で加熱調理するための、密閉された加熱器具。天火。", "primary_collocate": null, "pronunciation": "おーぶん", "ipa": "oːbɯɴ", "syllable_count": 4, "sentences": [{"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "オーブン", "complexity_tier": "T4", "furigana": "高温[こうおん]のオーブンへ投入[とうにゅう]された瞬間[しゅんかん]、生地[きじ]は熱[ねつ]エネルギーによって急激[きゅうげき]に膨張[ぼうちょう]します。", "sentence_source": "mined"}, {"text": "焼く前に、オーブンの予熱を待った。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "焼[や]く前[まえ]に、オーブンの予熱[よねつ]を待[ま]った。", "sentence_source": "generated"}, {"text": "料理を始める前に、オーブンを180度に温めておきます。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "料理[りょうり]を始[はじ]める前[まえ]に、オーブンを180度[ど]に温[あたた]めておきます。", "sentence_source": "generated"}, {"text": "このオーブンは、パンもクッキーも上手に焼ける。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "このオーブンは、パンもクッキーも上手[じょうず]に焼[や]ける。", "sentence_source": "generated"}, {"text": "オーブンの中でチーズがとけて、いい匂いがしてきた。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "オーブンの中[なか]でチーズがとけて、いい匂[にお]いがしてきた。", "sentence_source": "generated"}, {"text": "焼き上がったら、熱いオーブンから天板を取り出すときに気をつけてください。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "焼[や]き上[あ]がったら、熱[あつ]いオーブンから天板[てんばん]を取[と]り出[だ]すときに気[き]をつけてください。", "sentence_source": "generated"}, {"text": "古いオーブンが壊れたので、新しいものを買うことにした。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "古[ふる]いオーブンが壊[こわ]れたので、新[あたら]しいものを買[か]うことにした。", "sentence_source": "generated"}, {"text": "母はオーブンで鶏肉を焼き、野菜も一緒に入れた。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "母[はは]はオーブンで鶏肉[とりにく]を焼[や]き、野菜[やさい]も一緒[いっしょ]に入[い]れた。", "sentence_source": "generated"}, {"text": "オーブンの扉を開けると、熱い空気が顔にあたった。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "オーブンの扉[とびら]を開[あ]けると、熱[あつ]い空気[くうき]が顔[かお]にあたった。", "sentence_source": "generated"}, {"text": "電子レンジとちがって、オーブンは食べ物をじっくり焼ける。", "target_word": "オーブン", "complexity_tier": "T3", "furigana": "電子[でんし]レンジとちがって、オーブンは食[た]べ物[もの]をじっくり焼[や]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オーブン", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "パンや肉などを内部の熱で焼く、密閉式の調理器具（天火）。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41331, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オーブン", "is_correct": true, "explanation": "食材を高温で加熱する器具として、文の流れに合う正解。"}, {"text": "掃除機", "is_correct": false, "explanation": "「掃除機」は床のごみを吸う器具で、高温で加熱する場所にはならない。"}, {"text": "扇風機", "is_correct": false, "explanation": "「扇風機」は風を送る器具で、加熱する器具としては合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫」は食材を冷やす器具で、高温の加熱には使えない。"}], "explanations": {"オーブン": "食材を高温で加熱する器具として、文の流れに合う正解。", "掃除機": "「掃除機」は床のごみを吸う器具で、高温で加熱する場所にはならない。", "扇風機": "「扇風機」は風を送る器具で、加熱する器具としては合わない。", "冷蔵庫": "「冷蔵庫」は食材を冷やす器具で、高温の加熱には使えない。"}, "sentence_index": 0, "correct_answer": "オーブン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の間、牛乳をオーブンで冷やして保存した。", "explanation": "ここは〈冷蔵庫〉の意味。オーブンは食材を加熱する器具で、冷やして保存する機能は持たないので合わない。"}, {"text": "床のごみを、オーブンで吸い取った。", "explanation": "ここは〈掃除機〉の意味。オーブンは加熱調理の器具で、ごみを吸い取る機能はないので合わない。"}, {"text": "朝、お米をオーブンで炊いた。", "explanation": "ここは〈炊飯器〉の意味。オーブンは食材を焼く器具で、米を炊く調理はできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41331, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オーブン", "is_correct": true, "explanation": "古くなって壊れた加熱器具で、買い替える流れに合う正解。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書」は壊れて買い替える対象として文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "「座布団」は壊れて買い替える対象としては不自然。"}, {"text": "帽子", "is_correct": false, "explanation": "「帽子」は壊れて買い替える文脈としては不自然。"}], "explanations": {"オーブン": "古くなって壊れた加熱器具で、買い替える流れに合う正解。", "教科書": "「教科書」は壊れて買い替える対象として文脈に合わない。", "座布団": "「座布団」は壊れて買い替える対象としては不自然。", "帽子": "「帽子」は壊れて買い替える文脈としては不自然。"}, "sentence_index": 6, "correct_answer": "オーブン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末、汚れた服をオーブンで洗った。", "explanation": "ここは〈洗濯機〉の意味。オーブンは加熱器具で、衣類を洗う機能は持たないので合わない。"}, {"text": "朝、オーブンでお湯を沸かした。", "explanation": "ここは〈電気ポット〉の意味。オーブンは食材を熱で焼く器具で、お湯を沸かす用途には使わないので合わない。"}, {"text": "オーブンで、部屋を涼しくした。", "explanation": "ここは〈扇風機〉の意味。オーブンは加熱調理の器具で、室内を涼しくする機能はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41331, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パンを焼くため、オーブンへ温めた。", "corrected_sentence": "パンを焼くため、オーブンを温めた。", "error_description": "「温める」の目的語は「を」で示す。「へ」は方向を表すため、「オーブンへ温めた」は不自然。正しくは「オーブンを温めた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41331, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末、クッキーをオーブンを焼いた。", "corrected_sentence": "週末、クッキーをオーブンで焼いた。", "error_description": "「オーブン」は焼く道具を示すので「で」が正しい。「を」では、オーブンを焼く対象になってしまい不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
