INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41332, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食べ物を口に入れたときの、口の中の感じ。", "primary_collocate": null, "pronunciation": "しょっかん", "ipa": "ɕokkaɴ", "syllable_count": 4, "sentences": [{"text": "このパンは外がかたくて、中は柔らかい食感だ。", "target_word": "食感", "complexity_tier": "T3", "furigana": "このパンは外[そと]がかたくて、中[なか]は柔[やわ]らかい食感[しょっかん]だ。", "sentence_source": "generated"}, {"text": "ゼリーのつるっとした食感が好きだ。", "target_word": "食感", "complexity_tier": "T3", "furigana": "ゼリーのつるっとした食感[しょっかん]が好[す]きだ。", "sentence_source": "generated"}, {"text": "新しいお菓子は、サクサクした食感で人気がある。", "target_word": "食感", "complexity_tier": "T3", "furigana": "新[あたら]しいお菓子[かし]は、サクサクした食感[しょっかん]で人気[にんき]がある。", "sentence_source": "generated"}, {"text": "湿気たせんべいは食感が悪くなり、食べる気がしない。", "target_word": "食感", "complexity_tier": "T3", "furigana": "湿気[しっけ]たせんべいは食感[しょっかん]が悪[わる]くなり、食[た]べる気[き]がしない。", "sentence_source": "generated"}, {"text": "味は同じでも、食感がちがうと別の食べ物のようだ。", "target_word": "食感", "complexity_tier": "T3", "furigana": "味[あじ]は同[おな]じでも、食感[しょっかん]がちがうと別[べつ]の食[た]べ物[もの]のようだ。", "sentence_source": "generated"}, {"text": "この店のうどんは、もちもちした食感が自慢だ。", "target_word": "食感", "complexity_tier": "T3", "furigana": "この店[みせ]のうどんは、もちもちした食感[しょっかん]が自慢[じまん]だ。", "sentence_source": "generated"}, {"text": "ナッツを入れると、食感が楽しくなる。", "target_word": "食感", "complexity_tier": "T3", "furigana": "ナッツを入[い]れると、食感[しょっかん]が楽[たの]しくなる。", "sentence_source": "generated"}, {"text": "豆腐は味が薄いが、なめらかな食感がおいしい。", "target_word": "食感", "complexity_tier": "T3", "furigana": "豆腐[とうふ]は味[あじ]が薄[うす]いが、なめらかな食感[しょっかん]がおいしい。", "sentence_source": "generated"}, {"text": "子どもは野菜のぐにゃっとした食感をいやがる。", "target_word": "食感", "complexity_tier": "T3", "furigana": "子[こ]どもは野菜[やさい]のぐにゃっとした食感[しょっかん]をいやがる。", "sentence_source": "generated"}, {"text": "冷凍すると、果物の食感が変わってしまう。", "target_word": "食感", "complexity_tier": "T3", "furigana": "冷凍[れいとう]すると、果物[くだもの]の食感[しょっかん]が変[か]わってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食感", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "食べ物を口に入れたときの口の中の感じ全般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41332, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食感", "is_correct": true, "explanation": "「柔らかい食感」は、口に入れたときの感じを表すので文に合う。"}, {"text": "温度", "is_correct": false, "explanation": "「柔らかい温度」は、食べ物の温かさや冷たさを表すので、柔らかさを説明する文には合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「柔らかい値段」は意味をなさず、パンの中の感じを表す文には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「柔らかい季節」は意味をなさず、パンの食べ心地を表す文には合わない。"}], "explanations": {"食感": "「柔らかい食感」は、口に入れたときの感じを表すので文に合う。", "温度": "「柔らかい温度」は、食べ物の温かさや冷たさを表すので、柔らかさを説明する文には合わない。", "値段": "「柔らかい値段」は意味をなさず、パンの中の感じを表す文には合わない。", "季節": "「柔らかい季節」は意味をなさず、パンの食べ心地を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "食感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この毛布は、食感がとても気持ちいい。", "explanation": "ここは〈感触〉の意味と取り違えている。触ったときの感じに使う語で、口に入れた感じの〈食感〉とは合わない。"}, {"text": "この飴は食感が甘い。", "explanation": "ここは〈味〉の意味と取り違えている。「甘い」は味の性質を表し、〈食感〉は硬さや歯ごたえなど口の中の感じを指すので、甘さの説明には使えない。"}, {"text": "この部屋は食感が広い。", "explanation": "ここは〈空間の感じ〉の意味と取り違えている。部屋の広さは空間の性質で、食べ物を口に入れたときの感じを指す〈食感〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41332, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食感", "is_correct": true, "explanation": "「楽しくなる」と合うのは口の中の感じを表す〈食感〉。ナッツを入れると口の中の感じが変わる。"}, {"text": "体重", "is_correct": false, "explanation": "「体重が楽しくなる」は意味をなさず、ナッツを入れた食べ物の話には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢が楽しくなる」は意味をなさず、食べ物の話には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が楽しくなる」は食べ物の感じを表す文には合わない。"}], "explanations": {"食感": "「楽しくなる」と合うのは口の中の感じを表す〈食感〉。ナッツを入れると口の中の感じが変わる。", "体重": "「体重が楽しくなる」は意味をなさず、ナッツを入れた食べ物の話には合わない。", "年齢": "「年齢が楽しくなる」は意味をなさず、食べ物の話には合わない。", "天気": "「天気が楽しくなる」は食べ物の感じを表す文には合わない。"}, "sentence_index": 6, "correct_answer": "食感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷凍すると、紅茶の食感が変わってしまう。", "explanation": "ここは〈香り〉の意味と取り違えている。香りは鼻で感じるもので、口の中の硬さなどを指す〈食感〉とは合わない。"}, {"text": "冷凍すると、店の食感が変わってしまう。", "explanation": "「店の評判」は世間のうわさの意味。食べたときの口の感じを表す〈食感〉とは合わない。"}, {"text": "このカーテンは食感が変わってしまう。", "explanation": "ここは〈手ざわり〉の意味と取り違えている。布などを触った感じを指す語で、食べ物の口の感じには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41332, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このクラッカーは食感をさくさくして、おいしい。", "corrected_sentence": "このクラッカーは食感がさくさくして、おいしい。", "error_description": "「食感」は主語なので「が」で示す。「を」では「さくさくして」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41332, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このヨーグルトは、なめらかな食感を特徴だ。", "corrected_sentence": "このヨーグルトは、なめらかな食感が特徴だ。", "error_description": "「食感」には「が」を付けて主語を示すのが正しい。「を」では「特徴だ」につながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
