INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41333, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食物を口に入れたときに感じる、硬さや柔らかさ、歯ごたえなどの触覚的な印象。", "primary_collocate": null, "pronunciation": "しょっかん", "ipa": "ɕokkaɴ", "syllable_count": 4, "sentences": [{"text": "このクッキーは歯ごたえのある食感で、よくかんで食べる。", "target_word": "食感", "complexity_tier": "T3", "furigana": "このクッキーは歯[は]ごたえのある食感[しょっかん]で、よくかんで食[た]べる。", "sentence_source": "generated"}, {"text": "煮すぎた野菜は、食感がなくなってしまった。", "target_word": "食感", "complexity_tier": "T3", "furigana": "煮[に]すぎた野菜[やさい]は、食感[しょっかん]がなくなってしまった。", "sentence_source": "generated"}, {"text": "ステーキは焼き方で、肉の食感が大きく変わる。", "target_word": "食感", "complexity_tier": "T3", "furigana": "ステーキは焼[や]き方[かた]で、肉[にく]の食感[しょっかん]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "年を取ると、かたい食感のものが食べにくくなる。", "target_word": "食感", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、かたい食感[しょっかん]のものが食[た]べにくくなる。", "sentence_source": "generated"}, {"text": "シェフは、パリッとした食感を出すために油の温度に気をつけた。", "target_word": "食感", "complexity_tier": "T3", "furigana": "シェフは、パリッとした食感[しょっかん]を出[だ]すために油[あぶら]の温度[おんど]に気[き]をつけた。", "sentence_source": "generated"}, {"text": "グミのような弾力のある食感が若者に受けている。", "target_word": "食感", "complexity_tier": "T3", "furigana": "グミのような弾力[だんりょく]のある食感[しょっかん]が若者[わかもの]に受[う]けている。", "sentence_source": "generated"}, {"text": "米の種類によって食感が少しずつ違う。", "target_word": "食感", "complexity_tier": "T3", "furigana": "米[こめ]の種類[しゅるい]によって食感[しょっかん]が少[すこ]しずつ違[ちが]う。", "sentence_source": "generated"}, {"text": "柔らかすぎる食感は、私には物足りない。", "target_word": "食感", "complexity_tier": "T3", "furigana": "柔[やわ]らかすぎる食感[しょっかん]は、私[わたし]には物足[ものた]りない。", "sentence_source": "generated"}, {"text": "麺のこしの強さは、食感を決める大切な点だ。", "target_word": "食感", "complexity_tier": "T3", "furigana": "麺[めん]のこしの強[つよ]さは、食感[しょっかん]を決[き]める大切[たいせつ]な点[てん]だ。", "sentence_source": "generated"}, {"text": "この新製品は、とろけるような食感が特徴だ。", "target_word": "食感", "complexity_tier": "T3", "furigana": "この新製品[しんせいひん]は、とろけるような食感[しょっかん]が特徴[とくちょう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食感", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "硬さ・柔らかさ・歯ごたえなど触覚で感じる食べ物の印象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41333, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食感", "is_correct": true, "explanation": "「歯ごたえのある食感」は、かむときの口の中の感じを表すので文に合う。"}, {"text": "温度", "is_correct": false, "explanation": "「歯ごたえのある温度」は意味をなさず、クッキーのかみごたえを表す文には合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「歯ごたえのある値段」は意味をなさず、食べ方の説明には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「歯ごたえのある季節」は意味をなさず、食べ方の説明には合わない。"}], "explanations": {"食感": "「歯ごたえのある食感」は、かむときの口の中の感じを表すので文に合う。", "温度": "「歯ごたえのある温度」は意味をなさず、クッキーのかみごたえを表す文には合わない。", "値段": "「歯ごたえのある値段」は意味をなさず、食べ方の説明には合わない。", "季節": "「歯ごたえのある季節」は意味をなさず、食べ方の説明には合わない。"}, "sentence_index": 0, "correct_answer": "食感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絹のショールは、食感が柔らかくて肌に心地よい。", "explanation": "ここは〈手ざわり〉の意味と取り違えている。布などを触った感じを表す語で、食べ物を口に入れた感じの〈食感〉とは合わない。"}, {"text": "年を取ると、熱い食感のものが食べにくくなる。", "explanation": "ここは〈温度〉の意味と取り違えている。食感は硬さや歯ごたえなど触覚の印象で、熱さは含まないので合わない。"}, {"text": "年を取ると、安い食感のものが買いにくくなる。", "explanation": "ここは〈値段〉の意味と取り違えている。「安い」は値段の性質で、噛んだときの硬さや歯ごたえを指す〈食感〉には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41333, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食感", "is_correct": true, "explanation": "「米の種類によって食感が少しずつ違う」は、口に入れたときの感じの違いを表すので文に合う。"}, {"text": "体重", "is_correct": false, "explanation": "「米の種類によって体重が少しずつ違う」は意味をなさず、食べたときの感じを表す文には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢が少しずつ違う」は米の種類の説明には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が少しずつ違う」は米の種類の説明には合わない。"}], "explanations": {"食感": "「米の種類によって食感が少しずつ違う」は、口に入れたときの感じの違いを表すので文に合う。", "体重": "「米の種類によって体重が少しずつ違う」は意味をなさず、食べたときの感じを表す文には合わない。", "年齢": "「年齢が少しずつ違う」は米の種類の説明には合わない。", "天気": "「天気が少しずつ違う」は米の種類の説明には合わない。"}, "sentence_index": 6, "correct_answer": "食感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新製品は、食感のよい香りが特徴だ。", "explanation": "ここは〈香り〉の意味と取り違えている。香りは鼻で感じるもので、噛んだときの硬さや歯ごたえを指す〈食感〉とは合わない。"}, {"text": "この新製品は、食感の高い評判が特徴だ。", "explanation": "ここは〈評判〉の意味と取り違えている。評判は世間の評価で、食べたときの感じを表す〈食感〉とは別の語になる。"}, {"text": "この新製品は、食感の明るい色が特徴だ。", "explanation": "ここは〈色〉の意味と取り違えている。色は目で見るもので、触覚的な印象を表す〈食感〉には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41333, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "焼きたてのクッキーは、さくっとした食感を魅力だ。", "corrected_sentence": "焼きたてのクッキーは、さくっとした食感が魅力だ。", "error_description": "「食感」は主語なので「が」で示す。「を」では「魅力だ」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41333, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店のパンは、もっちりした食感を評判だ。", "corrected_sentence": "この店のパンは、もっちりした食感が評判だ。", "error_description": "「食感」は主語なので「が」で示す。「を」では「評判だ」とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41334, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「風味がよくなる」の主語を示す「が」が正解です。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「風味をよくなる」とは結びつかません。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を示し、「風味によくなる」は不自然で文に合いません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「よくなる」の主語の位置には入りません。"}], "correct_answer": "が", "explanations": {"が": "「風味がよくなる」の主語を示す「が」が正解です。", "を": "「を」は目的語を示すため、「風味をよくなる」とは結びつかません。", "に": "「に」は相手や帰着点を示し、「風味によくなる」は不自然で文に合いません。", "へ": "「へ」は方向を示すので、「よくなる」の主語の位置には入りません。"}, "error_tags": {"を": "目的語", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41334, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41334, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "食べ物や飲み物の、口に入れたときの感じや香りのことです。", "primary_collocate": null, "pronunciation": "ふうみ", "ipa": "ɸɯːmi", "syllable_count": 3, "sentences": [{"text": "このお茶は、さわやかな風味がします。", "target_word": "風味", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]は、さわやかな風味[ふうみ]がします。", "sentence_source": "generated"}, {"text": "レモンを入れると、魚の風味がよくなります。", "target_word": "風味", "complexity_tier": "T3", "furigana": "レモンを入[い]れると、魚[さかな]の風味[ふうみ]がよくなります。", "sentence_source": "generated"}, {"text": "風味のいいコーヒー豆を買いました。", "target_word": "風味", "complexity_tier": "T3", "furigana": "風味[ふうみ]のいいコーヒー豆[まめ]を買[か]いました。", "sentence_source": "generated"}, {"text": "長く置いたら、パンの風味が落ちてしまいました。", "target_word": "風味", "complexity_tier": "T3", "furigana": "長[なが]く置[お]いたら、パンの風味[ふうみ]が落[お]ちてしまいました。", "sentence_source": "generated"}, {"text": "バターの風味が強くて、クッキーがおいしいです。", "target_word": "風味", "complexity_tier": "T3", "furigana": "バターの風味[ふうみ]が強[つよ]くて、クッキーがおいしいです。", "sentence_source": "generated"}, {"text": "この店のスープは、野菜の風味を大切にしています。", "target_word": "風味", "complexity_tier": "T3", "furigana": "この店[みせ]のスープは、野菜[やさい]の風味[ふうみ]を大切[たいせつ]にしています。", "sentence_source": "generated"}, {"text": "冷たくすると、ジュースの風味が弱くなります。", "target_word": "風味", "complexity_tier": "T3", "furigana": "冷[つめ]たくすると、ジュースの風味[ふうみ]が弱[よわ]くなります。", "sentence_source": "generated"}, {"text": "ハーブを加えて、料理に風味を出しました。", "target_word": "風味", "complexity_tier": "T3", "furigana": "ハーブを加[くわ]えて、料理[りょうり]に風味[ふうみ]を出[だ]しました。", "sentence_source": "generated"}, {"text": "風味がよいので、そのまま食べても十分おいしいです。", "target_word": "風味", "complexity_tier": "T3", "furigana": "風味[ふうみ]がよいので、そのまま食[た]べても十分[じゅうぶん]おいしいです。", "sentence_source": "generated"}, {"text": "古い油を使うと、天ぷらの風味が悪くなります。", "target_word": "風味", "complexity_tier": "T3", "furigana": "古[ふる]い油[あぶら]を使[つか]うと、天[てん]ぷらの風味[ふうみ]が悪[わる]くなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風味", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "食べ物や飲み物の味わいと香りの全体的な感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41334, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風味", "is_correct": true, "explanation": "「さわやかな風味がする」は飲み物の味や香りの感じを表し、文に合います。"}, {"text": "材料", "is_correct": false, "explanation": "材料は料理を作るときに使う物を指すため、「さわやかな材料がします」とは言えません。"}, {"text": "産地", "is_correct": false, "explanation": "産地は生産された場所のことで、口に入れたときの感じを表さないので合いません。"}, {"text": "包装", "is_correct": false, "explanation": "包装は商品を包む物や方法を指すため、香りや味の感じには使えません。"}], "explanations": {"風味": "「さわやかな風味がする」は飲み物の味や香りの感じを表し、文に合います。", "材料": "材料は料理を作るときに使う物を指すため、「さわやかな材料がします」とは言えません。", "産地": "産地は生産された場所のことで、口に入れたときの感じを表さないので合いません。", "包装": "包装は商品を包む物や方法を指すため、香りや味の感じには使えません。"}, "sentence_index": 0, "correct_answer": "風味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラベンダーの花畑で、風味がとても強くて気持ちがいいです。", "explanation": "花畑の香りは食べ物や飲み物ではないので、この語の意味の範囲外です。風味は口に入れる食べ物や飲み物の感じを指します。"}, {"text": "彼は風味がある人で、みんなに好かれています。", "explanation": "ここは〈人柄〉の意味です。風味は食べ物や飲み物の感じを表すので、人の性格には使いません。"}, {"text": "この古い書店は、落ち着いた風味があって、長居したくなります。", "explanation": "ここは〈雰囲気〉の意味です。風味は食べ物や飲み物の感じを指すので、店の雰囲気には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41334, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風味", "is_correct": true, "explanation": "「風味が弱くなる」は飲み物の味や香りの強さが変わることを表し、文に合います。"}, {"text": "温度", "is_correct": false, "explanation": "温度は熱さや冷たさの度合いを指すので、「ジュースの温度が弱くなる」は味の強さの変化を表さず合いません。"}, {"text": "容器", "is_correct": false, "explanation": "容器は中身を入れる入れ物のことで、ジュースの味の強さが変わるという意味では使えません。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格のことで、ジュースの味の強さとは関係がないので合いません。"}], "explanations": {"風味": "「風味が弱くなる」は飲み物の味や香りの強さが変わることを表し、文に合います。", "温度": "温度は熱さや冷たさの度合いを指すので、「ジュースの温度が弱くなる」は味の強さの変化を表さず合いません。", "容器": "容器は中身を入れる入れ物のことで、ジュースの味の強さが変わるという意味では使えません。", "値段": "値段は価格のことで、ジュースの味の強さとは関係がないので合いません。"}, "sentence_index": 6, "correct_answer": "風味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このセーターは、やわらかい風味があって、気持ちがいいです。", "explanation": "ここは〈手触り〉の意味です。風味は食べ物や飲み物の感じを指すので、布の感触には使いません。"}, {"text": "このギターは、深い風味の音が出ます。", "explanation": "ここは〈音色〉の意味です。風味は飲食物の味や香りに使い、楽器の音には使いません。"}, {"text": "この服は風味がおしゃれで、気に入りました。", "explanation": "ここは〈見た目〉の意味です。風味は食べ物や飲み物の感じで、服の見た目には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41334, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このお茶は、さわやかな風味が感じます。", "corrected_sentence": "このお茶は、さわやかな風味を感じます。", "error_description": "「感じる」は目的語に「を」を取るので、「風味が」は「風味を」にする必要があります。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41334, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このスープに風味を買いました。", "corrected_sentence": "このスープに風味を出しました。", "error_description": "「風味を出す」が正しい組み合わせです。「買う」は風味と結びつかないので、「出しました」にする必要があります。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41336, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "出資先を示す格助詞で、「ベンチャーに出資する」が自然な形。"}, {"text": "を", "is_correct": false, "explanation": "「出資する」の相手を「を」で示すと不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すので、出資先を示す位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すが、出資先の示し方としては不自然になる。"}], "correct_answer": "に", "explanations": {"に": "出資先を示す格助詞で、「ベンチャーに出資する」が自然な形。", "を": "「出資する」の相手を「を」で示すと不自然になる。", "で": "手段や場所を表すので、出資先を示す位置には入らない。", "と": "相手や並列を表すが、出資先の示し方としては不自然になる。"}, "error_tags": {"を": "目的語の取り違え", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41336, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "助けるの目的語を示す「を」で、「ベンチャーを助けた」が自然。"}, {"text": "に", "is_correct": false, "explanation": "受け手を示すと「ベンチャーに助けた」となり、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、助けた対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を表すので、助けた対象を示す位置には入らない。"}], "correct_answer": "を", "explanations": {"を": "助けるの目的語を示す「を」で、「ベンチャーを助けた」が自然。", "に": "受け手を示すと「ベンチャーに助けた」となり、不自然になる。", "へ": "方向を表すので、助けた対象を示せない。", "より": "比較の基準を表すので、助けた対象を示す位置には入らない。"}, "error_tags": {"に": "受け手・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41336, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "新しく事業を始めたばかりの会社のこと。", "primary_collocate": null, "pronunciation": "べんちゃー", "ipa": "bentɕaː", "syllable_count": 4, "sentences": [{"text": "彼は将来性を信じて、友人のベンチャーに資金を出した。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "彼[かれ]は将来性[しょうらいせい]を信[しん]じて、友人[ゆうじん]のベンチャーに資金[しきん]を出[だ]した。", "sentence_source": "generated"}, {"text": "ベンチャーに出資する人は、失敗する危険も覚悟している。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "ベンチャーに出資[しゅっし]する人[ひと]は、失敗[しっぱい]する危険[きけん]も覚悟[かくご]している。", "sentence_source": "generated"}, {"text": "大きな会社が、小さなベンチャーを支援する計画を発表した。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "大[おお]きな会社[かいしゃ]が、小[ちい]さなベンチャーを支援[しえん]する計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "彼女は貯金の一部を、新しいベンチャーに投じた。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は貯金[ちょきん]の一部[いちぶ]を、新[あたら]しいベンチャーに投[とう]じた。", "sentence_source": "generated"}, {"text": "ベンチャーは成功すれば大きな利益を生むが、失敗すれば資金を失う。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "ベンチャーは成功[せいこう]すれば大[おお]きな利益[りえき]を生[う]むが、失敗[しっぱい]すれば資金[しきん]を失[うしな]う。", "sentence_source": "generated"}, {"text": "市は若者のベンチャーを応援するため、補助金を用意した。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "市[し]は若者[わかもの]のベンチャーを応援[おうえん]するため、補助金[ほじょきん]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "新しい技術を持つベンチャーに、多くの投資家が注目している。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]を持[も]つベンチャーに、多[おお]くの投資家[とうしか]が注目[ちゅうもく]している。", "sentence_source": "generated"}, {"text": "父は退職金で、知り合いのベンチャーを助けた。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "父[ちち]は退職金[たいしょくきん]で、知[し]り合[あ]いのベンチャーを助[たす]けた。", "sentence_source": "generated"}, {"text": "資金が足りず、ベンチャーを始めた若者たちは苦労した。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "資金[しきん]が足[た]りず、ベンチャーを始[はじ]めた若者[わかもの]たちは苦労[くろう]した。", "sentence_source": "generated"}, {"text": "銀行は、リスクの高いベンチャーには簡単にお金を貸さない。", "target_word": "ベンチャー", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]は、リスクの高[たか]いベンチャーには簡単[かんたん]にお金[かね]を貸[か]さない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベンチャー", "label": "基本形"}, {"form": "ベンチャーの", "label": "連体形"}, {"form": "ベンチャーに", "label": "に格形"}], "register": "neutral", "sense_fingerprint": "新しく事業を始めたばかりの会社や事業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41336, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ベンチャー", "is_correct": true, "explanation": "新しく事業を起こす会社を指し、資金を出す相手として自然に入る。"}, {"text": "倒産", "is_correct": false, "explanation": "経営が行き詰まって潰れることで、資金を出す対象にはならない。"}, {"text": "廃業", "is_correct": false, "explanation": "事業をやめることで、将来性を信じて出資する文脈と合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "従業員を辞めさせることで、出資先の意味とは別。"}], "explanations": {"ベンチャー": "新しく事業を起こす会社を指し、資金を出す相手として自然に入る。", "倒産": "経営が行き詰まって潰れることで、資金を出す対象にはならない。", "廃業": "事業をやめることで、将来性を信じて出資する文脈と合わない。", "解雇": "従業員を辞めさせることで、出資先の意味とは別。"}, "sentence_index": 0, "correct_answer": "ベンチャー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場はベンチャーの老舗で、創業から百年を超える。", "explanation": "「大手企業」の意味でベンチャーを使っているが、ベンチャーは新しく事業を始めた会社を指すので、創業百年の会社には使えない。"}, {"text": "週末に家族でベンチャーの旅に出かけ、山で一泊した。", "explanation": "英語の冒険の意味を借りて旅行に使っている。ベンチャーは事業や会社の話に使う語で、旅には使わない。"}, {"text": "この市役所はベンチャーで、住民の手続きを受け付けている。", "explanation": "「行政機関」の意味でベンチャーを使っているが、ベンチャーは新しく事業を始める会社を指すので、市役所には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41336, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ベンチャー", "is_correct": true, "explanation": "新興企業を指し、投資家が注目する対象として合う。"}, {"text": "不良債権", "is_correct": false, "explanation": "回収できない貸付金の意味で、注目される新技術とは噛み合わない。"}, {"text": "不況", "is_correct": false, "explanation": "景気の悪さを表す語で、特定の企業を指せない。"}, {"text": "手形", "is_correct": false, "explanation": "支払いの約束を示す証書で、技術に注目する文脈と合わない。"}], "explanations": {"ベンチャー": "新興企業を指し、投資家が注目する対象として合う。", "不良債権": "回収できない貸付金の意味で、注目される新技術とは噛み合わない。", "不況": "景気の悪さを表す語で、特定の企業を指せない。", "手形": "支払いの約束を示す証書で、技術に注目する文脈と合わない。"}, "sentence_index": 6, "correct_answer": "ベンチャー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はベンチャーで休んで、友達と話した。", "explanation": "「ベンチ」の意味でベンチャーを使っているが、ベンチャーは事業を始める会社やその資金を指すので、座る場所には使えない。"}, {"text": "彼は難しい試験のベンチャーに臨んで、高得点を取った。", "explanation": "〈挑戦〉の意味でベンチャーを使っているが、ベンチャーは事業を始める会社やその資金を指すので、試験の挑戦には使えない。"}, {"text": "庭のベンチャーが毎朝、花に水をやっている。", "explanation": "〈庭師〉の意味でベンチャーを使っているが、ベンチャーは事業を始める会社やその資金を指す語なので、人の職業には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41336, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は将来性を信じて、友人のベンチャーを資金を提供した。", "corrected_sentence": "彼は将来性を信じて、友人のベンチャーに資金を提供した。", "error_description": "「ベンチャーを」は誤り。資金を提供する相手は「に」で示すので、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41336, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい技術を持つベンチャーを、多くの投資家が関心を寄せている。", "corrected_sentence": "新しい技術を持つベンチャーに、多くの投資家が関心を寄せている。", "error_description": "「ベンチャーを」は誤り。「関心を寄せる」は対象を「に」で示すので、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41338, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「十分なキャピタルがない」と、存在の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「ない」は存在を表すので「を」は取らない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を示すが、存在の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「ない」の対象として合わない。"}], "correct_answer": "が", "explanations": {"が": "「十分なキャピタルがない」と、存在の対象を示す。", "を": "目的語を示すが、「ない」は存在を表すので「を」は取らない。", "に": "帰着点を示すが、存在の対象にはならない。", "へ": "方向を示すが、「ない」の対象として合わない。"}, "error_tags": {"を": "目的語", "に": "帰着", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41338, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「退職金をキャピタルにする」と、元手として使う意味を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「して」の主語にはならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、目的語が二つになり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、元手にするという文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「退職金をキャピタルにする」と、元手として使う意味を示す。", "が": "主語を示すが、「して」の主語にはならない。", "を": "目的語を示すが、目的語が二つになり文が成り立たない。", "へ": "方向を示すが、元手にするという文には合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41338, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もとでに なる おかね。", "primary_collocate": null, "pronunciation": "きゃぴたる", "ipa": "kjapitaɾɯ", "syllable_count": 4, "sentences": [{"text": "店を開くために、まずキャピタルを集めました。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "店[みせ]を開[ひら]くために、まずキャピタルを集[あつ]めました。", "sentence_source": "generated"}, {"text": "新しい会社には、十分なキャピタルがないと続けられません。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "新[あたら]しい会社[かいしゃ]には、十分[じゅうぶん]なキャピタルがないと続[つづ]けられません。", "sentence_source": "generated"}, {"text": "キャピタルが少ないので、小さな店から始めます。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "キャピタルが少[すく]ないので、小[ちい]さな店[みせ]から始[はじ]めます。", "sentence_source": "generated"}, {"text": "友だちは自分のキャピタルを全部使って、カフェを開きました。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "友[とも]だちは自分[じぶん]のキャピタルを全部[ぜんぶ]使[つか]って、カフェを開[ひら]きました。", "sentence_source": "generated"}, {"text": "銀行からキャピタルを借りて、工場を建てました。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]からキャピタルを借[か]りて、工場[こうじょう]を建[た]てました。", "sentence_source": "generated"}, {"text": "事業が大きくなるにつれて、もっと多くのキャピタルが必要になりました。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "事業[じぎょう]が大[おお]きくなるにつれて、もっと多[おお]くのキャピタルが必要[ひつよう]になりました。", "sentence_source": "generated"}, {"text": "キャピタルがなくなって、会社は新しい機械を買えなくなりました。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "キャピタルがなくなって、会社[かいしゃ]は新[あたら]しい機械[きかい]を買[か]えなくなりました。", "sentence_source": "generated"}, {"text": "父は退職金をキャピタルにして、小さな店を始めました。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "父[ちち]は退職金[たいしょくきん]をキャピタルにして、小[ちい]さな店[みせ]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "投資家がキャピタルを出してくれることになり、計画が進みました。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "投資家[とうしか]がキャピタルを出[だ]してくれることになり、計画[けいかく]が進[すす]みました。", "sentence_source": "generated"}, {"text": "少ないキャピタルでも、よい計画があれば会社は始められます。", "target_word": "キャピタル", "complexity_tier": "T3", "furigana": "少[すく]ないキャピタルでも、よい計画[けいかく]があれば会社[かいしゃ]は始[はじ]められます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "キャピタル", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "事業や商売を始めるときの元手になる資金（資本）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41338, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "キャピタル", "is_correct": true, "explanation": "「まずキャピタルを集める」で、事業を始めるための元手の資金を指すので自然。"}, {"text": "ゴール", "is_correct": false, "explanation": "目標地点の意味で、集める対象にならない。"}, {"text": "ストレス", "is_correct": false, "explanation": "心の負担の意味で、集めて使うものではない。"}, {"text": "ひげ", "is_correct": false, "explanation": "体の一部で、店を開く準備として集める対象にならない。"}], "explanations": {"キャピタル": "「まずキャピタルを集める」で、事業を始めるための元手の資金を指すので自然。", "ゴール": "目標地点の意味で、集める対象にならない。", "ストレス": "心の負担の意味で、集めて使うものではない。", "ひげ": "体の一部で、店を開く準備として集める対象にならない。"}, "sentence_index": 0, "correct_answer": "キャピタル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は最後のキャピタルを振り絞って、テストの最後まで集中しました。", "explanation": "ここは〈集中力〉と取り違えた例。キャピタルは元手になるお金の意味なので、集中力を振り絞るという文脈には合わない。"}, {"text": "祖父はキャピタルを使い果たして、山の頂上にたどり着きました。", "explanation": "ここは〈体力〉と取り違えた例。キャピタルはお金で、体力の意味では使わない。"}, {"text": "兄はキャピタルを使い果たして、論文を書き上げました。", "explanation": "ここは〈時間〉と取り違えた例。キャピタルは時間を表さないので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41338, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "キャピタル", "is_correct": true, "explanation": "資金がなくなって機械が買えなくなる、という文の主語に自然に入る。"}, {"text": "ドレス", "is_correct": false, "explanation": "衣服の一種で、会社の資金の話には合わない。"}, {"text": "ユーモア", "is_correct": false, "explanation": "人の性質で、機械が買えなくなる理由にならない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓の布で、会社の資金が尽きる文に合わない。"}], "explanations": {"キャピタル": "資金がなくなって機械が買えなくなる、という文の主語に自然に入る。", "ドレス": "衣服の一種で、会社の資金の話には合わない。", "ユーモア": "人の性質で、機械が買えなくなる理由にならない。", "カーテン": "窓の布で、会社の資金が尽きる文に合わない。"}, "sentence_index": 6, "correct_answer": "キャピタル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "キャピタルが豊富なので、歴史の質問に何でも答えられます。", "explanation": "ここは〈知識〉と取り違えた例。キャピタルは元手になるお金の意味で、歴史の質問に答える知識の豊かさとは結びつかない。"}, {"text": "キャピタルが少なくても、努力すれば上達できます。", "explanation": "ここは〈才能〉と取り違えた例。キャピタルは資金なので、技能の上達とは結びつかない。"}, {"text": "キャピタルをたくさん覚えると、本が読みやすくなります。", "explanation": "ここは〈語彙〉と取り違えた例。キャピタルは資金の意味で、覚える対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41338, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は、キャピタルを足りなくて、新しい機械を買えませんでした。", "corrected_sentence": "会社は、キャピタルが足りなくて、新しい機械を買えませんでした。", "error_description": "「足りない」は主語を「が」で示す。「を」は目的語を示すので誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41338, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父はキャピタルを集まって、店を開きました。", "corrected_sentence": "父はキャピタルを集めて、店を開きました。", "error_description": "「集まる」は目的語を取らない自動詞。他動詞の「集める」を使うのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41340, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『調達が難しい』の主語で、『難しい』の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "『難しい』は目的語を取らないので、『を』は不自然。"}, {"text": "の", "is_correct": false, "explanation": "『資金の調達』の『の』は修飾に使うもので、ここでは主語の位置を埋められない。"}, {"text": "へ", "is_correct": false, "explanation": "『調達へ難しい』は方向の意味になり、主語の働きとして成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『調達が難しい』の主語で、『難しい』の主語として正しい。", "を": "『難しい』は目的語を取らないので、『を』は不自然。", "の": "『資金の調達』の『の』は修飾に使うもので、ここでは主語の位置を埋められない。", "へ": "『調達へ難しい』は方向の意味になり、主語の働きとして成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41340, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『機械を調達する』の目的語。『調達する』は物を目的語にするので正しい。"}, {"text": "に", "is_correct": false, "explanation": "『機械に調達する』は相手や場所の意味になり、ここには合わない。"}, {"text": "で", "is_correct": false, "explanation": "『機械で調達する』は手段の意味になり、文の意味が変わる。"}, {"text": "と", "is_correct": false, "explanation": "『機械と調達する』は並列になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『機械を調達する』の目的語。『調達する』は物を目的語にするので正しい。", "に": "『機械に調達する』は相手や場所の意味になり、ここには合わない。", "で": "『機械で調達する』は手段の意味になり、文の意味が変わる。", "と": "『機械と調達する』は並列になり、文が成り立たない。"}, "error_tags": {"に": "相手・場所", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41340, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "必要なものを集めること。", "primary_collocate": null, "pronunciation": "ちょうたつ", "ipa": "tɕoːtatsɯ", "syllable_count": 4, "sentences": [{"text": "祭りの準備のために、必要な道具を調達した。", "target_word": "調達", "complexity_tier": "T3", "furigana": "まつりのじゅんびのために、ひつようなどうぐをちょうたつした。", "sentence_source": "generated"}, {"text": "資金の調達が難しくて、計画が止まった。", "target_word": "調達", "complexity_tier": "T3", "furigana": "しきんのちょうたつがむずかしくて、けいかくがとまった。", "sentence_source": "generated"}, {"text": "登山の前に、食料を調達しておくことになった。", "target_word": "調達", "complexity_tier": "T3", "furigana": "とざんのまえに、しょくりょうをちょうたつしておくことになった。", "sentence_source": "generated"}, {"text": "災害のとき、水を調達できる場所を確認しておく。", "target_word": "調達", "complexity_tier": "T3", "furigana": "さいがいのとき、みずをちょうたつできるばしょをかくにんしておく。", "sentence_source": "generated"}, {"text": "店を開くお金を、銀行から調達した。", "target_word": "調達", "complexity_tier": "T3", "furigana": "みせをひらくおかねを、ぎんこうからちょうたつした。", "sentence_source": "generated"}, {"text": "材料の調達が遅れたので、工事が始まらなかった。", "target_word": "調達", "complexity_tier": "T3", "furigana": "ざいりょうのちょうたつがおくれたので、こうじがはじまらなかった。", "sentence_source": "generated"}, {"text": "キャンプでは、薪を近くの森で調達する。", "target_word": "調達", "complexity_tier": "T3", "furigana": "きゃんぷでは、まきをちかくのもりでちょうたつする。", "sentence_source": "generated"}, {"text": "新しい機械を調達するため、会社は予算を増やした。", "target_word": "調達", "complexity_tier": "T3", "furigana": "あたらしいきかいをちょうたつするため、かいしゃはよさんをふやした。", "sentence_source": "generated"}, {"text": "必要な部品を海外から調達している工場もある。", "target_word": "調達", "complexity_tier": "T3", "furigana": "ひつようなぶひんをかいがいからちょうたつしているこうじょうもある。", "sentence_source": "generated"}, {"text": "全員分の制服を調達するのに、二週間かかった。", "target_word": "調達", "complexity_tier": "T3", "furigana": "ぜんいんぶんのせいふくをちょうたつするのに、にしゅうかんかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "調達", "label": "基本形"}, {"form": "調達する", "label": "する動詞"}, {"form": "調達した", "label": "過去形"}, {"form": "調達して", "label": "て形"}, {"form": "調達しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "必要な物や資金を用意して集める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41340, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "調達", "is_correct": true, "explanation": "必要な道具を集めて用意するという意味で、ここに入る。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、道具を対象にしないので文が成り立たない。"}, {"text": "応援", "is_correct": false, "explanation": "応援は人や団体を支える行為で、道具には使わない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まりを終わらせることで、道具を用意する文脈に合わない。"}], "explanations": {"調達": "必要な道具を集めて用意するという意味で、ここに入る。", "散歩": "散歩は歩くことで、道具を対象にしないので文が成り立たない。", "応援": "応援は人や団体を支える行為で、道具には使わない。", "解散": "解散は集まりを終わらせることで、道具を用意する文脈に合わない。"}, "sentence_index": 0, "correct_answer": "調達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "災害のとき、避難計画を調達しておく。", "explanation": "ここは〈作成〉の意味。避難計画は作るもので、調達は物や資金を集める意味なので合わない。"}, {"text": "二人のあいだの誤解を調達した。", "explanation": "ここは〈解消〉の意味。誤解は解くものなので、物を集める〈調達〉とは合わない。"}, {"text": "提案の内容を調達して、会議で話し合った。", "explanation": "ここは〈検討〉の意味。提案は検討するもので、調達は物や資金に使う語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41340, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "調達", "is_correct": true, "explanation": "薪など必要なものを集めるという意味で、ここに入る。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は楽器や曲を奏でることで、薪を対象にしない。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は生まれることで、物を対象にする動詞ではない。"}, {"text": "通院", "is_correct": false, "explanation": "通院は病院に通うことで、薪を対象にしない。"}], "explanations": {"調達": "薪など必要なものを集めるという意味で、ここに入る。", "演奏": "演奏は楽器や曲を奏でることで、薪を対象にしない。", "誕生": "誕生は生まれることで、物を対象にする動詞ではない。", "通院": "通院は病院に通うことで、薪を対象にしない。"}, "sentence_index": 6, "correct_answer": "調達"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の議事録を調達するのに、二週間かかった。", "explanation": "ここは〈整理〉の意味。議事録は整えるもので、調達は物や資金を集める意味なので合わない。"}, {"text": "制服のデザインを調達するため、三回も話し合った。", "explanation": "ここは〈改善〉の意味。デザインは良くするもので、調達とは合わない。"}, {"text": "制服の着用ルールを調達するため、全員を集めた。", "explanation": "ここは〈説明〉の意味。ルールは説明するもので、調達は物や資金を集める意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41340, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食料を調達で、登山の準備を終えた。", "corrected_sentence": "食料を調達して、登山の準備を終えた。", "error_description": "『調達で』は誤り。正しくは『調達して』。『調達する』のて形『調達して』で文を続けるので、『で』では続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41340, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "予算が足りず、新しい機械の調達を遅れた。", "corrected_sentence": "予算が足りず、新しい機械の調達が遅れた。", "error_description": "『調達を遅れた』は誤り。正しくは『調達が遅れた』。『遅れる』は『〜が遅れる』と取るので、調達には『が』が必要。『を』だと目的語になり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41342, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「増えている」の主語を示す。若い人たちのスタートアップが増える、という文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「増える」は自動詞なので「を」は取らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「増える」と結びつかず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「増える」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「増えている」の主語を示す。若い人たちのスタートアップが増える、という文になる。", "を": "目的語を示すが、「増える」は自動詞なので「を」は取らない。", "と": "並列や相手を示すが、「増える」と結びつかず文が成り立たない。", "へ": "方向を示すが、「増える」の主語にはならない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41342, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「スタートアップの社長」と、会社に属する人を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「スタートアップが社長は」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、社長とは結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、社長を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「スタートアップの社長」と、会社に属する人を示す。", "が": "主語を示すが、「スタートアップが社長は」では意味が通らない。", "を": "目的語を示すが、社長とは結びつかない。", "へ": "方向を示すが、社長を修飾できない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41342, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "新しく立ち上げた、成長をめざす若い会社。", "primary_collocate": null, "pronunciation": "すたーとあっぷ", "ipa": "sɯtaːtoappɯ", "syllable_count": 7, "sentences": [{"text": "彼は大学を出てすぐ、スタートアップを立ち上げました。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]を出[で]てすぐ、スタートアップを立[た]ち上[あ]げました。", "sentence_source": "generated"}, {"text": "この町には、若い人たちのスタートアップが増えています。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "この町[まち]には、若[わか]い人[ひと]たちのスタートアップが増[ふ]えています。", "sentence_source": "generated"}, {"text": "スタートアップは、小さな会社から大きく成長することがあります。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "スタートアップは、小[ちい]さな会社[かいしゃ]から大[おお]きく成長[せいちょう]することがあります。", "sentence_source": "generated"}, {"text": "姉はスタートアップで働いていて、毎日とても忙しいです。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "姉[あね]はスタートアップで働[はたら]いていて、毎日[まいにち]とても忙[いそが]しいです。", "sentence_source": "generated"}, {"text": "スタートアップの資金を集めるため、投資家に会いました。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "スタートアップの資金[しきん]を集[あつ]めるため、投資家[とうしか]に会[あ]いました。", "sentence_source": "generated"}, {"text": "スタートアップは社員が少ないので、一人ひとりの仕事が大切です。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "スタートアップは社員[しゃいん]が少[すく]ないので、一人[ひとり]ひとりの仕事[しごと]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "このスタートアップは、アプリで野菜を売る新しい会社です。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "このスタートアップは、アプリで野菜[やさい]を売[う]る新[あたら]しい会社[かいしゃ]です。", "sentence_source": "generated"}, {"text": "スタートアップの社長は、まだ二十五歳です。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "スタートアップの社長[しゃちょう]は、まだ二十五歳[にじゅうごさい]です。", "sentence_source": "generated"}, {"text": "スタートアップを成功させるには、よいアイデアと仲間が必要です。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "スタートアップを成功[せいこう]させるには、よいアイデアと仲間[なかま]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "失敗を恐れずにスタートアップに挑戦する若者が、増えました。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を恐[おそ]れずにスタートアップに挑戦[ちょうせん]する若者[わかもの]が、増[ふ]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スタートアップ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "新しく立ち上げた、成長をめざす若い会社（起業・新興企業）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41342, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スタートアップ", "is_correct": true, "explanation": "「立ち上げる」の目的語として、新しく始めた若い会社を指すので自然。"}, {"text": "ハンモック", "is_correct": false, "explanation": "吊るして寝る道具で、会社を立ち上げるとは言えない。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "食品で、会社の立ち上げの対象にならない。"}, {"text": "ドライヤー", "is_correct": false, "explanation": "髪を乾かす道具で、会社を立ち上げる文に合わない。"}], "explanations": {"スタートアップ": "「立ち上げる」の目的語として、新しく始めた若い会社を指すので自然。", "ハンモック": "吊るして寝る道具で、会社を立ち上げるとは言えない。", "ヨーグルト": "食品で、会社の立ち上げの対象にならない。", "ドライヤー": "髪を乾かす道具で、会社を立ち上げる文に合わない。"}, "sentence_index": 0, "correct_answer": "スタートアップ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場は創業六十年で、地域の仕事を長く支えてきたスタートアップです。", "explanation": "ここは〈町工場〉と取り違えた例。スタートアップは設立してまもない会社を指すので、創業六十年の工場には合わない。"}, {"text": "この店は百年続く老舗で、スタートアップとして知られています。", "explanation": "ここは〈伝統ある店〉の意味と取り違えた例。スタートアップは設立してまもない会社を指すので、百年続く店には合わない。"}, {"text": "この会社は社員が一万人もいる大企業で、スタートアップとして有名です。", "explanation": "ここは〈大手〉の意味と取り違えた例。スタートアップは少人数で始まった若い会社なので、社員一万人の会社には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41342, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スタートアップ", "is_correct": true, "explanation": "野菜を売る新しい会社を指す語として、この文の主語に自然に入る。"}, {"text": "カーペット", "is_correct": false, "explanation": "床に敷く布製品で、野菜を売る会社の説明にならない。"}, {"text": "ブーメラン", "is_correct": false, "explanation": "投げて戻る遊具で、会社を表す文に合わない。"}, {"text": "ソファ", "is_correct": false, "explanation": "座る家具で、アプリで野菜を売る会社とは結びつかない。"}], "explanations": {"スタートアップ": "野菜を売る新しい会社を指す語として、この文の主語に自然に入る。", "カーペット": "床に敷く布製品で、野菜を売る会社の説明にならない。", "ブーメラン": "投げて戻る遊具で、会社を表す文に合わない。", "ソファ": "座る家具で、アプリで野菜を売る会社とは結びつかない。"}, "sentence_index": 6, "correct_answer": "スタートアップ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父が四十年営んでいる八百屋は、地元で親しまれるスタートアップです。", "explanation": "ここは〈個人商店〉と取り違えた例。スタートアップは設立してまもない会社を指すので、四十年続く八百屋には合わない。"}, {"text": "この大学は創立百年を超えるスタートアップで、毎年多くの学生が入学します。", "explanation": "ここは〈名門〉と取り違えた例。スタートアップは若い会社なので、創立百年を超える大学には合わない。"}, {"text": "この店は地元で長く愛されるスタートアップで、毎日行列ができます。", "explanation": "ここは〈名店〉と取り違えた例。スタートアップは新しく始めた会社なので、長く愛される店には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41342, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちは去年、スタートアップに立ち上げました。", "corrected_sentence": "友だちは去年、スタートアップを立ち上げました。", "error_description": "「立ち上げる」は目的語を「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41342, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹はスタートアップを働いている。", "corrected_sentence": "妹はスタートアップで働いている。", "error_description": "「働く」は場所を「で」で示す自動詞。目的語を示す「を」は誤りで、正しくは「で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41344, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『経営がうまくいかない』の主語で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "『うまくいかない』は目的語を取らないので、『を』は不自然。"}, {"text": "の", "is_correct": false, "explanation": "『経営のうまくいかず』は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『経営へうまくいかず』は方向の意味になり、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『経営がうまくいかない』の主語で、正しい。", "を": "『うまくいかない』は目的語を取らないので、『を』は不自然。", "の": "『経営のうまくいかず』は文法的に成り立たない。", "へ": "『経営へうまくいかず』は方向の意味になり、文が成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41344, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41344, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "会社や店などを運営して、続けていくこと。", "primary_collocate": null, "pronunciation": "けいえい", "ipa": "keːeː", "syllable_count": 4, "sentences": [{"text": "父は小さな店の経営を三十年続けている。", "target_word": "経営", "complexity_tier": "T3", "furigana": "ちちはちいさなみせのけいえいをさんじゅうねんつづけている。", "sentence_source": "generated"}, {"text": "経営がうまくいかず、会社は店を閉めた。", "target_word": "経営", "complexity_tier": "T3", "furigana": "けいえいがうまくいかず、かいしゃはみせをしめた。", "sentence_source": "generated"}, {"text": "彼女は若いのに、会社を経営している。", "target_word": "経営", "complexity_tier": "T3", "furigana": "かのじょはわかいのに、かいしゃをけいえいしている。", "sentence_source": "generated"}, {"text": "新しい社長は、無駄をなくして経営を立て直した。", "target_word": "経営", "complexity_tier": "T3", "furigana": "あたらしいしゃちょうは、むだをなくしてけいえいをたてなおした。", "sentence_source": "generated"}, {"text": "経営が安定してから、社員の給料を上げた。", "target_word": "経営", "complexity_tier": "T3", "furigana": "けいえいがあんていしてから、しゃいんのきゅうりょうをあげた。", "sentence_source": "generated"}, {"text": "兄は大学で、会社の経営について学んでいる。", "target_word": "経営", "complexity_tier": "T3", "furigana": "あにはだいがくで、かいしゃのけいえいについてまなんでいる。", "sentence_source": "generated"}, {"text": "旅館を経営する夫婦が、地元の食材を使っている。", "target_word": "経営", "complexity_tier": "T3", "furigana": "りょかんをけいえいするふうふが、じもとのしょくざいをつかっている。", "sentence_source": "generated"}, {"text": "売り上げが減ったので、経営の方針を見直すことになった。", "target_word": "経営", "complexity_tier": "T3", "furigana": "うりあげがへったので、けいえいのほうしんをみなおすことになった。", "sentence_source": "generated"}, {"text": "祖母が経営していた食堂を、母が受け継いだ。", "target_word": "経営", "complexity_tier": "T3", "furigana": "そぼがけいえいしていたしょくどうを、ははがうけついだ。", "sentence_source": "generated"}, {"text": "経営を任された弟は、毎晩遅くまで帳簿を見ている。", "target_word": "経営", "complexity_tier": "T3", "furigana": "けいえいをまかされたおとうとは、まいばんおそくまでちょうぼをみている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "経営", "label": "基本形"}, {"form": "経営する", "label": "する動詞"}, {"form": "経営した", "label": "過去形"}, {"form": "経営して", "label": "て形"}, {"form": "経営しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "会社や店を運営して続けていく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41344, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "経営", "is_correct": true, "explanation": "会社や店を運営して続けるという意味で、ここに入る。"}, {"text": "子育て", "is_correct": false, "explanation": "子育ては子どもを育てることで、店を対象にしない。"}, {"text": "留学", "is_correct": false, "explanation": "留学は外国で学ぶことで、店には使わない。"}, {"text": "夜景", "is_correct": false, "explanation": "夜景は夜の景色で、店の仕事を指さない。"}], "explanations": {"経営": "会社や店を運営して続けるという意味で、ここに入る。", "子育て": "子育ては子どもを育てることで、店を対象にしない。", "留学": "留学は外国で学ぶことで、店には使わない。", "夜景": "夜景は夜の景色で、店の仕事を指さない。"}, "sentence_index": 0, "correct_answer": "経営"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手術後の経営を、医師が毎日見守った。", "explanation": "ここは〈経過〉の意味。経営は会社や店を運営する意味で、病状の推移には使わない。"}, {"text": "寺では、経営を読んでから食事をする。", "explanation": "ここは〈経典〉（仏教の教えの書物）の意味。経営は会社を運営する意味なので、書物を指す語としては使わない。"}, {"text": "東京を経営して、大阪に向かう新幹線に乗った。", "explanation": "ここは〈経由〉（途中を通る）の意味。経営は会社や店を運営することで、通過する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41344, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "経営", "is_correct": true, "explanation": "旅館を運営するという意味で、『旅館を経営する』として自然。"}, {"text": "出版", "is_correct": false, "explanation": "出版は本や雑誌を世に出すことで、旅館は対象にならない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲を作ることで、旅館とは合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、旅館を対象にする動詞ではない。"}], "explanations": {"経営": "旅館を運営するという意味で、『旅館を経営する』として自然。", "出版": "出版は本や雑誌を世に出すことで、旅館は対象にならない。", "作曲": "作曲は曲を作ることで、旅館とは合わない。", "散歩": "散歩は歩くことで、旅館を対象にする動詞ではない。"}, "sentence_index": 6, "correct_answer": "経営"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新人の経営を任された先輩は、毎日一時間ほど付き合っている。", "explanation": "ここは〈指導〉の意味。新人を教え導く仕事で、会社や店を運営する〈経営〉とは合わない。"}, {"text": "大型バスの経営を任された運転手は、毎朝早く車庫へ向かう。", "explanation": "ここは〈運行〉（車両を走らせる）の意味。経営は会社や店を運営することで、車両を走らせる意味では使わない。"}, {"text": "受付の経営を任された彼女は、毎日お客さんを迎えている。", "explanation": "ここは〈担当〉の意味。受付を受け持つことで、組織や店全体を運営する〈経営〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41344, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長は経営を方針を決めた。", "corrected_sentence": "社長は経営の方針を決めた。", "error_description": "『経営を』は誤り。正しくは『経営の』。『方針』の前に『経営』を置くと修飾になるので『の』が必要。『を』を重ねると目的語が二つになり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41344, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店の経営を失敗して、閉店した。", "corrected_sentence": "店の経営に失敗して、閉店した。", "error_description": "『経営を』は誤り。正しくは『経営に』。『失敗する』は『〜に失敗する』と取るので、経営には『に』が必要。『を』だと目的語になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
