INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41348, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41348, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間の代わりに考える機械のことです。", "primary_collocate": null, "pronunciation": "えーあい", "ipa": "eːai", "syllable_count": 4, "sentences": [{"text": "AI は人の代わりに考えてくれる機械です。", "target_word": "AI", "complexity_tier": "T2", "furigana": "AI は人[ひと]の代[か]わりに考[かんが]えてくれる機械[きかい]です。", "sentence_source": "generated"}, {"text": "わたしは AI に天気を聞きました。", "target_word": "AI", "complexity_tier": "T2", "furigana": "わたしは AI に天気[てんき]を聞[き]きました。", "sentence_source": "generated"}, {"text": "AI のおかげで、むずかしい計算がすぐ終わった。", "target_word": "AI", "complexity_tier": "T2", "furigana": "AI のおかげで、むずかしい計算[けいさん]がすぐ終[お]わった。", "sentence_source": "generated"}, {"text": "このお店では、AI がお客さんの質問に答える。", "target_word": "AI", "complexity_tier": "T2", "furigana": "このお店[みせ]では、AI がお客[きゃく]さんの質問[しつもん]に答[こた]える。", "sentence_source": "generated"}, {"text": "兄は AI と話しながら宿題をしている。", "target_word": "AI", "complexity_tier": "T2", "furigana": "兄[あに]は AI と話[はな]しながら宿題[しゅくだい]をしている。", "sentence_source": "generated"}, {"text": "AI は人間のように考えるが、人間ではない。", "target_word": "AI", "complexity_tier": "T3", "furigana": "AI は人間[にんげん]のように考[かんが]えるが、人間[にんげん]ではない。", "sentence_source": "generated"}, {"text": "家のそうじをするロボットは、AI に話しかけると答えてくれる。", "target_word": "AI", "complexity_tier": "T2", "furigana": "家[いえ]のそうじをするロボットは、AI に話[はな]しかけると答[こた]えてくれる。", "sentence_source": "generated"}, {"text": "AI に絵をかいてもらったら、とてもきれいだった。", "target_word": "AI", "complexity_tier": "T2", "furigana": "AI に絵[え]をかいてもらったら、とてもきれいだった。", "sentence_source": "generated"}, {"text": "先生は、AI に頼りすぎてはいけないと言った。", "target_word": "AI", "complexity_tier": "T3", "furigana": "先生[せんせい]は、AI に頼[たよ]りすぎてはいけないと言[い]った。", "sentence_source": "generated"}, {"text": "病院でも AI が医者の仕事を手伝っている。", "target_word": "AI", "complexity_tier": "T3", "furigana": "病院[びょういん]でも AI が医者[いしゃ]の仕事[しごと]を手伝[てつだ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "AI", "label": "基本形"}, {"form": "AIの", "label": "連体修飾形"}], "register": "日常的・やさしい話し言葉", "sense_fingerprint": "人の代わりに考えて答えてくれる機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41348, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "AI", "is_correct": true, "explanation": "『AI は人の代わりに考えてくれる機械です』の主語で、機械を指す。"}, {"text": "天気", "is_correct": false, "explanation": "『天気は人の代わりに考えてくれる機械です』は成り立たない。"}, {"text": "友達", "is_correct": false, "explanation": "『友達は…機械です』は意味が矛盾する。"}, {"text": "ごはん", "is_correct": false, "explanation": "『ごはんは…機械です』は成り立たず、機械を表さない。"}], "explanations": {"AI": "『AI は人の代わりに考えてくれる機械です』の主語で、機械を指す。", "天気": "『天気は人の代わりに考えてくれる機械です』は成り立たない。", "友達": "『友達は…機械です』は意味が矛盾する。", "ごはん": "『ごはんは…機械です』は成り立たず、機械を表さない。"}, "sentence_index": 0, "correct_answer": "AI"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお店では、AI をスープに入れて味を整えた。", "explanation": "ここは〈調味料〉の意味。AI は機械を指す語で、料理に入れる材料にはならない。"}, {"text": "このお店では、AI の味が評判で、毎朝行列ができる。", "explanation": "ここは料理の〈風味〉の意味。AI は機械を指すので、食べ物の風味とは結びつかない。"}, {"text": "このお店は、AI の雰囲気が若いお客さんに人気だ。", "explanation": "ここは店内の〈空気感〉の意味。AI は機械を指す語で、場の空気感は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41348, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "AI", "is_correct": true, "explanation": "『AI に話しかけると答えてくれる』で、話しかけると答える機械を指す。空欄に入る。"}, {"text": "ごはん", "is_correct": false, "explanation": "『ごはんに話しかけると答えてくれる』は意味が通らない。"}, {"text": "ふとん", "is_correct": false, "explanation": "『ふとんに話しかけると答えてくれる』は成り立たない。"}, {"text": "傘", "is_correct": false, "explanation": "『傘に話しかけると答えてくれる』は意味が通らず、機械を表さない。"}], "explanations": {"AI": "『AI に話しかけると答えてくれる』で、話しかけると答える機械を指す。空欄に入る。", "ごはん": "『ごはんに話しかけると答えてくれる』は意味が通らない。", "ふとん": "『ふとんに話しかけると答えてくれる』は成り立たない。", "傘": "『傘に話しかけると答えてくれる』は意味が通らず、機械を表さない。"}, "sentence_index": 6, "correct_answer": "AI"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病院では、AI の医学生が実習で患者を担当している。", "explanation": "ここは〈研修医〉の意味。AI は機械を指す語で、医療の現場で働く人にはならない。"}, {"text": "病院では、AI の薬剤を毎朝患者に配っている。", "explanation": "ここは〈医薬品〉の意味。AI は機械を指す語で、医薬品の名称にはならない。"}, {"text": "病院では、AI の検査室で血液を調べている。", "explanation": "ここは施設名の〈研究所〉の意味。AI は機械を指す語で、場所の名前にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41348, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家の AI を、毎朝ニュースを読んでくれる。", "corrected_sentence": "家の AI が、毎朝ニュースを読んでくれる。", "error_description": "『読んでくれる』の主語には『が』が付く。『AI を』は目的語の形になり、文の意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41348, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病院の受付では AI を案内をしている。", "corrected_sentence": "病院の受付では AI が案内をしている。", "error_description": "『案内をしている』の主語には『が』が付く。『AI を』は目的語になり、文の意味が変わる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
