INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41349, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41349, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間の知能を模倣し、学習や問題解決を行うコンピューターシステムや技術の総称。", "primary_collocate": null, "pronunciation": "えーあい", "ipa": "eːai", "syllable_count": 4, "sentences": [{"text": "医療の現場では、AI が画像を分析して病気の発見を助けている。", "target_word": "AI", "complexity_tier": "T3", "furigana": "医療[いりょう]の現場[げんば]では、AI が画像[がぞう]を分析[ぶんせき]して病気[びょうき]の発見[はっけん]を助[たす]けている。", "sentence_source": "generated"}, {"text": "AI は大量のデータから学習して、判断の精度を高めていく。", "target_word": "AI", "complexity_tier": "T3", "furigana": "AI は大量[たいりょう]のデータから学習[がくしゅう]して、判断[はんだん]の精度[せいど]を高[たか]めていく。", "sentence_source": "generated"}, {"text": "企業は AI を導入することで、顧客対応の効率を上げようとしている。", "target_word": "AI", "complexity_tier": "T4", "furigana": "企業[きぎょう]は AI を導入[どうにゅう]することで、顧客対応[こきゃくたいおう]の効率[こうりつ]を上[あ]げようとしている。", "sentence_source": "generated"}, {"text": "AI の判断の根拠が分からないという問題が、専門家の間で議論されている。", "target_word": "AI", "complexity_tier": "T4", "furigana": "AI の判断[はんだん]の根拠[こんきょ]が分[わ]からないという問題[もんだい]が、専門家[せんもんか]の間[あいだ]で議論[ぎろん]されている。", "sentence_source": "generated"}, {"text": "翻訳の分野でも、AI の進歩によって訳文の自然さが大きく向上した。", "target_word": "AI", "complexity_tier": "T4", "furigana": "翻訳[ほんやく]の分野[ぶんや]でも、AI の進歩[しんぽ]によって訳文[やくぶん]の自然[しぜん]さが大[おお]きく向上[こうじょう]した。", "sentence_source": "generated"}, {"text": "研究者は、AI が社会に与える影響を慎重に検討すべきだと主張している。", "target_word": "AI", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]は、AI が社会[しゃかい]に与[あた]える影響[えいきょう]を慎重[しんちょう]に検討[けんとう]すべきだと主張[しゅちょう]している。", "sentence_source": "generated"}, {"text": "AI が生成した文章かどうかを見分けるのは、年々難しくなっている。", "target_word": "AI", "complexity_tier": "T4", "furigana": "AI が生成[せいせい]した文章[ぶんしょう]かどうかを見分[みわ]けるのは、年々[ねんねん]難[むずか]しくなっている。", "sentence_source": "generated"}, {"text": "自動運転車は、AI が周囲の状況を判断して走行を制御する仕組みだ。", "target_word": "AI", "complexity_tier": "T4", "furigana": "自動運転車[じどううんてんしゃ]は、AI が周囲[しゅうい]の状況[じょうきょう]を判断[はんだん]して走行[そうこう]を制御[せいぎょ]する仕組[しく]みだ。", "sentence_source": "generated"}, {"text": "政府は AI の利用に関する新しい指針を発表した。", "target_word": "AI", "complexity_tier": "T3", "furigana": "政府[せいふ]は AI の利用[りよう]に関[かん]する新[あたら]しい指針[ししん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "大学では、AI を活用した個別指導の研究が進められている。", "target_word": "AI", "complexity_tier": "T4", "furigana": "大学[だいがく]では、AI を活用[かつよう]した個別指導[こべつしどう]の研究[けんきゅう]が進[すす]められている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "AI", "label": "基本形"}, {"form": "AIの", "label": "連体修飾形"}], "register": "やや硬い・書き言葉", "sense_fingerprint": "学習や問題解決を行う知能技術の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41349, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "AI", "is_correct": true, "explanation": "画像を分析する人工知能を指し、文の主語として自然に入る。"}, {"text": "患者", "is_correct": false, "explanation": "『患者が画像を分析して』は意味が合わない。患者は分析しない。"}, {"text": "薬剤", "is_correct": false, "explanation": "『薬剤が画像を分析して』は成り立たない。"}, {"text": "処方箋", "is_correct": false, "explanation": "『処方箋が画像を分析して』は成り立たず、主語にならない。"}], "explanations": {"AI": "画像を分析する人工知能を指し、文の主語として自然に入る。", "患者": "『患者が画像を分析して』は意味が合わない。患者は分析しない。", "薬剤": "『薬剤が画像を分析して』は成り立たない。", "処方箋": "『処方箋が画像を分析して』は成り立たず、主語にならない。"}, "sentence_index": 0, "correct_answer": "AI"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この公園には、AI の芝生が敷いてある。", "explanation": "ここは〈人工〉の意味（人工芝）。AI は機械の知能を指す語で、人工物の意味にはならない。"}, {"text": "この会社は、AI の資本金を毎年増やしている。", "explanation": "ここは〈資金〉の意味。AI は技術を指す語で、会社のお金の名目にはならない。"}, {"text": "この店では、AI を一つずつ手で磨いている。", "explanation": "ここは〈機械〉の意味。AI はソフトウェアや技術を指すので、手で磨く物としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41349, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "AI", "is_correct": true, "explanation": "『AI が生成した文章』の形で、生成主体になる。空欄に入る。"}, {"text": "カメラ", "is_correct": false, "explanation": "『カメラが生成した文章』は成り立たず、文章を生成しない。"}, {"text": "モニター", "is_correct": false, "explanation": "『モニターが生成した文章』は意味が通らない。"}, {"text": "キーボード", "is_correct": false, "explanation": "『キーボードが生成した文章』は成り立たない。"}], "explanations": {"AI": "『AI が生成した文章』の形で、生成主体になる。空欄に入る。", "カメラ": "『カメラが生成した文章』は成り立たず、文章を生成しない。", "モニター": "『モニターが生成した文章』は意味が通らない。", "キーボード": "『キーボードが生成した文章』は成り立たない。"}, "sentence_index": 6, "correct_answer": "AI"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学では、AI の入学金を値上げして学生を集めている。", "explanation": "ここは〈学費〉の意味。AI は技術を指す語で、お金の名目にはならない。"}, {"text": "大学では、AI の定食を毎日出している。", "explanation": "ここは〈料理〉の意味。AI は技術を指す語で、食事の名前にはならない。"}, {"text": "大学の図書館では、AI の入場券を一枚ずつ手で切っている。", "explanation": "ここは〈切符〉の意味。AI は技術を指す語で、切符の名前にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41349, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "企業は AI に活用して、在庫の管理を効率化している。", "corrected_sentence": "企業は AI を活用して、在庫の管理を効率化している。", "error_description": "『活用する』は目的語に『を』を取る。『AI に』は『活用する』と結びつかず、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41349, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府は AI に利用について、新しい指針を発表した。", "corrected_sentence": "政府は AI の利用について、新しい指針を発表した。", "error_description": "『AI の利用』の『の』を『に』に変えると、『利用』と結びつかず不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41352, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「職をつける」の「を」。つける対象を表す格助詞で、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「職がつける」は主語と他動詞が合わない。「つける」には目的語の「を」が必要。"}, {"text": "で", "is_correct": false, "explanation": "「職で付ける」は手段を表すが、つける対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「職へ付ける」は方向を表すが、つける対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「職をつける」の「を」。つける対象を表す格助詞で、正しい。", "が": "「職がつける」は主語と他動詞が合わない。「つける」には目的語の「を」が必要。", "で": "「職で付ける」は手段を表すが、つける対象にはならない。", "へ": "「職へ付ける」は方向を表すが、つける対象にはならない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41352, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「職を探している」の「を」。探す対象を表す格助詞で、正しい。"}, {"text": "と", "is_correct": false, "explanation": "「職と探している」は並列を表し、探す対象を表さないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「職より探している」は比較を表し、探す対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「職の探している」は連体修飾になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「職を探している」の「を」。探す対象を表す格助詞で、正しい。", "と": "「職と探している」は並列を表し、探す対象を表さないので合わない。", "より": "「職より探している」は比較を表し、探す対象にはならない。", "の": "「職の探している」は連体修飾になり、文が成り立たない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41352, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "仕事の種類のことです。", "primary_collocate": null, "pronunciation": "しょく", "ipa": "ɕokɯ", "syllable_count": 2, "sentences": [{"text": "好きな職を選んで、毎日楽しく働きたい。", "target_word": "職", "complexity_tier": "T3", "furigana": "好[す]きな職[しょく]を選[えら]んで、毎日[まいにち]楽[たの]しく働[はたら]きたい。", "sentence_source": "generated"}, {"text": "手に職をつけると、どこでも働けるよ。", "target_word": "職", "complexity_tier": "T3", "furigana": "手[て]に職[しょく]をつけると、どこでも働[はたら]けるよ。", "sentence_source": "generated"}, {"text": "兄は体をこわしたのをきっかけに、職を変えた。", "target_word": "職", "complexity_tier": "T3", "furigana": "兄[あに]は体[からだ]をこわしたのをきっかけに、職[しょく]を変[か]えた。", "sentence_source": "generated"}, {"text": "最近はITの職が人気で、募集も多い。", "target_word": "職", "complexity_tier": "T3", "furigana": "最近[さいきん]はITの職[しょく]が人気[にんき]で、募集[ぼしゅう]も多[おお]い。", "sentence_source": "generated"}, {"text": "看護師のような人を助ける職に就きたい。", "target_word": "職", "complexity_tier": "T3", "furigana": "看護師[かんごし]のような人[ひと]を助[たす]ける職[しょく]に就[つ]きたい。", "sentence_source": "generated"}, {"text": "学校の先生は、人に教える職だ。", "target_word": "職", "complexity_tier": "T2", "furigana": "学校[がっこう]の先生[せんせい]は、人[ひと]に教[おし]える職[しょく]だ。", "sentence_source": "generated"}, {"text": "この町には、農業に関わる職が多い。", "target_word": "職", "complexity_tier": "T3", "furigana": "この町には、農業に関わる職[しょく]が多い。", "sentence_source": "generated"}, {"text": "私は事務の職を探しています。", "target_word": "職", "complexity_tier": "T2", "furigana": "私[わたし]は事務[じむ]の職[しょく]を探[さが]しています。", "sentence_source": "generated"}, {"text": "職の種類が多すぎて、どれを選べばいいか迷う。", "target_word": "職", "complexity_tier": "T3", "furigana": "職[しょく]の種類[しゅるい]が多[おお]すぎて、どれを選[えら]べばいいか迷[まよ]う。", "sentence_source": "generated"}, {"text": "長く続けられる職を見つけたい。", "target_word": "職", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]けられる職[しょく]を見[み]つけたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "職", "label": "基本形"}], "register": "中立", "sense_fingerprint": "医者・事務・農業など、仕事の種類や分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41352, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "職", "is_correct": true, "explanation": "「好きな職を選んで」で、選ぶ対象の仕事の種類を指す。"}, {"text": "柱", "is_correct": false, "explanation": "柱は建物の部材で、働き方を選ぶ文の対象ではない。"}, {"text": "桶", "is_correct": false, "explanation": "桶は水などを入れる容器で、働く仕事の種類として合わない。"}, {"text": "壺", "is_correct": false, "explanation": "壺は器で、「楽しく働きたい」と続けても意味が通らない。"}], "explanations": {"職": "「好きな職を選んで」で、選ぶ対象の仕事の種類を指す。", "柱": "柱は建物の部材で、働き方を選ぶ文の対象ではない。", "桶": "桶は水などを入れる容器で、働く仕事の種類として合わない。", "壺": "壺は器で、「楽しく働きたい」と続けても意味が通らない。"}, "sentence_index": 0, "correct_answer": "職"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その大会では、どの職に出場するか選べる。", "explanation": "ここは〈種目〉（競技の部門）の意味。職は仕事の種類なので、大会への出場には使わない。"}, {"text": "この本は歴史の職を丁寧に扱っている。", "explanation": "ここは〈分野〉（学問や話題の領域）の意味。職は仕事の種類で、扱う領域を指さないので合わない。"}, {"text": "物語の職は、身近な出来事が多い。", "explanation": "ここは〈題材〉（作品の素材）の意味。職は仕事の種類で、作品の素材にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41352, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "職", "is_correct": true, "explanation": "「農業に関わる職」で、農業に関係する仕事の種類を指す。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、「農業に関わる」の対象として意味が通らない。"}, {"text": "幕", "is_correct": false, "explanation": "幕は布の仕切りや舞台の幕で、仕事の種類が多いという文の対象ではない。"}, {"text": "縄", "is_correct": false, "explanation": "縄は物を縛る紐で、仕事の種類の多さを表す文の対象として合わない。"}], "explanations": {"職": "「農業に関わる職」で、農業に関係する仕事の種類を指す。", "鍋": "鍋は調理器具で、「農業に関わる」の対象として意味が通らない。", "幕": "幕は布の仕切りや舞台の幕で、仕事の種類が多いという文の対象ではない。", "縄": "縄は物を縛る紐で、仕事の種類の多さを表す文の対象として合わない。"}, "sentence_index": 6, "correct_answer": "職"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うちの会社の職は、食品の製造です。", "explanation": "ここは〈業種〉（会社の事業分野）の意味。職は働く人の仕事の種類で、会社の事業分野は表さないので合わない。"}, {"text": "この店は魚の職が多い。", "explanation": "ここは〈種類〉（同じ仲間の区分）の意味。職は仕事の種類で、魚の仲間の区分には使わないので合わない。"}, {"text": "動物の職を学ぶ授業がある。", "explanation": "ここは〈分類〉（仲間ごとの区分）の意味。動物の区分を職で言うことはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
