INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41354, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "色の名前です。赤や青などの色を言います。", "primary_collocate": null, "pronunciation": "からー", "ipa": "kaɾaː", "syllable_count": 3, "sentences": [{"text": "好きなカラーは何ですか。", "target_word": "カラー", "complexity_tier": "T2", "furigana": "好[す]きなカラーは何[なん]ですか。", "sentence_source": "generated"}, {"text": "新しいかばんを買いました。カラーは青にしました。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "新[あたら]しいかばんを買[か]いました。カラーは青[あお]にしました。", "sentence_source": "generated"}, {"text": "この服にはほかのカラーもありますか。", "target_word": "カラー", "complexity_tier": "T2", "furigana": "この服[ふく]にはほかのカラーもありますか。", "sentence_source": "generated"}, {"text": "赤は元気なカラーだと思う。", "target_word": "カラー", "complexity_tier": "T2", "furigana": "赤[あか]は元気[げんき]なカラーだと思[おも]う。", "sentence_source": "generated"}, {"text": "春になると、店にはやさしいカラーの服が並ぶ。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "春[はる]になると、店[みせ]にはやさしいカラーの服[ふく]が並[なら]ぶ。", "sentence_source": "generated"}, {"text": "わたしのクラスのカラーは緑です。", "target_word": "カラー", "complexity_tier": "T2", "furigana": "わたしのクラスのカラーは緑[みどり]です。", "sentence_source": "generated"}, {"text": "この車のカラーは白で、よごれが目立つ。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "この車[くるま]のカラーは白[しろ]で、よごれが目立[め]つ。", "sentence_source": "generated"}, {"text": "ペンのカラーは、赤、青、黒の三つから選べます。", "target_word": "カラー", "complexity_tier": "T2", "furigana": "ペンのカラーは、赤[あか]、青[あお]、黒[くろ]の三[みっ]つから選[えら]べます。", "sentence_source": "generated"}, {"text": "この部屋は明るいカラーでそろえてある。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "この部屋[へや]は明[あか]るいカラーでそろえてある。", "sentence_source": "generated"}, {"text": "虹には赤や青など、たくさんのカラーがある。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "虹[にじ]には赤[あか]や青[あお]など、たくさんのカラーがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カラー", "label": "基本形"}, {"form": "カラーの", "label": "連体修飾形"}, {"form": "カラーが", "label": "主格の形"}], "register": "日常的・やさしい話し言葉", "sense_fingerprint": "赤や青など、一つ一つの色の種類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: よごれ (Zipf 2.32)']::text[], '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41354, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カラー", "is_correct": true, "explanation": "「好きなカラー」は色の種類を尋ねる自然な表現で、空所に入る。"}, {"text": "くしゃみ", "is_correct": false, "explanation": "「好きなくしゃみは何ですか」は意味が通らない。"}, {"text": "ため息", "is_correct": false, "explanation": "「好きなため息は何ですか」は意味が通らない。"}, {"text": "まばたき", "is_correct": false, "explanation": "「好きなまばたきは何ですか」は意味が通らない。"}], "explanations": {"カラー": "「好きなカラー」は色の種類を尋ねる自然な表現で、空所に入る。", "くしゃみ": "「好きなくしゃみは何ですか」は意味が通らない。", "ため息": "「好きなため息は何ですか」は意味が通らない。", "まばたき": "「好きなまばたきは何ですか」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "カラー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツはカラーが細かく、柄がはっきりしている。", "explanation": "ここは〈柄〉の意味。柄は布の模様を指すので、色の名前を表すカラーとは合わない。"}, {"text": "あのリボンはカラーが長く、端が床につく。", "explanation": "ここは〈長さ〉の意味。長さは寸法を表すが、カラーは色の種類なので、リボンの寸法の話には合わない。"}, {"text": "この色はカラーが高い。", "explanation": "ここは〈明度〉の意味。明度は明るさの度合いを表すが、カラーは色の種類なので「高い」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41354, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カラー", "is_correct": true, "explanation": "「この車のカラーは白」は車の色を表す自然な形で、空所に入る。"}, {"text": "スピード", "is_correct": false, "explanation": "「この車のスピードは白で」は意味が通らない。"}, {"text": "ねじ", "is_correct": false, "explanation": "「この車のねじは白で」は、色の説明として成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "「この車の眠気は白で」は意味が通らない。"}], "explanations": {"カラー": "「この車のカラーは白」は車の色を表す自然な形で、空所に入る。", "スピード": "「この車のスピードは白で」は意味が通らない。", "ねじ": "「この車のねじは白で」は、色の説明として成り立たない。", "眠気": "「この車の眠気は白で」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "カラー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお茶はカラーがまろやかで、飲みやすい。", "explanation": "ここは〈口当たり〉の意味。口当たりは飲んだときの舌ざわりを指すが、カラーは色の種類なので、お茶の味の話には合わない。"}, {"text": "この録音はカラーが大きく、ノイズが目立つ。", "explanation": "ここは〈音量〉の意味。音量は音の大きさを表すが、カラーは色の種類なので、録音の大きさの話には合わない。"}, {"text": "この曲はカラーが速く、踊りやすい。", "explanation": "ここは〈テンポ〉の意味。テンポは曲の速さを表すが、カラーは色の種類なので「速い」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41354, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "かばんのカラーを、青が好きです。", "corrected_sentence": "かばんのカラーは、青が好きです。", "error_description": "「カラー」に続く助詞が誤り。主題を示す「は」が正しく、「を」では「好き」の対象が文の中で成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41354, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このノートのカラーに、赤か青から選べます。", "corrected_sentence": "このノートのカラーは、赤か青から選べます。", "error_description": "「カラー」に続く助詞が誤り。主題を示す「は」が正しく、「に」では「選べます」の対象が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41355, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白黒", "is_correct": true, "explanation": "この意味のカラーの対義語。色がない状態を表すので、色がついた状態と対になる。"}, {"text": "写真", "is_correct": false, "explanation": "撮影の対象や成果物を表す名詞で、カラーと対になる語ではない。"}, {"text": "テレビ", "is_correct": false, "explanation": "機器の名前で、カラーとは対義関係にない。"}, {"text": "雑誌", "is_correct": false, "explanation": "出版物の名前で、カラーとは対義関係にない。"}], "correct_answer": "白黒", "explanations": {"白黒": "この意味のカラーの対義語。色がない状態を表すので、色がついた状態と対になる。", "写真": "撮影の対象や成果物を表す名詞で、カラーと対になる語ではない。", "テレビ": "機器の名前で、カラーとは対義関係にない。", "雑誌": "出版物の名前で、カラーとは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41355, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白黒", "is_correct": true, "explanation": "この意味のカラーの対義語。色がない状態を表すので、色がついた状態と対になる。"}, {"text": "夢", "is_correct": false, "explanation": "抽象的な名詞で、カラーとは対義関係にない。"}, {"text": "映画", "is_correct": false, "explanation": "作品の種類を表す名詞で、カラーとは対義関係にない。"}, {"text": "絵本", "is_correct": false, "explanation": "本の種類を表す名詞で、カラーとは対義関係にない。"}], "correct_answer": "白黒", "explanations": {"白黒": "この意味のカラーの対義語。色がない状態を表すので、色がついた状態と対になる。", "夢": "抽象的な名詞で、カラーとは対義関係にない。", "映画": "作品の種類を表す名詞で、カラーとは対義関係にない。", "絵本": "本の種類を表す名詞で、カラーとは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41355, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "色。光の波長によって見える視覚的な性質。", "primary_collocate": null, "pronunciation": "からー", "ipa": "kaɾaː", "syllable_count": 3, "sentences": [{"text": "写真は、カラーのほうが鮮やかに見える。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "写真[しゃしん]は、カラーのほうが鮮[あざ]やかに見[み]える。", "sentence_source": "generated"}, {"text": "この古い写真は白黒だが、新しい写真はカラーで撮られている。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "この古[ふる]い写真[しゃしん]は白黒[しろくろ]だが、新[あたら]しい写真[しゃしん]はカラーで撮[と]られている。", "sentence_source": "generated"}, {"text": "印刷はカラーにすると、白黒より料金が高くなる。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "印刷[いんさつ]はカラーにすると、白黒[しろくろ]より料金[りょうきん]が高[たか]くなる。", "sentence_source": "generated"}, {"text": "昔のテレビは白黒だったが、今はどれもカラーで映る。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "昔[むかし]のテレビは白黒[しろくろ]だったが、今[いま]はどれもカラーで映[うつ]る。", "sentence_source": "generated"}, {"text": "カラーで見ると、その花の美しさがよく分かる。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "カラーで見[み]ると、その花[はな]の美[うつく]しさがよく分[わ]かる。", "sentence_source": "generated"}, {"text": "資料の図はカラーのほうが、違いが分かりやすい。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "資料[しりょう]の図[ず]はカラーのほうが、違[ちが]いが分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "祖父は、初めてカラーの映画を見たときの驚きを話してくれた。", "target_word": "カラー", "complexity_tier": "T4", "furigana": "祖父[そふ]は、初[はじ]めてカラーの映画[えいが]を見[み]たときの驚[おどろ]きを話[はな]してくれた。", "sentence_source": "generated"}, {"text": "雑誌の最初のページだけがカラーで、残りは白黒だ。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "雑誌[ざっし]の最初[さいしょ]のページだけがカラーで、残[のこ]りは白黒[しろくろ]だ。", "sentence_source": "generated"}, {"text": "このプリンターはカラーでもきれいに印刷できる。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "このプリンターはカラーでもきれいに印刷[いんさつ]できる。", "sentence_source": "generated"}, {"text": "子どもの頃に見た夢は、白黒ではなくカラーだった。", "target_word": "カラー", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]に見[み]た夢[ゆめ]は、白黒[しろくろ]ではなくカラーだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カラー", "label": "基本形"}, {"form": "カラーの", "label": "連体修飾形"}, {"form": "カラーで", "label": "手段・状態を表す形"}], "register": "一般的", "sense_fingerprint": "白黒に対する、色がついた状態や視覚的な色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41355, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カラー", "is_correct": true, "explanation": "「カラーのほうが鮮やかに見える」は色のついた写真との対比を表す自然な形で、空所に入る。"}, {"text": "くしゃみ", "is_correct": false, "explanation": "「くしゃみのほうが鮮やかに見える」は意味が通らない。"}, {"text": "ため息", "is_correct": false, "explanation": "「ため息のほうが鮮やかに見える」は意味が通らない。"}, {"text": "ねむけ", "is_correct": false, "explanation": "「ねむけのほうが鮮やかに見える」は意味が通らない。"}], "explanations": {"カラー": "「カラーのほうが鮮やかに見える」は色のついた写真との対比を表す自然な形で、空所に入る。", "くしゃみ": "「くしゃみのほうが鮮やかに見える」は意味が通らない。", "ため息": "「ため息のほうが鮮やかに見える」は意味が通らない。", "ねむけ": "「ねむけのほうが鮮やかに見える」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "カラー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この金属は表面のカラーが強く、鏡のように映る。", "explanation": "ここは〈光沢〉の意味。光沢は表面が光を反射する度合いを指すので、色の性質を表すカラーとは合わない。"}, {"text": "この懐中電灯はカラーが強く、遠くまで届く。", "explanation": "ここは〈光の強さ（輝度）〉の意味。光の強さは明るさの度合いを表すが、カラーは色の性質なので「強い」とは言えず、光が遠くまで届く話には合わない。"}, {"text": "絵を描くために、カラーを水で溶いた。", "explanation": "ここは〈絵の具〉の意味。カラーは色そのもので、画材の絵の具ではないので、水で溶く対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41355, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カラー", "is_correct": true, "explanation": "「初めてカラーの映画」は、色のついた映画を指す自然な形。"}, {"text": "ダイヤ", "is_correct": false, "explanation": "「初めてダイヤの映画」は意味をなさない。"}, {"text": "ウール", "is_correct": false, "explanation": "「ウールの映画」は材質の語で、映画の種類を表せないので合わない。"}, {"text": "チーズ", "is_correct": false, "explanation": "「チーズの映画」は意味が通らない。"}], "explanations": {"カラー": "「初めてカラーの映画」は、色のついた映画を指す自然な形。", "ダイヤ": "「初めてダイヤの映画」は意味をなさない。", "ウール": "「ウールの映画」は材質の語で、映画の種類を表せないので合わない。", "チーズ": "「チーズの映画」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "カラー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この写真はカラーが高く、鮮やかだ。", "explanation": "ここは〈彩度〉の意味。彩度は鮮やかさの度合いを表すが、カラーは色の種類を指すので「高い」とは言えない。"}, {"text": "このモニターはカラーが細かく、文字がくっきり読める。", "explanation": "ここは〈解像度〉の意味。解像度は画面の細かさを表すが、カラーは色の種類なので「細かい」とは言えず、文字の読みやすさの話には合わない。"}, {"text": "このりんごはカラーが甘い。", "explanation": "ここは〈甘み（糖度）〉の意味。糖度は味の濃さを表すが、カラーは色のことなので、果物の味の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41355, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この古いアルバムは白黒だが、新しい写真はカラーに撮られている。", "corrected_sentence": "この古いアルバムは白黒だが、新しい写真はカラーで撮られている。", "error_description": "「カラー」に続く助詞が誤り。手段・状態を表す「で」が正しく、「に」は「撮られる」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41355, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雑誌の表紙だけがカラーに、中の記事は白黒だ。", "corrected_sentence": "雑誌の表紙だけがカラーで、中の記事は白黒だ。", "error_description": "「カラー」に続く助詞が誤り。状態を表す「で」が正しく、「に」は結果や場所を表すので、この文の述語と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41356, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「栗鼠は」で、文頭の栗鼠を話題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「栗鼠を長いしっぽを持っていて」は目的語が重なり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「栗鼠に長いしっぽを持っていて」は持ち主を表せず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「栗鼠で長いしっぽを持っていて」は手段を表し、持ち主の説明にならない。"}], "correct_answer": "は", "explanations": {"は": "「栗鼠は」で、文頭の栗鼠を話題として示す。", "を": "「栗鼠を長いしっぽを持っていて」は目的語が重なり、不自然。", "に": "「栗鼠に長いしっぽを持っていて」は持ち主を表せず、意味が通らない。", "で": "「栗鼠で長いしっぽを持っていて」は手段を表し、持ち主の説明にならない。"}, "error_tags": {"は": "topic", "を": "object", "に": "indirect", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41356, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「栗鼠の写真」で、写真の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「栗鼠を写真を撮ろう」は目的語が二つ重なり、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「栗鼠から写真を撮ろう」は起点を表し、写真の対象にならず意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「栗鼠より写真を撮ろう」は比較を表し、写真の対象を示せず文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「栗鼠の写真」で、写真の対象を示す。", "を": "「栗鼠を写真を撮ろう」は目的語が二つ重なり、不自然。", "から": "「栗鼠から写真を撮ろう」は起点を表し、写真の対象にならず意味が通らない。", "より": "「栗鼠より写真を撮ろう」は比較を表し、写真の対象を示せず文が成り立たない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "より": "比較", "を": "object"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41356, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さな動物で、木の上に住み、長いしっぽがあります。", "primary_collocate": null, "pronunciation": "りす", "ipa": "ɾisɯ", "syllable_count": 2, "sentences": [{"text": "木の上に栗鼠がいるのを、子どもが見つけた。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "木[き]の上[うえ]に栗鼠[りす]がいるのを、子[こ]どもが見[み]つけた。", "sentence_source": "generated"}, {"text": "栗鼠は長いしっぽを持っていて、木の上を速く走る。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]は長[なが]いしっぽを持[も]っていて、木[き]の上[うえ]を速[はや]く走[はし]る。", "sentence_source": "generated"}, {"text": "動物園で栗鼠にえさをやった。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]で栗鼠[りす]にえさをやった。", "sentence_source": "generated"}, {"text": "栗鼠のしっぽは体と同じくらい長い。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]のしっぽは体[からだ]と同[おな]じくらい長[なが]い。", "sentence_source": "generated"}, {"text": "朝、庭の木に栗鼠が来て、木の実を食べていた。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "朝[あさ]、庭[にわ]の木[き]に栗鼠[りす]が来[き]て、木[き]の実[み]を食[た]べていた。", "sentence_source": "generated"}, {"text": "祖父の家の近くの森には、栗鼠が住んでいる。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "祖父[そふ]の家[いえ]の近[ちか]くの森[もり]には、栗鼠[りす]が住[す]んでいる。", "sentence_source": "generated"}, {"text": "栗鼠は小さいので、猫に捕まらないように高い木に登る。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]は小[ちい]さいので、猫[ねこ]に捕[つか]まらないように高[たか]い木[き]に登[のぼ]る。", "sentence_source": "generated"}, {"text": "私は栗鼠の写真を撮ろうとしたが、すぐ逃げてしまった。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "私[わたし]は栗鼠[りす]の写真[しゃしん]を撮[と]ろうとしたが、すぐ逃[に]げてしまった。", "sentence_source": "generated"}, {"text": "栗鼠が木から降りてきて、私の前を横切った。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]が木[き]から降[お]りてきて、私[わたし]の前[まえ]を横切[よこぎ]った。", "sentence_source": "generated"}, {"text": "弟は栗鼠が好きで、部屋に栗鼠のぬいぐるみがたくさんある。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "弟[おとうと]は栗鼠[りす]が好[す]きで、部屋[へや]に栗鼠[りす]のぬいぐるみがたくさんある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "栗鼠", "label": "基本形"}, {"form": "リス", "label": "カタカナ表記"}], "register": "neutral", "sense_fingerprint": "木の上に住む長いしっぽの小さな動物(日常的・やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41356, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "栗鼠", "is_correct": true, "explanation": "木の上にいる小動物として、「木の上に___がいるのを」に自然に入る。"}, {"text": "ペンギン", "is_correct": false, "explanation": "木の上にはいない鳥で、文の場面に合わない。"}, {"text": "クジラ", "is_correct": false, "explanation": "海の哺乳類で、木の上にいる文脈に合わない。"}, {"text": "マグロ", "is_correct": false, "explanation": "海の魚で、木の上にいる文脈に合わない。"}], "explanations": {"栗鼠": "木の上にいる小動物として、「木の上に___がいるのを」に自然に入る。", "ペンギン": "木の上にはいない鳥で、文の場面に合わない。", "クジラ": "海の哺乳類で、木の上にいる文脈に合わない。", "マグロ": "海の魚で、木の上にいる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "栗鼠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "栗鼠は丸くなって、背中のとげで身を守る。", "explanation": "ここは〈ハリネズミ〉の防御法。栗鼠は背中にとげを持たず、身を守る方法が違うので合わない。"}, {"text": "栗鼠は袋で子どもを育てる。", "explanation": "ここは〈カンガルー〉の育児。栗鼠は袋を持たないので、子育ての話には合わない。"}, {"text": "栗鼠は水かきで水中を泳ぐ。", "explanation": "ここは〈カエル〉の特徴。栗鼠は水かきを持たず、水中を泳がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41356, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栗鼠", "is_correct": true, "explanation": "小さくて猫に狙われやすく、高い木に登る動物として、文の主語に自然に入る。"}, {"text": "イルカ", "is_correct": false, "explanation": "海の動物で、木に登る文脈に合わない。"}, {"text": "ヒトデ", "is_correct": false, "explanation": "海の生き物で、木に登る文脈に合わない。"}, {"text": "ナマズ", "is_correct": false, "explanation": "淡水の魚で、木に登る文脈に合わない。"}], "explanations": {"栗鼠": "小さくて猫に狙われやすく、高い木に登る動物として、文の主語に自然に入る。", "イルカ": "海の動物で、木に登る文脈に合わない。", "ヒトデ": "海の生き物で、木に登る文脈に合わない。", "ナマズ": "淡水の魚で、木に登る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "栗鼠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "栗鼠は南極で群れを作って暮らす。", "explanation": "ここは〈ペンギン〉の生態。栗鼠は南極に住まず、主に森で暮らすので合わない。"}, {"text": "栗鼠は細長い体で穴に入る。", "explanation": "ここは〈イタチ〉の体つきと習性。栗鼠は細長い体を持たず、穴に入る習性もないので合わない。"}, {"text": "栗鼠は水中で魚を捕まえる。", "explanation": "ここは〈カワウソ〉の狩り。栗鼠は水に入らず魚を捕まえないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41356, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、庭の木に栗鼠を来て、木の実を食べていた。", "corrected_sentence": "夕方、庭の木に栗鼠が来て、木の実を食べていた。", "error_description": "主語を示す「が」が正しい。「来る」の主語には「が」を付けるので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41356, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は庭に来た栗鼠を木の実をあげた。", "corrected_sentence": "祖母は庭に来た栗鼠に木の実をあげた。", "error_description": "「あげる」の相手を示す「に」が正しい。「を」にすると「木の実を」と目的語が重なり、文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41357, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「栗鼠が」で、走っている主語を示す。文中にも現れる形。"}, {"text": "を", "is_correct": false, "explanation": "「栗鼠を走っていた」は、動物を走る対象として扱うことになり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「栗鼠に走っていた」は、動作の主体を示せず成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「栗鼠から走っていた」は起点を表すが、動作の主体にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "「栗鼠が」で、走っている主語を示す。文中にも現れる形。", "を": "「栗鼠を走っていた」は、動物を走る対象として扱うことになり不自然。", "に": "「栗鼠に走っていた」は、動作の主体を示せず成り立たない。", "から": "「栗鼠から走っていた」は起点を表すが、動作の主体にならず不自然。"}, "error_tags": {"が": "subject", "を": "object", "に": "indirect", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
