INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41357, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木の上で生活する小型のげっ歯類で、ふさふさした尾と大きな目が特徴です。", "primary_collocate": null, "pronunciation": "りす", "ipa": "ɾisɯ", "syllable_count": 2, "sentences": [{"text": "栗鼠は木の実を地面に埋めて、冬のために蓄える。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]は木[き]の実[み]を地面[じめん]に埋[う]めて、冬[ふゆ]のために蓄[たくわ]える。", "sentence_source": "generated"}, {"text": "公園で栗鼠がふさふさした尾を立てて走っていた。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "公園[こうえん]で栗鼠[りす]がふさふさした尾[お]を立[た]てて走[はし]っていた。", "sentence_source": "generated"}, {"text": "栗鼠は大きな目で、木の上から地面の動きをよく見張る。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]は大[おお]きな目[め]で、木[き]の上[うえ]から地面[じめん]の動[うご]きをよく見張[みは]る。", "sentence_source": "generated"}, {"text": "栗鼠はげっ歯類なので、前歯が一生伸び続ける。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]はげっ歯類[しるい]なので、前歯[まえば]が一生[いっしょう]伸[の]び続[つづ]ける。", "sentence_source": "generated"}, {"text": "栗鼠が木の枝から枝へ軽やかに跳び移るのを見た。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]が木[き]の枝[えだ]から枝[えだ]へ軽[かろ]やかに跳[と]び移[うつ]るのを見[み]た。", "sentence_source": "generated"}, {"text": "冬眠する種類もいるが、日本の栗鼠は冬も活動する。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "冬眠[とうみん]する種類[しゅるい]もいるが、日本[にほん]の栗鼠[りす]は冬[ふゆ]も活動[かつどう]する。", "sentence_source": "generated"}, {"text": "栗鼠は地面に降りてきて、落ちたどんぐりを探していた。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]は地面[じめん]に降[お]りてきて、落[お]ちたどんぐりを探[さが]していた。", "sentence_source": "generated"}, {"text": "森の入り口に「栗鼠に餌を与えないでください」という看板があった。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "森[もり]の入[い]り口[ぐち]に「栗鼠[りす]に餌[えさ]を与[あた]えないでください」という看板[かんばん]があった。", "sentence_source": "generated"}, {"text": "栗鼠は警戒心が強いので、近づくとすぐ木の上に逃げてしまう。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "栗鼠[りす]は警戒心[けいかいしん]が強[つよ]いので、近[ちか]づくとすぐ木[き]の上[うえ]に逃[に]げてしまう。", "sentence_source": "generated"}, {"text": "この絵本には、尾の大きな栗鼠が主人公として出てくる。", "target_word": "栗鼠", "complexity_tier": "T3", "furigana": "この絵本[えほん]には、尾[お]の大[おお]きな栗鼠[りす]が主人公[しゅじんこう]として出[で]てくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "栗鼠", "label": "基本形"}, {"form": "リス", "label": "カタカナ表記"}], "register": "neutral", "sense_fingerprint": "小型のげっ歯類。ふさふさした尾と大きな目を持ち、木の上で暮らす動物(生物学的・特徴重視)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41357, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "栗鼠", "is_correct": true, "explanation": "木の実を地面に埋めて冬に蓄える動物として、文の主語に自然に入る。"}, {"text": "ペンギン", "is_correct": false, "explanation": "木の実を埋めて蓄える習性がなく、文の内容と合わない。"}, {"text": "クジラ", "is_correct": false, "explanation": "海に住む動物で、木の実を蓄える文脈に合わない。"}, {"text": "カエル", "is_correct": false, "explanation": "木の実を地面に埋めて蓄える習性がなく、文の内容と合わない。"}], "explanations": {"栗鼠": "木の実を地面に埋めて冬に蓄える動物として、文の主語に自然に入る。", "ペンギン": "木の実を埋めて蓄える習性がなく、文の内容と合わない。", "クジラ": "海に住む動物で、木の実を蓄える文脈に合わない。", "カエル": "木の実を地面に埋めて蓄える習性がなく、文の内容と合わない。"}, "sentence_index": 0, "correct_answer": "栗鼠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "栗鼠は川に潜り、魚を捕まえる。", "explanation": "ここは〈カワウソ〉の狩り。栗鼠は川に潜らず魚も捕まえないので合わない。"}, {"text": "栗鼠は土の中にトンネルを掘って暮らす。", "explanation": "ここは〈モグラ〉の生態。栗鼠は主に木の上で暮らすので、地中生活の話には合わない。"}, {"text": "栗鼠は夜に超音波で飛ぶ。", "explanation": "ここは〈コウモリ〉の特徴。栗鼠は空を飛ばず、木の上を跳んで移動するので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41357, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栗鼠", "is_correct": true, "explanation": "地面に降りてどんぐりを探す動物として、文の主語に自然に入る。"}, {"text": "イルカ", "is_correct": false, "explanation": "海の動物で、地面に降りてどんぐりを探す文脈に合わない。"}, {"text": "マグロ", "is_correct": false, "explanation": "海の魚で、どんぐりを探す文脈に合わない。"}, {"text": "ヒトデ", "is_correct": false, "explanation": "海の生き物で、地面に降りてどんぐりを探す文脈に合わない。"}], "explanations": {"栗鼠": "地面に降りてどんぐりを探す動物として、文の主語に自然に入る。", "イルカ": "海の動物で、地面に降りてどんぐりを探す文脈に合わない。", "マグロ": "海の魚で、どんぐりを探す文脈に合わない。", "ヒトデ": "海の生き物で、地面に降りてどんぐりを探す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "栗鼠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "栗鼠は、背中のとげで身を守る。", "explanation": "ここは〈ハリネズミ〉の防御法。栗鼠には背中のとげがなく、身を守る方法が違うので合わない。"}, {"text": "栗鼠は袋の中で子どもを育てる。", "explanation": "ここは〈カンガルー〉の育児。栗鼠は袋を持たず、巣の中で子を育てるので合わない。"}, {"text": "栗鼠は南極で群れを作って暮らす。", "explanation": "ここは〈ペンギン〉の生態。栗鼠は南極に住まず、主に森で暮らすので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41357, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭で栗鼠を、ふさふさした尾を立てて走っていた。", "corrected_sentence": "庭で栗鼠が、ふさふさした尾を立てて走っていた。", "error_description": "主語を示す「が」が正しい。「を」は「走る」の目的語を示すため、動物が主語の文として成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41357, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の木の下で栗鼠にどんぐりを拾っていた。", "corrected_sentence": "庭の木の下で栗鼠がどんぐりを拾っていた。", "error_description": "主語を示す「が」が正しい。「に」では「拾う」の動作の主体が示されず、文として成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41358, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「電車の中で」は学び直しが行われる場所を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は存在の場所を示す。動作の場所には「で」を使う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すが、「電車の中」は場所なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。学び直す場所への移動ではないため不自然。"}], "correct_answer": "で", "explanations": {"で": "正解。「電車の中で」は学び直しが行われる場所を示す。", "に": "「に」は存在の場所を示す。動作の場所には「で」を使う。", "を": "「を」は対象を示すが、「電車の中」は場所なので合わない。", "へ": "「へ」は方向を示す。学び直す場所への移動ではないため不自然。"}, "error_tags": {"に": "存在の場所", "を": "目的語の格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41358, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41358, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "以前に勉強したことを、もう一度勉強すること。", "primary_collocate": null, "pronunciation": "まなびなおす", "ipa": "manabinaosɯ", "syllable_count": 6, "sentences": [{"text": "試験に落ちたので、数学を最初から学び直すつもりだ。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "試験[しけん]に落[お]ちたので、数学[すうがく]を最初[さいしょ]から学[まな]び直[なお]すつもりだ。", "sentence_source": "generated"}, {"text": "今、中学の英語を、通勤の電車の中で学び直している。", "target_word": "学び直している", "complexity_tier": "T3", "furigana": "今[いま]、中学[ちゅうがく]の英語[えいご]を、通勤[つうきん]の電車[でんしゃ]の中[なか]で学[まな]び直[なお]している。", "sentence_source": "generated"}, {"text": "忘れてしまった漢字を、毎晩少しずつ学び直した。", "target_word": "学び直した", "complexity_tier": "T3", "furigana": "忘[わす]れてしまった漢字[かんじ]を、毎晩[まいばん]少[すこ]しずつ学[まな]び直[なお]した。", "sentence_source": "generated"}, {"text": "昔習った歴史を、大人になって学び直すとおもしろい。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "昔[むかし]習[なら]った歴史[れきし]を、大人[おとな]になって学[まな]び直[なお]すとおもしろい。", "sentence_source": "generated"}, {"text": "基礎ができていなかったので、一年生の内容から学び直した。", "target_word": "学び直した", "complexity_tier": "T3", "furigana": "基礎[きそ]ができていなかったので、一年生[いちねんせい]の内容[ないよう]から学[まな]び直[なお]した。", "sentence_source": "generated"}, {"text": "兄は料理の基本を学び直すために、教室に通っている。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "兄[あに]は料理[りょうり]の基本[きほん]を学[まな]び直[なお]すために、教室[きょうしつ]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "学び直すなら、まず前に習った本をもう一度読むといい。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "学[まな]び直[なお]すなら、まず前[まえ]に習[なら]った本[ほん]をもう一度[いちど]読[よ]むといい。", "sentence_source": "generated"}, {"text": "昔習ったピアノの楽譜の読み方を、学び直している。", "target_word": "学び直し", "complexity_tier": "T3", "furigana": "昔[むかし]習[なら]ったピアノの楽譜[がくふ]の読[よ]み方[かた]を、学[まな]び直[なお]している。", "sentence_source": "generated"}, {"text": "わからなくなったところは、前の章に戻って学び直そう。", "target_word": "学び直そう", "complexity_tier": "T3", "furigana": "わからなくなったところは、前[まえ]の章[しょう]に戻[もど]って学[まな]び直[なお]そう。", "sentence_source": "generated"}, {"text": "母は若いころに習った英会話を学び直して、旅行で使った。", "target_word": "学び直して", "complexity_tier": "T3", "furigana": "母[はは]は若[わか]いころに習[なら]った英会話[えいかいわ]を学[まな]び直[なお]して、旅行[りょこう]で使[つか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学び直す", "label": "終止形"}, {"form": "学び直した", "label": "過去形"}, {"form": "学び直して", "label": "て形"}, {"form": "学び直さない", "label": "否定形"}, {"form": "学び直そう", "label": "意志形"}, {"form": "学び直せば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "以前に習ったのに忘れたり不十分だったりした内容を、もう一度勉強し直すこと(日常的な復習)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41358, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学び直す", "is_correct": true, "explanation": "正解。「つもりだ」の前は辞書形で、計画を表す。"}, {"text": "学び直さ", "is_correct": false, "explanation": "未然形は「つもり」には続かない。"}, {"text": "学び直せ", "is_correct": false, "explanation": "命令形は「つもり」には続かない。"}, {"text": "学び直して", "is_correct": false, "explanation": "て形は「つもり」には続かない。"}], "explanations": {"学び直す": "正解。「つもりだ」の前は辞書形で、計画を表す。", "学び直さ": "未然形は「つもり」には続かない。", "学び直せ": "命令形は「つもり」には続かない。", "学び直して": "て形は「つもり」には続かない。"}, "sentence_index": 0, "correct_answer": "学び直す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今まで一度も習ったことのない天文学を、学び直すことにした。", "explanation": "ここは〈学ぶ〉〈習う〉の意味。学び直すは以前学んだ内容をもう一度学ぶ語で、未習の内容には合わない。"}, {"text": "汚れた窓を、もう一度学び直した。", "explanation": "ここは〈拭き直す〉の意味。学び直すは学習内容に使い、窓は対象にならない。"}, {"text": "昔の友人の顔を、ふと学び直した。", "explanation": "ここは〈思い出す〉の意味。学び直すは学習の再開を表し、顔には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41358, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学び直す", "is_correct": true, "explanation": "正解。「〜なら」の前は辞書形。"}, {"text": "学び直して", "is_correct": false, "explanation": "て形は「なら」には続かない。"}, {"text": "学び直そう", "is_correct": false, "explanation": "意志形は「〜なら」には続かず、文が成り立たない。"}, {"text": "学び直せば", "is_correct": false, "explanation": "仮定形に「なら」を続けると文が成り立たない。"}], "explanations": {"学び直す": "正解。「〜なら」の前は辞書形。", "学び直して": "て形は「なら」には続かない。", "学び直そう": "意志形は「〜なら」には続かず、文が成り立たない。", "学び直せば": "仮定形に「なら」を続けると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "学び直す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一度は退職を決めたが、考えを学び直して残ることにした。", "explanation": "ここは〈思い直す〉の意味。学び直すは知識や能力の学習に使い、考えの変更には使わない。"}, {"text": "失恋からようやく学び直すことができた。", "explanation": "ここは〈立ち直る〉の意味。学び直すは学習に限られ、気持ちの回復には使わない。"}, {"text": "失った信用を、学び直すため誠実に働き続けた。", "explanation": "ここは〈取り戻す〉の意味。学び直すは知識や能力に使い、信用には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41358, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "忘れた公式へ、もう一度学び直した。", "corrected_sentence": "忘れた公式を、もう一度学び直した。", "error_description": "「学び直す」の対象は「を」で示す。「公式へ」は方向を表すので誤りで、「公式を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "学び直している", "is_correct": true, "explanation": "正解。進行中の動作を表す「ている形」。"}, {"text": "学び直す", "is_correct": false, "explanation": "終止形では進行中の動作を表せず、文の意味が合わない。"}, {"text": "学び直さ", "is_correct": false, "explanation": "未然形のままでは文が終わらず、文として成り立たない。"}, {"text": "学び直さない", "is_correct": false, "explanation": "否定形は学ばないという意味になり、文の内容と逆になる。"}], "correct_form": "学び直している", "base_form": "学び直す", "form_label": "ている形", "sentence_index": 1, "explanations": {"学び直している": "正解。進行中の動作を表す「ている形」。", "学び直す": "終止形では進行中の動作を表せず、文の意味が合わない。", "学び直さ": "未然形のままでは文が終わらず、文として成り立たない。", "学び直さない": "否定形は学ばないという意味になり、文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41358, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週から、英語の文法を最初から学び直せと思う。", "corrected_sentence": "来週から、英語の文法を最初から学び直そうと思う。", "error_description": "「〜と思う」の前には意志形を使う。「学び直せ」は命令形なので、「学び直そう」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "学び直し", "is_correct": true, "explanation": "正解。「〜ている」の前は連用形。"}, {"text": "学び直そう", "is_correct": false, "explanation": "意志形は「〜ている」には続かず、文が成り立たない。"}, {"text": "学び直せ", "is_correct": false, "explanation": "命令形・仮定形は「〜ている」には続かない。"}, {"text": "学び直した", "is_correct": false, "explanation": "過去形は「〜ている」の前には続かず、文が成り立たない。"}], "correct_form": "学び直し", "base_form": "学び直す", "form_label": "連用形", "sentence_index": 7, "explanations": {"学び直し": "正解。「〜ている」の前は連用形。", "学び直そう": "意志形は「〜ている」には続かず、文が成り立たない。", "学び直せ": "命令形・仮定形は「〜ている」には続かない。", "学び直した": "過去形は「〜ている」の前には続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41359, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41359, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「夜間講座で」は学び直しが行われる場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。夜間講座が学び直すという意味になり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。夜間講座と学び直すという関係は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示す。学び直す場を表せず不自然。"}], "correct_answer": "で", "explanations": {"で": "正解。「夜間講座で」は学び直しが行われる場所を示す。", "が": "「が」は主語を示す。夜間講座が学び直すという意味になり、不自然。", "と": "「と」は相手や並列を示す。夜間講座と学び直すという関係は成り立たない。", "に": "「に」は到達点や相手を示す。学び直す場を表せず不自然。"}, "error_tags": {"が": "主語の格", "と": "並列・相手", "に": "到達・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41359, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "以前に学んだことをもう一度学ぶこと。特に、新たな能力を身につけるために再学習すること。", "primary_collocate": null, "pronunciation": "まなびなおす", "ipa": "manabinaosɯ", "syllable_count": 6, "sentences": [{"text": "そのため、社内外で新しい知識や技術を学び直すリスキリングが不可欠である。", "target_word": "学び直す", "complexity_tier": "T4", "furigana": "そのため、社内外[しゃないがい]で新[あたら]しい知識[ちしき]や技術[ぎじゅつ]を学[まな]び直[なお]すリスキリングが不可欠[ふかけつ]である。", "sentence_source": "mined"}, {"text": "転職を機に、大学院でデータ分析を学び直すことにした。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "転職[てんしょく]を機[き]に、大学院[だいがくいん]でデータ分析[ぶんせき]を学[まな]び直[なお]すことにした。", "sentence_source": "generated"}, {"text": "会社は社員が新しい技術を学び直す機会を支援している。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]が新[あたら]しい技術[ぎじゅつ]を学[まな]び直[なお]す機会[きかい]を支援[しえん]している。", "sentence_source": "generated"}, {"text": "時代の変化が速いので、大人になってからも学び直すことが大切だ。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "時代[じだい]の変化[へんか]が速[はや]いので、大人[おとな]になってからも学[まな]び直[なお]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼女は子育てが落ち着いてから、会計の知識を学び直して資格を取った。", "target_word": "学び直して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は子育[こそだ]てが落[お]ち着[つ]いてから、会計[かいけい]の知識[ちしき]を学[まな]び直[なお]して資格[しかく]を取[と]った。", "sentence_source": "generated"}, {"text": "定年後に語学を学び直したいと考える人が増えている。", "target_word": "学び直したい", "complexity_tier": "T3", "furigana": "定年後[ていねんご]に語学[ごがく]を学[まな]び直[なお]したいと考[かんが]える人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "AIを使う仕事に就くために、基礎から学び直さなければならない。", "target_word": "学び直さ", "complexity_tier": "T3", "furigana": "AIを使[つか]う仕事[しごと]に就[つ]くために、基礎[きそ]から学[まな]び直[なお]さなければならない。", "sentence_source": "generated"}, {"text": "夜間講座で学び直した経験が、昇進につながった。", "target_word": "学び直した", "complexity_tier": "T3", "furigana": "夜間講座[やかんこうざ]で学[まな]び直[なお]した経験[けいけん]が、昇進[しょうしん]につながった。", "sentence_source": "generated"}, {"text": "新しい分野に挑戦するなら、まず必要な技能を学び直すべきだ。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "新[あたら]しい分野[ぶんや]に挑戦[ちょうせん]するなら、まず必要[ひつよう]な技能[ぎのう]を学[まな]び直[なお]すべきだ。", "sentence_source": "generated"}, {"text": "学び直す意欲があれば、年齢に関係なく新しい仕事に移れる。", "target_word": "学び直す", "complexity_tier": "T3", "furigana": "学[まな]び直[なお]す意欲[いよく]があれば、年齢[ねんれい]に関係[かんけい]なく新[あたら]しい仕事[しごと]に移[うつ]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学び直す", "label": "終止形"}, {"form": "学び直した", "label": "過去形"}, {"form": "学び直して", "label": "て形"}, {"form": "学び直さない", "label": "否定形"}, {"form": "学び直したい", "label": "願望形"}, {"form": "学び直せば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "新しい能力や仕事のために、社会人などが知識・技術を再び学ぶこと(リスキリング的)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 社内外 (Zipf 1.9)','sentence 9 above tier T3: contains vocabulary far above tier T3: 移れる (Zipf 1.97)']::text[], '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41359, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学び直す", "is_correct": true, "explanation": "正解。「新しい知識や技術を学び直す」が「リスキリング」を修飾し、再学習の内容を説明する。"}, {"text": "引き受ける", "is_correct": false, "explanation": "「引き受ける」は仕事などを請け負う意味。「引き受けるリスキリング」では知識や技術を学ぶ内容と合わない。"}, {"text": "片付ける", "is_correct": false, "explanation": "「片付ける」は物を整理する、または仕事を終わらせる意味で、学習の内容を指せない。"}, {"text": "買い換える", "is_correct": false, "explanation": "「買い換える」は新しい物に替える意味で、知識や技術には使わない。"}], "explanations": {"学び直す": "正解。「新しい知識や技術を学び直す」が「リスキリング」を修飾し、再学習の内容を説明する。", "引き受ける": "「引き受ける」は仕事などを請け負う意味。「引き受けるリスキリング」では知識や技術を学ぶ内容と合わない。", "片付ける": "「片付ける」は物を整理する、または仕事を終わらせる意味で、学習の内容を指せない。", "買い換える": "「買い換える」は新しい物に替える意味で、知識や技術には使わない。"}, "sentence_index": 0, "correct_answer": "学び直す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この春、初めて簿記を学び直すことにした。", "explanation": "ここは〈習う〉の意味。学び直すは以前学んだ内容が前提なので、初めての学習には合わない。"}, {"text": "散らかった部屋を、休日にもう一度学び直した。", "explanation": "ここは〈片付け直す〉の意味。学び直すは学習内容が対象で、部屋は対象にならない。"}, {"text": "地震で崩れた家を、学び直すことになった。", "explanation": "ここは〈建て直す〉の意味。学び直すは知識や能力の再学習に使い、建物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41359, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学び直さ", "is_correct": true, "explanation": "正解。「〜なければならない」の前は未然形。"}, {"text": "学び直し", "is_correct": false, "explanation": "連用形は「〜なければならない」には続かない。"}, {"text": "学び直す", "is_correct": false, "explanation": "終止形を「なければならない」の前に置くと文が成立しない。"}, {"text": "学び直せ", "is_correct": false, "explanation": "命令形は義務の表現には接続しない。"}], "explanations": {"学び直さ": "正解。「〜なければならない」の前は未然形。", "学び直し": "連用形は「〜なければならない」には続かない。", "学び直す": "終止形を「なければならない」の前に置くと文が成立しない。", "学び直せ": "命令形は義務の表現には接続しない。"}, "sentence_index": 6, "correct_answer": "学び直さ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "フリーズしたパソコンを、再起動して学び直した。", "explanation": "ここは〈再起動する〉の意味。学び直すは人が知識や技能を身につけ直すことで、機械には使わない。"}, {"text": "雨で写りの悪くなった写真を、学び直した。", "explanation": "ここは〈撮り直す〉の意味。学び直すは知識や能力の再学習に使い、写真の撮影には使わない。"}, {"text": "失恋からようやく学び直すことができた。", "explanation": "ここは〈立ち直る〉の意味。学び直すは学習に限られ、気持ちの回復には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41359, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社の研修で、社員は最新の会計ソフトに学び直す。", "corrected_sentence": "会社の研修で、社員は最新の会計ソフトを学び直す。", "error_description": "「学び直す」の対象は「を」で示す。「会計ソフトに」は誤りで、「会計ソフトを」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "学び直す", "is_correct": true, "explanation": "正解。「〜ことにした」の前は辞書形。"}, {"text": "学び直さ", "is_correct": false, "explanation": "未然形のままでは「ことにした」に続かず、文として成り立たない。"}, {"text": "学び直して", "is_correct": false, "explanation": "て形は文を続ける形で、「〜ことにした」の直前には置けない。"}, {"text": "学び直せば", "is_correct": false, "explanation": "仮定形は「〜ことにした」の前には続かない。"}], "correct_form": "学び直す", "base_form": "学び直す", "form_label": "終止形", "sentence_index": 1, "explanations": {"学び直す": "正解。「〜ことにした」の前は辞書形。", "学び直さ": "未然形のままでは「ことにした」に続かず、文として成り立たない。", "学び直して": "て形は文を続ける形で、「〜ことにした」の直前には置けない。", "学び直せば": "仮定形は「〜ことにした」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41359, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末の時間を使って、英語を学び直そうために通信講座を申し込んだ。", "corrected_sentence": "週末の時間を使って、英語を学び直すために通信講座を申し込んだ。", "error_description": "「〜ために」の前は辞書形。「学び直そう」は意志形なので、「学び直すために」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "学び直した", "is_correct": true, "explanation": "正解。過去に行った経験を修飾する過去形。"}, {"text": "学び直せ", "is_correct": false, "explanation": "命令形は名詞「経験」を修飾できず、文として成り立たない。"}, {"text": "学び直そう", "is_correct": false, "explanation": "意志形は名詞「経験」を直接修飾できず、文が不自然になる。"}, {"text": "学び直さない", "is_correct": false, "explanation": "否定形にすると「学び直さない経験」となり、文の意味が変わる。"}], "correct_form": "学び直した", "base_form": "学び直す", "form_label": "過去形", "sentence_index": 7, "explanations": {"学び直した": "正解。過去に行った経験を修飾する過去形。", "学び直せ": "命令形は名詞「経験」を修飾できず、文として成り立たない。", "学び直そう": "意志形は名詞「経験」を直接修飾できず、文が不自然になる。", "学び直さない": "否定形にすると「学び直さない経験」となり、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41360, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「対人の力」で、対人が力の内容を修飾する。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「対人が力が育つ」は主語が二つ並び不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「育つ」は目的語を取らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示す。「対人に力が育つ」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「対人の力」で、対人が力の内容を修飾する。", "が": "「が」は主語を示す。「対人が力が育つ」は主語が二つ並び不自然。", "を": "「を」は目的語を示すが、「育つ」は目的語を取らない。", "に": "「に」は位置や相手を示す。「対人に力が育つ」は意味が通らない。"}, "error_tags": {"が": "主語の格", "を": "目的語の格", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41360, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「対人の悩み」で、対人が悩みの内容を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示す。「増える」は自動詞なので「対人を」は続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「対人へ悩み」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。「対人と悩み」は並ぶ関係として不自然。"}], "correct_answer": "の", "explanations": {"の": "正解。「対人の悩み」で、対人が悩みの内容を修飾する。", "を": "「を」は他動詞の目的語を示す。「増える」は自動詞なので「対人を」は続かない。", "へ": "「へ」は方向を示す。「対人へ悩み」は文として成り立たない。", "と": "「と」は並列を示す。「対人と悩み」は並ぶ関係として不自然。"}, "error_tags": {"を": "目的語の格", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41360, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人と話したり、仲良くしたりすること。", "primary_collocate": null, "pronunciation": "たいじん", "ipa": "taidʑiɴ", "syllable_count": 4, "sentences": [{"text": "人見知りの弟は、対人の場に出るとすぐ黙ってしまう。", "target_word": "対人", "complexity_tier": "T3", "furigana": "人見知[ひとみし]りの弟[おとうと]は、対人[たいじん]の場[ば]に出[で]るとすぐ黙[だま]ってしまう。", "sentence_source": "generated"}, {"text": "友だちと遊ぶことで、対人の力が育つ。", "target_word": "対人", "complexity_tier": "T3", "furigana": "友[とも]だちと遊[あそ]ぶことで、対人[たいじん]の力[ちから]が育[そだ]つ。", "sentence_source": "generated"}, {"text": "大人数の飲み会は、対人の場が苦手な私には少し大変だ。", "target_word": "対人", "complexity_tier": "T3", "furigana": "大人数[おおにんずう]の飲[の]み会[かい]は、対人[たいじん]の場[ば]が苦手[にがて]な私[わたし]には少[すこ]し大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "対人の機会が減ると、人と話すのが怖くなることがある。", "target_word": "対人", "complexity_tier": "T3", "furigana": "対人[たいじん]の機会[きかい]が減[へ]ると、人[ひと]と話[はな]すのが怖[こわ]くなることがある。", "sentence_source": "generated"}, {"text": "アルバイトは、対人の経験を積むいい機会だ。", "target_word": "対人", "complexity_tier": "T3", "furigana": "アルバイトは、対人[たいじん]の経験[けいけん]を積[つ]むいい機会[きかい]だ。", "sentence_source": "generated"}, {"text": "対人の関わりでは、相手の目を見て挨拶することが基本だ。", "target_word": "対人", "complexity_tier": "T3", "furigana": "対人[たいじん]の関[かか]わりでは、相手[あいて]の目[め]を見[み]て挨拶[あいさつ]することが基本[きほん]だ。", "sentence_source": "generated"}, {"text": "彼は対人の感覚がよく、誰とでもすぐ仲良くなる。", "target_word": "対人", "complexity_tier": "T3", "furigana": "彼[かれ]は対人[たいじん]の感覚[かんかく]がよく、誰[だれ]とでもすぐ仲良[なかよ]くなる。", "sentence_source": "generated"}, {"text": "引っ越してから、対人の悩みが増えて夜眠れなくなった。", "target_word": "対人", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してから、対人[たいじん]の悩[なや]みが増[ふ]えて夜[よる]眠[ねむ]れなくなった。", "sentence_source": "generated"}, {"text": "初めての対人の場では、笑顔で挨拶するようにしている。", "target_word": "対人", "complexity_tier": "T3", "furigana": "初[はじ]めての対人[たいじん]の場[ば]では、笑顔[えがお]で挨拶[あいさつ]するようにしている。", "sentence_source": "generated"}, {"text": "留学して対人の経験を重ね、人前で話すのが怖くなくなった。", "target_word": "対人", "complexity_tier": "T3", "furigana": "留学[りゅうがく]して対人[たいじん]の経験[けいけん]を重[かさ]ね、人前[ひとまえ]で話[はな]すのが怖[こわ]くなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対人", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "日常生活で人と話したり付き合ったりすること(人づき合いの場面や力)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41360, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対人", "is_correct": true, "explanation": "正解。「対人の場」は人と話したり付き合ったりする場面を指す。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の場」は人付き合いの場面を表さず、文の意味に合わない。"}, {"text": "数値", "is_correct": false, "explanation": "「数値の場」は人と話す場面とは無関係。"}, {"text": "機械", "is_correct": false, "explanation": "「機械の場」は人付き合いの場面を指せない。"}], "explanations": {"対人": "正解。「対人の場」は人と話したり付き合ったりする場面を指す。", "天気": "「天気の場」は人付き合いの場面を表さず、文の意味に合わない。", "数値": "「数値の場」は人と話す場面とは無関係。", "機械": "「機械の場」は人付き合いの場面を指せない。"}, "sentence_index": 0, "correct_answer": "対人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "久しぶりに会った友だちと、対人が弾んだ。", "explanation": "ここは〈会話〉の意味。〈弾む〉は話の流れに使うもので、〈対人〉は人と接する性質なので合わない。"}, {"text": "病院での対人時間は十時までだ。", "explanation": "ここは〈面会〉の意味。〈対人〉は人と接する性質を表し、来訪して会う時間は指さない。"}, {"text": "彼は恋人と対人を続けている。", "explanation": "ここは〈交際〉の意味。〈対人〉は人付き合いの能力や場面を指し、恋人との関係は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41360, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対人", "is_correct": true, "explanation": "正解。「対人の感覚」は人と接する力や勘を指す。"}, {"text": "陶器", "is_correct": false, "explanation": "「陶器の感覚」は人付き合いの力を表さない。"}, {"text": "天候", "is_correct": false, "explanation": "「天候の感覚」は人と接する力とは無関係。"}, {"text": "海藻", "is_correct": false, "explanation": "「海藻の感覚」は文の意味に合わない。"}], "explanations": {"対人": "正解。「対人の感覚」は人と接する力や勘を指す。", "陶器": "「陶器の感覚」は人付き合いの力を表さない。", "天候": "「天候の感覚」は人と接する力とは無関係。", "海藻": "「海藻の感覚」は文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "対人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日の対人を考えておいた。", "explanation": "ここは〈対策〉の意味。〈対人〉は人と接する性質や場面を表し、雨への備えは指さない。"}, {"text": "彼は対人が激しく、初対面の人とは目を合わせられない。", "explanation": "ここは〈人見知り〉の意味。〈対人〉は人と接する性質を表し、性格の強さは言い表せない。"}, {"text": "話を聞きながら、対人を打つ。", "explanation": "ここは〈相槌〉の意味。〈対人〉は相槌を打つものではなく、人と接する性質を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41360, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は初対面の人と話すことが多く、対人を慣れている。", "corrected_sentence": "彼女は初対面の人と話すことが多く、対人に慣れている。", "error_description": "「慣れる」は「に」を取る。「対人を」は誤りで、「対人に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41360, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は対人に苦手で、人前では声が小さくなる。", "corrected_sentence": "私は対人が苦手で、人前では声が小さくなる。", "error_description": "「苦手だ」は「〜が苦手」と「が」を取る。「対人に」は誤りで、「対人が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41361, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「対人の仕事」で、対人が仕事の性質を修飾する。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「対人へ仕事なので」は文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「対人を仕事なので」は文がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「対人に仕事」は文の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「対人の仕事」で、対人が仕事の性質を修飾する。", "へ": "「へ」は方向を示す。「対人へ仕事なので」は文として成り立たない。", "を": "「対人を仕事なので」は文がつながらない。", "に": "「対人に仕事」は文の関係が成り立たない。"}, "error_tags": {"へ": "方向", "を": "目的語の格", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41361, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「対人の経験」で、対人が経験の内容を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「経験が豊富」の前に「対人を」は続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「対人へ経験」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。「対人と経験」は並ぶ語として不自然。"}], "correct_answer": "の", "explanations": {"の": "正解。「対人の経験」で、対人が経験の内容を修飾する。", "を": "「を」は目的語を示す。「経験が豊富」の前に「対人を」は続かない。", "へ": "「へ」は方向を示す。「対人へ経験」は文として成り立たない。", "と": "「と」は並列を示す。「対人と経験」は並ぶ語として不自然。"}, "error_tags": {"を": "目的語の格", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41361, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人を相手にすること。人と接するさま。", "primary_collocate": null, "pronunciation": "たいじん", "ipa": "taidʑiɴ", "syllable_count": 4, "sentences": [{"text": "企業は、単純な作業だけでなく、創造性や対人スキルを求められる役割へ従業員をシフトさせなければならない。", "target_word": "対人", "complexity_tier": "T4", "furigana": "企業[きぎょう]は、単純[たんじゅん]な作業[さぎょう]だけでなく、創造性[そうぞうせい]や対人[たいじん]スキルを求[もと]められる役割[やくわり]へ従業員[じゅうぎょういん]をシフトさせなければならない。", "sentence_source": "mined"}, {"text": "接客は対人の仕事なので、相手の表情をよく見ることが大切だ。", "target_word": "対人", "complexity_tier": "T3", "furigana": "接客[せっきゃく]は対人[たいじん]の仕事[しごと]なので、相手[あいて]の表情[ひょうじょう]をよく見[み]ることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼は対人の場面になると緊張して、声が小さくなってしまう。", "target_word": "対人", "complexity_tier": "T3", "furigana": "彼[かれ]は対人[たいじん]の場面[ばめん]になると緊張[きんちょう]して、声[こえ]が小[ちい]さくなってしまう。", "sentence_source": "generated"}, {"text": "対人の業務が多い部署では、聞く力が特に求められる。", "target_word": "対人", "complexity_tier": "T3", "furigana": "対人[たいじん]の業務[ぎょうむ]が多[おお]い部署[ぶしょ]では、聞[き]く力[ちから]が特[とく]に求[もと]められる。", "sentence_source": "generated"}, {"text": "医師や看護師のような対人の職業は、体力だけでなく気配りも必要だ。", "target_word": "対人", "complexity_tier": "T3", "furigana": "医師[いし]や看護師[かんごし]のような対人[たいじん]の職業[しょくぎょう]は、体力[たいりょく]だけでなく気配[きくば]りも必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "在宅勤務が続いて、対人の経験が減ったと感じている。", "target_word": "対人", "complexity_tier": "T3", "furigana": "在宅勤務[ざいたくきんむ]が続[つづ]いて、対人[たいじん]の経験[けいけん]が減[へ]ったと感[かん]じている。", "sentence_source": "generated"}, {"text": "店員や介護職のような対人の仕事は機械に任せにくいので、人手不足が続いている。", "target_word": "対人", "complexity_tier": "T3", "furigana": "店員[てんいん]や介護職[かいごしょく]のような対人[たいじん]の仕事[しごと]は機械[きかい]に任[まか]せにくいので、人手[ひとで]不足[ぶそく]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "彼女は対人の経験が豊富で、初対面の人ともすぐ打ち解ける。", "target_word": "対人", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は対人[たいじん]の経験[けいけん]が豊富[ほうふ]で、初対面[しょたいめん]の人[ひと]ともすぐ打ち解[うちと]ける。", "sentence_source": "generated"}, {"text": "対人の仕事に疲れて、一人で作業できる職場へ移りたいと思った。", "target_word": "対人", "complexity_tier": "T3", "furigana": "対人[たいじん]の仕事[しごと]に疲[つか]れて、一人[ひとり]で作業[さぎょう]できる職場[しょくば]へ移[うつ]りたいと思[おも]った。", "sentence_source": "generated"}, {"text": "新入社員向けの研修では、電話応対など対人の場での振る舞いを学ぶ。", "target_word": "対人", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]向[む]けの研修[けんしゅう]では、電話応対[でんわおうたい]など対人[たいじん]の場[ば]での振[ふ]る舞[ま]いを学[まな]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対人", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "仕事や職業の場面で、人を相手にすること・人と接する性質(対人スキル・対人サービスなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41361, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対人", "is_correct": true, "explanation": "正解。「対人スキル」は人と接する能力を指す。"}, {"text": "食品", "is_correct": false, "explanation": "「食品スキル」という言い方はなく、人と接する能力を表さない。"}, {"text": "天候", "is_correct": false, "explanation": "「天候スキル」は人との関わりを表さず、文の意味に合わない。"}, {"text": "数値", "is_correct": false, "explanation": "「数値スキル」は人と接する能力とは無関係。"}], "explanations": {"対人": "正解。「対人スキル」は人と接する能力を指す。", "食品": "「食品スキル」という言い方はなく、人と接する能力を表さない。", "天候": "「天候スキル」は人との関わりを表さず、文の意味に合わない。", "数値": "「数値スキル」は人と接する能力とは無関係。"}, "sentence_index": 0, "correct_answer": "対人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トラブルへの対人を迅速に行う。", "explanation": "ここは〈対応〉の意味。〈対人〉は人を相手にする性質を表し、トラブルの処理には使わない。"}, {"text": "この調査の対人は中学生だ。", "explanation": "ここは〈対象〉の意味。〈対人〉は人と接する性質を表し、調査の対象は指さない。"}, {"text": "在宅勤務が終わり、対人で会議をするようになった。", "explanation": "ここは〈対面〉の意味。〈対人〉は会議の形式（直接会うこと）を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41361, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対人", "is_correct": true, "explanation": "正解。店員や介護職のように、人を相手にする仕事を指す。"}, {"text": "機械", "is_correct": false, "explanation": "「機械の仕事」では、後の「機械に任せにくい」と矛盾する。"}, {"text": "燃料", "is_correct": false, "explanation": "「燃料の仕事」は人を相手にする仕事の説明にならない。"}, {"text": "漁業", "is_correct": false, "explanation": "「漁業の仕事」は店員や介護職と並ぶ、人を相手にする仕事の例にならない。"}], "explanations": {"対人": "正解。店員や介護職のように、人を相手にする仕事を指す。", "機械": "「機械の仕事」では、後の「機械に任せにくい」と矛盾する。", "燃料": "「燃料の仕事」は人を相手にする仕事の説明にならない。", "漁業": "「漁業の仕事」は店員や介護職と並ぶ、人を相手にする仕事の例にならない。"}, "sentence_index": 6, "correct_answer": "対人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "機械の対人を毎日行う。", "explanation": "ここは〈点検〉の意味。〈対人〉は作業の名詞ではなく、機械の点検には使えない。"}, {"text": "二人の性格の対人が面白い。", "explanation": "ここは〈対比〉の意味。〈対人〉は人と接する性質を表し、性格同士の比べ合わせは指さない。"}, {"text": "就職の対人で、まず自己紹介をする。", "explanation": "ここは〈面接〉の意味。面接は選考の場を指す語で、〈対人〉は人と接する性質を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41361, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は対人を苦手だが、接客のアルバイトを続けている。", "corrected_sentence": "私は対人が苦手だが、接客のアルバイトを続けている。", "error_description": "「苦手だ」は「〜が苦手だ」と「が」を取る。「対人を」は誤りで、「対人が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41361, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は対人な仕事が得意で、お客さんとすぐ打ち解ける。", "corrected_sentence": "彼女は対人の仕事が得意で、お客さんとすぐ打ち解ける。", "error_description": "「対人」は名詞なので、名詞につなぐには「の」を使う。「対人な」は不自然で、「対人の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
