INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41362, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "しろ。しろい いろ。", "primary_collocate": null, "pronunciation": "ほわいと", "ipa": "hoɰaito", "syllable_count": 4, "sentences": [{"text": "ホワイトの運動靴は、雨の日にすぐ汚れる。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "ホワイトの運動靴(うんどうぐつ)は、雨(あめ)の日(ひ)にすぐ汚(よご)れる。", "sentence_source": "generated"}, {"text": "このノートパソコンはホワイトで、見た目がとてもきれいだ。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "このノートパソコンはホワイトで、見(み)た目(め)がとてもきれいだ。", "sentence_source": "generated"}, {"text": "壁をホワイトに塗ると、部屋が明るくなる。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "壁(かべ)をホワイトに塗(ぬ)ると、部屋(へや)が明(あか)るくなる。", "sentence_source": "generated"}, {"text": "兄は黒より、ホワイトの自転車のほうが好きだと言った。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "兄(あに)は黒(くろ)より、ホワイトの自転車(じてんしゃ)のほうが好(す)きだと言(い)った。", "sentence_source": "generated"}, {"text": "ホワイトの花びらが風に舞っていた。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "ホワイトの花(はな)びらが風(かぜ)に舞(ま)っていた。", "sentence_source": "generated"}, {"text": "冬の山は雪が積もってホワイトの景色になり、とても美しかった。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "冬(ふゆ)の山(やま)は雪(ゆき)が積(つ)もってホワイトの景色(けしき)になり、とても美(うつく)しかった。", "sentence_source": "generated"}, {"text": "カップの色はホワイトとピンクから選べます。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "カップの色(いろ)はホワイトとピンクから選(えら)べます。", "sentence_source": "generated"}, {"text": "汚れが目立つのに、彼女はいつもホワイトを選ぶ。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "汚(よご)れが目立(めだ)つのに、彼女(かのじょ)はいつもホワイトを選(えら)ぶ。", "sentence_source": "generated"}, {"text": "ホワイトのカーテンを付けたら、部屋が広く感じられた。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "ホワイトのカーテンを付(つ)けたら、部屋(へや)が広(ひろ)く感(かん)じられた。", "sentence_source": "generated"}, {"text": "ホワイトの大きな犬が庭を走っている。", "target_word": "ホワイト", "complexity_tier": "T3", "furigana": "ホワイトの大(おお)きな犬(いぬ)が庭(にわ)を走(はし)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ホワイト", "label": "基本形"}], "register": "標準", "sense_fingerprint": "しろい色。物の色を言うときの白。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41362, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ホワイト", "is_correct": true, "explanation": "「〜の運動靴」と色を表す名詞として入る。雨で汚れるという文脈とも合う。"}, {"text": "ソファ", "is_correct": false, "explanation": "ソファは運動靴の色や種類を表さず、「〜の運動靴」の形にならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は靴の修飾に使わず、文として通らない。"}, {"text": "豆腐", "is_correct": false, "explanation": "豆腐は食品で、靴の色や種類を表さない。"}], "explanations": {"ホワイト": "「〜の運動靴」と色を表す名詞として入る。雨で汚れるという文脈とも合う。", "ソファ": "ソファは運動靴の色や種類を表さず、「〜の運動靴」の形にならない。", "鉛筆": "鉛筆は靴の修飾に使わず、文として通らない。", "豆腐": "豆腐は食品で、靴の色や種類を表さない。"}, "sentence_index": 0, "correct_answer": "ホワイト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験の途中で、頭がホワイトになった。", "explanation": "ここは〈真っ白〉の意味（頭が働かなくなる）。色のホワイトでは「頭が真っ白になった」の意味が出せない。"}, {"text": "朝起きて、まずホワイトを一杯飲んだ。", "explanation": "ここは〈白湯〉の意味（沸かして冷ました湯）。色の白では飲み物を指せないので合わない。"}, {"text": "寝不足で、ホワイトが赤く充血していた。", "explanation": "ここは〈白目〉の意味（目の白い部分）。色の白では目の一部を指せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41362, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ホワイト", "is_correct": true, "explanation": "「ホワイトとピンク」と色の候補を並べる名詞。カップの色の選択肢として正しい。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "ヨーグルトはカップの色の候補にならず、「〜から選べる」の文脈に合わない。"}, {"text": "ドライヤー", "is_correct": false, "explanation": "ドライヤーは色ではなく、カップの色の選択肢として成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団はカップの色の候補として成り立たず、文が通らない。"}], "explanations": {"ホワイト": "「ホワイトとピンク」と色の候補を並べる名詞。カップの色の選択肢として正しい。", "ヨーグルト": "ヨーグルトはカップの色の候補にならず、「〜から選べる」の文脈に合わない。", "ドライヤー": "ドライヤーは色ではなく、カップの色の選択肢として成り立たない。", "座布団": "座布団はカップの色の候補として成り立たず、文が通らない。"}, "sentence_index": 6, "correct_answer": "ホワイト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この答案は何も書かず、ホワイトのまま提出された。", "explanation": "ここは〈白紙〉の意味（何も書いていない紙）。色の白を表すホワイトでは、この状態は言えない。"}, {"text": "夕食はホワイトと味噌汁だった。", "explanation": "ここは〈白米〉の意味（精白した米）。色の白を表すホワイトでは、ご飯を指すことはできない。"}, {"text": "ホワイトが岸に寄せては返していた。", "explanation": "ここは〈白波〉の意味（白く泡立つ波）。色の白では波そのものを指せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41362, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の海辺に、ホワイトに帽子をかぶった人がいた。", "corrected_sentence": "夏の海辺に、ホワイトの帽子をかぶった人がいた。", "error_description": "「ホワイトの帽子」と色を修飾するには「の」が必要。「ホワイトに」の「に」は場所や方向を表すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41362, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの帽子はホワイトたった。", "corrected_sentence": "あの帽子はホワイトだった。", "error_description": "「だった」の「だ」が「た」に変わっている（ホワイトたった）。「たった」は「ただ」の意味の副詞になり、名詞述語の過去形としては誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41364, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『エースとして』の『と』。資格や立場を表し、文の流れに合う。"}, {"text": "に", "is_correct": false, "explanation": "『エースにして』は『エースにする』の形で、『エースとして』の立場を表す『と』とは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表す。『エースへして』は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『エースの』は連体修飾。『エースのして』は文法的に続かない。"}], "correct_answer": "と", "explanations": {"と": "『エースとして』の『と』。資格や立場を表し、文の流れに合う。", "に": "『エースにして』は『エースにする』の形で、『エースとして』の立場を表す『と』とは合わない。", "へ": "『へ』は方向を表す。『エースへして』は成り立たない。", "の": "『エースの』は連体修飾。『エースのして』は文法的に続かない。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "に": "結果"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41364, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41364, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをがんばってやって、みんなにすごいとおもわれること。", "primary_collocate": null, "pronunciation": "かつやく", "ipa": "kat͡sɯjakɯ", "syllable_count": 4, "sentences": [{"text": "運動会のリレーで、ゆうたくんが活躍した。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]のリレーで、ゆうたくんが活躍[かつやく]した。", "sentence_source": "generated"}, {"text": "兄はサッカー部のエースとして活躍している。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "兄[あに]はサッカー部[ぶ]のエースとして活躍[かつやく]している。", "sentence_source": "generated"}, {"text": "試合での彼女の活躍に、みんなが拍手を送った。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "試合[しあい]での彼女[かのじょ]の活躍[かつやく]に、みんなが拍手[はくしゅ]を送[おく]った。", "sentence_source": "generated"}, {"text": "活躍した選手には、先生からメダルがわたされた。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "活躍[かつやく]した選手[せんしゅ]には、先生[せんせい]からメダルがわたされた。", "sentence_source": "generated"}, {"text": "弟は学芸会で、主役として活躍した。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "弟[おとうと]は学芸会[がくげいかい]で、主役[しゅやく]として活躍[かつやく]した。", "sentence_source": "generated"}, {"text": "野球が好きな私は、日本人選手の活躍をテレビで見るのが楽しみだ。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "野球[やきゅう]が好[す]きな私[わたし]は、日本人[にほんじん]選手[せんしゅ]の活躍[かつやく]をテレビで見[み]るのが楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "今日の活躍はすごかったね。ヒーローみたいだった。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "今日[きょう]の活躍[かつやく]はすごかったね。ヒーローみたいだった。", "sentence_source": "generated"}, {"text": "活躍できるように、毎日たくさん練習している。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "活躍[かつやく]できるように、毎日[まいにち]たくさん練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "クラスの係で活躍した人が、先生にほめられた。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "クラスの係[かかり]で活躍[かつやく]した人[ひと]が、先生[せんせい]にほめられた。", "sentence_source": "generated"}, {"text": "姉は水泳大会で活躍して、金メダルをとった。", "target_word": "活躍", "complexity_tier": "T3", "furigana": "姉[あね]は水泳大会[すいえいたいかい]で活躍[かつやく]して、金[きん]メダルをとった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活躍する", "label": "基本形"}, {"form": "活躍した", "label": "過去形"}, {"form": "活躍して", "label": "テ形"}], "register": "標準", "sense_fingerprint": "がんばって目立つ働きをして、みんなに感心されること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: わたさ (Zipf 2.15)']::text[], '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41364, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活躍", "is_correct": true, "explanation": "空欄に入るのは『活躍』だけ。リレーで目立つ働きをした意味に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "『リレーで翻訳した』は意味が通らない。翻訳は言語を置きかえる作業で、競技の場面には入らない。"}, {"text": "消毒", "is_correct": false, "explanation": "『リレーで消毒した』は文脈に合わない。消毒は菌を殺す行為を指す。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものをとかす意味で、リレーの文脈には入らない。"}], "explanations": {"活躍": "空欄に入るのは『活躍』だけ。リレーで目立つ働きをした意味に合う。", "翻訳": "『リレーで翻訳した』は意味が通らない。翻訳は言語を置きかえる作業で、競技の場面には入らない。", "消毒": "『リレーで消毒した』は文脈に合わない。消毒は菌を殺す行為を指す。", "解凍": "凍ったものをとかす意味で、リレーの文脈には入らない。"}, "sentence_index": 0, "correct_answer": "活躍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一日中部屋で寝ていて、活躍した。", "explanation": "ここは〈休む〉の意味。体を休めることは〈休む〉で表し、〈活躍〉は人に認められる目立つ働きを指すので合わない。"}, {"text": "祭りの夜、町中が活躍に満ちていた。", "explanation": "ここは〈活気〉の意味。〈活躍〉は人の目立つ働きを指すので、町のにぎわいの表現には合わない。"}, {"text": "あの店は連日、活躍だ。", "explanation": "ここは〈盛況〉の意味。店のにぎわいは〈盛況〉で表し、〈活躍〉は人の働きに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41364, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活躍", "is_correct": true, "explanation": "『今日の活躍』は、目立つ働きを指す語として文に合う。"}, {"text": "消灯", "is_correct": false, "explanation": "『今日の消灯はすごかった』は意味が通らない。消灯は明かりを消すこと。"}, {"text": "放電", "is_correct": false, "explanation": "電気を放出する現象で、人の働きを評価する文脈には入らない。"}, {"text": "誤植", "is_correct": false, "explanation": "印刷の誤りを指し、『ヒーローみたいだった』と続く文脈と合わない。"}], "explanations": {"活躍": "『今日の活躍』は、目立つ働きを指す語として文に合う。", "消灯": "『今日の消灯はすごかった』は意味が通らない。消灯は明かりを消すこと。", "放電": "電気を放出する現象で、人の働きを評価する文脈には入らない。", "誤植": "印刷の誤りを指し、『ヒーローみたいだった』と続く文脈と合わない。"}, "sentence_index": 6, "correct_answer": "活躍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合は大いに活躍した。", "explanation": "ここは〈盛り上がる〉の意味。試合の熱気は〈盛り上がる〉で表し、〈活躍〉は人の目立つ働きに使う。"}, {"text": "彼は会議で一言も発言せず、ただ座って活躍していた。", "explanation": "ここは〈傍観〉の意味。関わらず見ているだけの様子は〈傍観〉で表し、〈活躍〉は積極的に成果を出す働きに使う。"}, {"text": "夏の海岸は多くの客で活躍する。", "explanation": "ここは〈賑わう〉の意味。場所のにぎわいは〈賑わう〉で表し、〈活躍〉は人の働きに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41364, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "チームは彼の活躍を勝った。", "corrected_sentence": "チームは彼の活躍で勝った。", "error_description": "『活躍』に付く助詞が誤り。手段・原因を表す『で』が正しく、『を』は目的語になって『勝つ』と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41364, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は舞台に活躍した。", "corrected_sentence": "彼は舞台で活躍した。", "error_description": "活躍の場所を表す助詞が誤り。場所の『で』が正しく、『に』は到着点を表すので『活躍』と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41365, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『社会で活躍できる』の『で』。活動する場所や場面を表し、文の流れに合う。"}, {"text": "を", "is_correct": false, "explanation": "『社会を活躍できる』は目的語になり、『活躍』は目的語を取らないので誤り。"}, {"text": "へ", "is_correct": false, "explanation": "『社会へ活躍できる』は方向を表すが、活動の場所を示す文にはならない。"}, {"text": "の", "is_correct": false, "explanation": "『社会の活躍できる』は連体修飾だが、文として続かない。"}], "correct_answer": "で", "explanations": {"で": "『社会で活躍できる』の『で』。活動する場所や場面を表し、文の流れに合う。", "を": "『社会を活躍できる』は目的語になり、『活躍』は目的語を取らないので誤り。", "へ": "『社会へ活躍できる』は方向を表すが、活動の場所を示す文にはならない。", "の": "『社会の活躍できる』は連体修飾だが、文として続かない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41365, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『国際会議で活躍した』の『で』。活躍の場所を表し、文の流れに合う。"}, {"text": "に", "is_correct": false, "explanation": "『国際会議に活躍した』は到着点を表す『に』で、活躍の場所を示す文には合わない。"}, {"text": "を", "is_correct": false, "explanation": "『国際会議を活躍した』は目的語になるが、『活躍』は目的語を取らないので誤り。"}, {"text": "より", "is_correct": false, "explanation": "『国際会議より活躍した』は比較を表し、ここでは比べる文脈がなく意味が合わない。"}], "correct_answer": "で", "explanations": {"で": "『国際会議で活躍した』の『で』。活躍の場所を表し、文の流れに合う。", "に": "『国際会議に活躍した』は到着点を表す『に』で、活躍の場所を示す文には合わない。", "を": "『国際会議を活躍した』は目的語になるが、『活躍』は目的語を取らないので誤り。", "より": "『国際会議より活躍した』は比較を表し、ここでは比べる文脈がなく意味が合わない。"}, "error_tags": {"に": "到着点", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41365, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の能力や才能を発揮して、社会や集団の中で積極的に活動すること。", "primary_collocate": null, "pronunciation": "かつやく", "ipa": "kat͡sɯjakɯ", "syllable_count": 4, "sentences": [{"text": "彼は海外のチームに移籍してから、大きな舞台で活躍している。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "彼[かれ]は海外[かいがい]のチームに移籍[いせき]してから、大[おお]きな舞台[ぶたい]で活躍[かつやく]している。", "sentence_source": "generated"}, {"text": "女性が社会で活躍できる環境づくりが進められている。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "女性[じょせい]が社会[しゃかい]で活躍[かつやく]できる環境[かんきょう]づくりが進[すす]められている。", "sentence_source": "generated"}, {"text": "若手の社員が現場で活躍し、会社の売り上げをのばした。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "若手[わかて]の社員[しゃいん]が現場[げんば]で活躍[かつやく]し、会社[かいしゃ]の売[う]り上[あ]げをのばした。", "sentence_source": "generated"}, {"text": "彼女は医師として、国内外で活躍を続けている。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は医師[いし]として、国内外[こくないがい]で活躍[かつやく]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "活躍の場を求めて、彼は地方から東京へ出てきた。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "活躍[かつやく]の場[ば]を求[もと]めて、彼[かれ]は地方[ちほう]から東京[とうきょう]へ出[で]てきた。", "sentence_source": "generated"}, {"text": "この俳優は舞台でも映画でも幅広く活躍している。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "この俳優[はいゆう]は舞台[ぶたい]でも映画[えいが]でも幅広[はばひろ]く活躍[かつやく]している。", "sentence_source": "generated"}, {"text": "新人の活躍により、チームは最下位から優勝争いに加わった。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "新人[しんじん]の活躍[かつやく]により、チームは最下位[さいかい]から優勝争[ゆうしょうあらそ]いに加[くわ]わった。", "sentence_source": "generated"}, {"text": "外国語が得意な彼は、通訳として国際会議で活躍した。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "外国語[がいこくご]が得意[とくい]な彼[かれ]は、通訳[つうやく]として国際会議[こくさいかいぎ]で活躍[かつやく]した。", "sentence_source": "generated"}, {"text": "才能を十分に発揮して活躍するには、周りの支えが欠かせない。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "才能[さいのう]を十分[じゅうぶん]に発揮[はっき]して活躍[かつやく]するには、周[まわ]りの支[ささ]えが欠[か]かせない。", "sentence_source": "generated"}, {"text": "定年後も、地域のボランティアとして活躍する人が多い。", "target_word": "活躍", "complexity_tier": "T4", "furigana": "定年後[ていねんご]も、地域[ちいき]のボランティアとして活躍[かつやく]する人[ひと]が多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活躍する", "label": "基本形"}, {"form": "活躍した", "label": "過去形"}, {"form": "活躍して", "label": "テ形"}], "register": "標準", "sense_fingerprint": "能力や才能を発揮して社会や集団の中で積極的に活動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41365, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活躍", "is_correct": true, "explanation": "『大きな舞台で活躍している』の空欄に入る。能力を発揮して活動する意味に合う。"}, {"text": "解凍", "is_correct": false, "explanation": "『大きな舞台で解凍している』は意味が通らない。解凍は冷凍品をとかすこと。"}, {"text": "消毒", "is_correct": false, "explanation": "『大きな舞台で消毒している』は文脈に合わない。消毒は菌を殺す行為。"}, {"text": "放電", "is_correct": false, "explanation": "電気を放出する現象で、舞台での活動を表す文には入らない。"}], "explanations": {"活躍": "『大きな舞台で活躍している』の空欄に入る。能力を発揮して活動する意味に合う。", "解凍": "『大きな舞台で解凍している』は意味が通らない。解凍は冷凍品をとかすこと。", "消毒": "『大きな舞台で消毒している』は文脈に合わない。消毒は菌を殺す行為。", "放電": "電気を放出する現象で、舞台での活動を表す文には入らない。"}, "sentence_index": 0, "correct_answer": "活躍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議室は朝から活躍があふれている。", "explanation": "ここは〈活気〉の意味。部屋の雰囲気は〈活気〉で表し、〈活躍〉は人の目立つ働きを指す。"}, {"text": "この町は連日、活躍の盛況だ。", "explanation": "ここは〈繁栄〉の意味。町が栄えている様子は〈繁栄〉で表し、〈活躍〉は人の働きに使う。"}, {"text": "この機械は電源が切れたまま、一晩中活躍した。", "explanation": "ここは〈停止〉の意味。止まっている状態は〈停止〉で表し、〈活躍〉は動いて成果を出す働きに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41365, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活躍", "is_correct": true, "explanation": "『新人の活躍により』の空欄に入る。新人が目立つ働きをしたという意味に合う。"}, {"text": "誤植", "is_correct": false, "explanation": "『新人の誤植により』は意味が通らない。誤植は印刷の誤りを指す。"}, {"text": "消灯", "is_correct": false, "explanation": "『新人の消灯により』は文脈に合わない。消灯は明かりを消すこと。"}, {"text": "水没", "is_correct": false, "explanation": "『新人の水没により』は意味が通らない。水没は水に沈むこと。"}], "explanations": {"活躍": "『新人の活躍により』の空欄に入る。新人が目立つ働きをしたという意味に合う。", "誤植": "『新人の誤植により』は意味が通らない。誤植は印刷の誤りを指す。", "消灯": "『新人の消灯により』は文脈に合わない。消灯は明かりを消すこと。", "水没": "『新人の水没により』は意味が通らない。水没は水に沈むこと。"}, "sentence_index": 6, "correct_answer": "活躍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "定年後は、地域の散歩道が活躍している。", "explanation": "ここは〈賑わう〉の意味。道のにぎわいは〈賑わう〉で表し、〈活躍〉は人の働きに使う。"}, {"text": "毎朝、公園で活躍している。", "explanation": "ここは〈練習〉の意味。毎朝の鍛錬は〈練習〉で表し、〈活躍〉は目立つ成果や働きに使う。"}, {"text": "彼は毎週日曜、家でごろごろして活躍している。", "explanation": "ここは〈休養〉の意味。家でのんびり休むことは〈休養〉で表し、〈活躍〉は人が目立つ成果を出す働きに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41365, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若手の社員は現場で活躍て、目標を達成した。", "corrected_sentence": "若手の社員は現場で活躍して、目標を達成した。", "error_description": "『活躍』はサ変動詞なので、テ形は『活躍して』。『活躍て』は動詞の活用形として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41365, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は本番の舞台に活躍した。", "corrected_sentence": "彼は本番の舞台で活躍した。", "error_description": "活躍の場所を表す助詞が誤り。場所の『で』が正しく、『に』は到着点を表すので『活躍』と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41368, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「キリングを禁止する」と対象を取る正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「キリングに禁止している」は対象を表せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「キリングで禁止している」は手段の意味になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「キリングへ禁止している」は方向の意味になり、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「キリングを禁止する」と対象を取る正しい格助詞。", "に": "「キリングに禁止している」は対象を表せず、文が成り立たない。", "で": "「キリングで禁止している」は手段の意味になり不自然。", "へ": "「キリングへ禁止している」は方向の意味になり、文が通らない。"}, "error_tags": {"に": "対象の誤用", "で": "手段の誤用", "へ": "方向の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
