INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41368, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生き物を死なせること。", "primary_collocate": null, "pronunciation": "きりんぐ", "ipa": "kiɾiŋɡɯ", "syllable_count": 4, "sentences": [{"text": "彼は、動物のキリングを見るのが苦手で、肉を食べない。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "彼(かれ)は、動物(どうぶつ)のキリングを見(み)るのが苦手(にがて)で、肉(にく)を食(た)べない。", "sentence_source": "generated"}, {"text": "この法律は、犬や猫のキリングを禁止している。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "この法律(ほうりつ)は、犬(いぬ)や猫(ねこ)のキリングを禁止(きんし)している。", "sentence_source": "generated"}, {"text": "ミステリー小説では、最初にキリングが起こり、探偵が呼ばれる。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "ミステリー小説(しょうせつ)では、最初(さいしょ)にキリングが起(お)こり、探偵(たんてい)が呼(よ)ばれる。", "sentence_source": "generated"}, {"text": "農場では、病気の牛のキリングが決まった。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "農場(のうじょう)では、病気(びょうき)の牛(うし)のキリングが決(き)まった。", "sentence_source": "generated"}, {"text": "キリングの方法について、ヨーロッパの国々で議論が続いている。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "キリングの方法(ほうほう)について、ヨーロッパの国々(くにぐに)で議論(ぎろん)が続(つづ)いている。", "sentence_source": "generated"}, {"text": "その国では、象のキリングが長いあいだ問題になっている。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "その国(くに)では、象(ぞう)のキリングが長(なが)いあいだ問題(もんだい)になっている。", "sentence_source": "generated"}, {"text": "漁師は、魚の鮮度を保つため、すばやいキリングを心がけている。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "漁師(りょうし)は、魚(さかな)の鮮度(せんど)を保(たも)つため、すばやいキリングを心(こころ)がけている。", "sentence_source": "generated"}, {"text": "彼女は、子どもに動物のキリングについてどう話すか悩んだ。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は、子(こ)どもに動物(どうぶつ)のキリングについてどう話(はな)すか悩(なや)んだ。", "sentence_source": "generated"}, {"text": "その映画のキリングの場面は、音だけで表現されていた。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "その映画(えいが)のキリングの場面(ばめん)は、音(おと)だけで表現(ひょうげん)されていた。", "sentence_source": "generated"}, {"text": "観光客による野鳥のキリングが、ニュースになった。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "観光客(かんこうきゃく)による野鳥(やちょう)のキリングが、ニュースになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "キリング", "label": "基本形"}], "register": "標準", "sense_fingerprint": "生き物の命をうばうこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "キリング", "is_correct": true, "explanation": "「動物のキリング」で、動物を死なせる行為を指す名詞として入る。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "「動物のヨーグルト」は成り立たず、見るものとして不自然。"}, {"text": "ネクタイ", "is_correct": false, "explanation": "ネクタイは動物の描写に使わず、文が通らない。"}, {"text": "リハーサル", "is_correct": false, "explanation": "リハーサルは動物の死を表さず、文脈に合わない。"}], "explanations": {"キリング": "「動物のキリング」で、動物を死なせる行為を指す名詞として入る。", "ヨーグルト": "「動物のヨーグルト」は成り立たず、見るものとして不自然。", "ネクタイ": "ネクタイは動物の描写に使わず、文が通らない。", "リハーサル": "リハーサルは動物の死を表さず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "キリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "引っ越しで、古い家具をキリングした。", "explanation": "ここは〈処分〉の意味（不要なものを捨てること）。キリングは生き物を死なせる語で、家具には使えないので合わない。"}, {"text": "事故で亡くなった彼のキリングを、家族は悼んだ。", "explanation": "事故による死は、人が人や動物を殺す行為（キリング）とは違うため、この語では言えない。"}, {"text": "会議のキリングを十時に決めて、全員に伝えた。", "explanation": "終わらせるという意味で使っているが、この定義は生き物を死なせることに限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "キリング", "is_correct": true, "explanation": "「すばやいキリング」で、魚を素早く仕留める行為を指す名詞として入る。"}, {"text": "マヨネーズ", "is_correct": false, "explanation": "マヨネーズは魚の処理を指さず、文脈に合わない。"}, {"text": "スリッパ", "is_correct": false, "explanation": "スリッパは処理の方法を表さず、「すばやい〜を心がける」の形にならない。"}, {"text": "ハンバーグ", "is_correct": false, "explanation": "ハンバーグは処理の行為を表さず、文が通らない。"}], "explanations": {"キリング": "「すばやいキリング」で、魚を素早く仕留める行為を指す名詞として入る。", "マヨネーズ": "マヨネーズは魚の処理を指さず、文脈に合わない。", "スリッパ": "スリッパは処理の方法を表さず、「すばやい〜を心がける」の形にならない。", "ハンバーグ": "ハンバーグは処理の行為を表さず、文が通らない。"}, "sentence_index": 6, "correct_answer": "キリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風による建物のキリングが、ニュースになった。", "explanation": "キリングは生き物を死なせる語。建物には使わず、「破壊」の語義で言うべき対象。"}, {"text": "古い車をキリングして、部品を売った。", "explanation": "ここは〈解体〉の意味（車などを分けて壊すこと）。キリングは生き物を死なせる語で、車には使えないので合わない。"}, {"text": "その映画は、結末のキリングが衝撃的だった。", "explanation": "物語の終わりの意味で使っているが、この定義は生き物を死なせることに限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業員は、豚のキリングで担当している。", "corrected_sentence": "作業員は、豚のキリングを担当している。", "error_description": "「担当する」は「〜を担当する」と対象を取る。「キリングで」の「で」は誤りで、「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保護団体は、野生動物のキリングを強く反対している。", "corrected_sentence": "保護団体は、野生動物のキリングに強く反対している。", "error_description": "「反対する」は「〜に反対する」と対象を「に」で表す。「キリングを」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41369, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「残酷なキリングの場面」と、キリングを場面の修飾語として続ける正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「キリングに場面」では場所や相手の意味になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「キリングで場面」では手段の意味になり、「場面が多い」と続かない。"}, {"text": "から", "is_correct": false, "explanation": "「キリングから場面」では起点の意味になり、場面の修飾として不自然。"}], "correct_answer": "の", "explanations": {"の": "「残酷なキリングの場面」と、キリングを場面の修飾語として続ける正しい格助詞。", "に": "「キリングに場面」では場所や相手の意味になり、文が成り立たない。", "で": "「キリングで場面」では手段の意味になり、「場面が多い」と続かない。", "から": "「キリングから場面」では起点の意味になり、場面の修飾として不自然。"}, "error_tags": {"に": "場所・相手の誤用", "で": "手段の誤用", "から": "起点の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41369, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「キリングを避ける」と対象を取る正しい格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「キリングへ避ける」では方向の意味になり、対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「キリングと避ける」では並列の意味になり、文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「キリングより避ける」は比較の意味になり、文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「キリングを避ける」と対象を取る正しい格助詞。", "へ": "「キリングへ避ける」では方向の意味になり、対象を表せない。", "と": "「キリングと避ける」では並列の意味になり、文が通らない。", "より": "「キリングより避ける」は比較の意味になり、文脈に合わない。"}, "error_tags": {"へ": "方向の誤用", "と": "並列の誤用", "より": "比較の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41369, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や動物などを殺すこと。また、何かを終わらせること。", "primary_collocate": null, "pronunciation": "きりんぐ", "ipa": "kiɾiŋɡɯ", "syllable_count": 4, "sentences": [{"text": "彼は、あの夜のキリングを誰にも話さなかった。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "彼(かれ)は、あの夜(よる)のキリングを誰(だれ)にも話(はな)さなかった。", "sentence_source": "generated"}, {"text": "その映画は残酷なキリングの場面が多くて、見ていられなかった。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "その映画(えいが)は残酷(ざんこく)なキリングの場面(ばめん)が多(おお)くて、見(み)ていられなかった。", "sentence_source": "generated"}, {"text": "野生動物のキリングは、法律で厳しく禁じられている。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "野生動物(やせいどうぶつ)のキリングは、法律(ほうりつ)で厳(きび)しく禁(きん)じられている。", "sentence_source": "generated"}, {"text": "ニュースは、森で起きた動物のキリングについて伝えていた。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "ニュースは、森(もり)で起(お)きた動物(どうぶつ)のキリングについて伝(つた)えていた。", "sentence_source": "generated"}, {"text": "警察は、その事件を計画的なキリングとして調べている。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "警察(けいさつ)は、その事件(じけん)を計画的(けいかくてき)なキリングとして調(しら)べている。", "sentence_source": "generated"}, {"text": "公園で小動物のキリングが続き、住民は不安になっている。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "公園(こうえん)で小動物(しょうどうぶつ)のキリングが続(つづ)き、住民(じゅうみん)は不安(ふあん)になっている。", "sentence_source": "generated"}, {"text": "その小説は、一つのキリングから物語が始まる。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "その小説(しょうせつ)は、一(ひと)つのキリングから物語(ものがたり)が始(はじ)まる。", "sentence_source": "generated"}, {"text": "彼は、不必要なキリングを避けるために、狩りをやめた。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "彼(かれ)は、不必要(ふひつよう)なキリングを避(さ)けるために、狩(か)りをやめた。", "sentence_source": "generated"}, {"text": "作者は、戦争のキリングをありのままに描いた。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "作者(さくしゃ)は、戦争(せんそう)のキリングをありのままに描(えが)いた。", "sentence_source": "generated"}, {"text": "魚の苦しみが少ないキリングの方法が研究されている。", "target_word": "キリング", "complexity_tier": "T3", "furigana": "魚(さかな)の苦(くる)しみが少(すく)ないキリングの方法(ほうほう)が研究(けんきゅう)されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "キリング", "label": "基本形"}], "register": "標準", "sense_fingerprint": "人や動物を殺すこと、また物事を終わらせること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41369, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "キリング", "is_correct": true, "explanation": "「あの夜のキリング」で、殺人という出来事を指す名詞として入る。"}, {"text": "マヨネーズ", "is_correct": false, "explanation": "マヨネーズは出来事を表さず、「話さなかった」の対象として成り立たない。"}, {"text": "スリッパ", "is_correct": false, "explanation": "スリッパは夜の出来事を表さず、文が通らない。"}, {"text": "ハンバーグ", "is_correct": false, "explanation": "ハンバーグは出来事ではなく、話す対象として不自然。"}], "explanations": {"キリング": "「あの夜のキリング」で、殺人という出来事を指す名詞として入る。", "マヨネーズ": "マヨネーズは出来事を表さず、「話さなかった」の対象として成り立たない。", "スリッパ": "スリッパは夜の出来事を表さず、文が通らない。", "ハンバーグ": "ハンバーグは出来事ではなく、話す対象として不自然。"}, "sentence_index": 0, "correct_answer": "キリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新商品はSNSで話題になり、若者の間でキリングと呼ばれて大ヒットした。", "explanation": "「大成功」を指す俗な用法。殺すこと・終わらせることとは別の意味なので、この定義では説明できない。"}, {"text": "古いデータを整理するため、不要なものをまとめてキリングの対象にした。", "explanation": "「削除」に近い意味で使っているが、キリングはデータを消す語ではない。"}, {"text": "作業員がケーブルをキリングした。", "explanation": "ここは〈切断〉の意味（断ち切ること）。キリングは生き物を死なせる語なので、物を断つ意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41369, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "キリング", "is_correct": true, "explanation": "「一つのキリング」の形で、物語の始まりとなる出来事を指す名詞として入る。"}, {"text": "カレー", "is_correct": false, "explanation": "カレーは物語の始まりを表す出来事ではなく、「一つのカレーから物語が始まる」は文として成り立たない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "ピアノは出来事を表さず、「一つのピアノから物語が始まる」は物語の出発点として不自然。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "ハンカチは物語の始まりとなる出来事を指さず、文脈に合わない。"}], "explanations": {"キリング": "「一つのキリング」の形で、物語の始まりとなる出来事を指す名詞として入る。", "カレー": "カレーは物語の始まりを表す出来事ではなく、「一つのカレーから物語が始まる」は文として成り立たない。", "ピアノ": "ピアノは出来事を表さず、「一つのピアノから物語が始まる」は物語の出発点として不自然。", "ハンカチ": "ハンカチは物語の始まりとなる出来事を指さず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "キリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ホテルのキリングは、電話でも受け付けている。", "explanation": "キリングは殺すこと・終わらせることの語で、予約を指すことはない。"}, {"text": "その店はキリングが人気で、毎日行列ができる。", "explanation": "ここは〈大人気〉の意味。キリングは殺すこと・終わらせることの語で、人気や評判の意味では使えない。"}, {"text": "祖母はキリングの花が好きで、庭に植えている。", "explanation": "キリングは花の名前ではない。生き物を死なせる、または終わらせる意味とは無関係。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41369, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はキリングで避けるため、山を下りた。", "corrected_sentence": "彼はキリングを避けるため、山を下りた。", "error_description": "「避ける」は「〜を避ける」と対象を取る。キリングには「を」が必要で、「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41369, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作家は、キリングに題材に選んで小説を書いた。", "corrected_sentence": "作家は、キリングを題材に選んで小説を書いた。", "error_description": "「選ぶ」の対象を表す「を」が必要。「キリングに」の「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42612, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「想像する」に続けて「〜すると」の条件を表し、文が成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "「想像する」の後に「で」は続かず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「想像する」の後に置くと意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は名詞に付くもので、「想像する」の後には置けない。"}], "correct_answer": "と", "explanations": {"と": "「想像する」に続けて「〜すると」の条件を表し、文が成り立つ。", "で": "「想像する」の後に「で」は続かず、文が成り立たない。", "へ": "方向を表す助詞で、「想像する」の後に置くと意味が通らない。", "を": "目的語の「を」は名詞に付くもので、「想像する」の後には置けない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "を": "目的語の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42612, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42612, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "まだ見たことのないものや、まだ起きていないことを、頭の中で考えること。", "primary_collocate": null, "pronunciation": "そうぞう", "ipa": "soːzoː", "syllable_count": 4, "sentences": [{"text": "まだ行ったことのない国の町を、写真を見ながら想像した。", "target_word": "想像", "complexity_tier": "T3", "furigana": "まだいったことのないくにのまちを、しゃしんをみながらそうぞうした。", "sentence_source": "generated"}, {"text": "未来の生活を想像すると、わくわくします。", "target_word": "想像", "complexity_tier": "T3", "furigana": "みらいのせいかつをそうぞうすると、わくわくします。", "sentence_source": "generated"}, {"text": "宇宙人がどんな姿をしているのか、想像もつかない。", "target_word": "想像", "complexity_tier": "T3", "furigana": "うちゅうじんがどんなすがたをしているのか、そうぞうもつかない。", "sentence_source": "generated"}, {"text": "子どものころ、雲を見て動物の形を想像して遊んだ。", "target_word": "想像", "complexity_tier": "T3", "furigana": "こどものころ、くもをみてどうぶつのかたちをそうぞうしてあそんだ。", "sentence_source": "generated"}, {"text": "彼が怒った顔は想像できないほど、いつも優しい人だ。", "target_word": "想像", "complexity_tier": "T3", "furigana": "かれがおこったかおはそうぞうできないほど、いつもやさしいひとだ。", "sentence_source": "generated"}, {"text": "明日の天気がどうなるか、空の色から想像してみた。", "target_word": "想像", "complexity_tier": "T3", "furigana": "あしたのてんきがどうなるか、そらのいろからそうぞうしてみた。", "sentence_source": "generated"}, {"text": "小説を読むと、登場人物の部屋を頭の中で想像したくなる。", "target_word": "想像", "complexity_tier": "T3", "furigana": "しょうせつをよむと、とうじょうじんぶつのへやをあたまのなかでそうぞうしたくなる。", "sentence_source": "generated"}, {"text": "十年後の自分を想像して、日記に書いた。", "target_word": "想像", "complexity_tier": "T3", "furigana": "じゅうねんごのじぶんをそうぞうして、にっきにかいた。", "sentence_source": "generated"}, {"text": "まだ起きていない事故のことを想像すると、怖くなる。", "target_word": "想像", "complexity_tier": "T3", "furigana": "まだおきていないじこのことをそうぞうすると、こわくなる。", "sentence_source": "generated"}, {"text": "絵がない本は、読む人が自由に想像できるところがおもしろい。", "target_word": "想像", "complexity_tier": "T3", "furigana": "えがないほんは、よむひとがじゆうにそうぞうできるところがおもしろい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "想像する", "label": "終止形"}, {"form": "想像した", "label": "過去形"}, {"form": "想像して", "label": "て形"}, {"form": "想像できる", "label": "可能形"}, {"form": "想像しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "見たことのないことや未来のことを頭の中で思い浮かべて考える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "写真を見ながら、行ったことのない町を頭の中で思い描く意味に合う。"}, {"text": "注文", "is_correct": false, "explanation": "品物などを頼む行為で、町を対象にできないので合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類などを洗う行為で、町を対象にできないので合わない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける行為で、写真の町を見る文脈には合わない。"}], "explanations": {"想像": "写真を見ながら、行ったことのない町を頭の中で思い描く意味に合う。", "注文": "品物などを頼む行為で、町を対象にできないので合わない。", "洗濯": "衣類などを洗う行為で、町を対象にできないので合わない。", "配達": "品物を届ける行為で、写真の町を見る文脈には合わない。"}, "sentence_index": 0, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事の費用を、電卓で想像した。", "explanation": "ここは〈計算〉の意味。数を電卓で出す作業で、頭の中で思い描く想像では合わない。"}, {"text": "昨日登った山の頂上からの景色を、想像して撮影した。", "explanation": "ここは〈撮影〉の意味。実際に目の前で見た景色は写真に撮るもので、想像では撮れない。"}, {"text": "目の前の花の色を、想像して書きとめた。", "explanation": "ここは〈観察〉の意味。目の前にあるものは見て確かめるので、想像ではなく観察する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "読んだ小説の場面を頭の中で思い描く意味に合う。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す行為で、頭の中の部屋には使えない。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼む行為で、登場人物の部屋には合わない。"}, {"text": "録音", "is_correct": false, "explanation": "音声を記録する行為で、部屋を思い描く文脈には合わない。"}], "explanations": {"想像": "読んだ小説の場面を頭の中で思い描く意味に合う。", "修理": "壊れたものを直す行為で、頭の中の部屋には使えない。", "注文": "品物を頼む行為で、登場人物の部屋には合わない。", "録音": "音声を記録する行為で、部屋を思い描く文脈には合わない。"}, "sentence_index": 6, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英語の手紙を、頭の中で想像して日本語にした。", "explanation": "ここは〈翻訳〉の意味。既にある文を別の言語に移す作業で、想像は使わない。"}, {"text": "スマホの電源が入っているかを、想像した。", "explanation": "ここは〈確認〉の意味。目で確かめられる事実は、想像ではなく確認する。"}, {"text": "配られた答案を、想像して点数をつけた。", "explanation": "ここは〈採点〉の意味。答案は実物があり、答えを基準に評価するので、想像では点数をつけられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "未来の町の姿を想像に、絵を描いた。", "corrected_sentence": "未来の町の姿を想像して、絵を描いた。", "error_description": "誤りは「想像に」。「想像」の後には「して」（て形）が続く。「に」は「想像」に直接つけられず、正しくは「想像して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "まだ見たことのない海の底を想像していみる。", "corrected_sentence": "まだ見たことのない海の底を想像してみる。", "error_description": "誤りは「していみる」。正しくは「想像してみる」（て形＋「みる」で試してみる）。「して」に余分な「い」が入っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
