INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42613, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "実際には見たり経験したりしていないことを、頭の中で思い描くこと。また、その内容。", "primary_collocate": null, "pronunciation": "そうぞう", "ipa": "soːzoː", "syllable_count": 4, "sentences": [{"text": "実際に見たことがないので、海の底の世界は想像するしかない。", "target_word": "想像", "complexity_tier": "T3", "furigana": "じっさいにみたことがないので、うみのそこのせかいはそうぞうするしかない。", "sentence_source": "generated"}, {"text": "彼の話を聞いて、昔の町の様子を想像した。", "target_word": "想像", "complexity_tier": "T3", "furigana": "かれのはなしをきいて、むかしのまちのようすをそうぞうした。", "sentence_source": "generated"}, {"text": "それは私の勝手な想像で、本当のことはわからない。", "target_word": "想像", "complexity_tier": "T3", "furigana": "それはわたしのかってなそうぞうで、ほんとうのことはわからない。", "sentence_source": "generated"}, {"text": "初めて会う人を、声だけで想像してみた。", "target_word": "想像", "complexity_tier": "T3", "furigana": "はじめてあうひとを、こえだけでそうぞうしてみた。", "sentence_source": "generated"}, {"text": "外国で一人暮らしをする大変さは、想像がつきません。", "target_word": "想像", "complexity_tier": "T3", "furigana": "がいこくでひとりぐらしをするたいへんさは、そうぞうがつきません。", "sentence_source": "generated"}, {"text": "あなたの想像は当たっていて、彼は本当に引っ越した。", "target_word": "想像", "complexity_tier": "T3", "furigana": "あなたのそうぞうはあたっていて、かれはほんとうにひっこした。", "sentence_source": "generated"}, {"text": "映画の続きを想像するのが、私の楽しみです。", "target_word": "想像", "complexity_tier": "T3", "furigana": "えいがのつづきをそうぞうするのが、わたしのたのしみです。", "sentence_source": "generated"}, {"text": "戦争の時代の暮らしを想像しながら、資料館を回った。", "target_word": "想像", "complexity_tier": "T3", "furigana": "せんそうのじだいのくらしをそうぞうしながら、しりょうかんをまわった。", "sentence_source": "generated"}, {"text": "友だちが泣いている理由を想像したが、わからなかった。", "target_word": "想像", "complexity_tier": "T3", "furigana": "ともだちがないているりゆうをそうぞうしたが、わからなかった。", "sentence_source": "generated"}, {"text": "その山の頂上からの景色は、言葉では想像できないほど美しい。", "target_word": "想像", "complexity_tier": "T3", "furigana": "そのやまのちょうじょうからのけしきは、ことばではそうぞうできないほどうつくしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "想像する", "label": "終止形"}, {"form": "想像した", "label": "過去形"}, {"form": "想像して", "label": "て形"}, {"form": "想像できる", "label": "可能形"}, {"form": "想像しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "経験していないことを思い描くこと、またその思い描いた内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "実際に見ていない海の底を頭の中で思い描くしかない、という文脈に合う。"}, {"text": "点検", "is_correct": false, "explanation": "実際に調べて確認する行為で、見ていない世界を対象にはできないので合わない。"}, {"text": "操作", "is_correct": false, "explanation": "機械などを動かす行為で、海の底の世界には使えない。"}, {"text": "購入", "is_correct": false, "explanation": "品物を買う行為で、世界を対象にする文脈には合わない。"}], "explanations": {"想像": "実際に見ていない海の底を頭の中で思い描くしかない、という文脈に合う。", "点検": "実際に調べて確認する行為で、見ていない世界を対象にはできないので合わない。", "操作": "機械などを動かす行為で、海の底の世界には使えない。", "購入": "品物を買う行為で、世界を対象にする文脈には合わない。"}, "sentence_index": 0, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔住んでいた町の人口を、アンケートで想像した。", "explanation": "人口は調べて数えるもので、アンケートで数える作業は頭の中で思い描く想像とは合わない。"}, {"text": "スマホの電池が残っているかを、想像した。", "explanation": "電池の残量は実際に確かめるものなので、頭の中で思い描く想像では合わない。"}, {"text": "会議の時間を、ストップウォッチで想像した。", "explanation": "時間はストップウォッチで計って測るもので、頭の中で思い描く想像では出せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想像", "is_correct": true, "explanation": "まだ見ていない映画の続きを頭の中で思い描く、という意味に合う。"}, {"text": "配布", "is_correct": false, "explanation": "印刷物などを配る行為で、映画の続きには合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "場所をきれいにする行為で、物語の続きには使えない。"}, {"text": "修繕", "is_correct": false, "explanation": "壊れたものを直す行為で、映画の続きには合わない。"}], "explanations": {"想像": "まだ見ていない映画の続きを頭の中で思い描く、という意味に合う。", "配布": "印刷物などを配る行為で、映画の続きには合わない。", "清掃": "場所をきれいにする行為で、物語の続きには使えない。", "修繕": "壊れたものを直す行為で、映画の続きには合わない。"}, "sentence_index": 6, "correct_answer": "想像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日登った山の頂上からの景色を、想像して撮影した。", "explanation": "目の前にある実際の景色は写真に撮るもので、頭の中で思い描く想像では撮れない。"}, {"text": "お釣りの金額を、頭の中で想像して求めた。", "explanation": "金額は計算して求めるもので、想像して出すものではない。"}, {"text": "友だちの作文を、想像して添削した。", "explanation": "実際に書かれた文章を直す作業で、頭の中で思い描く想像では行えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その遺跡が栄えていた頃の姿を想像に、絵にした。", "corrected_sentence": "その遺跡が栄えていた頃の姿を想像して、絵にした。", "error_description": "誤りは「想像に」。「想像」の後には「して」（て形）が続く。「に」は「想像」に直接つけられず、正しくは「想像して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次の回の結末を想像いるのが、毎週の楽しみだ。", "corrected_sentence": "次の回の結末を想像するのが、毎週の楽しみだ。", "error_description": "誤りは「想像いる」の「いる」。正しくは「想像する」。「いる」は存在の動詞で、「想像」と組み合わせられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42652, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「地方の暮らし」の〈の〉。名詞を修飾する正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すが、「地方が暮らし」は名詞を修飾できず成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すが、「地方を暮らし」は文法的に続かない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すため、「地方へ暮らし」は名詞を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「地方の暮らし」の〈の〉。名詞を修飾する正しい助詞。", "が": "〈が〉は主語を示すが、「地方が暮らし」は名詞を修飾できず成り立たない。", "を": "〈を〉は目的語を示すが、「地方を暮らし」は文法的に続かない。", "へ": "〈へ〉は方向を表すため、「地方へ暮らし」は名詞を修飾できない。"}, "error_tags": {"が": "主語", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
