INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42652, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市部以外の地域。田舎や小さな町を含む。", "primary_collocate": null, "pronunciation": "ちほう", "ipa": "tɕihoː", "syllable_count": 3, "sentences": [{"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "地方", "complexity_tier": "T3", "furigana": "高校[こうこう]を卒業[そつぎょう]したばかりの10代[じゅうだい]の彼[かれ]が選[えら]んだ道[みち]は、地方[ちほう]の有機農家[ゆうきのうか]で働[はたら]くことでした。", "sentence_source": "mined"}, {"text": "都会は便利ですが、地方の暮らしにはゆったりした時間があります。", "target_word": "地方", "complexity_tier": "T3", "furigana": "都会[とかい]は便利[べんり]ですが、地方[ちほう]の暮[く]らしにはゆったりした時間[じかん]があります。", "sentence_source": "generated"}, {"text": "私は東京で生まれましたが、仕事の都合で地方に引っ越しました。", "target_word": "地方", "complexity_tier": "T3", "furigana": "私[わたし]は東京[とうきょう]で生[う]まれましたが、仕事[しごと]の都合[つごう]で地方[ちほう]に引[ひ]っ越[こ]しました。", "sentence_source": "generated"}, {"text": "地方では、電車が一時間に一本しか来ない駅も珍しくありません。", "target_word": "地方", "complexity_tier": "T4", "furigana": "地方[ちほう]では、電車[でんしゃ]が一時間[いちじかん]に一本[いっぽん]しか来[こ]ない駅[えき]も珍[めずら]しくありません。", "sentence_source": "generated"}, {"text": "祖父は地方の小さな町で、一人で暮らしています。", "target_word": "地方", "complexity_tier": "T3", "furigana": "祖父[そふ]は地方[ちほう]の小[ちい]さな町[まち]で、一人[ひとり]で暮[く]らしています。", "sentence_source": "generated"}, {"text": "大学を出たら、都会ではなく地方で働きたいと考えています。", "target_word": "地方", "complexity_tier": "T3", "furigana": "大学[だいがく]を出[で]たら、都会[とかい]ではなく地方[ちほう]で働[はたら]きたいと考[かんが]えています。", "sentence_source": "generated"}, {"text": "都市は人が多いが、地方では人口が減り、学校が次々に閉校しています。", "target_word": "地方", "complexity_tier": "T4", "furigana": "都市[とし]は人[ひと]が多[おお]いが、地方[ちほう]では人口[じんこう]が減[へ]り、学校[がっこう]が次々[つぎつぎ]に閉校[へいこう]しています。", "sentence_source": "generated"}, {"text": "この祭りは、地方ならではの伝統行事として知られています。", "target_word": "地方", "complexity_tier": "T4", "furigana": "この祭[まつ]りは、地方[ちほう]ならではの伝統行事[でんとうぎょうじ]として知[し]られています。", "sentence_source": "generated"}, {"text": "来月から、いくつかの地方を回って、農家の話を聞く旅に出ます。", "target_word": "地方", "complexity_tier": "T3", "furigana": "来月[らいげつ]から、いくつかの地方[ちほう]を回[まわ]って、農家[のうか]の話[はなし]を聞[き]く旅[たび]に出[で]ます。", "sentence_source": "generated"}, {"text": "地方の野菜は新鮮で、都会のスーパーより安く買えます。", "target_word": "地方", "complexity_tier": "T3", "furigana": "地方[ちほう]の野菜[やさい]は新鮮[しんせん]で、都会[とかい]のスーパーより安[やす]く買[か]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地方", "label": "基本形"}], "register": "中立", "sense_fingerprint": "大都市に対する、都市部以外の田舎や小さな町の地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 閉校 (Zipf 2.36)']::text[], 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42652, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地方", "is_correct": true, "explanation": "「地方の有機農家」の〈地方〉。都市部以外の地域を指し、文脈に合う。"}, {"text": "教室", "is_correct": false, "explanation": "「教室の有機農家」は意味が通らず、農業の場所として成り立たない。"}, {"text": "漁業", "is_correct": false, "explanation": "「漁業の有機農家」は農家と組み合わず、意味が成り立たない。"}, {"text": "鉄道", "is_correct": false, "explanation": "「鉄道の有機農家」は農家の場所として成り立たず、文脈に合わない。"}], "explanations": {"地方": "「地方の有機農家」の〈地方〉。都市部以外の地域を指し、文脈に合う。", "教室": "「教室の有機農家」は意味が通らず、農業の場所として成り立たない。", "漁業": "「漁業の有機農家」は農家と組み合わず、意味が成り立たない。", "鉄道": "「鉄道の有機農家」は農家の場所として成り立たず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "腕の地方に、ずっと痛みがある。", "explanation": "ここは〈部位〉の意味。体の一部を指すのに〈地方〉は使わないので、定義とも合わない。"}, {"text": "この曲の地方はサビだ。", "explanation": "ここは〈部分〉の意味。曲の一部を指すのに〈地方〉は使わないので、定義とも合わない。"}, {"text": "この駅は都会の地方にあり、通勤に便利だ。", "explanation": "ここは〈市街地〉の意味。地方は都市部以外を指すので、〈都会の地方〉と言えば矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42652, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地方", "is_correct": true, "explanation": "「地方では人口が減り」の〈地方〉。都市と対比される地域を指し、文脈に合う。"}, {"text": "工場", "is_correct": false, "explanation": "「工場では人口が減り」は意味が通らず、対比の文脈にも合わない。"}, {"text": "病院", "is_correct": false, "explanation": "「病院では人口が減り」は場所として成り立たず、文脈にも合わない。"}, {"text": "空港", "is_correct": false, "explanation": "「空港では人口が減り」は文脈に合わず、人口減少の場所として不自然。"}], "explanations": {"地方": "「地方では人口が減り」の〈地方〉。都市と対比される地域を指し、文脈に合う。", "工場": "「工場では人口が減り」は意味が通らず、対比の文脈にも合わない。", "病院": "「病院では人口が減り」は場所として成り立たず、文脈にも合わない。", "空港": "「空港では人口が減り」は文脈に合わず、人口減少の場所として不自然。"}, "sentence_index": 6, "correct_answer": "地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このビルの三階の地方に、会議室がある。", "explanation": "ここは〈フロア〉の意味。階を指すのに〈地方〉は使わないので、定義とも合わない。"}, {"text": "彼女は医学の地方で、長く研究を続けている。", "explanation": "ここは〈分野〉の意味。学問の領域を指すのに〈地方〉は使わないので、定義とも合わない。"}, {"text": "彼らは出発の地方に集まった。", "explanation": "ここは〈地点〉の意味。一点を指す語ではないので、〈地方〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42652, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は地方を出身です。", "corrected_sentence": "私は地方の出身です。", "error_description": "「地方を出身」の〈を〉が誤り。「出身」は名詞なので「地方の出身」と〈の〉で続ける必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42652, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地方を農家から、季節の野菜を取り寄せています。", "corrected_sentence": "地方の農家から、季節の野菜を取り寄せています。", "error_description": "「地方を農家から」の〈を〉が誤り。〈を〉は目的語を示すが、「地方」は「農家」を修飾するので〈の〉で続け、「地方の農家から」とする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
