INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42674, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもたいへんなこと。", "primary_collocate": null, "pronunciation": "かこく", "ipa": "kakokɯ", "syllable_count": 3, "sentences": [{"text": "砂漠での訓練は、想像以上に過酷だった。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "さばくでのくんれんは、そうぞういじょうにかこくだった。", "sentence_source": "generated"}, {"text": "彼は過酷な環境でも、文句を言わず働いた。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "かれはかこくなかんきょうでも、もんくをいわずはたらいた。", "sentence_source": "generated"}, {"text": "冬の山は寒さが厳しく、登山者にとって過酷だ。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "ふゆのやまはさむさがきびしく、とざんしゃにとってかこくだ。", "sentence_source": "generated"}, {"text": "過酷な仕事が続いて、体を壊す人も多い。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "かこくなしごとがつづいて、からだをこわすひともおおい。", "sentence_source": "generated"}, {"text": "長い距離を走るこの大会は、とても過酷なことで知られる。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "ながいきょりをはしるこのたいかいは、とてもかこくなことでしられる。", "sentence_source": "generated"}, {"text": "毎日十五時間の労働は、あまりに過酷だ。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "まいにちじゅうごじかんのろうどうは、あまりにかこくだ。", "sentence_source": "generated"}, {"text": "過酷な練習を乗りこえて、彼らは優勝した。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "かこくなれんしゅうをのりこえて、かれらはゆうしょうした。", "sentence_source": "generated"}, {"text": "戦争中の人々の暮らしは、過酷だったと祖母は話す。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "せんそうちゅうのひとびとのくらしは、かこくだったとそぼははなす。", "sentence_source": "generated"}, {"text": "暑さの中で作業する農家の仕事は、過酷になりやすい。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "あつさのなかでさぎょうするのうかのしごとは、かこくになりやすい。", "sentence_source": "generated"}, {"text": "過酷な旅だったが、景色の美しさが疲れを忘れさせた。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "かこくなたびだったが、けしきのうつくしさがつかれをわすれさせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過酷だ", "label": "終止形"}, {"form": "過酷な", "label": "連体形"}, {"form": "過酷に", "label": "連用形"}, {"form": "過酷で", "label": "て形"}, {"form": "過酷だった", "label": "過去形"}], "register": "標準", "sense_fingerprint": "条件や仕事がきびしく、耐えるのがとても大変なようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 乗りこえ (Zipf 1.63)']::text[], '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42674, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過酷", "is_correct": true, "explanation": "訓練が想像以上に厳しく、耐えがたいことを表す。文の意味に合う。"}, {"text": "快適", "is_correct": false, "explanation": "「想像以上に快適だった」では、訓練の厳しさと矛盾して文脈に合わない。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やか」は落ち着いた様子を表し、厳しい訓練の描写には合わない。"}, {"text": "手軽", "is_correct": false, "explanation": "「手軽」は楽に扱える様子を表し、厳しい訓練の描写とは反対の意味になるため文脈に合わない。"}], "explanations": {"過酷": "訓練が想像以上に厳しく、耐えがたいことを表す。文の意味に合う。", "快適": "「想像以上に快適だった」では、訓練の厳しさと矛盾して文脈に合わない。", "穏やか": "「穏やか」は落ち着いた様子を表し、厳しい訓練の描写には合わない。", "手軽": "「手軽」は楽に扱える様子を表し、厳しい訓練の描写とは反対の意味になるため文脈に合わない。"}, "sentence_index": 0, "correct_answer": "過酷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このホテルは過酷なほど快適で、一晩中ぐっすり眠れた。", "explanation": "「心地よい」の意味と取り違えている。「過酷」は苦しく耐えがたい状況を表すので、快適さの形容には合わない。"}, {"text": "この歌は過酷なリズムで、子どもも踊りやすい。", "explanation": "「軽快」の意味と取り違えている。「過酷」は苦しい状況や労働を表す語で、リズムの明るさには使わない。"}, {"text": "彼のデザインは過酷で、若い客に人気がある。", "explanation": "「ハード」のような格好よさを表す場面では「過酷」は使えない。ここはデザインの評価なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過酷", "is_correct": true, "explanation": "厳しい練習を乗りこえたことを表し、文の意味に合う。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈な練習」は苦しさを乗りこえた話と合わず、文脈に合わない。"}, {"text": "上品", "is_correct": false, "explanation": "「上品」は品のよさを表し、練習の描写とは結びつかない。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな練習」は練習の性質として不自然で、優勝へ至る文脈に合わない。"}], "explanations": {"過酷": "厳しい練習を乗りこえたことを表し、文の意味に合う。", "退屈": "「退屈な練習」は苦しさを乗りこえた話と合わず、文脈に合わない。", "上品": "「上品」は品のよさを表し、練習の描写とは結びつかない。", "静か": "「静かな練習」は練習の性質として不自然で、優勝へ至る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "過酷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この旅館は過酷な造りで、客室がとても広い。", "explanation": "「豪華」の意味と取り違えている。「過酷」は苦しい状況を表し、建物の造りの豪華さには使わない。"}, {"text": "彼女の性格は過酷で、誰とでもすぐ打ち解ける。", "explanation": "「厳しい」の意味と取り違えている。「過酷」は苦しい環境や労働に使う語で、人の性格を言う場面には使わない。"}, {"text": "このドーナツは過酷な甘さで、子どもに人気がある。", "explanation": "味の強さを表す場面では「過酷」は使わない。「濃厚」などが合う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42674, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "過酷の練習で、選手は疲れきった。", "corrected_sentence": "過酷な練習で、選手は疲れきった。", "error_description": "「過酷」は形容動詞なので、名詞を修飾するには「な」が必要。「の」は誤りで、正しくは「過酷な」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過酷な", "is_correct": true, "explanation": "連体形。名詞「環境」を修飾するので「過酷な」が正しい。"}, {"text": "過酷だ", "is_correct": false, "explanation": "終止形。名詞を直接修飾できない。"}, {"text": "過酷に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞「環境」には続かない。"}, {"text": "過酷で", "is_correct": false, "explanation": "て形。文を中で続ける形で、名詞を修飾できない。"}], "correct_form": "過酷な", "base_form": "過酷だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"過酷な": "連体形。名詞「環境」を修飾するので「過酷な」が正しい。", "過酷だ": "終止形。名詞を直接修飾できない。", "過酷に": "連用形。動詞や形容詞を修飾する形で、名詞「環境」には続かない。", "過酷で": "て形。文を中で続ける形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42674, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "過酷だな練習を続けて、彼らは優勝した。", "corrected_sentence": "過酷な練習を続けて、彼らは優勝した。", "error_description": "「過酷だ」の連体形は「過酷な」。「だな」は名詞を修飾できず、誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過酷だった", "is_correct": true, "explanation": "過去の断定。「過酷だったと祖母は話す」の述語として正しい。"}, {"text": "過酷だったとき", "is_correct": false, "explanation": "「とき」は時を表す語で、「と祖母は話す」の引用の前には続けられず、文が成り立たない。"}, {"text": "過酷ならば", "is_correct": false, "explanation": "仮定の条件形。「と祖母は話す」の前に続けると、文の述語として成り立たない。"}, {"text": "過酷なら", "is_correct": false, "explanation": "仮定形。条件を表す形になり、「と祖母は話す」の述語としては成り立たない。"}], "correct_form": "過酷だった", "base_form": "過酷だ", "form_label": "過去形", "sentence_index": 7, "explanations": {"過酷だった": "過去の断定。「過酷だったと祖母は話す」の述語として正しい。", "過酷だったとき": "「とき」は時を表す語で、「と祖母は話す」の引用の前には続けられず、文が成り立たない。", "過酷ならば": "仮定の条件形。「と祖母は話す」の前に続けると、文の述語として成り立たない。", "過酷なら": "仮定形。条件を表す形になり、「と祖母は話す」の述語としては成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42701, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "が", "is_correct": false, "explanation": "「畜産がは」と続くと助詞が重なり、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「畜産をは」と続くと助詞が重なり、文として成り立たない。"}, {"text": "で", "is_correct": true, "explanation": "正解。「畜産では」は、畜産という分野の中での話を示すので自然。"}, {"text": "の", "is_correct": false, "explanation": "「畜産のは」と続くと助詞が重なり、文として成り立たない。"}], "correct_answer": "で", "explanations": {"が": "「畜産がは」と続くと助詞が重なり、文として成り立たない。", "を": "「畜産をは」と続くと助詞が重なり、文として成り立たない。", "で": "正解。「畜産では」は、畜産という分野の中での話を示すので自然。", "の": "「畜産のは」と続くと助詞が重なり、文として成り立たない。"}, "error_tags": {"が": "主語の誤り", "を": "目的語の誤り", "の": "連体の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42701, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "へ", "is_correct": false, "explanation": "「畜産へ、動物の命を預かる大変な仕事です」は方向を示す形で、主題として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「畜産に、動物の命を預かる大変な仕事です」は場所や相手を示す形で、主題の文として不自然。"}, {"text": "は", "is_correct": true, "explanation": "正解。畜産を主題として述べる文なので「は」。"}, {"text": "と", "is_correct": false, "explanation": "「畜産と、動物の命を預かる大変な仕事です」は並列の形になり、説明の主題として不自然。"}], "correct_answer": "は", "explanations": {"へ": "「畜産へ、動物の命を預かる大変な仕事です」は方向を示す形で、主題として成り立たない。", "に": "「畜産に、動物の命を預かる大変な仕事です」は場所や相手を示す形で、主題の文として不自然。", "は": "正解。畜産を主題として述べる文なので「は」。", "と": "「畜産と、動物の命を預かる大変な仕事です」は並列の形になり、説明の主題として不自然。"}, "error_tags": {"へ": "方向の誤り", "に": "位置・相手の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42701, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "動物を育てて、食べ物や皮などをとること。", "primary_collocate": null, "pronunciation": "ちくさん", "ipa": "tɕikɯsaɴ", "syllable_count": 4, "sentences": [{"text": "叔父は山の近くで畜産をして、牛乳と肉を売っています。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "叔父[おじ]は山[やま]の近[ちか]くで畜産[ちくさん]をして、牛乳[ぎゅうにゅう]と肉[にく]を売[う]っています。", "sentence_source": "generated"}, {"text": "畜産では、牛や豚や鶏を育てます。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]では、牛[うし]や豚[ぶた]や鶏[にわとり]を育[そだ]てます。", "sentence_source": "generated"}, {"text": "畜産をする人は、毎日動物にえさをやらなければなりません。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]をする人[ひと]は、毎日[まいにち]動物[どうぶつ]にえさをやらなければなりません。", "sentence_source": "generated"}, {"text": "夏休みに、畜産をしている友達の家を手伝いました。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、畜産[ちくさん]をしている友達[ともだち]の家[いえ]を手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "畜産のおかげで、私たちは卵や肉を食べることができます。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]のおかげで、私[わたし]たちは卵[たまご]や肉[にく]を食[た]べることができます。", "sentence_source": "generated"}, {"text": "この地方は草原が広いので、畜産に向いています。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "この地方[ちほう]は草原[そうげん]が広[ひろ]いので、畜産[ちくさん]に向[む]いています。", "sentence_source": "generated"}, {"text": "畜産を学ぶために、父は農業高校に入りました。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]を学[まな]ぶために、父[ちち]は農業[のうぎょう]高校[こうこう]に入[はい]りました。", "sentence_source": "generated"}, {"text": "畜産は、動物の命を預かる大変な仕事です。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]は、動物[どうぶつ]の命[いのち]を預[あず]かる大変[たいへん]な仕事[しごと]です。", "sentence_source": "generated"}, {"text": "学校の見学で、畜産の様子を実際に見ました。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "学校[がっこう]の見学[けんがく]で、畜産[ちくさん]の様子[ようす]を実際[じっさい]に見[み]ました。", "sentence_source": "generated"}, {"text": "雪の多い地域でも、畜産を続けている家族がいます。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "雪[ゆき]の多[おお]い地域[ちいき]でも、畜産[ちくさん]を続[つづ]けている家族[かぞく]がいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "畜産", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "牛や豚などの動物を育てて、肉や乳や皮などを得る仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散歩", "is_correct": false, "explanation": "「散歩をして、牛乳と肉を売っています」は意味が通らない。牛乳と肉を得る仕事の文脈に合わない。"}, {"text": "畜産", "is_correct": true, "explanation": "正解。牛を育てて牛乳と肉を売る仕事を指し、「畜産をして」が自然。"}, {"text": "読書", "is_correct": false, "explanation": "「読書をして、牛乳と肉を売っています」は文脈が成り立たない。"}, {"text": "将棋", "is_correct": false, "explanation": "「将棋をして、牛乳と肉を売っています」は意味をなさない。"}], "explanations": {"散歩": "「散歩をして、牛乳と肉を売っています」は意味が通らない。牛乳と肉を得る仕事の文脈に合わない。", "畜産": "正解。牛を育てて牛乳と肉を売る仕事を指し、「畜産をして」が自然。", "読書": "「読書をして、牛乳と肉を売っています」は文脈が成り立たない。", "将棋": "「将棋をして、牛乳と肉を売っています」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "畜産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みに、畜産で花を育てている友達の家を手伝いました。", "explanation": "ここは〈園芸〉の意味。花や野菜を育てるのは園芸で、畜産は家畜を飼うことに使う。"}, {"text": "夏休みに、畜産で木を切っている友達の家を手伝いました。", "explanation": "ここは〈林業〉の意味。木を切って林を管理するのは林業で、畜産は家畜の飼育に使う。"}, {"text": "夏休みに、畜産で魚を捕っている友達の家を手伝いました。", "explanation": "ここは〈漁業〉の意味。魚を捕るのは漁業で、畜産は牛・豚・鶏などの家畜に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "囲碁", "is_correct": false, "explanation": "「囲碁を学ぶために農業高校に入った」は意味が通らない。"}, {"text": "畜産", "is_correct": true, "explanation": "正解。農業高校で学ぶ内容として、畜産を学ぶという文が自然。"}, {"text": "作文", "is_correct": false, "explanation": "「作文を学ぶために農業高校に入った」は学校選びの理由として成り立たない。"}, {"text": "手芸", "is_correct": false, "explanation": "「手芸を学ぶために農業高校に入った」は文脈に合わない。"}], "explanations": {"囲碁": "「囲碁を学ぶために農業高校に入った」は意味が通らない。", "畜産": "正解。農業高校で学ぶ内容として、畜産を学ぶという文が自然。", "作文": "「作文を学ぶために農業高校に入った」は学校選びの理由として成り立たない。", "手芸": "「手芸を学ぶために農業高校に入った」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "畜産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪の多い地域でも、畜産で米を作っている家族がいます。", "explanation": "ここは〈農業〉の意味。米を育てて収穫するのは農業で、畜産は動物を育てて食べ物などをとることに使う。"}, {"text": "雪の多い地域でも、畜産で庭を作っている家族がいます。", "explanation": "ここは〈造園〉の意味。庭を作るのは造園で、畜産は家畜の飼育に使う。"}, {"text": "雪の多い地域でも、畜産で紙を作っている家族がいます。", "explanation": "ここは〈製紙〉の意味。紙を作るのは製紙で、畜産は家畜を育てる産業に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42701, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は田舎で畜産に営み、毎朝新鮮な牛乳を届けてくれます。", "corrected_sentence": "祖母は田舎で畜産を営み、毎朝新鮮な牛乳を届けてくれます。", "error_description": "「営む」は他動詞で、対象の畜産は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は畜産を営まれて、牛を育てています。", "corrected_sentence": "叔父は畜産を営んで、牛を育てています。", "error_description": "「営む」は他動詞で、対象の畜産は「を」で示す。受身の「営まれて」にすると目的語の「を」は「が」に変わるため、「畜産を営まれて」は誤り。能動の「営んで」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42702, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "「畜産を盛んで」は「盛ん」が目的語を取らないため不自然。"}, {"text": "が", "is_correct": true, "explanation": "正解。「盛ん」の主語になる畜産には「が」を使う。"}, {"text": "へ", "is_correct": false, "explanation": "「畜産へ盛んで」は方向を示す形で、盛んさの主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「畜産の盛んで」と続くと名詞の後に形容動詞の述語が続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"を": "「畜産を盛んで」は「盛ん」が目的語を取らないため不自然。", "が": "正解。「盛ん」の主語になる畜産には「が」を使う。", "へ": "「畜産へ盛んで」は方向を示す形で、盛んさの主語にならない。", "の": "「畜産の盛んで」と続くと名詞の後に形容動詞の述語が続かず、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "の": "連体の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42702, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "が", "is_correct": false, "explanation": "「畜産が出るふん」では畜産が出る主体になり、ふんの出どころという意味が崩れる。"}, {"text": "から", "is_correct": true, "explanation": "正解。ふんが畜産から出るという起点を示すので「から」。"}, {"text": "と", "is_correct": false, "explanation": "「畜産と出るふん」は動詞の修飾として成り立たず、ふんの出どころを示せない。"}, {"text": "に", "is_correct": false, "explanation": "「畜産に出るふん」は場所や相手を示す形で、ふんの出どころの意味にならない。"}], "correct_answer": "から", "explanations": {"が": "「畜産が出るふん」では畜産が出る主体になり、ふんの出どころという意味が崩れる。", "から": "正解。ふんが畜産から出るという起点を示すので「から」。", "と": "「畜産と出るふん」は動詞の修飾として成り立たず、ふんの出どころを示せない。", "に": "「畜産に出るふん」は場所や相手を示す形で、ふんの出どころの意味にならない。"}, "error_tags": {"が": "主語の誤り", "と": "並列の誤り", "に": "位置・相手の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42702, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "家畜や家禽を飼育し、肉・卵・乳・皮などの生活に役立つ物を生産する産業。", "primary_collocate": null, "pronunciation": "ちくさん", "ipa": "tɕikɯsaɴ", "syllable_count": 4, "sentences": [{"text": "鶏は家禽の一つで、人間が管理する家畜として畜産の中で大切に育てられています。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "鶏[にわとり]は家禽[かきん]の一[ひと]つで、人間[にんげん]が管理[かんり]する家畜[かちく]として畜産[ちくさん]の中[なか]で大切[たいせつ]に育[そだ]てられています。", "sentence_source": "generated"}, {"text": "北海道は畜産がさかんで、牛乳やチーズが全国に送られています。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]は畜産[ちくさん]がさかんで、牛乳[ぎゅうにゅう]やチーズが全国[ぜんこく]に送[おく]られています。", "sentence_source": "generated"}, {"text": "畜産では、動物の健康を守ることが何より大切です。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]では、動物[どうぶつ]の健康[けんこう]を守[まも]ることが何[なに]より大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "畜産を営む農家は、毎朝早くから牛の世話をします。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]を営[いとな]む農家[のうか]は、毎朝[まいあさ]早[はや]くから牛[うし]の世話[せわ]をします。", "sentence_source": "generated"}, {"text": "輸入した飼料の値段が上がり、畜産に大きな影響が出ています。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "輸入[ゆにゅう]した飼料[しりょう]の値段[ねだん]が上[あ]がり、畜産[ちくさん]に大[おお]きな影響[えいきょう]が出[で]ています。", "sentence_source": "generated"}, {"text": "この大学には、畜産について学べる学部があります。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "この大学[だいがく]には、畜産[ちくさん]について学[まな]べる学部[がくぶ]があります。", "sentence_source": "generated"}, {"text": "畜産の現場では、豚や鶏の数を毎日記録しています。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]の現場[げんば]では、豚[ぶた]や鶏[にわとり]の数[かず]を毎日[まいにち]記録[きろく]しています。", "sentence_source": "generated"}, {"text": "畜産から出るふんを、肥料として利用する取り組みが広がっています。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "畜産[ちくさん]から出[で]るふんを、肥料[ひりょう]として利用[りよう]する取[と]り組[く]みが広[ひろ]がっています。", "sentence_source": "generated"}, {"text": "日本の畜産は、狭い土地で効率よく行う工夫が進んでいます。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "日本[にほん]の畜産[ちくさん]は、狭[せま]い土地[とち]で効率[こうりつ]よく行[おこな]う工夫[くふう]が進[すす]んでいます。", "sentence_source": "generated"}, {"text": "祖父は長年畜産に関わり、立派な牛を育ててきました。", "target_word": "畜産", "complexity_tier": "T3", "furigana": "祖父[そふ]は長年[ながねん]畜産[ちくさん]に関[かか]わり、立派[りっぱ]な牛[うし]を育[そだ]ててきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "畜産", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "牛・豚・鶏などを飼育して肉や卵や乳を生産する産業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42702, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "読書", "is_correct": false, "explanation": "「読書の中で大切に育てられています」は意味が通らない。家畜を育てる文脈に合わない。"}, {"text": "畜産", "is_correct": true, "explanation": "正解。家畜を人が管理して育てる分野を指し、「畜産の中で」が自然。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩の中で大切に育てられています」は意味が通らない。家畜の飼育の文脈に合わない。"}, {"text": "作文", "is_correct": false, "explanation": "「作文の中で大切に育てられています」は意味が通らない。"}], "explanations": {"読書": "「読書の中で大切に育てられています」は意味が通らない。家畜を育てる文脈に合わない。", "畜産": "正解。家畜を人が管理して育てる分野を指し、「畜産の中で」が自然。", "散歩": "「散歩の中で大切に育てられています」は意味が通らない。家畜の飼育の文脈に合わない。", "作文": "「作文の中で大切に育てられています」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "畜産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "農家は毎朝早くから田んぼの畜産をします。", "explanation": "ここは〈農業〉の意味。田んぼや作物を育てることは農業で、畜産は家畜を飼うことに使う。"}, {"text": "畜産では、木を伐って運びます。", "explanation": "ここは〈林業〉の意味。木を伐って運ぶのは林業で、畜産は家畜を育てる産業に使う。"}, {"text": "畜産では、船で魚を捕って売ります。", "explanation": "ここは〈漁業〉の意味。魚を捕るのは漁業で、畜産は牛・豚・鶏などの家畜に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42702, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡眠", "is_correct": false, "explanation": "「睡眠の現場では、豚や鶏の数を記録」は意味が通らない。家畜の管理の文脈に合わない。"}, {"text": "畜産", "is_correct": true, "explanation": "正解。家畜の数を毎日記録する現場を指し、「畜産の現場」が自然。"}, {"text": "落語", "is_correct": false, "explanation": "「落語の現場では豚や鶏の数を記録」は意味をなさない。"}, {"text": "将棋", "is_correct": false, "explanation": "「将棋の現場」では家畜の記録という文脈が成り立たない。"}], "explanations": {"睡眠": "「睡眠の現場では、豚や鶏の数を記録」は意味が通らない。家畜の管理の文脈に合わない。", "畜産": "正解。家畜の数を毎日記録する現場を指し、「畜産の現場」が自然。", "落語": "「落語の現場では豚や鶏の数を記録」は意味をなさない。", "将棋": "「将棋の現場」では家畜の記録という文脈が成り立たない。"}, "sentence_index": 6, "correct_answer": "畜産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は長年畜産に関わり、大きな鯛を育ててきました。", "explanation": "ここは〈養殖〉の意味。魚や貝を育てるのは養殖で、畜産は牛・豚・鶏などの家畜に使う。"}, {"text": "祖父は長年畜産に関わり、立派な花を育ててきました。", "explanation": "ここは〈園芸〉の意味。花や野菜を育てるのは園芸で、畜産は家畜を飼うことに使う。"}, {"text": "祖父は長年畜産に関わり、立派な庭を作ってきました。", "explanation": "ここは〈造園〉の意味。庭や公園を作ることは造園で、畜産は家畜の飼育に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42702, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町では畜産を盛んで、多くの農家が牛を飼っています。", "corrected_sentence": "この町では畜産が盛んで、多くの農家が牛を飼っています。", "error_description": "「盛んで」は主語に「が」を取る形容動詞。「畜産を盛んで」は誤りで、正しくは「畜産が盛んで」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42702, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は大学で畜産を学ぶ、卒業後は牧場で働いています。", "corrected_sentence": "彼は大学で畜産を学んで、卒業後は牧場で働いています。", "error_description": "「学ぶ」で文を止めると後の「、卒業後は」が続かない。動詞の te 形「学んで」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42706, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42706, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「草取りが終わると」で、草取りを主語にする。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を表すが、「草取りと終わると」では文の構造が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「草取りより終わると」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「草取りの終わると」とは言わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「草取りが終わると」で、草取りを主語にする。", "と": "並列や引用を表すが、「草取りと終わると」では文の構造が成り立たない。", "より": "比較を表すので、「草取りより終わると」は意味が通らない。", "の": "「草取りの終わると」とは言わない。"}, "error_tags": {"と": "companion_or_quote", "より": "comparison", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42706, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "草をとること。", "primary_collocate": null, "pronunciation": "くさとり", "ipa": "kɯsatoɾi", "syllable_count": 4, "sentences": [{"text": "日曜日の朝、家族で庭の草取りをした。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "にちようびのあさ、かぞくでにわのくさとりをした。", "sentence_source": "generated"}, {"text": "夏は草がすぐ伸びるので、草取りが大変だ。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "なつはくさがすぐのびるので、くさとりがたいへんだ。", "sentence_source": "generated"}, {"text": "草取りをしていたら、背中が痛くなってきた。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "くさとりをしていたら、せなかがいたくなってきた。", "sentence_source": "generated"}, {"text": "おばあさんは毎朝、畑で草取りをしている。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "おばあさんはまいあさ、はたけでくさとりをしている。", "sentence_source": "generated"}, {"text": "草取りのあとは、手をよく洗いましょう。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "くさとりのあとは、てをよくあらいましょう。", "sentence_source": "generated"}, {"text": "暑い日の草取りは、帽子をかぶって行う。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "あついひのくさとりは、ぼうしをかぶっておこなう。", "sentence_source": "generated"}, {"text": "学校の花壇の草取りを、クラスのみんなで手伝った。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "がっこうのかだんのくさとりを、クラスのみんなでてつだった。", "sentence_source": "generated"}, {"text": "草取りが終わると、庭が明るくなった。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "くさとりがおわると、にわがあかるくなった。", "sentence_source": "generated"}, {"text": "雨のあとは土がやわらかく、草取りがしやすい。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "あめのあとはつちがやわらかく、くさとりがしやすい。", "sentence_source": "generated"}, {"text": "草取りの道具を買いに、店へ行った。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "くさとりのどうぐをかいに、みせへいった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "草取りをする", "label": "終止形"}, {"form": "草取りをした", "label": "過去形"}, {"form": "草取りをして", "label": "て形"}, {"form": "草取りをしない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "庭や畑などの雑草を抜いて取り除く作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草取り", "is_correct": true, "explanation": "正解。「庭の草取りをした」で、雑草を抜く作業を表す。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う作業。「庭の洗濯をした」とは言わないので空欄に入らない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作る作業。「庭の料理をした」は不自然で、空欄に合わない。"}, {"text": "買い物", "is_correct": false, "explanation": "店で品物を買うこと。「庭の買い物をした」とは言わないので合わない。"}], "explanations": {"草取り": "正解。「庭の草取りをした」で、雑草を抜く作業を表す。", "洗濯": "衣類を洗う作業。「庭の洗濯をした」とは言わないので空欄に入らない。", "料理": "食べ物を作る作業。「庭の料理をした」は不自然で、空欄に合わない。", "買い物": "店で品物を買うこと。「庭の買い物をした」とは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "草取り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の草取りをして、床をぴかぴかにした。", "explanation": "ここは〈掃除〉の意味。草取りは庭や畑の雑草を取る作業で、部屋の掃除には使わないので不自然。"}, {"text": "この草取りは、畑の草を枯らす。", "explanation": "ここは〈除草剤〉の意味。草取りは手で草を取る作業で、草を枯らす薬品ではないので合わない。"}, {"text": "おばあさんは毎朝、畑で草取りを育てている。", "explanation": "ここは〈作物〉の意味。草取りは雑草を取る作業の名前で、畑で育てる対象の作物とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草取り", "is_correct": true, "explanation": "正解。「花壇の草取りを手伝った」で、雑草を抜く作業を表す。"}, {"text": "洗車", "is_correct": false, "explanation": "車を洗うこと。「花壇の洗車」とは言わないので空欄に入らない。"}, {"text": "宿題", "is_correct": false, "explanation": "学校で出される課題。「花壇の宿題を手伝った」は意味が通らない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読むこと。「花壇の読書を手伝った」とは言わないので合わない。"}], "explanations": {"草取り": "正解。「花壇の草取りを手伝った」で、雑草を抜く作業を表す。", "洗車": "車を洗うこと。「花壇の洗車」とは言わないので空欄に入らない。", "宿題": "学校で出される課題。「花壇の宿題を手伝った」は意味が通らない。", "読書": "本を読むこと。「花壇の読書を手伝った」とは言わないので合わない。"}, "sentence_index": 6, "correct_answer": "草取り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の終わり際に、草取りを決めた。", "explanation": "ここは〈ゴールを決める〉の意味。草取りは得点ではないので、「決める」の目的語にならない。"}, {"text": "草取りの種を買いに、店へ行った。", "explanation": "ここは〈草（雑草）〉の意味。草取りは取り除く作業の名前で、草や植物そのものにはならないので合わない。"}, {"text": "毎週、草取りを歌ったおかげで、花がよく育っている。", "explanation": "ここは〈民謡〉の意味。草取りは作業の名前で、民謡のように歌うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草取りが始めて、庭が明るくなった。", "corrected_sentence": "草取りを始めて、庭が明るくなった。", "error_description": "誤った形：「草取りが」。正しい形：「草取りを」。「始める」は他動詞なので目的語に「を」を使う。「が」では不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草取りに手伝ってくれた。", "corrected_sentence": "草取りを手伝ってくれた。", "error_description": "誤った形：「草取りに」。正しい形：「草取りを」。「手伝う」は「〜を手伝う」の形で、目的語に「を」を使う。「に」では不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42707, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「草取りをしないと」で、「する」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "「する」は目的語に「を」を取るので、「草取りがしないと」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「草取りにしないと」とは言わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「草取りへしないと」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「草取りをしないと」で、「する」の目的語を表す。", "が": "「する」は目的語に「を」を取るので、「草取りがしないと」は不自然。", "に": "「草取りにしないと」とは言わない。", "へ": "方向を表すので、「草取りへしないと」は成り立たない。"}, "error_tags": {"が": "subject_marker", "に": "target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42707, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「草取りを済ませた」で、「済ませる」の目的語を表す。"}, {"text": "の", "is_correct": false, "explanation": "「草取りの、済ませた」では、動詞の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手がないので、「草取りと、済ませた」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「草取りへ、済ませた」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「草取りを済ませた」で、「済ませる」の目的語を表す。", "の": "「草取りの、済ませた」では、動詞の目的語にならない。", "と": "並列の相手がないので、「草取りと、済ませた」は不自然。", "へ": "方向を表すので、「草取りへ、済ませた」は成り立たない。"}, "error_tags": {"の": "possessive", "と": "companion_or_quote", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42707, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "庭や畑などに生えている不要な草を、抜いたり切ったりして取り除くこと。", "primary_collocate": null, "pronunciation": "くさとり", "ipa": "kɯsatoɾi", "syllable_count": 4, "sentences": [{"text": "畑の草取りは、野菜を育てるために欠かせない仕事だ。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "はたけのくさとりは、やさいをそだてるためにかかせないしごとだ。", "sentence_source": "generated"}, {"text": "草取りをしないと、庭は雑草だらけになってしまう。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "くさとりをしないと、にわはざっそうだらけになってしまう。", "sentence_source": "generated"}, {"text": "父は鎌を使って、庭の隅の草取りをした。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "ちちはかまをつかって、にわのすみのくさとりをした。", "sentence_source": "generated"}, {"text": "駐車場の草取りは、町内会の人たちが毎月行っている。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "ちゅうしゃじょうのくさとりは、ちょうないかいのひとたちがまいつきおこなっている。", "sentence_source": "generated"}, {"text": "手で抜く草取りは時間がかかるが、根まで取れる。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "てでぬくくさとりはじかんがかかるが、ねまでとれる。", "sentence_source": "generated"}, {"text": "草取りを始めて一時間で、庭の半分がきれいになった。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "くさとりをはじめていちじかんで、にわのはんぶんがきれいになった。", "sentence_source": "generated"}, {"text": "夏休みに、祖母の家の草取りを手伝った。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "なつやすみに、そぼのいえのくさとりをてつだった。", "sentence_source": "generated"}, {"text": "お墓の周りの草取りを、お盆の前に済ませた。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "おはかのまわりのくさとりを、おぼんのまえにすませた。", "sentence_source": "generated"}, {"text": "草取りをするときは、虫に刺されないように長袖を着る。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "くさとりをするときは、むしにさされないようにながそでをきる。", "sentence_source": "generated"}, {"text": "毎週の草取りのおかげで、花がよく育っている。", "target_word": "草取り", "complexity_tier": "T3", "furigana": "まいしゅうのくさとりのおかげで、はながよくそだっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "草取りをする", "label": "終止形"}, {"form": "草取りをした", "label": "過去形"}, {"form": "草取りをして", "label": "て形"}, {"form": "草取りをしない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "庭や畑に生えた不要な雑草を抜いたり切ったりして取り除く作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42707, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草取り", "is_correct": true, "explanation": "正解。「畑の草取りは、野菜を育てるために欠かせない仕事だ」で、雑草を取る作業を表す。"}, {"text": "採点", "is_correct": false, "explanation": "答案に点数をつけること。「畑の採点」とは言わないので合わない。"}, {"text": "運転", "is_correct": false, "explanation": "車などを操作すること。「畑の運転」は意味が通らない。"}, {"text": "散髪", "is_correct": false, "explanation": "髪を切ること。「畑の散髪」とは言わないので空欄に入らない。"}], "explanations": {"草取り": "正解。「畑の草取りは、野菜を育てるために欠かせない仕事だ」で、雑草を取る作業を表す。", "採点": "答案に点数をつけること。「畑の採点」とは言わないので合わない。", "運転": "車などを操作すること。「畑の運転」は意味が通らない。", "散髪": "髪を切ること。「畑の散髪」とは言わないので空欄に入らない。"}, "sentence_index": 0, "correct_answer": "草取り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駐車場の草取りを、デッキブラシで磨いた。", "explanation": "ここは〈掃除〉の意味。草取りは雑草を取る作業で、床を磨く掃除とは違うので合わない。"}, {"text": "この草取りは、畑の草を薬で枯らす。", "explanation": "ここは〈除草剤〉の意味。草取りは抜いたり切ったりして草を取り除く作業で、薬で枯らす除草剤とは違うので合わない。"}, {"text": "駐車場の草取りを、車の修理に使った。", "explanation": "ここは〈道具〉の意味。草取りは作業の名前で、車の修理に使う道具にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42707, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草取り", "is_correct": true, "explanation": "正解。「祖母の家の草取りを手伝った」で、雑草を抜く作業を表す。"}, {"text": "天気", "is_correct": false, "explanation": "その時の空模様。「天気を手伝う」とは言わないので空欄に入らない。"}, {"text": "地図", "is_correct": false, "explanation": "場所を示した図。「地図を手伝う」は意味が通らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方の空の色。「夕焼けを手伝う」は意味が通らない。"}], "explanations": {"草取り": "正解。「祖母の家の草取りを手伝った」で、雑草を抜く作業を表す。", "天気": "その時の空模様。「天気を手伝う」とは言わないので空欄に入らない。", "地図": "場所を示した図。「地図を手伝う」は意味が通らない。", "夕焼け": "夕方の空の色。「夕焼けを手伝う」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "草取り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎週、草取りを歌ったおかげで、花がよく育っている。", "explanation": "ここは〈民謡〉の意味。草取りは作業の名前で、民謡のように歌うものではないので合わない。"}, {"text": "毎週の草取りの種のおかげで、花がよく育っている。", "explanation": "ここは〈草（雑草）〉の意味。草取りは取り除く作業の名前で、草や植物そのものにはならないので合わない。"}, {"text": "毎週の草取りを、花瓶に入れて飾った。", "explanation": "ここは〈花材〉の意味。草取りは作業の名前で、花瓶に生ける花材にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42707, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草取りが、昨日のうちに終わらせた。", "corrected_sentence": "草取りを、昨日のうちに終わらせた。", "error_description": "誤った形：「草取りが」。正しい形：「草取りを」。「終わらせる」は他動詞なので目的語に「を」を使う。「が」では不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42707, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草取りを続けったら、腰が痛くなった。", "corrected_sentence": "草取りを続けたら、腰が痛くなった。", "error_description": "誤った形：「続けった」。正しい形：「続けたら」。「続ける」の過去の仮定形は「続けたら」で、「続けった」は存在しない形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42726, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「家禽が百羽以上います」の主語を示す「が」。存在する対象として家禽がここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「家禽を百羽以上います」では、いるという動詞に目的語は使えないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「家禽に百羽以上います」では家禽が場所や相手になり、存在の主語として働かない。"}, {"text": "で", "is_correct": false, "explanation": "「家禽で百羽以上います」は手段や場所を表し、存在を示す主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「家禽が百羽以上います」の主語を示す「が」。存在する対象として家禽がここに入る。", "を": "「家禽を百羽以上います」では、いるという動詞に目的語は使えないので合わない。", "に": "「家禽に百羽以上います」では家禽が場所や相手になり、存在の主語として働かない。", "で": "「家禽で百羽以上います」は手段や場所を表し、存在を示す主語にはならない。"}, "error_tags": {"を": "目的語の誤り", "に": "場所・相手の誤り", "で": "手段・場所の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42726, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「家禽の卵」の所属を示す「の」。家禽から取れる卵が新鮮なうちに売られる、という意味で入る。"}, {"text": "が", "is_correct": false, "explanation": "「家禽が卵が」と主語が二つ重なり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「家禽へ卵が」では家禽が方向や相手になり、売られる卵の所属を表せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「家禽より卵が」は比べる文になり、卵の所属を示す文脈と合わない。"}], "correct_answer": "の", "explanations": {"の": "「家禽の卵」の所属を示す「の」。家禽から取れる卵が新鮮なうちに売られる、という意味で入る。", "が": "「家禽が卵が」と主語が二つ重なり、文として成り立たない。", "へ": "「家禽へ卵が」では家禽が方向や相手になり、売られる卵の所属を表せないので合わない。", "より": "「家禽より卵が」は比べる文になり、卵の所属を示す文脈と合わない。"}, "error_tags": {"が": "主語の重複", "へ": "方向・相手の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42726, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が食べるために育てる鳥です。", "primary_collocate": null, "pronunciation": "かきん", "ipa": "kakiɴ", "syllable_count": 3, "sentences": [{"text": "ニワトリは、人が卵や肉のために育てる家禽です。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "ニワトリは、人[ひと]が卵[たまご]や肉[にく]のために育[そだ]てる家禽[かきん]です。", "sentence_source": "generated"}, {"text": "この農場には、家禽が百羽以上います。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "この農場[のうじょう]には、家禽[かきん]が百羽[ひゃくわ]以上[いじょう]います。", "sentence_source": "generated"}, {"text": "家禽の世話は、朝早く起きて餌をやることから始まります。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "家禽[かきん]の世話[せわ]は、朝早[あさはや]く起[お]きて餌[えさ]をやることから始[はじ]まります。", "sentence_source": "generated"}, {"text": "アヒルも七面鳥も、食べるために育てられる家禽の仲間です。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "アヒルも七面鳥[しちめんちょう]も、食[た]べるために育[そだ]てられる家禽[かきん]の仲間[なかま]です。", "sentence_source": "generated"}, {"text": "家禽は小屋で飼うので、キツネに食べられる心配が少ないです。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "家禽[かきん]は小屋[こや]で飼[か]うので、キツネに食[た]べられる心配[しんぱい]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "スズメは野鳥なので、家禽とは呼びません。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "スズメは野鳥[やちょう]なので、家禽[かきん]とは呼[よ]びません。", "sentence_source": "generated"}, {"text": "弟は動物が好きで、将来は家禽を育てる仕事がしたいと言っています。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "弟[おとうと]は動物[どうぶつ]が好[す]きで、将来[しょうらい]は家禽[かきん]を育[そだ]てる仕事[しごと]がしたいと言[い]っています。", "sentence_source": "generated"}, {"text": "市場では、家禽の卵が新鮮なうちに売られています。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "市場[いちば]では、家禽[かきん]の卵[たまご]が新鮮[しんせん]なうちに売[う]られています。", "sentence_source": "generated"}, {"text": "家禽が逃げないように、毎晩小屋の戸を閉めます。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "家禽[かきん]が逃[に]げないように、毎晩[まいばん]小屋[こや]の戸[と]を閉[し]めます。", "sentence_source": "generated"}, {"text": "寒い日は、家禽が風邪をひかないように、小屋に藁を敷きます。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、家禽[かきん]が風邪[かぜ]をひかないように、小屋[こや]に藁[わら]を敷[し]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家禽", "label": "基本形"}], "register": "中立（ですます体）", "sense_fingerprint": "人が食べる目的で育てる身近な鳥（ニワトリなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家禽", "is_correct": true, "explanation": "「人が卵や肉のために育てる家禽です」で、食用に育てる鳥の総称として入る。"}, {"text": "野鳥", "is_correct": false, "explanation": "野鳥は野生の鳥で、人が育てるという文と矛盾するので成り立たない。"}, {"text": "渡り鳥", "is_correct": false, "explanation": "渡り鳥は季節に移動する野生の鳥で、人が卵や肉のために育てるものとは矛盾する。"}, {"text": "野生動物", "is_correct": false, "explanation": "野生動物は野に暮らす動物の総称で、卵や肉のために育てるものとは合わない。"}], "explanations": {"家禽": "「人が卵や肉のために育てる家禽です」で、食用に育てる鳥の総称として入る。", "野鳥": "野鳥は野生の鳥で、人が育てるという文と矛盾するので成り立たない。", "渡り鳥": "渡り鳥は季節に移動する野生の鳥で、人が卵や肉のために育てるものとは矛盾する。", "野生動物": "野生動物は野に暮らす動物の総称で、卵や肉のために育てるものとは合わない。"}, "sentence_index": 0, "correct_answer": "家禽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ヤギは、乳をしぼるために育てられる家禽です。", "explanation": "ここは〈家畜〉の意味。ヤギは鳥ではないので家禽とは言わず、家畜と呼ぶので誤り。"}, {"text": "犬は、家族の一員として大切に育てられる家禽です。", "explanation": "ここは〈ペット〉の意味。犬は食用の鳥ではないので家禽とは言わず、ペットと呼ぶので誤り。"}, {"text": "うなぎは、養殖場で育てる家禽です。", "explanation": "ここは〈水産物〉の意味。うなぎは魚で、鳥ではないので家禽とは言わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家禽", "is_correct": true, "explanation": "「将来は家禽を育てる仕事がしたい」で、食用に育てる鳥を指す語として入る。"}, {"text": "瓦礫", "is_correct": false, "explanation": "瓦礫は崩れた建物などの残骸で、育てる対象にならないので文が成り立たない。"}, {"text": "大気", "is_correct": false, "explanation": "大気は空気の層で、仕事として育てる対象にはならないので文が成り立たない。"}, {"text": "岩石", "is_correct": false, "explanation": "岩石は地中の固い石の集まりで、育てる仕事の対象にはならないので文が成り立たない。"}], "explanations": {"家禽": "「将来は家禽を育てる仕事がしたい」で、食用に育てる鳥を指す語として入る。", "瓦礫": "瓦礫は崩れた建物などの残骸で、育てる対象にならないので文が成り立たない。", "大気": "大気は空気の層で、仕事として育てる対象にはならないので文が成り立たない。", "岩石": "岩石は地中の固い石の集まりで、育てる仕事の対象にはならないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "家禽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭では、トマトやなすを家禽として育てている。", "explanation": "ここは〈農作物〉の意味。トマトやなすは野菜で、鳥の家禽とは言わないので誤り。"}, {"text": "猟師は、山で家禽を獲物として仕留めた。", "explanation": "ここは〈獲物〉の意味。猟で仕留めるのは野生の獲物で、人が食用に育てる家禽は獲物とは言わないので誤り。"}, {"text": "バードウォッチングで、庭に来た家禽の種類を数えた。", "explanation": "ここは〈野鳥〉の意味。庭に自然に来る鳥は野鳥で、人が食べるために育てる家禽とは言わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42726, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小屋では、家禽が餌を与えます。", "corrected_sentence": "小屋では、家禽に餌を与えます。", "error_description": "誤りは「家禽が」。「餌を与える」の受け手は「家禽に」で示す。「家禽が」だと家禽が与える側になり、人が餌を与える文の関係が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42726, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家禽が毎朝確かめます。", "corrected_sentence": "家禽を毎朝確かめます。", "error_description": "誤りは「家禽が」。「確かめる」の目的語は「家禽を」で示す。「家禽が」だと家禽が確かめる主体になり、確かめられる対象が消えて文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42727, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「家禽を数千羽も飼う」の目的語を示す「を」。飼う対象として家禽がここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「家禽が」では家禽が主語になり、飼う人の動作が消えて文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「家禽に」では家禽が相手になり、数千羽を飼う目的語として働かない。"}, {"text": "で", "is_correct": false, "explanation": "「家禽で」は手段や場所を表し、飼う対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「家禽を数千羽も飼う」の目的語を示す「を」。飼う対象として家禽がここに入る。", "が": "「家禽が」では家禽が主語になり、飼う人の動作が消えて文が崩れる。", "に": "「家禽に」では家禽が相手になり、数千羽を飼う目的語として働かない。", "で": "「家禽で」は手段や場所を表し、飼う対象を示せないので合わない。"}, "error_tags": {"が": "主語の誤り", "に": "相手・場所の誤り", "で": "手段・場所の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42727, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「家禽の卵」の所属を示す「の」。家禽から取れる卵、という意味で入る。"}, {"text": "が", "is_correct": false, "explanation": "「家禽が卵は」では家禽が主語になり、後の「栄養が豊富」との関係が崩れて不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「家禽を卵は」では家禽が目的語になり、文の主題「卵は」と噛み合わない。"}, {"text": "に", "is_correct": false, "explanation": "「家禽に卵は」では家禽が相手になり、栄養の説明と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "「家禽の卵」の所属を示す「の」。家禽から取れる卵、という意味で入る。", "が": "「家禽が卵は」では家禽が主語になり、後の「栄養が豊富」との関係が崩れて不自然になる。", "を": "「家禽を卵は」では家禽が目的語になり、文の主題「卵は」と噛み合わない。", "に": "「家禽に卵は」では家禽が相手になり、栄養の説明と結びつかない。"}, "error_tags": {"が": "主語の誤り", "を": "目的語の誤り", "に": "相手・場所の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42727, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "卵や肉を食用にするために飼育される鳥類の総称。ニワトリ、アヒル、七面鳥などが含まれる。", "primary_collocate": null, "pronunciation": "かきん", "ipa": "kakiɴ", "syllable_count": 3, "sentences": [{"text": "家禽の一つであり、人間が管理する家畜として、畜産業界で重要な役割を果たしています。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "家禽[かきん]の一[ひと]つであり、人間[にんげん]が管理[かんり]する家畜[かちく]として、畜産[ちくさん]業界[ぎょうかい]で重要[じゅうよう]な役割[やくわり]を果[は]たしています。", "sentence_source": "mined"}, {"text": "農場では、ニワトリやアヒルなどの家禽を数千羽も飼っています。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "農場[のうじょう]では、ニワトリやアヒルなどの家禽[かきん]を数千羽[すうせんわ]も飼[か]っています。", "sentence_source": "generated"}, {"text": "家禽は野生の鳥と違って、人に育てられるため、人をあまり怖がりません。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "家禽[かきん]は野生[やせい]の鳥[とり]と違[ちが]って、人[ひと]に育[そだ]てられるため、人[ひと]をあまり怖[こわ]がりません。", "sentence_source": "generated"}, {"text": "この地域では、冬になると家禽が病気にかかりやすいので、小屋を暖かくします。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、冬[ふゆ]になると家禽[かきん]が病気[びょうき]にかかりやすいので、小屋[こや]を暖[あたた]かくします。", "sentence_source": "generated"}, {"text": "七面鳥はアメリカで人気のある家禽で、感謝祭の食卓に欠かせません。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "七面鳥[しちめんちょう]はアメリカで人気[にんき]のある家禽[かきん]で、感謝祭[かんしゃさい]の食卓[しょくたく]に欠[か]かせません。", "sentence_source": "generated"}, {"text": "鳥インフルエンザが広がり、家禽を飼う農家は消毒を徹底しています。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "鳥[とり]インフルエンザが広[ひろ]がり、家禽[かきん]を飼[か]う農家[のうか]は消毒[しょうどく]を徹底[てってい]しています。", "sentence_source": "generated"}, {"text": "カモは野生にもいますが、アヒルは人が育てる家禽です。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "カモは野生[やせい]にもいますが、アヒルは人[ひと]が育[そだ]てる家禽[かきん]です。", "sentence_source": "generated"}, {"text": "家禽の卵は栄養が豊富なので、昔から多くの家庭で食べられてきました。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "家禽[かきん]の卵[たまご]は栄養[えいよう]が豊富[ほうふ]なので、昔[むかし]から多[おお]くの家庭[かてい]で食[た]べられてきました。", "sentence_source": "generated"}, {"text": "犬や猫はペットであって、家禽ではありません。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "犬[いぬ]や猫[ねこ]はペットであって、家禽[かきん]ではありません。", "sentence_source": "generated"}, {"text": "祖父の農場では、家禽の世話をするのが私の毎朝の仕事でした。", "target_word": "家禽", "complexity_tier": "T3", "furigana": "祖父[そふ]の農場[のうじょう]では、家禽[かきん]の世話[せわ]をするのが私[わたし]の毎朝[まいあさ]の仕事[しごと]でした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家禽", "label": "基本形"}], "register": "中立（やや書き言葉）", "sense_fingerprint": "食用の卵や肉を得るために人が飼う鳥類の総称（ニワトリ・アヒル・七面鳥など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42727, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家禽", "is_correct": true, "explanation": "「家禽の一つであり、人間が管理する家畜として」で、食用の卵や肉のために飼う鳥類の総称として入る。"}, {"text": "野鳥", "is_correct": false, "explanation": "野鳥は野生の鳥で、人間が管理する家畜とは両立せず文が矛盾する。"}, {"text": "猛禽", "is_correct": false, "explanation": "猛禽は肉食の鳥類で、人間が管理する家畜として位置づける文と矛盾する。"}, {"text": "渡り鳥", "is_correct": false, "explanation": "渡り鳥は季節に移動する野生の鳥で、人間が管理する家畜とは矛盾する。"}], "explanations": {"家禽": "「家禽の一つであり、人間が管理する家畜として」で、食用の卵や肉のために飼う鳥類の総称として入る。", "野鳥": "野鳥は野生の鳥で、人間が管理する家畜とは両立せず文が矛盾する。", "猛禽": "猛禽は肉食の鳥類で、人間が管理する家畜として位置づける文と矛盾する。", "渡り鳥": "渡り鳥は季節に移動する野生の鳥で、人間が管理する家畜とは矛盾する。"}, "sentence_index": 0, "correct_answer": "家禽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牛や豚は、人間が管理する家禽だ。", "explanation": "ここは〈家畜〉の意味。家禽は食用に飼う鳥類に限るので、牛や豚には使わないので誤り。"}, {"text": "うさぎは室内で楽しむ家禽として人気がある。", "explanation": "ここは〈ペット〉の意味。うさぎは鳥でも食用の鳥でもないので、家禽とは呼ばないので誤り。"}, {"text": "ペンギンは泳ぐ家禽として知られる。", "explanation": "ここは〈野生の鳥〉の意味。家禽は人が食用に育てる鳥に限るので、野生のペンギンには使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42727, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家禽", "is_correct": true, "explanation": "「アヒルは人が育てる家禽です」で、食用に育てられる鳥類を指す語として入る。"}, {"text": "雀", "is_correct": false, "explanation": "雀は野生の小鳥で、人が食用に育てるものとは矛盾するので文が合わない。"}, {"text": "鷲", "is_correct": false, "explanation": "鷲は猛禽で、人が食用に育てる家禽とは性質が合わず矛盾する。"}, {"text": "鶯", "is_correct": false, "explanation": "鶯は鳴き声で知られる野鳥で、食用に育てる家禽とは矛盾する。"}], "explanations": {"家禽": "「アヒルは人が育てる家禽です」で、食用に育てられる鳥類を指す語として入る。", "雀": "雀は野生の小鳥で、人が食用に育てるものとは矛盾するので文が合わない。", "鷲": "鷲は猛禽で、人が食用に育てる家禽とは性質が合わず矛盾する。", "鶯": "鶯は鳴き声で知られる野鳥で、食用に育てる家禽とは矛盾する。"}, "sentence_index": 6, "correct_answer": "家禽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "魚市場では、新鮮な家禽が朝早くから競り落とされる。", "explanation": "ここは〈水産物〉の意味。魚市場で扱うのは魚介類で、鳥の家禽とは言わないので誤り。"}, {"text": "畑では、野菜や果物などの家禽を育てている。", "explanation": "ここは〈農作物〉の意味。野菜や果物は農作物で、鳥の家禽とは言わないので誤り。"}, {"text": "猟師は山で家禽を追って、一日中歩いた。", "explanation": "ここは〈獲物〉の意味。猟で追うのは野生の獲物で、人が食用に育てる家禽は猟の対象ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42727, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鶏舎では、アヒルなどの家禽に数百羽も飼っています。", "corrected_sentence": "鶏舎では、アヒルなどの家禽を数百羽も飼っています。", "error_description": "誤りは「家禽に」。「飼う」の目的語は「を」で示す。「に」だと家禽が飼われる相手のように読め、数百羽を飼う文が成り立たないので「を」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42727, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "養鶏場では、家禽が毎朝数えます。", "corrected_sentence": "養鶏場では、家禽を毎朝数えます。", "error_description": "誤りは「家禽が」。「数える」の目的語は「家禽を」で示す。「家禽が」だと家禽が数える主体になり、数えられる対象が消えて文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42730, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "形容詞「悪い」の主語を示す「が」。「天候が悪い」で文意が通る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語の格で、形容詞「悪い」の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示し、「天候に悪い」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、主語の役割を果たさない。"}], "correct_answer": "が", "explanations": {"が": "形容詞「悪い」の主語を示す「が」。「天候が悪い」で文意が通る。", "を": "「を」は目的語の格で、形容詞「悪い」の主語にはならない。", "に": "「に」は相手や場所を示し、「天候に悪い」は成立しない。", "で": "「で」は手段や場所を示し、主語の役割を果たさない。"}, "error_tags": {"を": "目的語", "に": "相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42730, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」の目的語を示す「を」。「天候を調べる」で文意が通る。"}, {"text": "に", "is_correct": false, "explanation": "「調べる」の対象には「に」を使わず、「天候に調べる」は成立しない。"}, {"text": "が", "is_correct": false, "explanation": "「調べる」は他動詞で目的語を取るため、「が」では文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「調べる」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」の目的語を示す「を」。「天候を調べる」で文意が通る。", "に": "「調べる」の対象には「に」を使わず、「天候に調べる」は成立しない。", "が": "「調べる」は他動詞で目的語を取るため、「が」では文が成立しない。", "で": "「で」は手段や場所を示し、「調べる」の目的語にはならない。"}, "error_tags": {"に": "対象", "が": "主語", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42730, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空のようすや、気温や風のこと。", "primary_collocate": null, "pronunciation": "てんこう", "ipa": "teŋkoː", "syllable_count": 4, "sentences": [{"text": "山の天候は変わりやすいので、雨具を持って行こう。", "target_word": "天候", "complexity_tier": "T3", "furigana": "やまのてんこうはかわりやすいので、あまぐをもっていこう。", "sentence_source": "generated"}, {"text": "天候が悪くて、船は港を出なかった。", "target_word": "天候", "complexity_tier": "T3", "furigana": "てんこうがわるくて、ふねはみなとをでなかった。", "sentence_source": "generated"}, {"text": "今日は天候に恵まれ、運動会が無事に終わった。", "target_word": "天候", "complexity_tier": "T3", "furigana": "きょうはてんこうにめぐまれ、うんどうかいがぶじにおわった。", "sentence_source": "generated"}, {"text": "天候が回復するまで、飛行機は飛ばないそうだ。", "target_word": "天候", "complexity_tier": "T3", "furigana": "てんこうがかいふくするまで、ひこうきはとばないそうだ。", "sentence_source": "generated"}, {"text": "農家の人は、天候を見ながら作物の世話をする。", "target_word": "天候", "complexity_tier": "T3", "furigana": "のうかのひとは、てんこうをみながらさくもつのせわをする。", "sentence_source": "generated"}, {"text": "旅行中の天候は、晴れたりくもったりだった。", "target_word": "天候", "complexity_tier": "T3", "furigana": "りょこうちゅうのてんこうは、はれたりくもったりだった。", "sentence_source": "generated"}, {"text": "急に天候が崩れて、私たちは近くの小屋に逃げ込んだ。", "target_word": "天候", "complexity_tier": "T3", "furigana": "きゅうにてんこうがくずれて、わたしたちはちかくのこやににげこんだ。", "sentence_source": "generated"}, {"text": "海の天候を調べてから、釣りに出かけた。", "target_word": "天候", "complexity_tier": "T3", "furigana": "うみのてんこうをしらべてから、つりにでかけた。", "sentence_source": "generated"}, {"text": "今年は天候が不順で、野菜の値段が上がっている。", "target_word": "天候", "complexity_tier": "T3", "furigana": "ことしはてんこうがふじゅんで、やさいのねだんがあがっている。", "sentence_source": "generated"}, {"text": "天候のせいで、花見の予定を一週間のばした。", "target_word": "天候", "complexity_tier": "T3", "furigana": "てんこうのせいで、はなみのよていをいっしゅうかんのばした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "天候", "label": "基本形"}], "register": "標準", "sense_fingerprint": "空の様子や気温、風などの天気の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42730, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天候", "is_correct": true, "explanation": "山の空模様や気温の状態を表し、変わりやすいという文に合う。"}, {"text": "規則", "is_correct": false, "explanation": "「規則」は決まりを指し、「変わりやすい」とつながらない。"}, {"text": "予算", "is_correct": false, "explanation": "「予算」は金額の計画で、山の様子を表す文には合わない。"}, {"text": "行事", "is_correct": false, "explanation": "「行事」は催しを指し、山の状態の描写には使えない。"}], "explanations": {"天候": "山の空模様や気温の状態を表し、変わりやすいという文に合う。", "規則": "「規則」は決まりを指し、「変わりやすい」とつながらない。", "予算": "「予算」は金額の計画で、山の様子を表す文には合わない。", "行事": "「行事」は催しを指し、山の状態の描写には使えない。"}, "sentence_index": 0, "correct_answer": "天候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の天候が長引いて、結論が出なかった。", "explanation": "「状況」の意味と取り違えている。「天候」は空や気温の状態で、会議の進み具合には使わない。"}, {"text": "彼女は天候に恵まれ、どんな難しい料理も作れる。", "explanation": "料理の腕前には「天候」を使わない。「才能」などの語が合う。"}, {"text": "試験の天候が三日後に決まるそうだ。", "explanation": "「日程」の意味と取り違えている。試験の日程に「天候」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42730, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天候", "is_correct": true, "explanation": "急に空模様が崩れたという文脈に合い、小屋に逃げ込む理由になる。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹が崩れる」は意味をなさず、文脈に合わない。"}, {"text": "返事", "is_correct": false, "explanation": "「返事が崩れる」は不自然で、急な出来事の描写に合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "「旋律」は音楽の要素で、崩れる対象として文脈に合わない。"}], "explanations": {"天候": "急に空模様が崩れたという文脈に合い、小屋に逃げ込む理由になる。", "空腹": "「空腹が崩れる」は意味をなさず、文脈に合わない。", "返事": "「返事が崩れる」は不自然で、急な出来事の描写に合わない。", "旋律": "「旋律」は音楽の要素で、崩れる対象として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "天候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の天候は穏やかで、誰とも争わない。", "explanation": "「性格」の意味と取り違えている。「天候」は空模様や気温の状態で、人の性格には使わない。"}, {"text": "この店は天候のよい味で、いつも客が並ぶ。", "explanation": "味の評価には「天候」を使わない。「美味」などの語が合う。"}, {"text": "この大学は天候の評判が高く、受験者が多い。", "explanation": "「名声」の意味と取り違えている。「天候」は空や気温の状態で、学校の評価には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42730, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天候を悪いので、船は港を出なかった。", "corrected_sentence": "天候が悪いので、船は港を出なかった。", "error_description": "「天候が悪い」の主語は「が」で示す。「を」は目的語の格で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42730, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急に天候を崩れて、私たちは小屋に逃げ込んだ。", "corrected_sentence": "急に天候が崩れて、私たちは小屋に逃げ込んだ。", "error_description": "「崩れる」は自動詞で、主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
