INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42731, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「天候の記録」の「の」で、名詞同士をつなぐ。文脈に合う。"}, {"text": "が", "is_correct": false, "explanation": "「天候が記録を見る」は文として成立せず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「天候に記録を見る」は成立せず、場所や相手の意味も合わない。"}, {"text": "で", "is_correct": false, "explanation": "「天候で記録を見る」は手段の意味が成立せず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「天候の記録」の「の」で、名詞同士をつなぐ。文脈に合う。", "が": "「天候が記録を見る」は文として成立せず、不自然。", "に": "「天候に記録を見る」は成立せず、場所や相手の意味も合わない。", "で": "「天候で記録を見る」は手段の意味が成立せず、不自然。"}, "error_tags": {"が": "主語", "に": "場所", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42731, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所や時間の、気温や雨・風などの状態。", "primary_collocate": null, "pronunciation": "てんこう", "ipa": "teŋkoː", "syllable_count": 4, "sentences": [{"text": "北海道の冬は、天候が厳しく、雪の日が多い。", "target_word": "天候", "complexity_tier": "T3", "furigana": "ほっかいどうのふゆは、てんこうがきびしく、ゆきのひがおおい。", "sentence_source": "generated"}, {"text": "試合の日の天候は、気温が低く、風も強かった。", "target_word": "天候", "complexity_tier": "T3", "furigana": "しあいのひのてんこうは、きおんがひくく、かぜもつよかった。", "sentence_source": "generated"}, {"text": "同じ季節でも、地域によって天候は大きく違う。", "target_word": "天候", "complexity_tier": "T3", "furigana": "おなじきせつでも、ちいきによっててんこうはおおきくちがう。", "sentence_source": "generated"}, {"text": "出発の時刻の天候によって、ツアーを中止する場合がある。", "target_word": "天候", "complexity_tier": "T3", "furigana": "しゅっぱつのじこくのてんこうによって、つあーをちゅうしするばあいがある。", "sentence_source": "generated"}, {"text": "今朝の天候は穏やかで、風もほとんどなかった。", "target_word": "天候", "complexity_tier": "T3", "furigana": "けさのてんこうはおだやかで、かぜもほとんどなかった。", "sentence_source": "generated"}, {"text": "天候が荒れた夜、港の漁師たちは船を守った。", "target_word": "天候", "complexity_tier": "T3", "furigana": "てんこうがあれたよる、みなとのりょうしたちはふねをまもった。", "sentence_source": "generated"}, {"text": "山の上と町では、天候がまったく違うことがある。", "target_word": "天候", "complexity_tier": "T3", "furigana": "やまのうえとまちでは、てんこうがまったくちがうことがある。", "sentence_source": "generated"}, {"text": "天候の記録を見ると、去年の夏は雨が少なかった。", "target_word": "天候", "complexity_tier": "T3", "furigana": "てんこうのきろくをみると、きょねんのなつはあめがすくなかった。", "sentence_source": "generated"}, {"text": "この島は一年を通して天候が安定している。", "target_word": "天候", "complexity_tier": "T3", "furigana": "このしまはいちねんをとおしててんこうがあんていしている。", "sentence_source": "generated"}, {"text": "雪や風などの天候に合わせて、道路の工事が止まった。", "target_word": "天候", "complexity_tier": "T3", "furigana": "ゆきやかぜなどのてんこうにあわせて、どうろのこうじがとまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "天候", "label": "基本形"}], "register": "標準", "sense_fingerprint": "ある場所や時間における気温・雨・風などの状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42731, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天候", "is_correct": true, "explanation": "冬の気温や雪などの状態を表し、「厳しく」と合う。"}, {"text": "眼鏡", "is_correct": false, "explanation": "「眼鏡が厳しく」は意味をなさず、天候の描写には合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "「辞書」は書籍で、冬の状態を表す文には使えない。"}, {"text": "食卓", "is_correct": false, "explanation": "「食卓」は家具や食事の場で、「厳しく」とは結びつかない。"}], "explanations": {"天候": "冬の気温や雪などの状態を表し、「厳しく」と合う。", "眼鏡": "「眼鏡が厳しく」は意味をなさず、天候の描写には合わない。", "辞書": "「辞書」は書籍で、冬の状態を表す文には使えない。", "食卓": "「食卓」は家具や食事の場で、「厳しく」とは結びつかない。"}, "sentence_index": 0, "correct_answer": "天候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の天候が長引いて、結論が出なかった。", "explanation": "「状況」の意味と取り違えている。「天候」は空や気温の状態で、会議の進み具合には使わない。"}, {"text": "彼女の天候は明るく、いつも周りを元気づける。", "explanation": "「性格」や「雰囲気」の意味と取り違えている。「天候」は場所や時間の気温・雨風の状態を表すので、人の明るさには使わない。"}, {"text": "この料理は天候が濃く、少しずつ味わいたい。", "explanation": "味の濃さには「天候」を使わない。「濃厚」などが合う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42731, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天候", "is_correct": true, "explanation": "山の上と町で空模様や気温が違うという文に合う。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息」は眠っている時の呼吸で、場所による違いを表す文には合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "「旋律」は音楽の要素で、山と町の違いを表す文には使えない。"}, {"text": "紅茶", "is_correct": false, "explanation": "「紅茶」は飲み物で、山と町の状態の違いを表す文には合わない。"}], "explanations": {"天候": "山の上と町で空模様や気温が違うという文に合う。", "寝息": "「寝息」は眠っている時の呼吸で、場所による違いを表す文には合わない。", "旋律": "「旋律」は音楽の要素で、山と町の違いを表す文には使えない。", "紅茶": "「紅茶」は飲み物で、山と町の状態の違いを表す文には合わない。"}, "sentence_index": 6, "correct_answer": "天候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この映画を見て、天候が高ぶった。", "explanation": "「感情」の意味と取り違えている。「天候」は空や気温の状態を表す語で、気持ちの高ぶりには使わない。"}, {"text": "この計画は天候が三つの段階に分かれている。", "explanation": "「過程」の意味と取り違えている。計画の進み方には「天候」を使わない。"}, {"text": "彼は天候の高い技術で、ピアノ演奏を披露した。", "explanation": "「腕前」の意味と取り違えている。「天候」は空や気温の状態で、演奏の腕前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42731, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北海道の春は、天候を穏やかで、雪の日が少ない。", "corrected_sentence": "北海道の春は、天候が穏やかで、雪の日が少ない。", "error_description": "「穏やかだ」の主語は「が」で示す。「を」は目的語の格で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42731, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の島では、天候をまったく安定している。", "corrected_sentence": "夏の島では、天候がまったく安定している。", "error_description": "「安定している」の主語は「が」で示す。「を」は目的語の格で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42744, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「猫の飼育には」の「に」で、飼育についての話題であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「猫の飼育を毎日の世話が大切」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「猫の飼育へ毎日の世話が大切」は意味が通らない。"}, {"text": "や", "is_correct": false, "explanation": "並列を表すが、「猫の飼育やは」と「は」が続かず不自然。"}], "correct_answer": "に", "explanations": {"に": "「猫の飼育には」の「に」で、飼育についての話題であることを示す。", "を": "「猫の飼育を毎日の世話が大切」は文として成り立たない。", "へ": "方向を表すが、「猫の飼育へ毎日の世話が大切」は意味が通らない。", "や": "並列を表すが、「猫の飼育やは」と「は」が続かず不自然。"}, "error_tags": {"を": "object", "へ": "direction", "や": "coordinate"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42744, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「飼育をしている」の「を」で、「する」の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「飼育がしている」は主語にならず、不自然な形になる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、「飼育でしている」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や資格を表すが、「飼育としている」は文の流れに合わない。"}], "correct_answer": "を", "explanations": {"を": "「飼育をしている」の「を」で、「する」の対象を示す。", "が": "「飼育がしている」は主語にならず、不自然な形になる。", "で": "手段や場所を表すが、「飼育でしている」は意味が通らない。", "と": "並列や資格を表すが、「飼育としている」は文の流れに合わない。"}, "error_tags": {"が": "subject", "で": "means", "と": "and"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42744, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "動物や生き物に食べ物をあげて、大きくなるのを助けること。", "primary_collocate": null, "pronunciation": "しいく", "ipa": "ɕiikɯ", "syllable_count": 3, "sentences": [{"text": "私は小学生のとき、メダカの飼育をしました。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "私[わたし]は小学生[しょうがくせい]のとき、メダカの飼育[しいく]をしました。", "sentence_source": "generated"}, {"text": "猫の飼育には、毎日の世話が大切です。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "猫[ねこ]の飼育[しいく]には、毎日[まいにち]の世話[せわ]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "このマンションでは、犬の飼育が禁止されています。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "このマンションでは、犬[いぬ]の飼育[しいく]が禁止[きんし]されています。", "sentence_source": "generated"}, {"text": "兄は熱帯魚の飼育が趣味で、水槽を三つ持っています。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "兄[あに]は熱帯魚[ねったいぎょ]の飼育[しいく]が趣味[しゅみ]で、水槽[すいそう]を三[みっ]つ持[も]っています。", "sentence_source": "generated"}, {"text": "カメの飼育は思ったより簡単で、餌も少しで足ります。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "カメの飼育[しいく]は思[おも]ったより簡単[かんたん]で、餌[えさ]も少[すこ]しで足[た]ります。", "sentence_source": "generated"}, {"text": "動物の飼育を通して、命の大切さを学びました。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の飼育[しいく]を通[とお]して、命[いのち]の大切[たいせつ]さを学[まな]びました。", "sentence_source": "generated"}, {"text": "ハムスターの飼育では、毎日決まった時間に餌をあげることが大切です。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "ハムスターの飼育[しいく]では、毎日[まいにち]決まった[きまった]時間[じかん]に餌[えさ]をあげることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "牛の飼育をしている祖父は、毎朝早く起きます。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "牛[うし]の飼育[しいく]をしている祖父[そふ]は、毎朝[まいあさ]早[はや]く起[お]きます。", "sentence_source": "generated"}, {"text": "クラスでカブトムシを飼育することになりました。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "クラスでカブトムシを飼育[しいく]することになりました。", "sentence_source": "generated"}, {"text": "初めての飼育なので、本を読んで勉強しています。", "target_word": "飼育", "complexity_tier": "T3", "furigana": "初[はじ]めての飼育[しいく]なので、本[ほん]を読[よ]んで勉強[べんきょう]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飼育", "label": "基本形"}, {"form": "飼育する", "label": "サ変動詞形"}], "register": "丁寧", "sense_fingerprint": "生き物に餌を与えて成長を助けること（飼育）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55130f35-71de-4368-abd1-621d34d03e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42744, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飼育", "is_correct": true, "explanation": "動物を育てる意味で、メダカを育てた経験を述べる文に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すこと。メダカには使えず、文に合わない。"}, {"text": "醸造", "is_correct": false, "explanation": "酒や醤油を発酵させて造ること。生き物の世話には使わない。"}, {"text": "製造", "is_correct": false, "explanation": "工場で製品を作ること。生き物には使えず「メダカの製造」は不自然。"}], "explanations": {"飼育": "動物を育てる意味で、メダカを育てた経験を述べる文に合う。", "採掘": "地下の資源を掘り出すこと。メダカには使えず、文に合わない。", "醸造": "酒や醤油を発酵させて造ること。生き物の世話には使わない。", "製造": "工場で製品を作ること。生き物には使えず「メダカの製造」は不自然。"}, "sentence_index": 0, "correct_answer": "飼育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は庭でバラの飼育を楽しんでいます。", "explanation": "ここは〈栽培〉の意味。植物を育てるのは〈栽培〉で、〈飼育〉は動物にだけ使うので合わない。"}, {"text": "会社は若手社員の飼育を重視しています。", "explanation": "ここは〈育成〉の意味。人材を育てるのは〈育成〉で、〈飼育〉は人には使わないので合わない。"}, {"text": "彼は木製の家具を飼育しています。", "explanation": "ここは〈製作〉の意味。家具や道具は〈製作〉で作るもので、〈飼育〉は生き物に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42744, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飼育", "is_correct": true, "explanation": "動物を世話して育てる意味で、ハムスターに毎日餌をあげる文脈に合う。"}, {"text": "培養", "is_correct": false, "explanation": "細胞や細菌を増やすこと。ハムスターには使えず、文に合わない。"}, {"text": "運用", "is_correct": false, "explanation": "制度やシステムを動かして使うこと。ハムスターには当てはまらない。"}, {"text": "製菓", "is_correct": false, "explanation": "菓子を作ること。生き物の世話には使わず、文に合わない。"}], "explanations": {"飼育": "動物を世話して育てる意味で、ハムスターに毎日餌をあげる文脈に合う。", "培養": "細胞や細菌を増やすこと。ハムスターには使えず、文に合わない。", "運用": "制度やシステムを動かして使うこと。ハムスターには当てはまらない。", "製菓": "菓子を作ること。生き物の世話には使わず、文に合わない。"}, "sentence_index": 6, "correct_answer": "飼育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この施設では、酵母の飼育を毎日行っています。", "explanation": "ここは〈培養〉の意味。微生物を増やすのは〈培養〉で、〈飼育〉は動物を世話する語なので合わない。"}, {"text": "この店では、ケーキの飼育を朝から続けています。", "explanation": "ここは〈製菓〉の意味。菓子は〈製菓〉で作るもので、〈飼育〉は生き物に使うので合わない。"}, {"text": "このチームでは、業務システムの飼育を任されています。", "explanation": "ここは〈運用〉の意味。業務システムは〈運用〉で動かすもので、〈飼育〉は使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42744, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は会社を辞めて、ヤギの飼育を専念しています。", "corrected_sentence": "父は会社を辞めて、ヤギの飼育に専念しています。", "error_description": "「専念する」は「に」を取るので、飼育の後の「を」は誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42744, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この牧場では、毎日牛の飼育を作っています。", "corrected_sentence": "この牧場では、毎日牛の飼育を行っています。", "error_description": "「飼育を行う」が正しい組み合わせ。「作る」は飼育と結びつかないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b443ac78-82b3-4c83-a73e-2eade64a010b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42753, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示し、「肉を目的に飼われる鶏です」と説明する文の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すため、説明文の主語にはならない。「鶏です」の主語として置くと不自然。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示すため、説明文の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、説明文の主語にはならない。文の意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "主題を示し、「肉を目的に飼われる鶏です」と説明する文の主語になる。", "を": "目的語を表すため、説明文の主語にはならない。「鶏です」の主語として置くと不自然。", "に": "方向や相手を示すため、説明文の主語にはならない。", "から": "起点を示すため、説明文の主語にはならない。文の意味が通らない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42753, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ブロイラーのもも肉」の所有・修飾を表し、もも肉の種類を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、「もも肉を焼いて食べました」の主語にするのは不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すため、ブロイラーともも肉を修飾関係でつなぐことができない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、もも肉を修飾する語にはならない。"}], "correct_answer": "の", "explanations": {"の": "「ブロイラーのもも肉」の所有・修飾を表し、もも肉の種類を示す。", "が": "主語を表すが、「もも肉を焼いて食べました」の主語にするのは不自然。", "で": "手段や場所を表すため、ブロイラーともも肉を修飾関係でつなぐことができない。", "へ": "方向を表すため、もも肉を修飾する語にはならない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42753, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "肉を食べるために育てられるにわとりのこと。", "primary_collocate": null, "pronunciation": "ぶろいらー", "ipa": "bɯɾoiɾaː", "syllable_count": 5, "sentences": [{"text": "父は養鶏場で、ブロイラーを育てる仕事をしています。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "父(ちち)は養鶏場(ようけいじょう)で、ブロイラーを育(そだ)てる仕事(しごと)をしています。", "sentence_source": "generated"}, {"text": "ブロイラーは、卵ではなく肉を目的に飼われる鶏です。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "ブロイラーは、卵(たまご)ではなく肉(にく)を目的(もくてき)に飼(か)われる鶏(にわとり)です。", "sentence_source": "generated"}, {"text": "市場には、よく太ったブロイラーが並んでいました。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "市場(いちば)には、よく太(ふと)ったブロイラーが並(なら)んでいました。", "sentence_source": "generated"}, {"text": "昔は卵用の鶏が多かったですが、今はブロイラーのほうが増えました。", "target_word": "ブロイラー", "complexity_tier": "T4", "furigana": "昔(むかし)は卵用(たまごよう)の鶏(にわとり)が多(おお)かったですが、今(いま)はブロイラーのほうが増(ふ)えました。", "sentence_source": "generated"}, {"text": "ブロイラーの餌には、とうもろこしがたくさん使われます。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "ブロイラーの餌(えさ)には、とうもろこしがたくさん使(つか)われます。", "sentence_source": "generated"}, {"text": "このレストランでは、ブロイラーではなく地鶏を使っています。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "このレストランでは、ブロイラーではなく地鶏(じどり)を使(つか)っています。", "sentence_source": "generated"}, {"text": "ブロイラーは大きくなるのが早く、飼育にかかる費用が安いです。", "target_word": "ブロイラー", "complexity_tier": "T4", "furigana": "ブロイラーは大(おお)きくなるのが早(はや)く、飼育(しいく)にかかる費用(ひよう)が安(やす)いです。", "sentence_source": "generated"}, {"text": "夕食に、ブロイラーのもも肉を焼いて食べました。", "target_word": "ブロイラー", "complexity_tier": "T2", "furigana": "夕食(ゆうしょく)に、ブロイラーのもも肉(にく)を焼(や)いて食(た)べました。", "sentence_source": "generated"}, {"text": "見学した農場では、白い羽のブロイラーが広い小屋にいました。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "見学(けんがく)した農場(のうじょう)では、白(しろ)い羽(はね)のブロイラーが広(ひろ)い小屋(こや)にいました。", "sentence_source": "generated"}, {"text": "病気を防ぐため、ブロイラーの小屋は毎日きれいに掃除します。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "病気(びょうき)を防(ふせ)ぐため、ブロイラーの小屋(こや)は毎日(まいにち)きれいに掃除(そうじ)します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブロイラー", "label": "基本形"}], "register": "中立（です・ます体）", "sense_fingerprint": "卵用ではなく肉用に育てられる鶏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42753, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブロイラー", "is_correct": true, "explanation": "父が養鶏場で育てる、肉用の鶏を指す語で、文の内容と一致する。"}, {"text": "機械", "is_correct": false, "explanation": "作業に使う機械で、育てる対象ではない。文の意味が通らない。"}, {"text": "鶏舎", "is_correct": false, "explanation": "鶏を入れる建物で、育てる対象ではない。文の意味が通らない。"}, {"text": "農具", "is_correct": false, "explanation": "農作業に使う道具で、育てる対象ではない。文の意味が通らない。"}], "explanations": {"ブロイラー": "父が養鶏場で育てる、肉用の鶏を指す語で、文の内容と一致する。", "機械": "作業に使う機械で、育てる対象ではない。文の意味が通らない。", "鶏舎": "鶏を入れる建物で、育てる対象ではない。文の意味が通らない。", "農具": "農作業に使う道具で、育てる対象ではない。文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "ブロイラー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ブロイラーは毎日卵を産むので、一年以上飼われます。", "explanation": "ここは〈採卵鶏〉の意味。ブロイラーは肉を目的に育てる鶏で、卵を産ませる用途とは合わない。"}, {"text": "ブロイラーはゆっくり育つので、味が濃いのが特徴です。", "explanation": "ここは〈地鶏〉の意味。ブロイラーは短期間で育つよう改良された鶏で、ゆっくり育つという説明とは合わない。"}, {"text": "ブロイラーは、美しい羽や鳴き声を楽しむために飼われます。", "explanation": "ここは〈観賞用の鳥〉の意味。ブロイラーは肉を食べるために育てる鶏なので、羽や鳴き声を楽しむ目的とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42753, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブロイラー", "is_correct": true, "explanation": "大きくなるのが早く、飼育費用が安い鶏を指す語で、文の内容と一致する。"}, {"text": "卵", "is_correct": false, "explanation": "産まれるものであって、大きくなるのが早く飼育費用が安いという説明の主語にはならない。"}, {"text": "牧草", "is_correct": false, "explanation": "家畜の餌になる草で、大きくなるのが早い鶏ではない。文の内容に合わない。"}, {"text": "農機", "is_correct": false, "explanation": "農作業の機械で、飼育される生き物ではない。文の意味が通らない。"}], "explanations": {"ブロイラー": "大きくなるのが早く、飼育費用が安い鶏を指す語で、文の内容と一致する。", "卵": "産まれるものであって、大きくなるのが早く飼育費用が安いという説明の主語にはならない。", "牧草": "家畜の餌になる草で、大きくなるのが早い鶏ではない。文の内容に合わない。", "農機": "農作業の機械で、飼育される生き物ではない。文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "ブロイラー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブロイラーは年を取ってかたくなったので、長く煮込んでスープにします。", "explanation": "ここは〈老鶏〉の意味。ブロイラーは若いうちに出荷する鶏なので、年を取って身がかたくなった鶏の使い方とは合わない。"}, {"text": "ブロイラーには、ニワトリやアヒルなどが含まれます。", "explanation": "ここは〈家禽〉の意味。ブロイラーは食肉用の鶏の一種を指すので、アヒルなどを含む総称としては合わない。"}, {"text": "ブロイラーは、ほかの鶏と闘わせるために毎日訓練します。", "explanation": "ここは〈闘鶏〉の意味。ブロイラーは食肉のために育てる鶏で、闘わせるために訓練する鶏とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42753, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ブロイラーで肉は、やわらかくて料理に向いています。", "corrected_sentence": "ブロイラーの肉は、やわらかくて料理に向いています。", "error_description": "「ブロイラー」と「肉」の間には所有・修飾の「の」が必要。「で」は手段や場所を表すので、「ブロイラーで肉」は成り立たない。正しくは「ブロイラーの肉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42753, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鶏舎では、ブロイラーに毎日たくさん出荷しています。", "corrected_sentence": "鶏舎では、ブロイラーを毎日たくさん出荷しています。", "error_description": "「出荷する」は目的語に「を」をとる。「に」にすると「ブロイラーに出荷する」となり不自然。正しくは「ブロイラーを出荷」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42754, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42754, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示し、ブロイラーが昔の鶏と比べて大きな体重になったという文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すが、「なりました」の文に目的語として置くと、文の構造が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、ここでは主語にあたる語の位置に置くと意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「体重になりました」の対象として方向を示す語ではない。"}], "correct_answer": "は", "explanations": {"は": "主題を示し、ブロイラーが昔の鶏と比べて大きな体重になったという文の主題になる。", "を": "目的語を表すが、「なりました」の文に目的語として置くと、文の構造が成り立たない。", "で": "手段や場所を表すが、ここでは主語にあたる語の位置に置くと意味が通らない。", "へ": "方向を表すが、「体重になりました」の対象として方向を示す語ではない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42754, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食用に飼育される若鶏。特に、短期間で大きく成長するように品種改良された鶏。", "primary_collocate": null, "pronunciation": "ぶろいらー", "ipa": "bɯɾoiɾaː", "syllable_count": 5, "sentences": [{"text": "ブロイラーは、食肉を得るために改良された鶏の品種です。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "ブロイラーは、食肉(しょくにく)を得(え)るために改良(かいりょう)された鶏(にわとり)の品種(ひんしゅ)です。", "sentence_source": "mined"}, {"text": "日本のスーパーで売られている鶏肉の多くは、ブロイラーです。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "日本(にほん)のスーパーで売(う)られている鶏肉(とりにく)の多(おお)くは、ブロイラーです。", "sentence_source": "generated"}, {"text": "ブロイラーは成長が早いので、短い期間で出荷できます。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "ブロイラーは成長(せいちょう)が早(はや)いので、短(みじか)い期間(きかん)で出荷(しゅっか)できます。", "sentence_source": "generated"}, {"text": "この農場では、ブロイラーを一度に何万羽も飼育しています。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "この農場(のうじょう)では、ブロイラーを一度(いちど)に何万羽(なんまんわ)も飼育(しいく)しています。", "sentence_source": "generated"}, {"text": "ブロイラーは普通の地鶏より安く売られますが、肉はやわらかいです。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "ブロイラーは普通(ふつう)の地鶏(じどり)より安(やす)く売(う)られますが、肉(にく)はやわらかいです。", "sentence_source": "generated"}, {"text": "ブロイラーのひなは、約二か月で食用の大きさに育ちます。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "ブロイラーのひなは、約(やく)二(に)か月(げつ)で食用(しょくよう)の大(おお)きさに育(そだ)ちます。", "sentence_source": "generated"}, {"text": "卵を産ませるための鶏と違って、ブロイラーは肉を取るために育てます。", "target_word": "ブロイラー", "complexity_tier": "T4", "furigana": "卵(たまご)を産(う)ませるための鶏(にわとり)と違(ちが)って、ブロイラーは肉(にく)を取(と)るために育(そだ)てます。", "sentence_source": "generated"}, {"text": "品種改良の結果、ブロイラーは昔の鶏の倍以上の体重になりました。", "target_word": "ブロイラー", "complexity_tier": "T4", "furigana": "品種(ひんしゅ)改良(かいりょう)の結果(けっか)、ブロイラーは昔(むかし)の鶏(にわとり)の倍(ばい)以上(いじょう)の体重(たいじゅう)になりました。", "sentence_source": "generated"}, {"text": "鶏舎で大量に育てられるブロイラーの飼い方が、問題になっています。", "target_word": "ブロイラー", "complexity_tier": "T4", "furigana": "鶏舎(けいしゃ)で大量(たいりょう)に育(そだ)てられるブロイラーの飼(か)い方(かた)が、問題(もんだい)になっています。", "sentence_source": "generated"}, {"text": "唐揚げ店で使われる鶏肉は、ほとんどがブロイラーです。", "target_word": "ブロイラー", "complexity_tier": "T3", "furigana": "唐揚(からあ)げ店(てん)で使(つか)われる鶏肉(とりにく)は、ほとんどがブロイラーです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブロイラー", "label": "基本形"}], "register": "中立（です・ます体）", "sense_fingerprint": "短期間で育つよう品種改良された食肉用の若鶏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブロイラー", "is_correct": true, "explanation": "食肉を得るために改良された鶏の品種を指す語で、文の内容と一致する。"}, {"text": "採卵鶏", "is_correct": false, "explanation": "卵を得るために飼う鶏で、食肉のために改良された品種ではないので、文の内容と矛盾する。"}, {"text": "文鳥", "is_correct": false, "explanation": "小型の観賞用の鳥で、鶏の品種ではない。食肉の品種という説明に合わない。"}, {"text": "錦鯉", "is_correct": false, "explanation": "観賞用の魚で、鶏ではない。食肉を得るための品種という文脈に合わない。"}], "explanations": {"ブロイラー": "食肉を得るために改良された鶏の品種を指す語で、文の内容と一致する。", "採卵鶏": "卵を得るために飼う鶏で、食肉のために改良された品種ではないので、文の内容と矛盾する。", "文鳥": "小型の観賞用の鳥で、鶏の品種ではない。食肉の品種という説明に合わない。", "錦鯉": "観賞用の魚で、鶏ではない。食肉を得るための品種という文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ブロイラー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この農場では、ブロイラーをじっくり時間をかけて一羽ずつ育てています。", "explanation": "ここは〈地鶏〉の意味。ブロイラーは短期間で大量に育てる鶏なので、じっくり一羽ずつ育てるという使い方は合わない。"}, {"text": "この卵は、毎日卵を産むブロイラーから取れたものです。", "explanation": "ここは〈採卵鶏〉の意味。ブロイラーは肉を取るための鶏で、卵を産ませる目的では飼わないので合わない。"}, {"text": "この薬膳店では、ブロイラーの黒い骨を煮出してスープにします。", "explanation": "ここは〈烏骨鶏〉の意味。ブロイラーは食用に育てる鶏で、黒い骨を持つ烏骨鶏の特徴とは合わないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブロイラー", "is_correct": true, "explanation": "卵を産ませる鶏と対比して、肉を取るために育てる鶏を指す語で、文の内容と一致する。"}, {"text": "飼料", "is_correct": false, "explanation": "家畜に与える餌で、肉を取るために育てる対象ではない。文の主語にはならない。"}, {"text": "養鶏場", "is_correct": false, "explanation": "鶏を飼う施設で、肉を取るために育てられる対象ではない。"}, {"text": "卵", "is_correct": false, "explanation": "産まれるものであって、育てて肉を取る対象ではない。文の内容に合わない。"}], "explanations": {"ブロイラー": "卵を産ませる鶏と対比して、肉を取るために育てる鶏を指す語で、文の内容と一致する。", "飼料": "家畜に与える餌で、肉を取るために育てる対象ではない。文の主語にはならない。", "養鶏場": "鶏を飼う施設で、肉を取るために育てられる対象ではない。", "卵": "産まれるものであって、育てて肉を取る対象ではない。文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "ブロイラー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブロイラーは身がかたいので、スープにして長く煮込みます。", "explanation": "ここは〈老鶏〉の意味。ブロイラーは若いうちに出荷される鶏なので、身がかたい年を取った鶏の使い方とは合わない。"}, {"text": "ブロイラーには、ニワトリやアヒルなどが含まれます。", "explanation": "ここは〈家禽〉の意味。ブロイラーは食肉用の鶏の一種を指すので、アヒルなどを含む総称としては合わない。"}, {"text": "ブロイラーは、闘わせるために体を鍛えて育てられる鶏です。", "explanation": "ここは〈闘鶏〉の意味。ブロイラーは食用に育てる鶏で、闘わせるために鍛える鶏ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は、ブロイラーが育てる農家で働いています。", "corrected_sentence": "私は、ブロイラーを育てる農家で働いています。", "error_description": "「育てる」の目的語には「を」が必要。「が」にすると、ブロイラーが育てる主体になり、文の意味が成り立たない。正しくは「ブロイラーを育てる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "養鶏場では、ブロイラーで肉用に育てています。", "corrected_sentence": "養鶏場では、ブロイラーを肉用に育てています。", "error_description": "「育てる」の目的語には「を」を使う。「で」は手段や場所を表すので、「ブロイラーで肉用に育てる」は不自然。正しくは「ブロイラーを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42774, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「育む」は生き物を直接の対象にとるので、対象を示す「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「生き物が育む」は目的語がなく、文が完結しない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を表す。「生き物の育む」では動詞につながらず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表す。「生き物より育む」では対象を示せず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「育む」は生き物を直接の対象にとるので、対象を示す「を」が正しい。", "が": "「生き物が育む」は目的語がなく、文が完結しない。", "の": "「の」は所属や修飾を表す。「生き物の育む」では動詞につながらず、文が成り立たない。", "より": "「より」は比較や起点を表す。「生き物より育む」では対象を示せず、不自然。"}, "error_tags": {"が": "主語の格", "の": "所属・修飾", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42774, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「育んでいる」の対象は「春の芽」なので、対象を示す「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」では「春の芽に育んでいる」となり、直接の対象が示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「春の芽へ育んでいる」では対象になれず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表す。「春の芽と育んでいる」では対象関係が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「育んでいる」の対象は「春の芽」なので、対象を示す「を」が正しい。", "に": "「に」では「春の芽に育んでいる」となり、直接の対象が示せず不自然。", "へ": "「へ」は方向を表す。「春の芽へ育んでいる」では対象になれず、文が成り立たない。", "と": "「と」は相手や並列を表す。「春の芽と育んでいる」では対象関係が成り立たない。"}, "error_tags": {"に": "位置・帰着", "へ": "方向", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42774, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "愛情や環境によって、生き物や子どもを大切に育てて大きくしたり、心や関係を大切に育てて成長させたりすること。", "primary_collocate": null, "pronunciation": "はぐくむ", "ipa": "haɡɯkɯmɯ", "syllable_count": 4, "sentences": [{"text": "親は愛情をこめて子どもを育む。", "target_word": "育む", "complexity_tier": "T3", "furigana": "親[おや]は愛情[あいじょう]をこめて子[こ]どもを育[はぐく]む。", "sentence_source": "generated"}, {"text": "豊かな自然が、多くの生き物を育む。", "target_word": "育む", "complexity_tier": "T3", "furigana": "豊[ゆた]かな自然[しぜん]が、多[おお]くの生[い]き物[もの]を育[はぐく]む。", "sentence_source": "generated"}, {"text": "この学校は、子どもの想像力を育む教育をしている。", "target_word": "育む", "complexity_tier": "T3", "furigana": "この学校[がっこう]は、子[こ]どもの想像力[そうぞうりょく]を育[はぐく]む教育[きょういく]をしている。", "sentence_source": "generated"}, {"text": "長い時間をかけて、二人は友情を育んだ。", "target_word": "育んだ", "complexity_tier": "T3", "furigana": "長[なが]い時間[じかん]をかけて、二人[ふたり]は友情[ゆうじょう]を育[はぐく]んだ。", "sentence_source": "generated"}, {"text": "川の水は、田んぼの稲を育んできた。", "target_word": "育んで", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は、田[た]んぼの稲[いね]を育[はぐく]んできた。", "sentence_source": "generated"}, {"text": "祖母は、花を一つ一つ大切に育んでいる。", "target_word": "育んで", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、花[はな]を一[ひと]つ一[ひと]つ大切[たいせつ]に育[はぐく]んでいる。", "sentence_source": "generated"}, {"text": "地域の人々が、子どもたちを育む場所をつくった。", "target_word": "育む", "complexity_tier": "T3", "furigana": "地域[ちいき]の人々[ひとびと]が、子[こ]どもたちを育[はぐく]む場所[ばしょ]をつくった。", "sentence_source": "generated"}, {"text": "暖かい土が、春の芽を育んでいる。", "target_word": "育んで", "complexity_tier": "T3", "furigana": "暖[あたた]かい土[つち]が、春[はる]の芽[め]を育[はぐく]んでいる。", "sentence_source": "generated"}, {"text": "毎日の会話が、家族の信頼を育む。", "target_word": "育む", "complexity_tier": "T3", "furigana": "毎日[まいにち]の会話[かいわ]が、家族[かぞく]の信頼[しんらい]を育[はぐく]む。", "sentence_source": "generated"}, {"text": "本を読む習慣は、心を育むと言われる。", "target_word": "育む", "complexity_tier": "T3", "furigana": "本[ほん]を読[よ]む習慣[しゅうかん]は、心[こころ]を育[はぐく]むと言[い]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "育む", "label": "辞書形"}, {"form": "育んだ", "label": "過去形"}, {"form": "育んで", "label": "て形"}, {"form": "育まない", "label": "否定形"}, {"form": "育みます", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "愛情や環境によって、子どもや生き物、心などを大切に育てて成長させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8104bb-358f-42db-9a79-a76080280153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42774, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漬ける", "is_correct": false, "explanation": "「子どもを漬ける」とは言わない。漬けるのは食べ物などで、子どもには使わない。"}, {"text": "育む", "is_correct": true, "explanation": "愛情をこめて子どもを大切に成長させる文なので、「子どもを育む」が入る。"}, {"text": "干す", "is_correct": false, "explanation": "干すのは洗濯物や食材などで、子どもを対象にはしないので合わない。"}, {"text": "注ぐ", "is_correct": false, "explanation": "注ぐのは液体などを対象にする動詞で、「子どもを注ぐ」は成り立たない。"}], "explanations": {"漬ける": "「子どもを漬ける」とは言わない。漬けるのは食べ物などで、子どもには使わない。", "育む": "愛情をこめて子どもを大切に成長させる文なので、「子どもを育む」が入る。", "干す": "干すのは洗濯物や食材などで、子どもを対象にはしないので合わない。", "注ぐ": "注ぐのは液体などを対象にする動詞で、「子どもを注ぐ」は成り立たない。"}, "sentence_index": 0, "correct_answer": "育む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼らは長い時間をかけて、大きな橋を育んだ。", "explanation": "育むは生き物や心を育てる語で、橋を作る意味では使わない。"}, {"text": "長い時間をかけて、店は商品の値段を育んだ。", "explanation": "育むは生き物や心を育てる語で、値段を上げる意味では使わない。"}, {"text": "長い時間をかけて、二人は試合を育んだ。", "explanation": "育むは生き物や心を育てる語で、試合を行う意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42774, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮る", "is_correct": false, "explanation": "煮るのは食べ物などを対象にする動詞で、「子どもたちを煮る場所」とは言わない。"}, {"text": "織る", "is_correct": false, "explanation": "織るは布などを作る動詞で、子どもたちを対象にはしないので合わない。"}, {"text": "育む", "is_correct": true, "explanation": "子どもたちを大切に育てる場所という意味になり、「子どもたちを育む場所」が入る。"}, {"text": "焦がす", "is_correct": false, "explanation": "焦がすのは食材などを熱で変色させる動詞で、子どもたちには使わないので合わない。"}], "explanations": {"煮る": "煮るのは食べ物などを対象にする動詞で、「子どもたちを煮る場所」とは言わない。", "織る": "織るは布などを作る動詞で、子どもたちを対象にはしないので合わない。", "育む": "子どもたちを大切に育てる場所という意味になり、「子どもたちを育む場所」が入る。", "焦がす": "焦がすのは食材などを熱で変色させる動詞で、子どもたちには使わないので合わない。"}, "sentence_index": 6, "correct_answer": "育む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の職人は、新しい機械を育んだ。", "explanation": "育むは生き物や心を育てる語で、機械を組み立てる意味では使わない。"}, {"text": "町の人々は、古い建物を育んでいる。", "explanation": "育むは生き物や心を育てる語で、建物を建てる意味では使わない。"}, {"text": "母は毎朝、おいしい料理を育んでいる。", "explanation": "育むは生き物や心を育てる語で、料理を用意する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42774, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "親は愛情をこめて子どもを育むでいる。", "corrected_sentence": "親は愛情をこめて子どもを育んでいる。", "error_description": "「育む」のて形は「育んで」。「育むで」は活用が誤っていて、「〜でいる」に続く正しい形は「育んで」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "育む", "is_correct": true, "explanation": "文末で現在の動作や性質を述べる辞書形で、anchor文の形と一致する。"}, {"text": "育んで", "is_correct": false, "explanation": "て形で、文末に置くと文が終わらず、述語として成り立たない。"}, {"text": "育まれる", "is_correct": false, "explanation": "受身形では「を」が残らないため、「多くの生き物を育まれる」は成り立たない。"}, {"text": "育め", "is_correct": false, "explanation": "命令形で、「豊かな自然が」を主語にすると命令文になり、文が成り立たない。"}], "correct_form": "育む", "base_form": "育む", "form_label": "辞書形", "sentence_index": 1, "explanations": {"育む": "文末で現在の動作や性質を述べる辞書形で、anchor文の形と一致する。", "育んで": "て形で、文末に置くと文が終わらず、述語として成り立たない。", "育まれる": "受身形では「を」が残らないため、「多くの生き物を育まれる」は成り立たない。", "育め": "命令形で、「豊かな自然が」を主語にすると命令文になり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42774, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人々が、子どもたちに育む場所をつくった。", "corrected_sentence": "町の人々が、子どもたちを育む場所をつくった。", "error_description": "「育む」は子どもたちを目的語にとるので、対象を示す「を」が正しい。「に」では「子どもたちに育む」となり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "育む", "is_correct": false, "explanation": "辞書形で、「育んでいる」の「育んで」の位置に入れると「育むいる」となり不自然。"}, {"text": "育まれる", "is_correct": false, "explanation": "受身形では「を」が残らないため、「春の芽を育まれている」は成り立たない。"}, {"text": "育もう", "is_correct": false, "explanation": "意志形で、「〜ている」と続かず、文の述語として合わない。"}, {"text": "育んで", "is_correct": true, "explanation": "て形で、「育んでいる」の形で進行を表し、anchor文の形と一致する。"}], "correct_form": "育んで", "base_form": "育む", "form_label": "て形", "sentence_index": 7, "explanations": {"育む": "辞書形で、「育んでいる」の「育んで」の位置に入れると「育むいる」となり不自然。", "育まれる": "受身形では「を」が残らないため、「春の芽を育まれている」は成り立たない。", "育もう": "意志形で、「〜ている」と続かず、文の述語として合わない。", "育んで": "て形で、「育んでいる」の形で進行を表し、anchor文の形と一致する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42801, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「雛が生まれます」と、雛を主語として示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「生まれます」は自動詞なので目的語の「を」は取らず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」は「雛で生まれる」とならず、文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「雛へ生まれる」とならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「雛が生まれます」と、雛を主語として示す格助詞。", "を": "「生まれます」は自動詞なので目的語の「を」は取らず、文が成り立たない。", "で": "場所・手段の「で」は「雛で生まれる」とならず、文が不自然になる。", "へ": "方向の「へ」は「雛へ生まれる」とならず、文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42801, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「あたためている」の対象を示す「を」で、雛が温められる対象になる。"}, {"text": "が", "is_correct": false, "explanation": "「雛が、親鳥が体で」と主語が二つになり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」は「雛で」とならず、文の構造に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「雛へあたためる」とならず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「あたためている」の対象を示す「を」で、雛が温められる対象になる。", "が": "「雛が、親鳥が体で」と主語が二つになり、文が成り立たない。", "で": "場所・手段の「で」は「雛で」とならず、文の構造に合わない。", "へ": "方向の「へ」は「雛へあたためる」とならず、不自然。"}, "error_tags": {"が": "主語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42801, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ちいさなとりのこども。", "primary_collocate": null, "pronunciation": "ひな", "ipa": "çina", "syllable_count": 2, "sentences": [{"text": "巣の中で、雛が親鳥の帰りを待っています。", "target_word": "雛", "complexity_tier": "T3", "furigana": "巣[す]の中[なか]で、雛[ひな]が親鳥[おやどり]の帰[かえ]りを待[ま]っています。", "sentence_source": "generated"}, {"text": "春になると、つばめの雛が生まれます。", "target_word": "雛", "complexity_tier": "T3", "furigana": "春[はる]になると、つばめの雛[ひな]が生[う]まれます。", "sentence_source": "generated"}, {"text": "雛はまだ小さいので、猫に見つからないか心配だ。", "target_word": "雛", "complexity_tier": "T3", "furigana": "雛[ひな]はまだ小[ちい]さいので、猫[ねこ]に見[み]つからないか心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "親鳥は雛に虫をくわえて運んできた。", "target_word": "雛", "complexity_tier": "T3", "furigana": "親鳥[おやどり]は雛[ひな]に虫[むし]をくわえて運[はこ]んできた。", "sentence_source": "generated"}, {"text": "木の上の巣から、雛の鳴き声が聞こえる。", "target_word": "雛", "complexity_tier": "T3", "furigana": "木[き]の上[うえ]の巣[す]から、雛[ひな]の鳴[な]き声[ごえ]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "雛が大きくなって、ようやく空を飛べるようになった。", "target_word": "雛", "complexity_tier": "T3", "furigana": "雛[ひな]が大[おお]きくなって、ようやく空[そら]を飛[と]べるようになった。", "sentence_source": "generated"}, {"text": "公園で落ちていた雛を見つけ、そっと巣に戻した。", "target_word": "雛", "complexity_tier": "T3", "furigana": "公園[こうえん]で落[お]ちていた雛[ひな]を見[み]つけ、そっと巣[す]に戻[もど]した。", "sentence_source": "generated"}, {"text": "羽がまだ生えていない雛を、親鳥が体であたためている。", "target_word": "雛", "complexity_tier": "T3", "furigana": "羽[はね]がまだ生[は]えていない雛[ひな]を、親鳥[おやどり]が体[からだ]であたためている。", "sentence_source": "generated"}, {"text": "毎朝、庭の巣をのぞいて雛の様子を見ている。", "target_word": "雛", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、庭[にわ]の巣[す]をのぞいて雛[ひな]の様子[ようす]を見[み]ている。", "sentence_source": "generated"}, {"text": "三羽の雛が、口を大きく開けてえさを待っていた。", "target_word": "雛", "complexity_tier": "T3", "furigana": "三羽[さんわ]の雛[ひな]が、口[くち]を大[おお]きく開[あ]けてえさを待[ま]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雛", "label": "基本形"}, {"form": "雛たち", "label": "複数形"}], "register": "中立", "sense_fingerprint": "巣の中にいる、まだ小さな鳥の子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42801, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雛", "is_correct": true, "explanation": "巣で親鳥を待つ、まだ小さな鳥の子を指し、文に合う。"}, {"text": "羽", "is_correct": false, "explanation": "羽は親鳥の帰りを待つ主体にならず、文が成り立たない。"}, {"text": "枝", "is_correct": false, "explanation": "枝は意思を持って待つものではなく、ここには合わない。"}, {"text": "葉", "is_correct": false, "explanation": "葉は親鳥の帰りを待つ主語にならず、文が不自然になる。"}], "explanations": {"雛": "巣で親鳥を待つ、まだ小さな鳥の子を指し、文に合う。", "羽": "羽は親鳥の帰りを待つ主体にならず、文が成り立たない。", "枝": "枝は意思を持って待つものではなく、ここには合わない。", "葉": "葉は親鳥の帰りを待つ主語にならず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "雛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園で、雛が母親の手を引いて歩いている。", "explanation": "ここは〈幼児〉の意味。雛は鳥の子に使う語で、人の子どもには使えない。"}, {"text": "木の中で雛が羽化するまで、じっと待つ。", "explanation": "ここは〈幼虫〉の意味。羽化は虫の変態で、鳥の雛には使えない。"}, {"text": "冷蔵庫に雛を入れておく。", "explanation": "ここは〈卵〉の意味。生きた鳥の子を冷蔵庫に入れる文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42801, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雛", "is_correct": true, "explanation": "落ちていた小鳥の子を巣に戻すという文脈に合う。"}, {"text": "靴", "is_correct": false, "explanation": "靴は巣に戻すものではなく、文脈に合わない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵を巣に戻すという文は意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は巣に戻す対象ではなく、ここでは合わない。"}], "explanations": {"雛": "落ちていた小鳥の子を巣に戻すという文脈に合う。", "靴": "靴は巣に戻すものではなく、文脈に合わない。", "鍵": "鍵を巣に戻すという文は意味が通らない。", "手紙": "手紙は巣に戻す対象ではなく、ここでは合わない。"}, "sentence_index": 6, "correct_answer": "雛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雛は、生まれてしばらくミルクで育つ。", "explanation": "ここは〈子猫〉の意味。ミルクで育つのは哺乳類の子で、鳥の雛には合わない。"}, {"text": "花壇に雛を三つ植えて、毎朝水をやる。", "explanation": "ここは〈苗〉の意味。雛は鳥の子で、植物のように植える対象にはならない。"}, {"text": "雛は、飼い主が帰ると尻尾を振って迎える。", "explanation": "ここは〈子犬〉の意味。尻尾を振って飼い主を迎えるのは犬の仕草で、鳥の雛には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42801, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜になると、雛を巣の中で静かに眠ります。", "corrected_sentence": "夜になると、雛は巣の中で静かに眠ります。", "error_description": "「眠ります」は自動詞で目的語を取らないため「を」は誤り。雛が主語なので正しくは「は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42801, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "親鳥は雛が守り、雨の日も巣から離れない。", "corrected_sentence": "親鳥は雛を守り、雨の日も巣から離れない。", "error_description": "「守る」の目的語なので「を」が正しい。「が」は主語を示すため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42802, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「雛は」で話題を示し、「黄色くてふわふわです」と説明する。"}, {"text": "を", "is_correct": false, "explanation": "「雛を黄色くて」は目的語にならず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「雛に黄色くて」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「雛で黄色くて」は手段にならず、不自然。"}], "correct_answer": "は", "explanations": {"は": "「雛は」で話題を示し、「黄色くてふわふわです」と説明する。", "を": "「雛を黄色くて」は目的語にならず、不自然。", "に": "「雛に黄色くて」は成り立たない。", "で": "「雛で黄色くて」は手段にならず、不自然。"}, "error_tags": {"を": "目的語", "に": "帰着・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
