INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42802, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "雛（ひな）は、鳥の子ども、特ににわとりの子どものことです。", "primary_collocate": null, "pronunciation": "ひな", "ipa": "çina", "syllable_count": 2, "sentences": [{"text": "農場で、にわとりの雛が生まれました。", "target_word": "雛", "complexity_tier": "T3", "furigana": "農場[のうじょう]で、にわとりの雛[ひな]が生[う]まれました。", "sentence_source": "generated"}, {"text": "卵からかえったばかりの雛は、黄色くてふわふわです。", "target_word": "雛", "complexity_tier": "T3", "furigana": "卵[たまご]からかえったばかりの雛[ひな]は、黄色[きいろ]くてふわふわです。", "sentence_source": "generated"}, {"text": "この小屋では、百羽の雛を育てています。", "target_word": "雛", "complexity_tier": "T3", "furigana": "この小屋[こや]では、百羽[ひゃっぱ]の雛[ひな]を育[そだ]てています。", "sentence_source": "generated"}, {"text": "雛は寒さに弱いので、ライトであたためます。", "target_word": "雛", "complexity_tier": "T3", "furigana": "雛[ひな]は寒[さむ]さに弱[よわ]いので、ライトであたためます。", "sentence_source": "generated"}, {"text": "雛が大きくなると、卵を産むようになる。", "target_word": "雛", "complexity_tier": "T3", "furigana": "雛[ひな]が大[おお]きくなると、卵[たまご]を産[う]むようになる。", "sentence_source": "generated"}, {"text": "母鳥は羽の下に雛を入れて守っていた。", "target_word": "雛", "complexity_tier": "T3", "furigana": "母鳥[ははどり]は羽[はね]の下[した]に雛[ひな]を入[い]れて守[まも]っていた。", "sentence_source": "generated"}, {"text": "ゆうべ生まれた雛に、細かい餌をあげました。", "target_word": "雛", "complexity_tier": "T3", "furigana": "ゆうべ生[う]まれた雛[ひな]に、細[こま]かい餌[えさ]をあげました。", "sentence_source": "generated"}, {"text": "農家の人は、毎日雛の数を数えている。", "target_word": "雛", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は、毎日[まいにち]雛[ひな]の数[かず]を数[かぞ]えている。", "sentence_source": "generated"}, {"text": "にわとりの雛は、生まれてすぐに歩くことができる。", "target_word": "雛", "complexity_tier": "T3", "furigana": "にわとりの雛[ひな]は、生[う]まれてすぐに歩[ある]くことができる。", "sentence_source": "generated"}, {"text": "子どもたちは、小さな雛をそっと手にのせた。", "target_word": "雛", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、小[ちい]さな雛[ひな]をそっと手[て]にのせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雛", "label": "基本形"}, {"form": "雛たち", "label": "複数形"}], "register": "中立", "sense_fingerprint": "にわとりなど飼われている鳥の子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42802, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雛", "is_correct": true, "explanation": "にわとりの子を指し、「にわとりの雛が生まれました」と自然につながる。"}, {"text": "子牛", "is_correct": false, "explanation": "にわとりの子は子牛ではなく、文が成り立たない。"}, {"text": "子犬", "is_correct": false, "explanation": "にわとりの子に子犬は使わず、文が合わない。"}, {"text": "子猫", "is_correct": false, "explanation": "にわとりの子に子猫は使わず、文が合わない。"}], "explanations": {"雛": "にわとりの子を指し、「にわとりの雛が生まれました」と自然につながる。", "子牛": "にわとりの子は子牛ではなく、文が成り立たない。", "子犬": "にわとりの子に子犬は使わず、文が合わない。", "子猫": "にわとりの子に子猫は使わず、文が合わない。"}, "sentence_index": 0, "correct_answer": "雛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園で、雛が母親と手をつないで歩いている。", "explanation": "ここは〈幼児〉の意味。雛は鳥の子に使う語なので、人間の子どもには使えない。"}, {"text": "雛は冷蔵庫に入れて保存する。", "explanation": "ここは〈卵〉の意味。生きた雛を冷蔵庫で保存する文は成り立たない。"}, {"text": "雛は、飼い主の帰りを玄関で吠えて待つ。", "explanation": "ここは〈子犬〉の意味。吠えて飼い主を待つのは犬の行動で、雛は鳴くが吠えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42802, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雛", "is_correct": true, "explanation": "ゆうべ生まれた鳥の子に餌をやる文脈に合う。"}, {"text": "花", "is_correct": false, "explanation": "花は餌をあげる対象ではなく、文が成り立たない。"}, {"text": "卵", "is_correct": false, "explanation": "卵には餌をあげないので、文脈に合わない。"}, {"text": "苗木", "is_correct": false, "explanation": "苗木に細かい餌をあげるという文は不自然。"}], "explanations": {"雛": "ゆうべ生まれた鳥の子に餌をやる文脈に合う。", "花": "花は餌をあげる対象ではなく、文が成り立たない。", "卵": "卵には餌をあげないので、文脈に合わない。", "苗木": "苗木に細かい餌をあげるという文は不自然。"}, "sentence_index": 6, "correct_answer": "雛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雛は喉をゴロゴロ鳴らしてなつく。", "explanation": "ここは〈子猫〉の意味。喉をゴロゴロ鳴らしてなつくのは猫の仕草で、鳥の雛には使えない。"}, {"text": "庭の土から雛が出てきた。", "explanation": "ここは〈芽〉の意味。雛は鳥の子で、植物の芽には使わない。"}, {"text": "雛を畑に植えて、水をたっぷりやる。", "explanation": "ここは〈苗〉の意味。雛は植物ではないので、畑に植える対象としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42802, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜は、雛が暖かい部屋で育てます。", "corrected_sentence": "夜は、雛を暖かい部屋で育てます。", "error_description": "「育てます」の目的語なので「を」が正しい。「が」は主語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42802, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは、小さな雛が両手でそっと包んだ。", "corrected_sentence": "子どもたちは、小さな雛を両手でそっと包んだ。", "error_description": "「包んだ」の目的語なので「を」が正しい。「が」だと雛が包む主語になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
