INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42815, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「やりがいを大切にする」の「を」。大切にする対象を表し、文として自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「やりがいが大切にして」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「やりがいへ大切にして」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を表すので、「やりがいと大切にして」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「やりがいを大切にする」の「を」。大切にする対象を表し、文として自然。", "が": "「が」は主語を示すので、「やりがいが大切にして」は成り立たない。", "へ": "「へ」は方向を表すので、「やりがいへ大切にして」は不自然。", "と": "「と」は相手や共同を表すので、「やりがいと大切にして」は意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42815, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに、それをしてよかったと感じること。", "primary_collocate": null, "pronunciation": "やりがい", "ipa": "jaɾiɡai", "syllable_count": 4, "sentences": [{"text": "この仕事は大変ですが、やりがいがあります。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "この仕事(しごと)は大変(たいへん)ですが、やりがいがあります。", "sentence_source": "generated"}, {"text": "子どもの笑顔を見ると、やりがいを感じます。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "子(こ)どもの笑顔(えがお)を見(み)ると、やりがいを感(かん)じます。", "sentence_source": "generated"}, {"text": "やりがいのない仕事は、続けるのがつらいです。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "やりがいのない仕事(しごと)は、続(つづ)けるのがつらいです。", "sentence_source": "generated"}, {"text": "兄は、人を助ける仕事にやりがいを見つけました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "兄(あに)は、人(ひと)を助(たす)ける仕事(しごと)にやりがいを見(み)つけました。", "sentence_source": "generated"}, {"text": "毎日同じ作業ばかりで、やりがいがなくなってきました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "毎日(まいにち)同(おな)じ作業(さぎょう)ばかりで、やりがいがなくなってきました。", "sentence_source": "generated"}, {"text": "先生になって、やりがいのある毎日を送っています。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "先生(せんせい)になって、やりがいのある毎日(まいにち)を送(おく)っています。", "sentence_source": "generated"}, {"text": "ありがとうと言われて、やりがいを感じました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "ありがとうと言(い)われて、やりがいを感(かん)じました。", "sentence_source": "generated"}, {"text": "給料より、やりがいを大切にして仕事を選びたいです。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "給料(きゅうりょう)より、やりがいを大切(たいせつ)にして仕事(しごと)を選(えら)びたいです。", "sentence_source": "generated"}, {"text": "難しい課題ほど、やりがいがあります。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "難(むずか)しい課題(かだい)ほど、やりがいがあります。", "sentence_source": "generated"}, {"text": "彼女は、やりがいのある仕事に出会えて幸せそうです。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は、やりがいのある仕事(しごと)に出会(であ)えて幸(しあわ)せそうです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "やりがい", "label": "基本形（かな表記）"}, {"form": "遣り甲斐", "label": "漢字表記"}], "register": "中立（丁寧体）", "sense_fingerprint": "することに価値があると感じる気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42815, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "やりがい", "is_correct": true, "explanation": "大変な仕事の中にある、してよかったと感じる充実感を表し、「やりがいがあります」と合う。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は寝ている間についた髪の乱れで、仕事の性質としては「あります」とつながらない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は寝ているときに出す言葉で、仕事の状態を表さないので合わない。"}, {"text": "寝相", "is_correct": false, "explanation": "寝相は寝ているときの体の姿勢で、仕事について「あります」とは言えない。"}], "explanations": {"やりがい": "大変な仕事の中にある、してよかったと感じる充実感を表し、「やりがいがあります」と合う。", "寝癖": "寝癖は寝ている間についた髪の乱れで、仕事の性質としては「あります」とつながらない。", "寝言": "寝言は寝ているときに出す言葉で、仕事の状態を表さないので合わない。", "寝相": "寝相は寝ているときの体の姿勢で、仕事について「あります」とは言えない。"}, "sentence_index": 0, "correct_answer": "やりがい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新しい制度から、大きなやりがいを受けています。", "explanation": "ここは〈恩恵〉（ありがたい利益）の意味。やりがいは自分の内側で感じる充実感で、制度から受け取るものではない。"}, {"text": "あの選手は決勝点を決めて、大きなやりがいを立てました。", "explanation": "ここは〈手柄〉（立てた功績）の意味。やりがいは感じるものなので、立てるものではない。"}, {"text": "来年度に向けて、会議の前にやりがいを組みました。", "explanation": "ここは〈予算〉（使うお金の計画）の意味。やりがいは組むものではないので、計画には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42815, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "やりがい", "is_correct": true, "explanation": "感謝された喜びや充実感を表し、「やりがいを感じました」と自然につながる。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格のことで、感じる対象にはならないので合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上面で、感じるものとして使えない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙などを送る仕組みで、感じる対象として使えない。"}], "explanations": {"やりがい": "感謝された喜びや充実感を表し、「やりがいを感じました」と自然につながる。", "値段": "値段は価格のことで、感じる対象にはならないので合わない。", "天井": "天井は部屋の上面で、感じるものとして使えない。", "郵便": "郵便は手紙などを送る仕組みで、感じる対象として使えない。"}, "sentence_index": 6, "correct_answer": "やりがい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作業には、多くの時間と大きなやりがいがかかります。", "explanation": "ここは〈労力〉（使う力や努力）の意味。やりがいは感じるものなので、「かかる」ものではない。"}, {"text": "二人のやりがいが面白くて、つい聞いてしまいます。", "explanation": "ここは〈やりとり〉（互いに言葉を交わすこと）の意味。やりがいは一人の充実感で、会話には使わない。"}, {"text": "リーダーは、重いやりがいを負っています。", "explanation": "ここは〈責任〉（引き受ける務め）の意味。やりがいは感じるもので、負うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42815, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボランティアで子どもに読み聞かせをして、やりがいに得ました。", "corrected_sentence": "ボランティアで子どもに読み聞かせをして、やりがいを得ました。", "error_description": "「得る」は目的語に「を」を取るので、「やりがいを得ました」が正しい。「やりがいに」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42815, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "難しい仕事を終えて、やりがいを感じります。", "corrected_sentence": "難しい仕事を終えて、やりがいを感じました。", "error_description": "「感じました」が正しい。「感じります」は動詞「感じる」の活用の誤りで、過去の「ました」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
