INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42816, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並列を表す「と」。「やりがいと達成感」と並べて言える。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を表すので、「やりがいを達成感で」とは並ばず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「やりがいへ達成感で」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「やりがいに」は文中で働かず、「達成感で胸がいっぱい」と続かないので不自然。"}], "correct_answer": "と", "explanations": {"と": "並列を表す「と」。「やりがいと達成感」と並べて言える。", "を": "「を」は対象を表すので、「やりがいを達成感で」とは並ばず不自然。", "へ": "「へ」は方向を表すので、「やりがいへ達成感で」は成り立たない。", "に": "「やりがいに」は文中で働かず、「達成感で胸がいっぱい」と続かないので不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "に": "与え先"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42816, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "仕事や活動を行うことで得られる、充実感や達成感。努力した結果、価値があったと思えること。", "primary_collocate": null, "pronunciation": "やりがい", "ipa": "jaɾiɡai", "syllable_count": 4, "sentences": [{"text": "一年かけた研究が認められて、努力のやりがいを実感しました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "一年(いちねん)かけた研究(けんきゅう)が認(みと)められて、努力(どりょく)のやりがいを実感(じっかん)しました。", "sentence_source": "generated"}, {"text": "練習は厳しいですが、勝ったときのやりがいは大きいです。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "練習(れんしゅう)は厳(きび)しいですが、勝(か)ったときのやりがいは大(おお)きいです。", "sentence_source": "generated"}, {"text": "完成した橋を見て、長い工事のやりがいを感じました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "完成(かんせい)した橋(はし)を見(み)て、長(なが)い工事(こうじ)のやりがいを感(かん)じました。", "sentence_source": "generated"}, {"text": "夜遅くまで働いた分、やりがいも大きかったです。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "夜遅(よるおそ)くまで働(はたら)いた分(ぶん)、やりがいも大(おお)きかったです。", "sentence_source": "generated"}, {"text": "やりがいを求めて、会社をやめて農業を始めました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "やりがいを求(もと)めて、会社(かいしゃ)をやめて農業(のうぎょう)を始(はじ)めました。", "sentence_source": "generated"}, {"text": "結果が出て、頑張ったやりがいがあったと思いました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "結果(けっか)が出(で)て、頑張(がんば)ったやりがいがあったと思(おも)いました。", "sentence_source": "generated"}, {"text": "このプロジェクトには、時間をかけるだけのやりがいがあります。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "このプロジェクトには、時間(じかん)をかけるだけのやりがいがあります。", "sentence_source": "generated"}, {"text": "努力が実ったとき、やりがいと達成感で胸がいっぱいになりました。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "努力(どりょく)が実(みの)ったとき、やりがいと達成感(たっせいかん)で胸(むね)がいっぱいになりました。", "sentence_source": "generated"}, {"text": "やりがいを感じられる職場で、長く働きたいです。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "やりがいを感(かん)じられる職場(しょくば)で、長(なが)く働(はたら)きたいです。", "sentence_source": "generated"}, {"text": "簡単すぎる仕事では、やりがいは得られません。", "target_word": "やりがい", "complexity_tier": "T3", "furigana": "簡単(かんたん)すぎる仕事(しごと)では、やりがいは得(え)られません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "やりがい", "label": "基本形（かな表記）"}, {"form": "遣り甲斐", "label": "漢字表記"}], "register": "中立（丁寧体）", "sense_fingerprint": "努力の結果として得られる充実感・達成感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42816, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "やりがい", "is_correct": true, "explanation": "努力の結果として得られる充実感を表し、「努力のやりがいを実感しました」と合う。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上面で、努力の結果として実感するものではない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格のことで、実感する対象にはならない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙などを送る仕組みで、実感の対象にはならない。"}], "explanations": {"やりがい": "努力の結果として得られる充実感を表し、「努力のやりがいを実感しました」と合う。", "天井": "天井は部屋の上面で、努力の結果として実感するものではない。", "値段": "値段は価格のことで、実感する対象にはならない。", "郵便": "郵便は手紙などを送る仕組みで、実感の対象にはならない。"}, "sentence_index": 0, "correct_answer": "やりがい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は難しい交渉をまとめて、大きなやりがいを立てました。", "explanation": "ここは〈手柄〉（立てた功績）の意味。やりがいは感じる充実感で、立てるものではない。"}, {"text": "新しい店の開業に向けて、やりがいを組みました。", "explanation": "ここは〈予算〉（お金の配分の計画）の意味。やりがいは組むものではないので合わない。"}, {"text": "子どもたちは、新しい先生にやりがいを寄せています。", "explanation": "ここは〈期待〉（よい結果を望む気持ち）の意味。やりがいは自分で感じるもので、人に寄せるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42816, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "やりがい", "is_correct": true, "explanation": "時間をかけた努力に見合う充実感を表し、「やりがいがあります」と合う。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は寝ている間についた髪の乱れで、「時間をかけるだけの寝癖」とは結びつかない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は寝ているときの発言で、プロジェクトの性質としては合わない。"}, {"text": "寝相", "is_correct": false, "explanation": "寝相は寝ている姿勢のことで、「時間をかけるだけの」物事としては成り立たない。"}], "explanations": {"やりがい": "時間をかけた努力に見合う充実感を表し、「やりがいがあります」と合う。", "寝癖": "寝癖は寝ている間についた髪の乱れで、「時間をかけるだけの寝癖」とは結びつかない。", "寝言": "寝言は寝ているときの発言で、プロジェクトの性質としては合わない。", "寝相": "寝相は寝ている姿勢のことで、「時間をかけるだけの」物事としては成り立たない。"}, "sentence_index": 6, "correct_answer": "やりがい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この大工事には、多くの人のやりがいがかかります。", "explanation": "ここは〈労力〉（使う力や人手）の意味。やりがいは感じるものなので、「かかる」ものではない。"}, {"text": "この川のやりがいを受けて、地域の人々は暮らしています。", "explanation": "ここは〈恩恵〉（ありがたい利益）の意味。やりがいは努力の結果に感じる充実感で、受け取るものではない。"}, {"text": "親は、子どもに対する重いやりがいを負っています。", "explanation": "ここは〈責任〉（引き受ける務め）の意味。やりがいは感じるもので、負うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42816, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地道な練習を続けて、やりがいに味わいました。", "corrected_sentence": "地道な練習を続けて、やりがいを味わいました。", "error_description": "「味わう」は目的語に「を」を取るので、「やりがいを味わいました」が正しい。「やりがいに」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42816, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長い準備を終えて、やりがいを実感するました。", "corrected_sentence": "長い準備を終えて、やりがいを実感しました。", "error_description": "「実感しました」が正しい。「実感するました」は「する」を活用させずに「ました」をつけた誤りで、「実感し」に「ました」をつける必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42834, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「小さな鶏舎があります」と存在の主語を示す。文の意味に合う。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「鶏舎とあります」では成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「鶏舎からあります」では存在を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「鶏舎よりあります」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「小さな鶏舎があります」と存在の主語を示す。文の意味に合う。", "と": "「と」は並列や相手を示すが、「鶏舎とあります」では成り立たない。", "から": "「から」は起点を示すが、「鶏舎からあります」では存在を示せない。", "より": "「より」は比較を示すが、「鶏舎よりあります」では意味が通らない。"}, "error_tags": {"と": "並列・相手", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42834, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「鶏舎のにおい」と所属を示す。「においが強い」に続く文の意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や時点を示すが、「鶏舎ににおいが」では続かない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「鶏舎をにおいが強い」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「鶏舎へにおいが強い」では成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「鶏舎のにおい」と所属を示す。「においが強い」に続く文の意味に合う。", "に": "「に」は場所や時点を示すが、「鶏舎ににおいが」では続かない。", "を": "「を」は目的語を示すが、「鶏舎をにおいが強い」では成り立たない。", "へ": "「へ」は方向を示すが、「鶏舎へにおいが強い」では成り立たない。"}, "error_tags": {"に": "場所・時点", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42834, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "にわとりをかうための家です。", "primary_collocate": null, "pronunciation": "けいしゃ", "ipa": "keːɕa", "syllable_count": 3, "sentences": [{"text": "鶏舎は、にわとりが住む家です。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "鶏舎[けいしゃ]は、にわとりが住[す]む家[いえ]です。", "sentence_source": "generated"}, {"text": "祖父の家の裏に、小さな鶏舎があります。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "祖父[そふ]の家[いえ]の裏[うら]に、小[ちい]さな鶏舎[けいしゃ]があります。", "sentence_source": "generated"}, {"text": "鶏舎の中には、白い鶏が二十羽います。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "鶏舎[けいしゃ]の中[なか]には、白[しろ]い鶏[にわとり]が二十羽[にじゅうわ]います。", "sentence_source": "generated"}, {"text": "夜になると、鶏は鶏舎で眠ります。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "夜[よる]になると、鶏[にわとり]は鶏舎[けいしゃ]で眠[ねむ]ります。", "sentence_source": "generated"}, {"text": "雨の日も、鶏舎の中なら鶏はぬれない。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]も、鶏舎[けいしゃ]の中[なか]なら鶏[にわとり]はぬれない。", "sentence_source": "generated"}, {"text": "朝、鶏舎から大きな鳴き声が聞こえてきた。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "朝[あさ]、鶏舎[けいしゃ]から大[おお]きな鳴[な]き声[ごえ]が聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "兄は木で鶏舎を作って、鶏を飼い始めた。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "兄[あに]は木[き]で鶏舎[けいしゃ]を作[つく]って、鶏[にわとり]を飼[か]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "鶏舎のにおいが強いので、風の日は窓を閉める。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "鶏舎[けいしゃ]のにおいが強[つよ]いので、風[かぜ]の日[ひ]は窓[まど]を閉[し]める。", "sentence_source": "generated"}, {"text": "鶏舎の床に、わらを敷いてあげた。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "鶏舎[けいしゃ]の床[ゆか]に、わらを敷[し]いてあげた。", "sentence_source": "generated"}, {"text": "学校の鶏舎には、当番の生徒が毎日餌を持っていく。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "学校[がっこう]の鶏舎[けいしゃ]には、当番[とうばん]の生徒[せいと]が毎日[まいにち]餌[えさ]を持[も]っていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鶏舎", "label": "基本形"}], "register": "中立", "sense_fingerprint": "にわとりを飼う家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42834, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鶏舎", "is_correct": true, "explanation": "にわとりが住む家を指す。「〜は、にわとりが住む家です」の定義に合う。"}, {"text": "餌箱", "is_correct": false, "explanation": "餌箱は餌を入れる器具で、にわとりが住む家ではない。"}, {"text": "羽毛", "is_correct": false, "explanation": "羽毛は鳥の体の一部や素材で、住む家にはならない。"}, {"text": "農具", "is_correct": false, "explanation": "農具は作業に使う道具で、住む家にはならない。"}], "explanations": {"鶏舎": "にわとりが住む家を指す。「〜は、にわとりが住む家です」の定義に合う。", "餌箱": "餌箱は餌を入れる器具で、にわとりが住む家ではない。", "羽毛": "羽毛は鳥の体の一部や素材で、住む家にはならない。", "農具": "農具は作業に使う道具で、住む家にはならない。"}, "sentence_index": 0, "correct_answer": "鶏舎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜になると、鶏舎は羽を広げて眠ります。", "explanation": "ここは〈鶏〉の意味。羽を広げて眠るのは鳥で、建物の鶏舎は合わない。"}, {"text": "夜になると、鶏舎は従業員を家に帰して、経営を終えます。", "explanation": "ここは〈養鶏場〉の意味。従業員を帰して経営を終えるのは養鶏場で、建物の鶏舎は合わない。"}, {"text": "夜になると、鶏は鶏舎を食べて眠ります。", "explanation": "ここは〈餌〉の意味。鶏が食べるのは餌で、建物の鶏舎は食べられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42834, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鶏舎", "is_correct": true, "explanation": "木で作る建物で、鶏を飼うための施設。文の意味に合う。"}, {"text": "鶏卵", "is_correct": false, "explanation": "鶏卵は鶏が産むもので、木で作る対象にはならない。"}, {"text": "乾草", "is_correct": false, "explanation": "乾草は飼料の一種で、木で作る建物ではない。"}, {"text": "農薬", "is_correct": false, "explanation": "農薬は薬品で、木で作る対象にはならない。"}], "explanations": {"鶏舎": "木で作る建物で、鶏を飼うための施設。文の意味に合う。", "鶏卵": "鶏卵は鶏が産むもので、木で作る対象にはならない。", "乾草": "乾草は飼料の一種で、木で作る建物ではない。", "農薬": "農薬は薬品で、木で作る対象にはならない。"}, "sentence_index": 6, "correct_answer": "鶏舎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校の鶏舎には、当番の生徒が毎朝馬の世話をしに行く。", "explanation": "ここは〈厩舎〉の意味。馬の世話をする場所は厩舎で、鶏を飼う鶏舎は合わない。"}, {"text": "学校の給食では、当番の生徒が毎朝鶏舎を溶いて、スクランブルエッグを作る。", "explanation": "ここは〈卵〉の意味。溶いて料理に使うのは卵で、建物の鶏舎は合わない。"}, {"text": "学校の鶏舎では、当番の生徒が毎日牛を放牧する。", "explanation": "ここは〈牧場〉の意味。牛を放牧するのは牧場で、鶏舎では成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42834, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父の家の裏に、小さな鶏舎を建っています。", "corrected_sentence": "祖父の家の裏に、小さな鶏舎が建っています。", "error_description": "「鶏舎が」の「が」が「を」になっている。「建つ」は「が」を取る自動詞なので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42834, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は木で小さな鶏舎が作って、鶏を飼い始めた。", "corrected_sentence": "兄は木で小さな鶏舎を作って、鶏を飼い始めた。", "error_description": "「鶏舎を作る」の「を」が「が」になっている。「作る」の目的語は「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42835, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「鶏舎の中」と所属・範囲を示す。文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「鶏舎を中は」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「鶏舎に中は」では続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「鶏舎へ中は」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「鶏舎の中」と所属・範囲を示す。文の意味に合う。", "を": "「を」は動作の対象を示すが、「鶏舎を中は」では文が成り立たない。", "に": "「に」は場所や相手を示すが、「鶏舎に中は」では続かない。", "へ": "「へ」は方向を示すが、「鶏舎へ中は」では文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42835, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「鶏舎は」と主題を示す。「広くて風通しがよく」と続く文の意味に合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「鶏舎で広くて」では自然に続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「鶏舎から広くて」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「鶏舎と広くて」では成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「鶏舎は」と主題を示す。「広くて風通しがよく」と続く文の意味に合う。", "で": "「で」は場所や手段を示すが、「鶏舎で広くて」では自然に続かない。", "から": "「から」は起点を示すが、「鶏舎から広くて」では文が成り立たない。", "と": "「と」は並列や相手を示すが、「鶏舎と広くて」では成り立たない。"}, "error_tags": {"で": "場所・手段", "から": "起点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42835, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "にわとりを飼育するための建物や施設。", "primary_collocate": null, "pronunciation": "けいしゃ", "ipa": "keːɕa", "syllable_count": 3, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]け、太陽[たいよう]が農場[のうじょう]を照[て]らし始[はじ]める朝[あさ]、農家[のうか]の男[おとこ]は鶏舎[けいしゃ]へと足[あし]を運[はこ]ぶ。", "sentence_source": "mined"}, {"text": "鶏舎の中は、羽の音と鳴き声でにぎやかだった。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "鶏舎[けいしゃ]の中[なか]は、羽[はね]の音[おと]と鳴[な]き声[ごえ]でにぎやかだった。", "sentence_source": "generated"}, {"text": "冬は寒さを防ぐため、鶏舎に暖房を入れる。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]さを防[ふせ]ぐため、鶏舎[けいしゃ]に暖房[だんぼう]を入[い]れる。", "sentence_source": "generated"}, {"text": "キツネが入らないように、鶏舎の扉をしっかり閉めた。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "キツネが入[はい]らないように、鶏舎[けいしゃ]の扉[とびら]をしっかり閉[し]めた。", "sentence_source": "generated"}, {"text": "卵を集めるために、毎朝鶏舎を見て回る。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "卵[たまご]を集[あつ]めるために、毎朝[まいあさ]鶏舎[けいしゃ]を見[み]て回[まわ]る。", "sentence_source": "generated"}, {"text": "台風が近づいたので、父は鶏舎の屋根を補強した。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいたので、父[ちち]は鶏舎[けいしゃ]の屋根[やね]を補強[ほきょう]した。", "sentence_source": "generated"}, {"text": "鶏舎の掃除を怠ると、病気が広がるおそれがある。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "鶏舎[けいしゃ]の掃除[そうじ]を怠[おこた]ると、病気[びょうき]が広[ひろ]がるおそれがある。", "sentence_source": "generated"}, {"text": "新しい鶏舎は広くて風通しがよく、鶏たちも元気だ。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "新[あたら]しい鶏舎[けいしゃ]は広[ひろ]くて風通[かぜとお]しがよく、鶏[にわとり]たちも元気[げんき]だ。", "sentence_source": "generated"}, {"text": "夕方になると、鶏は自分から鶏舎へ戻ってくる。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]になると、鶏[にわとり]は自分[じぶん]から鶏舎[けいしゃ]へ戻[もど]ってくる。", "sentence_source": "generated"}, {"text": "小学校の見学で、生徒たちは鶏舎の中をのぞいた。", "target_word": "鶏舎", "complexity_tier": "T3", "furigana": "小学校[しょうがっこう]の見学[けんがく]で、生徒[せいと]たちは鶏舎[けいしゃ]の中[なか]をのぞいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鶏舎", "label": "基本形"}], "register": "中立", "sense_fingerprint": "にわとりを飼育するための建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42835, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鶏舎", "is_correct": true, "explanation": "農家が足を運ぶ先となる、鶏を飼う建物。文の意味に合う。"}, {"text": "飼料", "is_correct": false, "explanation": "飼料は鶏に与える餌で、足を運ぶ行き先にはならない。"}, {"text": "鶏卵", "is_correct": false, "explanation": "鶏卵は鶏が産むもので、人が足を運ぶ場所ではない。"}, {"text": "羽毛", "is_correct": false, "explanation": "羽毛は素材で、「へと足を運ぶ」の目的地にはならない。"}], "explanations": {"鶏舎": "農家が足を運ぶ先となる、鶏を飼う建物。文の意味に合う。", "飼料": "飼料は鶏に与える餌で、足を運ぶ行き先にはならない。", "鶏卵": "鶏卵は鶏が産むもので、人が足を運ぶ場所ではない。", "羽毛": "羽毛は素材で、「へと足を運ぶ」の目的地にはならない。"}, "sentence_index": 0, "correct_answer": "鶏舎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝になると、鶏舎が大きな声で鳴いた。", "explanation": "ここは〈鶏〉の意味。鳴くのは鶏で、建物の鶏舎は鳴かないので合わない。"}, {"text": "夕食に、鶏舎を焼いて家族に出した。", "explanation": "ここは〈鶏肉〉の意味。焼いて食卓に出せるのは鶏肉で、建物の鶏舎は食べ物ではないので合わない。"}, {"text": "毎朝、鶏舎を割って、オムレツの材料にしている。", "explanation": "ここは〈鶏卵〉の意味。割って材料にするのは卵で、建物の鶏舎は割れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42835, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鶏舎", "is_correct": true, "explanation": "「〜の掃除を怠る」で掃除の対象になる建物。文の意味に合う。"}, {"text": "乾草", "is_correct": false, "explanation": "乾草は鶏の餌や敷材で、掃除を怠る対象の建物ではない。"}, {"text": "肥料", "is_correct": false, "explanation": "肥料は施す物で、掃除の対象にはならない。"}, {"text": "作物", "is_correct": false, "explanation": "作物は育てるもので、掃除を怠る対象にはならない。"}], "explanations": {"鶏舎": "「〜の掃除を怠る」で掃除の対象になる建物。文の意味に合う。", "乾草": "乾草は鶏の餌や敷材で、掃除を怠る対象の建物ではない。", "肥料": "肥料は施す物で、掃除の対象にはならない。", "作物": "作物は育てるもので、掃除を怠る対象にはならない。"}, "sentence_index": 6, "correct_answer": "鶏舎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小学校の見学で、生徒たちは広大な鶏舎を馬で駆けて回った。", "explanation": "ここは〈牧場〉の意味。馬で駆け回る広さの場所は牧場で、鶏を飼う建物の鶏舎は合わない。"}, {"text": "小学校の見学で、生徒たちは鶏舎を抱いて頭をなでた。", "explanation": "ここは〈鶏〉の意味。抱いてなでられるのは鶏で、建物の鶏舎には合わない。"}, {"text": "小学校の見学で、生徒たちは鶏舎で牛の乳搾りを体験した。", "explanation": "ここは〈牛舎〉の意味。乳搾りは乳牛に対して行うので、鶏舎には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42835, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は裏庭に鶏舎が建てた。", "corrected_sentence": "父は裏庭に鶏舎を建てた。", "error_description": "「鶏舎を建てる」の「を」が「が」になっている。「建てる」は目的語を「を」で示すので、「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42835, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鶏舎に掃除を怠ると、病気がすぐに広がるおそれがある。", "corrected_sentence": "鶏舎の掃除を怠ると、病気がすぐに広がるおそれがある。", "error_description": "「鶏舎の掃除」の「の」が「に」になっている。掃除の対象を示す「の」が正しく、「鶏舎に掃除を怠る」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42837, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不潔", "is_correct": true, "explanation": "『清潔』の対義語。よごれていて衛生的でない状態を表す。"}, {"text": "不要", "is_correct": false, "explanation": "必要がないことを表し、清潔の対義語ではない。"}, {"text": "不安", "is_correct": false, "explanation": "心配な気持ちを表し、よごれの有無とは関係がない。"}, {"text": "不便", "is_correct": false, "explanation": "使いにくいことを表し、清潔とは反対の関係にない。"}], "correct_answer": "不潔", "explanations": {"不潔": "『清潔』の対義語。よごれていて衛生的でない状態を表す。", "不要": "必要がないことを表し、清潔の対義語ではない。", "不安": "心配な気持ちを表し、よごれの有無とは関係がない。", "不便": "使いにくいことを表し、清潔とは反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
