INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42837, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "よごれていないこと。きれいなこと。", "primary_collocate": null, "pronunciation": "せいけつ", "ipa": "seːket͡sɯ", "syllable_count": 4, "sentences": [{"text": "食事の前には、手を清潔にしましょう。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]には、手[て]を清潔[せいけつ]にしましょう。", "sentence_source": "generated"}, {"text": "母はいつも部屋を清潔に保っている。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "母[はは]はいつも部屋[へや]を清潔[せいけつ]に保[たも]っている。", "sentence_source": "generated"}, {"text": "この病院はとても清潔で、安心して入院できる。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "この病院[びょういん]はとても清潔[せいけつ]で、安心[あんしん]して入院[にゅういん]できる。", "sentence_source": "generated"}, {"text": "清潔なタオルで顔をふいた。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "清潔[せいけつ]なタオルで顔[かお]をふいた。", "sentence_source": "generated"}, {"text": "歯をみがいて、体を清潔にしてから寝る。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "歯[は]をみがいて、体[からだ]を清潔[せいけつ]にしてから寝[ね]る。", "sentence_source": "generated"}, {"text": "兄の制服はいつも清潔で、しわもない。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "兄[あに]の制服[せいふく]はいつも清潔[せいけつ]で、しわもない。", "sentence_source": "generated"}, {"text": "よごれた水は飲まないで、清潔な水を飲んでください。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "よごれた水[みず]は飲[の]まないで、清潔[せいけつ]な水[みず]を飲[の]んでください。", "sentence_source": "generated"}, {"text": "台所が清潔だと、料理もおいしく感じる。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "台所[だいどころ]が清潔[せいけつ]だと、料理[りょうり]もおいしく感[かん]じる。", "sentence_source": "generated"}, {"text": "清潔なシーツに替えたので、ぐっすり眠れた。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "清潔[せいけつ]なシーツに替[か]えたので、ぐっすり眠[ねむ]れた。", "sentence_source": "generated"}, {"text": "トイレが清潔なレストランは、安心して入れる。", "target_word": "清潔", "complexity_tier": "T3", "furigana": "トイレが清潔[せいけつ]なレストランは、安心[あんしん]して入[はい]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "清潔だ", "label": "終止形"}, {"form": "清潔な", "label": "連体形"}, {"form": "清潔に", "label": "連用形"}], "register": "標準", "sense_fingerprint": "よごれがなくきれいな状態（身近な基本義）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: みがい (Zipf 1.96)']::text[], '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42837, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清潔", "is_correct": true, "explanation": "『手を清潔にしましょう』の空欄に入る。よごれをなくす意味で、食事の前の衛生に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "『手を頑丈にしましょう』は意味が通らない。頑丈は丈夫さを表す語。"}, {"text": "退屈", "is_correct": false, "explanation": "退屈は気分の状態を表し、手の扱いには使わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "『手を乱暴にしましょう』は衛生の注意として不自然。乱暴は扱いが荒いことを表す。"}], "explanations": {"清潔": "『手を清潔にしましょう』の空欄に入る。よごれをなくす意味で、食事の前の衛生に合う。", "頑丈": "『手を頑丈にしましょう』は意味が通らない。頑丈は丈夫さを表す語。", "退屈": "退屈は気分の状態を表し、手の扱いには使わない。", "乱暴": "『手を乱暴にしましょう』は衛生の注意として不自然。乱暴は扱いが荒いことを表す。"}, "sentence_index": 0, "correct_answer": "清潔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はゲームの腕前が清潔だ。", "explanation": "ここは〈清潔〉の意味ではない。〈清潔〉はよごれのないことで、腕前の良さには〈巧みだ〉を使う。"}, {"text": "彼は答案を清潔に見つめた。", "explanation": "ここは〈じっと〉の意味。じっと見る様子は〈じっと〉で表し、〈清潔〉は汚れのなさに使う。"}, {"text": "清潔な動きで相手の攻撃をかわした。", "explanation": "ここは〈機敏〉の意味。動きのすばやさは〈機敏〉で表し、〈清潔〉は衛生の状態に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42837, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清潔", "is_correct": true, "explanation": "『清潔な水を飲んでください』の空欄に入る。衛生的な水という意味に合う。"}, {"text": "冷静", "is_correct": false, "explanation": "『冷静な水』は意味が通らない。冷静は落ち着いた態度を表す。"}, {"text": "陽気", "is_correct": false, "explanation": "『陽気な水』は意味が通らない。陽気は人や雰囲気の明るさを表す。"}, {"text": "豪快", "is_correct": false, "explanation": "『豪快な水』は意味が通らない。豪快は勢いが大きいことを表す。"}], "explanations": {"清潔": "『清潔な水を飲んでください』の空欄に入る。衛生的な水という意味に合う。", "冷静": "『冷静な水』は意味が通らない。冷静は落ち着いた態度を表す。", "陽気": "『陽気な水』は意味が通らない。陽気は人や雰囲気の明るさを表す。", "豪快": "『豪快な水』は意味が通らない。豪快は勢いが大きいことを表す。"}, "sentence_index": 6, "correct_answer": "清潔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は清潔な値段で評判だ。", "explanation": "ここは〈手頃〉の意味。価格の安さは〈手頃〉で表し、〈清潔〉は衛生の状態に使う。"}, {"text": "清潔な寝息を立てて眠った。", "explanation": "ここは〈安らか〉の意味。寝息の穏やかさは〈安らか〉で表し、〈清潔〉は汚れのなさに使う。"}, {"text": "清潔なスピードで走った。", "explanation": "ここは〈快速〉の意味。速さは〈快速〉で表し、〈清潔〉は速度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42837, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食事の前には、手を清潔で洗いましょう。", "corrected_sentence": "食事の前には、手を清潔に洗いましょう。", "error_description": "『清潔』が動詞『洗う』を修飾する形が誤り。副詞的な連用形『清潔に』が正しく、『清潔で』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42837, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベッドのシーツを清潔なしたら、眠りやすくなった。", "corrected_sentence": "ベッドのシーツを清潔にしたら、眠りやすくなった。", "error_description": "『清潔』は形容動詞なので、『にする』の連用形『清潔に』が正しい。『清潔なした』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42838, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不潔", "is_correct": true, "explanation": "『清潔』の対義語。よごれていて衛生的でない状態を表す。"}, {"text": "不規則", "is_correct": false, "explanation": "決まりがないことを表し、清潔の対義語ではない。"}, {"text": "不健康", "is_correct": false, "explanation": "体の健康が損なわれた状態を表し、よごれの有無とは関係がない。"}, {"text": "不適切", "is_correct": false, "explanation": "ふさわしくないことを表し、清潔の反対語とは言えない。"}], "correct_answer": "不潔", "explanations": {"不潔": "『清潔』の対義語。よごれていて衛生的でない状態を表す。", "不規則": "決まりがないことを表し、清潔の対義語ではない。", "不健康": "体の健康が損なわれた状態を表し、よごれの有無とは関係がない。", "不適切": "ふさわしくないことを表し、清潔の反対語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42838, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不潔", "is_correct": true, "explanation": "『清潔』の対義語。よごれていて衛生的でない状態を表す。"}, {"text": "不穏", "is_correct": false, "explanation": "落ち着かず危険な気配があることを表し、清潔の対義語ではない。"}, {"text": "不親切", "is_correct": false, "explanation": "人への接し方が冷たいことを表し、よごれの有無とは関係がない。"}, {"text": "不作法", "is_correct": false, "explanation": "礼儀に外れた振る舞いを表し、清潔の反対の状態とは言えない。"}], "correct_answer": "不潔", "explanations": {"不潔": "『清潔』の対義語。よごれていて衛生的でない状態を表す。", "不穏": "落ち着かず危険な気配があることを表し、清潔の対義語ではない。", "不親切": "人への接し方が冷たいことを表し、よごれの有無とは関係がない。", "不作法": "礼儀に外れた振る舞いを表し、清潔の反対の状態とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42838, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "汚れがなく、衛生的で美しい状態であること。", "primary_collocate": null, "pronunciation": "せいけつ", "ipa": "seːket͡sɯ", "syllable_count": 4, "sentences": [{"text": "食品工場では、衛生管理のために作業着を清潔に保つことが求められる。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "食品工場[しょくひんこうじょう]では、衛生管理[えいせいかんり]のために作業着[さぎょうぎ]を清潔[せいけつ]に保[たも]つことが求[もと]められる。", "sentence_source": "generated"}, {"text": "清潔な街並みが評判の観光地で、道にごみは一つも落ちていなかった。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "清潔[せいけつ]な街並[まちな]みが評判[ひょうばん]の観光地[かんこうち]で、道[みち]にごみは一[ひと]つも落[お]ちていなかった。", "sentence_source": "generated"}, {"text": "手術室は、常に清潔な状態でなければならない。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "手術室[しゅじゅつしつ]は、常[つね]に清潔[せいけつ]な状態[じょうたい]でなければならない。", "sentence_source": "generated"}, {"text": "彼は髪も服も清潔で、第一印象がとてもよい。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "彼[かれ]は髪[かみ]も服[ふく]も清潔[せいけつ]で、第一印象[だいいちいんしょう]がとてもよい。", "sentence_source": "generated"}, {"text": "宿の部屋は清潔で、窓から見える景色も美しかった。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "宿[やど]の部屋[へや]は清潔[せいけつ]で、窓[まど]から見[み]える景色[けしき]も美[うつく]しかった。", "sentence_source": "generated"}, {"text": "感染症を防ぐには、手洗いで手を清潔にしておくことが大切だ。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "感染症[かんせんしょう]を防[ふせ]ぐには、手洗[てあら]いで手[て]を清潔[せいけつ]にしておくことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "店の入口が清潔かどうかで、客は店の印象を決める。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "店[みせ]の入口[いりぐち]が清潔[せいけつ]かどうかで、客[きゃく]は店[みせ]の印象[いんしょう]を決[き]める。", "sentence_source": "generated"}, {"text": "清潔な環境で育てた野菜として、この農園の商品は人気がある。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "清潔[せいけつ]な環境[かんきょう]で育[そだ]てた野菜[やさい]として、この農園[のうえん]の商品[しょうひん]は人気[にんき]がある。", "sentence_source": "generated"}, {"text": "調理器具を清潔に保つことは、飲食店の基本的な責任だ。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "調理器具[ちょうりきぐ]を清潔[せいけつ]に保[たも]つことは、飲食店[いんしょくてん]の基本的[きほんてき]な責任[せきにん]だ。", "sentence_source": "generated"}, {"text": "清潔な身なりで面接に臨んだおかげで、好印象を与えられた。", "target_word": "清潔", "complexity_tier": "T4", "furigana": "清潔[せいけつ]な身[み]なりで面接[めんせつ]に臨[のぞ]んだおかげで、好印象[こうインしょう]を与[あた]えられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "清潔だ", "label": "終止形"}, {"form": "清潔な", "label": "連体形"}, {"form": "清潔に", "label": "連用形"}], "register": "標準", "sense_fingerprint": "汚れがなく衛生的で美しい状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42838, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清潔", "is_correct": true, "explanation": "『作業着を清潔に保つ』の空欄に入る。衛生管理の文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "『作業着を陽気に保つ』は意味が通らない。陽気は人や雰囲気の明るさを表す。"}, {"text": "大胆", "is_correct": false, "explanation": "『作業着を大胆に保つ』は文脈に合わない。大胆は思い切った様子を表す。"}, {"text": "空腹", "is_correct": false, "explanation": "『作業着を空腹に保つ』は意味が通らない。空腹は腹が空いている状態。"}], "explanations": {"清潔": "『作業着を清潔に保つ』の空欄に入る。衛生管理の文脈に合う。", "陽気": "『作業着を陽気に保つ』は意味が通らない。陽気は人や雰囲気の明るさを表す。", "大胆": "『作業着を大胆に保つ』は文脈に合わない。大胆は思い切った様子を表す。", "空腹": "『作業着を空腹に保つ』は意味が通らない。空腹は腹が空いている状態。"}, "sentence_index": 0, "correct_answer": "清潔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は試合で清潔に勝った。", "explanation": "ここは〈公正〉の意味。正々堂々と勝つことは〈公正〉で表し、〈清潔〉は汚れのなさや衛生に使う。"}, {"text": "この数字は清潔で、計算に誤りがない。", "explanation": "ここは〈正確〉の意味。数字の正しさは〈正確〉で表し、〈清潔〉は数字には使わない。"}, {"text": "厳密な検査のため、清潔な規則を作った。", "explanation": "ここは〈簡潔〉の意味。短く分かりやすい規則は〈簡潔〉で表し、〈清潔〉は汚れのなさに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42838, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清潔", "is_correct": true, "explanation": "『店の入口が清潔かどうかで』の空欄に入る。衛生的な印象を決めるという文脈に合う。"}, {"text": "豪快", "is_correct": false, "explanation": "『店の入口が豪快かどうかで』は文脈に合わない。豪快は勢いが大きいことを表す。"}, {"text": "残念", "is_correct": false, "explanation": "『店の入口が残念かどうかで』は意味が通らない。残念は失望を表す。"}, {"text": "不器用", "is_correct": false, "explanation": "手先の扱いが下手なことを表し、店の入口の状態には使わない。"}], "explanations": {"清潔": "『店の入口が清潔かどうかで』の空欄に入る。衛生的な印象を決めるという文脈に合う。", "豪快": "『店の入口が豪快かどうかで』は文脈に合わない。豪快は勢いが大きいことを表す。", "残念": "『店の入口が残念かどうかで』は意味が通らない。残念は失望を表す。", "不器用": "手先の扱いが下手なことを表し、店の入口の状態には使わない。"}, "sentence_index": 6, "correct_answer": "清潔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "清潔な決断で、新しい事業を始めた。", "explanation": "ここは〈大胆〉の意味。思い切った決断は〈大胆〉で表し、〈清潔〉は決断には使わない。"}, {"text": "清潔な勘で新商品の売れ行きを読んだ。", "explanation": "ここは〈的確〉の意味。見通しの正しさは〈的確〉で表し、〈清潔〉は汚れのなさや衛生に使う。"}, {"text": "清潔なステップで踊った。", "explanation": "ここは〈軽快〉の意味。動きの軽やかさは〈軽快〉で表し、〈清潔〉は踊りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42838, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業場は、常に清潔の状態に保たなければならない。", "corrected_sentence": "作業場は、常に清潔な状態に保たなければならない。", "error_description": "『清潔』は形容動詞なので、名詞を修飾するときは『清潔な』。『清潔の』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42838, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業服を清潔をしておく。", "corrected_sentence": "作業服を清潔にしておく。", "error_description": "『清潔』を状態に変える場合は『清潔に』が正しい。『清潔を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
