INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42841, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物が食べるもののことです。", "primary_collocate": null, "pronunciation": "えさ", "ipa": "esa", "syllable_count": 2, "sentences": [{"text": "毎朝、庭の池の魚に餌をやるのが私の仕事です。", "target_word": "餌", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、庭[にわ]の池[いけ]の魚[さかな]に餌[えさ]をやるのが私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "うさぎの餌は、野菜と牧草です。", "target_word": "餌", "complexity_tier": "T3", "furigana": "うさぎの餌[えさ]は、野菜[やさい]と牧草[ぼくそう]です。", "sentence_source": "generated"}, {"text": "この餌は、小さな子犬でも食べやすい形をしています。", "target_word": "餌", "complexity_tier": "T3", "furigana": "この餌[えさ]は、小[ちい]さな子犬[こいぬ]でも食[た]べやすい形[かたち]をしています。", "sentence_source": "generated"}, {"text": "弟は、ペットの亀の餌を買いに店へ行きました。", "target_word": "餌", "complexity_tier": "T3", "furigana": "弟[おとうと]は、ペットの亀[かめ]の餌[えさ]を買[か]いに店[みせ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "雨の日は、鳥があまり餌を探しに出ません。", "target_word": "餌", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、鳥[とり]があまり餌[えさ]を探[さが]しに出[で]ません。", "sentence_source": "generated"}, {"text": "魚が餌を食べなくなったら、水の温度を確かめてください。", "target_word": "餌", "complexity_tier": "T3", "furigana": "魚[さかな]が餌[えさ]を食[た]べなくなったら、水[みず]の温度[おんど]を確[たし]かめてください。", "sentence_source": "generated"}, {"text": "公園の鳩に餌をあげないでください、と看板に書いてあります。", "target_word": "餌", "complexity_tier": "T3", "furigana": "公園[こうえん]の鳩[はと]に餌[えさ]をあげないでください、と看板[かんばん]に書[か]いてあります。", "sentence_source": "generated"}, {"text": "ひなは口を大きく開けて、親から餌をもらいます。", "target_word": "餌", "complexity_tier": "T3", "furigana": "ひなは口[くち]を大[おお]きく開[あ]けて、親[おや]から餌[えさ]をもらいます。", "sentence_source": "generated"}, {"text": "猫の餌を買うとき、いつも成分表を見ます。", "target_word": "餌", "complexity_tier": "T3", "furigana": "猫[ねこ]の餌[えさ]を買[か]うとき、いつも成分表[せいぶんひょう]を見[み]ます。", "sentence_source": "generated"}, {"text": "冬の間、森の動物は木の実を餌にして生きています。", "target_word": "餌", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、森[もり]の動物[どうぶつ]は木[き]の実[み]を餌[えさ]にして生[い]きています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "餌", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "動物が食べるもの、または動物に食べさせるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42841, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餌", "is_correct": true, "explanation": "「魚に餌をやる」で、池の魚に与える食べ物を指す。ここに入る語。"}, {"text": "網", "is_correct": false, "explanation": "網は魚を捕る道具で、魚に「やる」ものではないので文が成り立たない。"}, {"text": "浮き", "is_correct": false, "explanation": "浮きは釣りの道具で、魚に与える対象にはならないので文が不自然になる。"}, {"text": "竿", "is_correct": false, "explanation": "竿は釣りに使う棒で、魚に与えるものではないので文が成り立たない。"}], "explanations": {"餌": "「魚に餌をやる」で、池の魚に与える食べ物を指す。ここに入る語。", "網": "網は魚を捕る道具で、魚に「やる」ものではないので文が成り立たない。", "浮き": "浮きは釣りの道具で、魚に与える対象にはならないので文が不自然になる。", "竿": "竿は釣りに使う棒で、魚に与えるものではないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "餌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "傷口に餌を塗って、ガーゼで覆った。", "explanation": "ここは〈薬〉（軟膏）の意味。傷口に塗るのは薬で、食べ物の餌は塗らないので誤り。"}, {"text": "畑に餌をまいて、野菜を育てる。", "explanation": "ここは〈肥料〉の意味。野菜を育てるために与えるものは肥料で、食べるものとしての餌とは言わないので誤り。"}, {"text": "牛乳には、体に必要な餌がたっぷり含まれている。", "explanation": "ここは〈栄養〉の意味。牛乳に含まれるのは栄養で、食べるものとしての餌ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42841, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餌", "is_correct": true, "explanation": "「公園の鳩に餌をあげないでください」で、鳩に与える食べ物を指す。ここに入る語。"}, {"text": "柵", "is_correct": false, "explanation": "柵は囲いで、鳩にあげるものではないので文が成り立たない。"}, {"text": "電線", "is_correct": false, "explanation": "電線は電気を送る線で、鳩にあげる対象にはならないので文が不自然になる。"}, {"text": "街灯", "is_correct": false, "explanation": "街灯は夜道を照らす灯りで、鳩にあげるものではないので文が成り立たない。"}], "explanations": {"餌": "「公園の鳩に餌をあげないでください」で、鳩に与える食べ物を指す。ここに入る語。", "柵": "柵は囲いで、鳩にあげるものではないので文が成り立たない。", "電線": "電線は電気を送る線で、鳩にあげる対象にはならないので文が不自然になる。", "街灯": "街灯は夜道を照らす灯りで、鳩にあげるものではないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "餌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車に餌を入れて、長い旅に出た。", "explanation": "ここは〈燃料〉の意味。車に入れるのは燃料で、食べ物を指す餌は車には使わないので誤り。"}, {"text": "カレーに入れる餌を、先に切っておく。", "explanation": "ここは〈材料〉の意味。料理の材料は食材と言い、餌を料理の材料として使うことはないので誤り。"}, {"text": "コップに餌を注いで、友達に出した。", "explanation": "ここは〈飲み物〉の意味。液体は注いで出すもので、餌は注げず飲み物の代わりにはならないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42841, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鳥に餌にあげるのは、朝だけにしています。", "corrected_sentence": "小鳥に餌をあげるのは、朝だけにしています。", "error_description": "誤りは「餌に」。「あげる」の目的語は「餌を」で示す。「餌に」だと餌が与える先のように読めて不自然になるので「を」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42841, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "犬に餌があげました。", "corrected_sentence": "犬に餌をあげました。", "error_description": "誤りは「餌が」。「あげる」の目的語は「餌を」で示す。「餌が」だと餌が主語になり、あげる動作の対象が消えて文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42842, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42842, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「動物に餌をやる」の目的語を示す「を」。与える食べ物として餌がここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「餌が」では餌が主語になり、「やってはいけません」の対象が消えて不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "「餌に」では餌が与える先や対象のように読め、「やる」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「餌で」は手段や場所を示し、与える対象を表せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「動物に餌をやる」の目的語を示す「を」。与える食べ物として餌がここに入る。", "が": "「餌が」では餌が主語になり、「やってはいけません」の対象が消えて不自然になる。", "に": "「餌に」では餌が与える先や対象のように読め、「やる」の目的語にならない。", "で": "「餌で」は手段や場所を示し、与える対象を表せないので合わない。"}, "error_tags": {"が": "主語の誤り", "に": "対象・方向の誤り", "で": "手段・場所の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42842, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物に与える食べ物のこと。特に、家畜やペットに与える食べ物を指すことが多い。", "primary_collocate": null, "pronunciation": "えさ", "ipa": "esa", "syllable_count": 2, "sentences": [{"text": "鶏の飼育は、温度や餌が厳密に調整された環境で行われます。", "target_word": "餌", "complexity_tier": "T3", "furigana": "鶏[にわとり]の飼育[しいく]は、温度[おんど]や餌[えさ]が厳密[げんみつ]に調整[ちょうせい]された環境[かんきょう]で行[おこな]われます。", "sentence_source": "mined"}, {"text": "犬の餌は、年齢に合わせて量を変えています。", "target_word": "餌", "complexity_tier": "T3", "furigana": "犬[いぬ]の餌[えさ]は、年齢[ねんれい]に合[あ]わせて量[りょう]を変[か]えています。", "sentence_source": "generated"}, {"text": "ペットショップで、ハムスター用の餌を一袋買いました。", "target_word": "餌", "complexity_tier": "T3", "furigana": "ペットショップで、ハムスター用の餌[えさ]を一袋買いました。", "sentence_source": "generated"}, {"text": "冬は食べ物が少ないので、鳥のために庭に餌を置きました。", "target_word": "餌", "complexity_tier": "T3", "furigana": "冬[ふゆ]は食[た]べ物[もの]が少[すく]ないので、鳥[とり]のために庭[にわ]に餌[えさ]を置[お]きました。", "sentence_source": "generated"}, {"text": "牧場では、朝と夕方の二回、牛に餌を与えます。", "target_word": "餌", "complexity_tier": "T3", "furigana": "牧場[ぼくじょう]では、朝[あさ]と夕方[ゆうがた]の二回[にかい]、牛[うし]に餌[えさ]を与[あた]えます。", "sentence_source": "generated"}, {"text": "猫が餌をたくさん残したので、病気ではないかと心配になりました。", "target_word": "餌", "complexity_tier": "T3", "furigana": "猫[ねこ]が餌[えさ]をたくさん残[のこ]したので、病気[びょうき]ではないかと心配[しんぱい]になりました。", "sentence_source": "generated"}, {"text": "餌の値段が上がり、農家の負担が増えています。", "target_word": "餌", "complexity_tier": "T3", "furigana": "餌[えさ]の値段[ねだん]が上[あ]がり、農家[のうか]の負担[ふたん]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "動物園では、むやみに動物に餌をやってはいけません。", "target_word": "餌", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、むやみに動物[どうぶつ]に餌[えさ]をやってはいけません。", "sentence_source": "generated"}, {"text": "親鳥はひなに餌を運ぶために、何度も巣と森を行き来します。", "target_word": "餌", "complexity_tier": "T3", "furigana": "親鳥[おやどり]はひなに餌[えさ]を運[はこ]ぶために、何度[なんど]も巣[す]と森[もり]を行[い]き来[き]します。", "sentence_source": "generated"}, {"text": "水槽の魚に餌を入れすぎると、水がすぐ汚れてしまいます。", "target_word": "餌", "complexity_tier": "T3", "furigana": "水槽[すいそう]の魚[さかな]に餌[えさ]を入[い]れすぎると、水[みず]がすぐ汚[よご]れてしまいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "餌", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家畜やペットなど、動物に与える食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42842, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餌", "is_correct": true, "explanation": "「温度や餌が厳密に調整された環境」で、飼育する動物に与える食べ物を指す。ここに入る語。"}, {"text": "巣箱", "is_correct": false, "explanation": "巣箱は鳥が巣に使う箱で、温度と並べて厳密に調整する対象ではないため、文が成り立たない。"}, {"text": "敷き藁", "is_correct": false, "explanation": "敷き藁は床に敷く材料で、温度と並べて「厳密に調整された」とは言えないので合わない。"}, {"text": "檻", "is_correct": false, "explanation": "檻は動物を閉じ込める囲いで、「温度や檻が調整される」という文にはならない。"}], "explanations": {"餌": "「温度や餌が厳密に調整された環境」で、飼育する動物に与える食べ物を指す。ここに入る語。", "巣箱": "巣箱は鳥が巣に使う箱で、温度と並べて厳密に調整する対象ではないため、文が成り立たない。", "敷き藁": "敷き藁は床に敷く材料で、温度と並べて「厳密に調整された」とは言えないので合わない。", "檻": "檻は動物を閉じ込める囲いで、「温度や檻が調整される」という文にはならない。"}, "sentence_index": 0, "correct_answer": "餌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ガソリンが切れたので、車に餌を入れて走らせた。", "explanation": "ここは〈燃料〉の意味。車に入れるのは燃料で、食べ物を指す餌は車には使わないので誤り。"}, {"text": "入院中は、毎朝決まった時間に餌が運ばれてくる。", "explanation": "ここは〈食事〉の意味。人の食事を餌と呼ぶのは不自然で、病院では食事と言うので誤り。"}, {"text": "大切なお客さまに餌をふるまった。", "explanation": "ここは〈ご馳走〉の意味。客をもてなす料理はご馳走・料理と言い、餌は使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42842, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餌", "is_correct": true, "explanation": "「餌の値段が上がり、農家の負担が増える」で、農家が買う飼料にあたる食べ物を指す。ここに入る語。"}, {"text": "鳴き声", "is_correct": false, "explanation": "鳴き声には値段がつかず、「値段が上がる」と結びつかないので文が成り立たない。"}, {"text": "足跡", "is_correct": false, "explanation": "足跡は地面に残る跡で、値段が上がる対象にはならないので文が不自然になる。"}, {"text": "羽音", "is_correct": false, "explanation": "羽音は羽ばたく音で、値段とは結びつかず、文の主語として成り立たない。"}], "explanations": {"餌": "「餌の値段が上がり、農家の負担が増える」で、農家が買う飼料にあたる食べ物を指す。ここに入る語。", "鳴き声": "鳴き声には値段がつかず、「値段が上がる」と結びつかないので文が成り立たない。", "足跡": "足跡は地面に残る跡で、値段が上がる対象にはならないので文が不自然になる。", "羽音": "羽音は羽ばたく音で、値段とは結びつかず、文の主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "餌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花壇に餌をまいて、春の花を育てる。", "explanation": "ここは〈肥料〉の意味。植物を育てるために与えるものは肥料で、餌は動物が食べるものに使うので誤り。"}, {"text": "この卵には、体に必要な餌がたくさん含まれている。", "explanation": "ここは〈栄養〉の意味。卵に含まれるのは栄養で、食べ物としての餌とは言わないので誤り。"}, {"text": "災害に備えて、家族の餌を三日分ためておく。", "explanation": "ここは〈食料〉の意味。非常時の備蓄は食料と言い、家族の備えを餌と呼ぶのは不自然なので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42842, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭に来た鳥に餌がまきました。", "corrected_sentence": "庭に来た鳥に餌をまきました。", "error_description": "誤りは「餌が」。「まく」の目的語は「餌を」と「を」で示す。「餌が」だと餌が主語になり、まく動作の対象が消えて文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42842, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池の鯉に餌がやりました。", "corrected_sentence": "池の鯉に餌をやりました。", "error_description": "誤りは「餌が」。「やる」の目的語は「餌を」で示す。「餌が」だと餌が主語になり、やる相手との関係が崩れて文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
