INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42878, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものの大きさのこと。", "primary_collocate": null, "pronunciation": "さいず", "ipa": "saizɯ", "syllable_count": 3, "sentences": [{"text": "この靴は私にはサイズが小さすぎて、足が痛くなった。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "この靴[くつ]は私[わたし]にはサイズが小[ちい]さすぎて、足[あし]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "箱のサイズを測ってから、ちょうどいい袋を買った。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "箱[はこ]のサイズを測[はか]ってから、ちょうどいい袋[ふくろ]を買[か]った。", "sentence_source": "generated"}, {"text": "兄は体が大きいので、大きいサイズの服しか着られない。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "兄[あに]は体[からだ]が大[おお]きいので、大[おお]きいサイズの服[ふく]しか着[き]られない。", "sentence_source": "generated"}, {"text": "写真のサイズが大きすぎて、メールで送れなかった。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "写真[しゃしん]のサイズが大[おお]きすぎて、メールで送[おく]れなかった。", "sentence_source": "generated"}, {"text": "部屋のサイズに合うカーペットを探している。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "部屋[へや]のサイズに合[あ]うカーペットを探[さが]している。", "sentence_source": "generated"}, {"text": "このカップは小さいサイズで、お茶が少ししか入らない。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "このカップは小[ちい]さいサイズで、お茶[ちゃ]が少[すこ]ししか入[はい]らない。", "sentence_source": "generated"}, {"text": "店員さんに「もっと大きいサイズはありますか」と聞いた。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "店員[てんいん]さんに「もっと大[おお]きいサイズはありますか」と聞[き]いた。", "sentence_source": "generated"}, {"text": "子どもの足はすぐ大きくなるので、毎年サイズを確かめる。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "子[こ]どもの足[あし]はすぐ大[おお]きくなるので、毎年[まいとし]サイズを確[たし]かめる。", "sentence_source": "generated"}, {"text": "ポスターのサイズはA3だから、普通の封筒には入らない。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "ポスターのサイズはA3だから、普通[ふつう]の封筒[ふうとう]には入[はい]らない。", "sentence_source": "generated"}, {"text": "指輪のサイズが合わなくなって、お店で直してもらった。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "指輪[ゆびわ]のサイズが合[あ]わなくなって、お店[みせ]で直[なお]してもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サイズ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものの大きさそのもの(靴・服・箱などの大小)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42878, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サイズ", "is_correct": true, "explanation": "「小さすぎて」と合う、靴の大きさを表す語。"}, {"text": "色", "is_correct": false, "explanation": "「色が小さすぎて」は意味が通らず、靴の話にも合わない。"}, {"text": "素材", "is_correct": false, "explanation": "「素材が小さすぎて」は文として不自然で、足の痛みの原因にならない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は〈小さい〉ではなく〈安い〉で表すので、「値段が小さすぎて」は合わない。"}], "explanations": {"サイズ": "「小さすぎて」と合う、靴の大きさを表す語。", "色": "「色が小さすぎて」は意味が通らず、靴の話にも合わない。", "素材": "「素材が小さすぎて」は文として不自然で、足の痛みの原因にならない。", "値段": "値段は〈小さい〉ではなく〈安い〉で表すので、「値段が小さすぎて」は合わない。"}, "sentence_index": 0, "correct_answer": "サイズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画のサイズは二時間で、途中で眠くなった。", "explanation": "ここは〈上映時間〉の意味。サイズは物の寸法に使う語なので、時間の長さには合わない。"}, {"text": "このケーキはサイズが甘くて、食べすぎてしまった。", "explanation": "ここは〈甘さ〉の意味。サイズは大きさの語で、味の強さには使わない。"}, {"text": "この机はサイズが静かだ。", "explanation": "ここは〈静かさ〉の意味。サイズは大きさを表す語で、音や雰囲気の静かさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42878, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サイズ", "is_correct": true, "explanation": "「もっと大きい」と合う、服の大きさを尋ねる語。"}, {"text": "色", "is_correct": false, "explanation": "「もっと大きい色」は意味が通らず、大きさを尋ねる文に合わない。"}, {"text": "値札", "is_correct": false, "explanation": "「もっと大きい値札」は不自然で、大きさを尋ねる文に合わない。"}, {"text": "レシート", "is_correct": false, "explanation": "「もっと大きいレシート」は意味が通らず、店員への質問として成り立たない。"}], "explanations": {"サイズ": "「もっと大きい」と合う、服の大きさを尋ねる語。", "色": "「もっと大きい色」は意味が通らず、大きさを尋ねる文に合わない。", "値札": "「もっと大きい値札」は不自然で、大きさを尋ねる文に合わない。", "レシート": "「もっと大きいレシート」は意味が通らず、店員への質問として成り立たない。"}, "sentence_index": 6, "correct_answer": "サイズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱はサイズが重くて、持ち上がらない。", "explanation": "ここは〈重さ〉の意味。サイズは寸法・大きさの区分で、重さは〈重い〉と言う。"}, {"text": "このカーテンはサイズが青くて、部屋が明るく見える。", "explanation": "ここは〈色〉の意味。サイズは大きさを表す語で、色には使わない。"}, {"text": "その猫はサイズが十歳だ。", "explanation": "ここは〈年齢〉の意味。サイズは大きさに使い、年齢は〈歳〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42878, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この服のサイズを合わないので、店で交換してもらった。", "corrected_sentence": "この服のサイズが合わないので、店で交換してもらった。", "error_description": "助詞の誤り。誤: サイズを合わない／正: サイズが合わない。「合わない」の主語はサイズなので助詞は〈が〉。〈を〉は目的語を示すため、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42878, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この帽子はサイズが合わなくなので、弟にあげた。", "corrected_sentence": "この帽子はサイズが合わないので、弟にあげた。", "error_description": "活用の誤り。誤: 合わなくなので／正: 合わないので。「〜ので」の前は動詞の形（ここでは「合わない」）で、「なくなる」を混ぜた形は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
