INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42879, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物の大きさや寸法を表す言葉。", "primary_collocate": null, "pronunciation": "さいず", "ipa": "saizɯ", "syllable_count": 3, "sentences": [{"text": "ジュースを買うとき、サイズはSかMかLから選べる。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "ジュースを買[か]うとき、サイズはSかMかLから選[えら]べる。", "sentence_source": "generated"}, {"text": "このカバンのサイズは、縦三十センチ、横四十センチです。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "このカバンのサイズは、縦[たて]三十[さんじゅう]センチ、横[よこ]四十[よんじゅう]センチです。", "sentence_source": "generated"}, {"text": "サイズが違う服を送られたので、店に電話して交換を頼んだ。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "サイズが違[ちが]う服[ふく]を送[おく]られたので、店[みせ]に電話[でんわ]して交換[こうかん]を頼[たの]んだ。", "sentence_source": "generated"}, {"text": "帽子のサイズが分からないときは、頭のまわりを測ってください。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "帽子[ぼうし]のサイズが分[わ]からないときは、頭[あたま]のまわりを測[はか]ってください。", "sentence_source": "generated"}, {"text": "机のサイズを確かめずに買ったので、部屋に入らなかった。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "机[つくえ]のサイズを確[たし]かめずに買[か]ったので、部屋[へや]に入[はい]らなかった。", "sentence_source": "generated"}, {"text": "大きいサイズのピザを頼んだが、五人で食べてもまだ余った。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "大[おお]きいサイズのピザを頼[たの]んだが、五人[ごにん]で食[た]べてもまだ余[あま]った。", "sentence_source": "generated"}, {"text": "このケースは携帯電話のサイズにぴったり合う。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "このケースは携帯電話[けいたいでんわ]のサイズにぴったり合[あ]う。", "sentence_source": "generated"}, {"text": "スーツのサイズを直すには、一週間ほどかかります。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "スーツのサイズを直[なお]すには、一週間[いっしゅうかん]ほどかかります。", "sentence_source": "generated"}, {"text": "写真を額に入れるには、まず額のサイズを調べておく。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "写真[しゃしん]を額[がく]に入[い]れるには、まず額[がく]のサイズを調[しら]べておく。", "sentence_source": "generated"}, {"text": "弟は成長して、去年の服はもうサイズが合わない。", "target_word": "サイズ", "complexity_tier": "T3", "furigana": "弟[おとうと]は成長[せいちょう]して、去年[きょねん]の服[ふく]はもうサイズが合[あ]わない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サイズ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "寸法やS・M・Lなど、大きさを示す区分や数値", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42879, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サイズ", "is_correct": true, "explanation": "S・M・Lという大きさの区分を表す語なので、選べるものとして合う。"}, {"text": "味", "is_correct": false, "explanation": "「味はSかMかLから選べる」は意味が通らない。ジュースの味はサイズでは選ばない。"}, {"text": "色", "is_correct": false, "explanation": "S・M・Lは大きさの区分で、「色はSかMかLから選べる」は成り立たない。"}, {"text": "香り", "is_correct": false, "explanation": "「香りはSかMかLから選べる」は不自然で、大きさの区分とは結びつかない。"}], "explanations": {"サイズ": "S・M・Lという大きさの区分を表す語なので、選べるものとして合う。", "味": "「味はSかMかLから選べる」は意味が通らない。ジュースの味はサイズでは選ばない。", "色": "S・M・Lは大きさの区分で、「色はSかMかLから選べる」は成り立たない。", "香り": "「香りはSかMかLから選べる」は不自然で、大きさの区分とは結びつかない。"}, "sentence_index": 0, "correct_answer": "サイズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この問題はサイズが難しい。", "explanation": "ここは〈難しさ〉の意味。サイズは寸法や大きさの区分で、難しさには〈難しい〉を使う。"}, {"text": "この肉はサイズが新鮮だ。", "explanation": "ここは〈鮮度〉の意味。サイズは大きさの区分で、新鮮さは表さない。"}, {"text": "この車はサイズが速い。", "explanation": "ここは〈速さ〉の意味。サイズは大きさを表す語なので、速度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42879, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サイズ", "is_correct": true, "explanation": "「ぴったり合う」と合う、携帯電話の寸法を表す語。"}, {"text": "声", "is_correct": false, "explanation": "「携帯電話の声にぴったり合う」は意味が通らず、ケースの寸法の話にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "「携帯電話の寿命にぴったり合う」は不自然で、ケースの寸法の話にならない。"}, {"text": "充電", "is_correct": false, "explanation": "「携帯電話の充電にぴったり合う」は不自然で、ケースの寸法の話にならない。"}], "explanations": {"サイズ": "「ぴったり合う」と合う、携帯電話の寸法を表す語。", "声": "「携帯電話の声にぴったり合う」は意味が通らず、ケースの寸法の話にならない。", "寿命": "「携帯電話の寿命にぴったり合う」は不自然で、ケースの寸法の話にならない。", "充電": "「携帯電話の充電にぴったり合う」は不自然で、ケースの寸法の話にならない。"}, "sentence_index": 6, "correct_answer": "サイズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鞄はサイズが重くて、肩が疲れる。", "explanation": "ここは〈重さ〉の意味。サイズは寸法・大きさの区分で、重さは〈重い〉と言う。"}, {"text": "この壁はサイズが白い。", "explanation": "ここは〈色〉の意味。サイズは大きさの区分で、色の白さには使わない。"}, {"text": "この子はサイズが五歳だ。", "explanation": "ここは〈年齢〉の意味。サイズは大きさに使い、年齢は〈歳〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42879, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このシャツのサイズに、店で測ってもらった。", "corrected_sentence": "このシャツのサイズを、店で測ってもらった。", "error_description": "助詞の誤り。誤: サイズに／正: サイズを。「測る」は〈を〉で測る対象（サイズ）を示す。〈に〉では測る対象にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42879, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "買う前に、靴のサイズと確かめておこう。", "corrected_sentence": "買う前に、靴のサイズを確かめておこう。", "error_description": "助詞の誤り。誤: サイズと確かめる／正: サイズを確かめる。「確かめる」は〈を〉で確認する対象を示す。〈と〉は並列や相手を表すので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42903, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "家畜を話題として示す「は」。「家畜は、肉や乳を得るために飼われています」に合う。"}, {"text": "を", "is_correct": false, "explanation": "「飼われています」は受身で、家畜を目的語にはとれない。文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「飼われています」の主語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、ここでは文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "家畜を話題として示す「は」。「家畜は、肉や乳を得るために飼われています」に合う。", "を": "「飼われています」は受身で、家畜を目的語にはとれない。文が成り立たない。", "へ": "「へ」は方向を示すので、「飼われています」の主語として成り立たない。", "より": "「より」は比較の基準を示すので、ここでは文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42903, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れる」の対象を示す「を」。「家畜を小屋の中に入れて」に合う。"}, {"text": "に", "is_correct": false, "explanation": "「中に」で場所がすでに示されているため、ここで「に」を続けると不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「入れる」の対象には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「入れる」の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「入れる」の対象を示す「を」。「家畜を小屋の中に入れて」に合う。", "に": "「中に」で場所がすでに示されているため、ここで「に」を続けると不自然になる。", "と": "「と」は並列や相手を示すので、「入れる」の対象には合わない。", "から": "「から」は起点を示すので、「入れる」の対象を示せない。"}, "error_tags": {"に": "場所（既出）", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42903, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間が生活のために飼育し、肉や乳、卵などを得たり、労働力として使う動物のこと。", "primary_collocate": null, "pronunciation": "かちく", "ipa": "katɕikɯ", "syllable_count": 3, "sentences": [{"text": "鶏は家禽の一つであり、人間が管理する家畜として、畜産業界で重要な役割を果たしています。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "鶏(にわとり)は家禽(かきん)の一(ひと)つであり、人間(にんげん)が管理(かんり)する家畜(かちく)として、畜産(ちくさん)業界(ぎょうかい)で重要(じゅうよう)な役割(やくわり)を果(は)たしています。", "sentence_source": "generated"}, {"text": "牛や豚などの家畜は、肉や乳を得るために飼われています。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "牛(うし)や豚(ぶた)などの家畜(かちく)は、肉(にく)や乳(ちち)を得(え)るために飼(か)われています。", "sentence_source": "generated"}, {"text": "農家の朝は早く、家畜に餌をやることから始まります。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "農家(のうか)の朝(あさ)は早(はや)く、家畜(かちく)に餌(えさ)をやることから始(はじ)まります。", "sentence_source": "generated"}, {"text": "昔の農村では、牛や馬は耕作を手伝う大切な家畜でした。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "昔(むかし)の農村(のうそん)では、牛(うし)や馬(うま)は耕作(こうさく)を手伝(てつだ)う大切(たいせつ)な家畜(かちく)でした。", "sentence_source": "generated"}, {"text": "家畜が病気になると、周りの農場にも広がるおそれがあります。", "target_word": "家畜", "complexity_tier": "T4", "furigana": "家畜(かちく)が病気(びょうき)になると、周(まわ)りの農場(のうじょう)にも広(ひろ)がるおそれがあります。", "sentence_source": "generated"}, {"text": "野生の動物と違って、家畜は人間に慣れています。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "野生(やせい)の動物(どうぶつ)と違(ちが)って、家畜(かちく)は人間(にんげん)に慣(な)れています。", "sentence_source": "generated"}, {"text": "山の牧場では、家畜が草を食べる姿を見られます。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "山(やま)の牧場(ぼくじょう)では、家畜(かちく)が草(くさ)を食(た)べる姿(すがた)を見(み)られます。", "sentence_source": "generated"}, {"text": "冬は寒いので、家畜を小屋の中に入れて世話をします。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "冬(ふゆ)は寒(さむ)いので、家畜(かちく)を小屋(こや)の中(なか)に入(い)れて世話(せわ)をします。", "sentence_source": "generated"}, {"text": "家畜の数が増えすぎて、牧草が足りなくなりました。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "家畜(かちく)の数(かず)が増(ふ)えすぎて、牧草(ぼくそう)が足(た)りなくなりました。", "sentence_source": "generated"}, {"text": "獣医は、家畜の健康を守る大切な仕事をしています。", "target_word": "家畜", "complexity_tier": "T4", "furigana": "獣医(じゅうい)は、家畜(かちく)の健康(けんこう)を守(まも)る大切(たいせつ)な仕事(しごと)をしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家畜", "label": "基本形"}], "register": "中立（です・ます体）", "sense_fingerprint": "牛・豚・馬など、人間が生活のために飼う動物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42903, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家畜", "is_correct": true, "explanation": "人が生活のために飼う動物を指し、「人間が管理する〜として、畜産業界で重要な役割」に合う。"}, {"text": "野生", "is_correct": false, "explanation": "野生は人が管理しないものを指すので、前の「人間が管理する」と矛盾する。"}, {"text": "害虫", "is_correct": false, "explanation": "害虫は人に害を与える虫で、畜産業界で役割を果たす対象ではない。"}, {"text": "植物", "is_correct": false, "explanation": "植物は畜産業の対象ではないので、「畜産業界で重要な役割」の対象に合わない。"}], "explanations": {"家畜": "人が生活のために飼う動物を指し、「人間が管理する〜として、畜産業界で重要な役割」に合う。", "野生": "野生は人が管理しないものを指すので、前の「人間が管理する」と矛盾する。", "害虫": "害虫は人に害を与える虫で、畜産業界で役割を果たす対象ではない。", "植物": "植物は畜産業の対象ではないので、「畜産業界で重要な役割」の対象に合わない。"}, "sentence_index": 0, "correct_answer": "家畜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では、家畜のロボットが毎朝製品を運んでいます。", "explanation": "ここは〈機械〉の意味。家畜は人が生活のために飼う動物を指すので、工場で製品を運ぶロボットには合わない。"}, {"text": "この畑では、トマトなどの家畜が毎年よく育ちます。", "explanation": "ここは〈作物〉の意味。家畜は動物を指すので、畑で育つトマトなどの植物には合わない。"}, {"text": "夏の夜は、蚊などの家畜が多くて困ります。", "explanation": "ここは〈害虫〉の意味。家畜は人が飼う動物を指すので、人を悩ませる蚊には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42903, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家畜", "is_correct": true, "explanation": "牧場で草を食べる動物を指し、「家畜が草を食べる姿」に合う。"}, {"text": "観光客", "is_correct": false, "explanation": "観光客は人なので、草を食べる姿の主語にはならない。"}, {"text": "野菜", "is_correct": false, "explanation": "野菜は食べられる側の植物で、草を食べる主語にならない。"}, {"text": "農機具", "is_correct": false, "explanation": "農機具は道具なので、草を食べる主語に合わない。"}], "explanations": {"家畜": "牧場で草を食べる動物を指し、「家畜が草を食べる姿」に合う。", "観光客": "観光客は人なので、草を食べる姿の主語にはならない。", "野菜": "野菜は食べられる側の植物で、草を食べる主語にならない。", "農機具": "農機具は道具なので、草を食べる主語に合わない。"}, "sentence_index": 6, "correct_answer": "家畜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "動物園では、家畜のトラが檻の中で昼寝をしています。", "explanation": "ここは〈猛獣〉の意味。家畜は生活や産業のために人が飼う動物を指すので、動物園のトラには合わない。"}, {"text": "台所では、家畜の包丁が毎日使われています。", "explanation": "ここは〈道具〉の意味。家畜は人が飼う動物を指すので、台所で使う包丁には合わない。"}, {"text": "この家では、家畜の猫が家族の布団で寝ています。", "explanation": "ここは〈ペット〉の意味。家畜は生活や産業のために飼う動物を指すので、家族と暮らす猫には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42903, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "農家では、家畜を飼うしています。", "corrected_sentence": "農家では、家畜を飼っています。", "error_description": "「飼う」のて形は促音便で「飼って」になる。「飼うしています」は誤りで、正しくは「飼っています」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42903, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農場では、毎朝家畜から新鮮な水を与えます。", "corrected_sentence": "農場では、毎朝家畜に新鮮な水を与えます。", "error_description": "「与える」の相手を示すのは「に」。「から」は起点を表すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42916, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "店への方向を示し、出荷先を表すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「店を出荷」では送る先を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、送る先を表せない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の助詞で、送る先を表せない。"}], "correct_answer": "へ", "explanations": {"へ": "店への方向を示し、出荷先を表すので正しい。", "を": "目的語を示すが、「店を出荷」では送る先を表せない。", "より": "比較の助詞で、送る先を表せない。", "と": "並列・相手の助詞で、送る先を表せない。"}, "error_tags": {"へ": "方向", "を": "目的語", "より": "比較", "と": "並列・相手"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入荷", "is_correct": true, "explanation": "店が商品を受け取る意味で、出荷の対義語。"}, {"text": "製造", "is_correct": false, "explanation": "ものを作る意味。送り出すことの反対語ではない。"}, {"text": "購入", "is_correct": false, "explanation": "買う意味。対義語ではない。"}, {"text": "配達", "is_correct": false, "explanation": "届ける意味。送り出す側と対になる語ではない。"}], "correct_answer": "入荷", "explanations": {"入荷": "店が商品を受け取る意味で、出荷の対義語。", "製造": "ものを作る意味。送り出すことの反対語ではない。", "購入": "買う意味。対義語ではない。", "配達": "届ける意味。送り出す側と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42916, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「出荷の仕事」と名詞を結ぶ助詞で正しい。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「出荷から仕事」では名詞どうしを結べない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示すが、「出荷で仕事」では意味がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "位置・方向を示すが、「出荷に仕事」は名詞を結ぶ用法にならない。"}], "correct_answer": "の", "explanations": {"の": "「出荷の仕事」と名詞を結ぶ助詞で正しい。", "から": "起点を示すが、「出荷から仕事」では名詞どうしを結べない。", "で": "場所・手段を示すが、「出荷で仕事」では意味がつながらない。", "に": "位置・方向を示すが、「出荷に仕事」は名詞を結ぶ用法にならない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "で": "場所・手段", "に": "位置・方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入荷", "is_correct": true, "explanation": "店が商品を受け取る意味で、出荷の対義語。"}, {"text": "生産", "is_correct": false, "explanation": "ものを作る意味。送り出すことの反対語ではない。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼む意味。対義語ではない。"}, {"text": "在庫", "is_correct": false, "explanation": "手元にある品物の量を指し、対義語ではない。"}], "correct_answer": "入荷", "explanations": {"入荷": "店が商品を受け取る意味で、出荷の対義語。", "生産": "ものを作る意味。送り出すことの反対語ではない。", "注文": "品物を頼む意味。対義語ではない。", "在庫": "手元にある品物の量を指し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42916, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "つくったものをお店やお客さんに送ること。", "primary_collocate": null, "pronunciation": "しゅっか", "ipa": "ɕɯkka", "syllable_count": 3, "sentences": [{"text": "パン工場では、朝早くにパンをお店へ出荷します。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "パン工場[こうじょう]では、朝早[あさはや]くにパンをお店[みせ]へ出荷[しゅっか]します。", "sentence_source": "generated"}, {"text": "今日収穫したトマトは、明日出荷されます。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "今日[きょう]収穫[しゅうかく]したトマトは、明日[あした]出荷[しゅっか]されます。", "sentence_source": "generated"}, {"text": "雨がひどくて、トラックでの出荷ができませんでした。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "雨[あめ]がひどくて、トラックでの出荷[しゅっか]ができませんでした。", "sentence_source": "generated"}, {"text": "農家のおじさんは、毎週みかんを出荷しています。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "農家[のうか]のおじさんは、毎週[まいしゅう]みかんを出荷[しゅっか]しています。", "sentence_source": "generated"}, {"text": "出荷の日が決まったら、お客さんに連絡します。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "出荷[しゅっか]の日[ひ]が決[き]まったら、お客[きゃく]さんに連絡[れんらく]します。", "sentence_source": "generated"}, {"text": "工場で作ったおもちゃは、全国のお店に出荷されます。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "工場[こうじょう]で作[つく]ったおもちゃは、全国[ぜんこく]のお店[みせ]に出荷[しゅっか]されます。", "sentence_source": "generated"}, {"text": "魚は新鮮なうちに出荷しなければなりません。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "魚[さかな]は新鮮[しんせん]なうちに出荷[しゅっか]しなければなりません。", "sentence_source": "generated"}, {"text": "出荷の仕事は、重い箱を運ぶので大変です。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "出荷[しゅっか]の仕事[しごと]は、重[おも]い箱[はこ]を運[はこ]ぶので大変[たいへん]です。", "sentence_source": "generated"}, {"text": "去年よりたくさんの卵を出荷することができました。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "去年[きょねん]よりたくさんの卵[たまご]を出荷[しゅっか]することができました。", "sentence_source": "generated"}, {"text": "注文を受けてから三日以内に出荷します。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]を受[う]けてから三日以内[みっかいない]に出荷[しゅっか]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出荷", "label": "名詞形"}, {"form": "出荷する", "label": "サ変動詞・辞書形"}, {"form": "出荷した", "label": "過去形"}, {"form": "出荷される", "label": "受身形"}], "register": "中立（です・ます体）", "sense_fingerprint": "作った物や収穫した物を店や客のもとへ送ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42916, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出荷", "is_correct": true, "explanation": "作ったパンを店へ送る意味で、この文の空欄に入る語。"}, {"text": "解説", "is_correct": false, "explanation": "説明する意味。パンを店へ送る場面には合わない。"}, {"text": "完成", "is_correct": false, "explanation": "仕上がる意味。「お店へ完成します」では意味が通らない。"}, {"text": "放送", "is_correct": false, "explanation": "電波や番組で伝える意味。パンを店へ放送することはできない。"}], "explanations": {"出荷": "作ったパンを店へ送る意味で、この文の空欄に入る語。", "解説": "説明する意味。パンを店へ送る場面には合わない。", "完成": "仕上がる意味。「お店へ完成します」では意味が通らない。", "放送": "電波や番組で伝える意味。パンを店へ放送することはできない。"}, "sentence_index": 0, "correct_answer": "出荷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達に手紙を出荷した。", "explanation": "ここは〈発送〉の意味。出荷は店や市場へ商品を大量に送る語で、個人の手紙には使わない。"}, {"text": "使わなくなった服を、フリマアプリに出荷した。", "explanation": "ここは〈出品〉の意味。出荷は店や市場へ商品を送る語で、アプリに品物を並べて売りに出す場面には使わない。"}, {"text": "電車は朝七時に駅を出荷した。", "explanation": "ここは〈出発〉の意味。出荷は品物を送る語で、電車が駅を離れる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42916, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出荷", "is_correct": true, "explanation": "新鮮なうちに店などへ送り出す意味で、この文の空欄に入る語。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味。魚には合わない。"}, {"text": "出版", "is_correct": false, "explanation": "本を世に出す意味。魚には使わない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かす意味。新鮮さと逆なので合わない。"}], "explanations": {"出荷": "新鮮なうちに店などへ送り出す意味で、この文の空欄に入る語。", "採点": "点数をつける意味。魚には合わない。", "出版": "本を世に出す意味。魚には使わない。", "解凍": "凍ったものを溶かす意味。新鮮さと逆なので合わない。"}, "sentence_index": 6, "correct_answer": "出荷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝八時に、会社へ出荷している。", "explanation": "ここは〈出勤〉の意味。出荷は品物を送る語なので、人が職場へ行く場面には合わない。"}, {"text": "来週は大阪へ出荷するので、家を空けます。", "explanation": "ここは〈出張〉の意味。出荷は荷物を送ることなので、人が遠方へ行く場面には使えない。"}, {"text": "彼女は来月のドラマに出荷する予定だ。", "explanation": "ここは〈出演〉の意味。出荷は品物を送る語なので、番組に出る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42916, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出荷が日が決まったら、店に知らせます。", "corrected_sentence": "出荷の日が決まったら、店に知らせます。", "error_description": "「出荷の日」が正しい。「の」を「が」に替えると名詞どうしの結びつきが崩れ、「出荷が日」は不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42916, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場は来月、新しい製品を海外を出荷する予定です。", "corrected_sentence": "工場は来月、新しい製品を海外へ出荷する予定です。", "error_description": "「海外へ出荷する」が正しい。方向を示す「へ」が「出荷」に直接かかる助詞なので、「を」に替えると目的語扱いになり不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42917, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「出荷が始まります」の主語を示す「が」。文の主語として合う。"}, {"text": "を", "is_correct": false, "explanation": "「始まる」は目的語を取らないので、「を」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「始まる」には「に」を続けないので、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、主語を示す位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「出荷が始まります」の主語を示す「が」。文の主語として合う。", "を": "「始まる」は目的語を取らないので、「を」は文が成り立たない。", "に": "「始まる」には「に」を続けないので、不自然になる。", "で": "「で」は手段や場所を示すので、主語を示す位置には合わない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42917, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「出荷の前に」の「の」。「出荷」と「前」をつなぐ。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「出荷と前に」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「出荷へ前に」は不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「出荷から前に」は文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「出荷の前に」の「の」。「出荷」と「前」をつなぐ。", "と": "「と」は並列や相手を示すので、「出荷と前に」は成り立たない。", "へ": "「へ」は方向を示すので、「出荷へ前に」は不自然になる。", "から": "「から」は起点を示すので、「出荷から前に」は文が成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42917, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "商品を市場や顧客に送り出すこと。また、その商品。", "primary_collocate": null, "pronunciation": "しゅっか", "ipa": "ɕɯkka", "syllable_count": 3, "sentences": [{"text": "彼らは驚くべきスピードで成長し、わずか数週間で出荷可能な体重になります。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "彼[かれ]らは驚[おどろ]くべきスピードで成長[せいちょう]し、わずか数週間[すうしゅうかん]で出荷[しゅっか]可能[かのう]な体重[たいじゅう]になります。", "sentence_source": "mined"}, {"text": "この工場では、毎朝六時から野菜の出荷が始まります。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、毎朝[まいあさ]六時[ろくじ]から野菜[やさい]の出荷[しゅっか]が始[はじ]まります。", "sentence_source": "generated"}, {"text": "台風の影響で、りんごの出荷が一週間遅れた。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、りんごの出荷[しゅっか]が一週間[いっしゅうかん]遅[おく]れた。", "sentence_source": "generated"}, {"text": "新しい商品は来月の初めに出荷される予定です。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]は来月[らいげつ]の初[はじ]めに出荷[しゅっか]される予定[よてい]です。", "sentence_source": "generated"}, {"text": "注文が多すぎて、出荷が間に合わなくなった。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]が多[おお]すぎて、出荷[しゅっか]が間[ま]に合[あ]わなくなった。", "sentence_source": "generated"}, {"text": "農家の人たちは、収穫した米をすぐに出荷しました。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]たちは、収穫[しゅうかく]した米[こめ]をすぐに出荷[しゅっか]しました。", "sentence_source": "generated"}, {"text": "検査に合格しないと、製品は出荷できません。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "検査[けんさ]に合格[ごうかく]しないと、製品[せいひん]は出荷[しゅっか]できません。", "sentence_source": "generated"}, {"text": "出荷の前に、箱の中身をもう一度確認してください。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "出荷[しゅっか]の前[まえ]に、箱[はこ]の中身[なかみ]をもう一度[いちど]確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "今月は牛乳の出荷が先月より二割増えました。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "今月[こんげつ]は牛乳[ぎゅうにゅう]の出荷[しゅっか]が先月[せんげつ]より二割[にわり]増[ふ]えました。", "sentence_source": "generated"}, {"text": "不良品が見つかったため、会社は出荷を止めた。", "target_word": "出荷", "complexity_tier": "T3", "furigana": "不良品[ふりょうひん]が見[み]つかったため、会社[かいしゃ]は出荷[しゅっか]を止[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出荷", "label": "名詞形"}, {"form": "出荷する", "label": "サ変動詞・辞書形"}, {"form": "出荷した", "label": "過去形"}, {"form": "出荷される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "生産者や業者が商品を市場・顧客に向けて送り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42917, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出荷", "is_correct": true, "explanation": "「出荷可能な」で、商品を送り出せる状態を表す。"}, {"text": "出発", "is_correct": false, "explanation": "出発は出かけること。「出発可能な体重」は意味が合わない。"}, {"text": "出張", "is_correct": false, "explanation": "出張は仕事で出かけること。体重には合わない。"}, {"text": "出世", "is_correct": false, "explanation": "出世は地位が上がること。体重には合わない。"}], "explanations": {"出荷": "「出荷可能な」で、商品を送り出せる状態を表す。", "出発": "出発は出かけること。「出発可能な体重」は意味が合わない。", "出張": "出張は仕事で出かけること。体重には合わない。", "出世": "出世は地位が上がること。体重には合わない。"}, "sentence_index": 0, "correct_answer": "出荷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "期限までに、宿題を先生に出荷しました。", "explanation": "ここは〈提出〉の意味。出荷は商品を市場や顧客に送り出すことなので、宿題を先生に出す場面には合わない。"}, {"text": "彼は朝、家から出荷しました。", "explanation": "ここは〈外出〉の意味。出荷は商品を送り出すことなので、人が家を出る場面には合わない。"}, {"text": "会社は新しい事業のために、銀行から資金を出荷した。", "explanation": "ここは〈融資〉の意味。出荷は商品を送り出すことなので、銀行が事業にお金を貸す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42917, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出荷", "is_correct": true, "explanation": "「検査に合格しないと、製品は出荷できません」の文に合う。"}, {"text": "出勤", "is_correct": false, "explanation": "出勤は会社に行くこと。製品には使わない。"}, {"text": "出現", "is_correct": false, "explanation": "現れること。製品が出現する文には合わない。"}, {"text": "出血", "is_correct": false, "explanation": "血が出ること。製品には合わない。"}], "explanations": {"出荷": "「検査に合格しないと、製品は出荷できません」の文に合う。", "出勤": "出勤は会社に行くこと。製品には使わない。", "出現": "現れること。製品が出現する文には合わない。", "出血": "血が出ること。製品には合わない。"}, "sentence_index": 6, "correct_answer": "出荷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客はその店で新しい靴を出荷しました。", "explanation": "ここは〈購入〉の意味。出荷は商品を送り出すことなので、客が買う場面には合わない。"}, {"text": "旅先で拾った財布を、警察に出荷しました。", "explanation": "ここは〈届け出〉の意味。出荷は商品を市場や顧客に送り出すことなので、拾い物を届ける場面には合わない。"}, {"text": "来月、彼は大阪へ出荷します。", "explanation": "ここは〈転勤〉の意味。出荷は商品を送り出すことなので、人が勤務地を移る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42917, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場では、毎朝製品の出荷に始めます。", "corrected_sentence": "工場では、毎朝製品の出荷を始めます。", "error_description": "「始める」の目的語を示すのは「を」。「に」にすると「始める」の目的語にならず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42917, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "検査が済んだ製品から、順に出荷ます。", "corrected_sentence": "検査が済んだ製品から、順に出荷します。", "error_description": "「出荷」はサ変動詞なので「します」が必要。「ます」だけでは動詞として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
