INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42963, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても、という意味。", "primary_collocate": null, "pronunciation": "ひじょう", "ipa": "çiʑoː", "syllable_count": 3, "sentences": [{"text": "この映画は非常におもしろかったです。", "target_word": "非常", "complexity_tier": "T3", "furigana": "この映画[えいが]は非常[ひじょう]におもしろかったです。", "sentence_source": "generated"}, {"text": "今日は非常に寒いので、あたたかい服を着てください。", "target_word": "非常", "complexity_tier": "T3", "furigana": "今日[きょう]は非常[ひじょう]に寒[さむ]いので、あたたかい服[ふく]を着[き]てください。", "sentence_source": "generated"}, {"text": "彼女は非常に頭がよくて、どんな問題でもすぐ解く。", "target_word": "非常", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は非常[ひじょう]に頭[あたま]がよくて、どんな問題[もんだい]でもすぐ解[と]く。", "sentence_source": "generated"}, {"text": "昨日の試験は非常に難しくて、みんな困っていた。", "target_word": "非常", "complexity_tier": "T3", "furigana": "昨日[きのう]の試験[しけん]は非常[ひじょう]に難[むずか]しくて、みんな困[こま]っていた。", "sentence_source": "generated"}, {"text": "このお店のラーメンは非常においしいと有名です。", "target_word": "非常", "complexity_tier": "T3", "furigana": "このお店[みせ]のラーメンは非常[ひじょう]においしいと有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "山の上からの景色は非常にきれいだった。", "target_word": "非常", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]からの景色[けしき]は非常[ひじょう]にきれいだった。", "sentence_source": "generated"}, {"text": "田中さんは非常に親切な人で、いつも助けてくれる。", "target_word": "非常", "complexity_tier": "T3", "furigana": "田中[たなか]さんは非常[ひじょう]に親切[しんせつ]な人[ひと]で、いつも助[たす]けてくれる。", "sentence_source": "generated"}, {"text": "非常に疲れていたので、帰ってすぐ寝てしまった。", "target_word": "非常", "complexity_tier": "T3", "furigana": "非常[ひじょう]に疲[つか]れていたので、帰[かえ]ってすぐ寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "この川は非常に深いから、泳がないでください。", "target_word": "非常", "complexity_tier": "T3", "furigana": "この川[かわ]は非常[ひじょう]に深[ふか]いから、泳[およ]がないでください。", "sentence_source": "generated"}, {"text": "先生の話は非常にわかりやすく、よく理解できた。", "target_word": "非常", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]は非常[ひじょう]にわかりやすく、よく理解[りかい]できた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "非常に", "label": "連用形"}, {"form": "非常な", "label": "連体形"}, {"form": "非常だ", "label": "終止形"}], "register": "やや硬い", "sense_fingerprint": "「非常に」の形で形容詞や動詞を強める、とてもの意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42963, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非常", "is_correct": true, "explanation": "「非常に」で「とても」の意味を表し、「おもしろかった」を強める。"}, {"text": "静か", "is_correct": false, "explanation": "「静かに」はおもしろさの程度を表さず、文が不自然になる。"}, {"text": "不要", "is_correct": false, "explanation": "「不要に」は程度を表さず、「不要におもしろい」は意味が通らない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔に」はおもしろさの程度を表さず、文に合わない。"}], "explanations": {"非常": "「非常に」で「とても」の意味を表し、「おもしろかった」を強める。", "静か": "「静かに」はおもしろさの程度を表さず、文が不自然になる。", "不要": "「不要に」は程度を表さず、「不要におもしろい」は意味が通らない。", "清潔": "「清潔に」はおもしろさの程度を表さず、文に合わない。"}, "sentence_index": 0, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の試験の答えは、非常に分からなかった。", "explanation": "ここは〈まったく〉（打ち消しと共に「全然」の意味）の意味。「非常に」は程度を強める語で、打ち消しとは合わない。"}, {"text": "非常のときは、このボタンを押してください。", "explanation": "ここは〈緊急〉の意味（非常時の意）。程度の「とても」とは別の語義で、程度の強調としては成り立たない。"}, {"text": "非常のときにそなえて、水を買っておいた。", "explanation": "ここは〈緊急〉の意味。「とても」の程度強調ではなく、非常時の意で使われている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42963, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非常", "is_correct": true, "explanation": "「非常に」で「とても」の意味を表し、「親切な」を強める。"}, {"text": "大切", "is_correct": false, "explanation": "「大切に親切」は程度を表さず、文が不自然になる。"}, {"text": "平気", "is_correct": false, "explanation": "「平気に親切」は意味が通らない。"}, {"text": "無料", "is_correct": false, "explanation": "「無料に親切」は意味が通らない。"}], "explanations": {"非常": "「非常に」で「とても」の意味を表し、「親切な」を強める。", "大切": "「大切に親切」は程度を表さず、文が不自然になる。", "平気": "「平気に親切」は意味が通らない。", "無料": "「無料に親切」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "非常のときには、裏口から外へ出てください。", "explanation": "ここは〈緊急〉の意味（非常時の意）。「非常に」の程度強調とは別の語義。"}, {"text": "非常の事態に、町中の人が急いで集まった。", "explanation": "ここは〈緊急〉の意味。程度の強調ではなく、非常時の意で使われている。"}, {"text": "この靴は、非常にやや大きい。", "explanation": "ここは〈やや〉（わずかに、の意味）の意味。「非常に」と重ねると程度が矛盾し、〈やや〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42963, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の料理は非常を安くておいしい。", "corrected_sentence": "この店の料理は非常に安くておいしい。", "error_description": "「とても」の意味で形容詞を修飾するのは「非常に」。「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "非常", "is_correct": true, "explanation": "文中の「非常に」は語幹「非常」に連用の「に」が付いた形で、語幹の「非常」が正しい。"}, {"text": "非常な", "is_correct": false, "explanation": "「非常な」は連体形で、名詞の前に置く形。「に寒い」の程度表現には合わない。"}, {"text": "非常だ", "is_correct": false, "explanation": "「非常だ」は終止・断定の形で、「寒いので」の前に置くと文が切れて合わない。"}, {"text": "非常で", "is_correct": false, "explanation": "「非常で」は中止形で、「寒い」を強める程度の語としては使えない。"}], "correct_form": "非常", "base_form": "非常だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"非常": "文中の「非常に」は語幹「非常」に連用の「に」が付いた形で、語幹の「非常」が正しい。", "非常な": "「非常な」は連体形で、名詞の前に置く形。「に寒い」の程度表現には合わない。", "非常だ": "「非常だ」は終止・断定の形で、「寒いので」の前に置くと文が切れて合わない。", "非常で": "「非常で」は中止形で、「寒い」を強める程度の語としては使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42963, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の説明は非常な丁寧で、みんな分かった。", "corrected_sentence": "彼の説明は非常に丁寧で、みんな分かった。", "error_description": "形容動詞「丁寧」を修飾する副詞の形は「非常に」。「非常な」は連体形なので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "非常", "is_correct": true, "explanation": "文中の「非常に」は語幹「非常」に連用の「に」が付いた形で、語幹の「非常」が正しい。"}, {"text": "非常だった", "is_correct": false, "explanation": "「非常だった」は過去の断定の形で、「疲れていた」の程度を表す位置には合わない。"}, {"text": "非常でない", "is_correct": false, "explanation": "「非常でない」は否定形で、「疲れた」の程度を強める位置に置くと意味が逆になる。"}, {"text": "非常だろう", "is_correct": false, "explanation": "「非常だろう」は推量の形で、「疲れていたので」と続かない。"}], "correct_form": "非常", "base_form": "非常だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"非常": "文中の「非常に」は語幹「非常」に連用の「に」が付いた形で、語幹の「非常」が正しい。", "非常だった": "「非常だった」は過去の断定の形で、「疲れていた」の程度を表す位置には合わない。", "非常でない": "「非常でない」は否定形で、「疲れた」の程度を強める位置に置くと意味が逆になる。", "非常だろう": "「非常だろう」は推量の形で、「疲れていたので」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
