INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42964, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "程度がはなはだしいさま。", "primary_collocate": null, "pronunciation": "ひじょう", "ipa": "çiʑoː", "syllable_count": 3, "sentences": [{"text": "兄は非常な努力をして、医者になった。", "target_word": "非常", "complexity_tier": "T3", "furigana": "兄[あに]は非常[ひじょう]な努力[どりょく]をして、医者[いしゃ]になった。", "sentence_source": "generated"}, {"text": "その知らせを聞いて、母は非常な喜びを見せた。", "target_word": "非常", "complexity_tier": "T3", "furigana": "その知[し]らせを聞[き]いて、母[はは]は非常[ひじょう]な喜[よろこ]びを見[み]せた。", "sentence_source": "generated"}, {"text": "山で道に迷い、非常な寒さに苦しんだ。", "target_word": "非常", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]い、非常[ひじょう]な寒[さむ]さに苦[くる]しんだ。", "sentence_source": "generated"}, {"text": "この仕事には、非常な集中力が必要だ。", "target_word": "非常", "complexity_tier": "T3", "furigana": "この仕事[しごと]には、非常[ひじょう]な集中力[しゅうちゅうりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼の演奏に、会場は非常な盛り上がりを見せた。", "target_word": "非常", "complexity_tier": "T3", "furigana": "彼[かれ]の演奏[えんそう]に、会場[かいじょう]は非常[ひじょう]な盛[も]り上[あ]がりを見[み]せた。", "sentence_source": "generated"}, {"text": "台風のあと、町は非常な混乱におちいった。", "target_word": "非常", "complexity_tier": "T3", "furigana": "台風[たいふう]のあと、町[まち]は非常[ひじょう]な混乱[こんらん]におちいった。", "sentence_source": "generated"}, {"text": "彼は非常な速さで走り、一位になった。", "target_word": "非常", "complexity_tier": "T3", "furigana": "彼[かれ]は非常[ひじょう]な速[はや]さで走[はし]り、一位[いちい]になった。", "sentence_source": "generated"}, {"text": "非常な暑さのため、運動会は中止になった。", "target_word": "非常", "complexity_tier": "T3", "furigana": "非常[ひじょう]な暑[あつ]さのため、運動会[うんどうかい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "子どもを育てる両親の苦労は、非常なものだったと思う。", "target_word": "非常", "complexity_tier": "T3", "furigana": "子[こ]どもを育[そだ]てる両親[りょうしん]の苦労[くろう]は、非常[ひじょう]なものだったと思[おも]う。", "sentence_source": "generated"}, {"text": "彼女は非常な読書家で、一年に百冊も本を読む。", "target_word": "非常", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は非常[ひじょう]な読書家[どくしょか]で、一年[いちねん]に百冊[ひゃくさつ]も本[ほん]を読[よ]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "非常な", "label": "連体形"}, {"form": "非常に", "label": "連用形"}, {"form": "非常だ", "label": "終止形"}], "register": "やや硬い", "sense_fingerprint": "「非常な＋名詞」の形で、程度が並はずれて大きいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: おちいっ (Zipf 2.07)']::text[], 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42964, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非常", "is_correct": true, "explanation": "「非常な努力」で、努力の程度がはなはだしいことを表す。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔な努力」は意味が通らない。"}, {"text": "平気", "is_correct": false, "explanation": "「平気な努力」は努力の程度を表せず、不自然。"}, {"text": "無料", "is_correct": false, "explanation": "「無料な努力」は意味が通らない。"}], "explanations": {"非常": "「非常な努力」で、努力の程度がはなはだしいことを表す。", "清潔": "「清潔な努力」は意味が通らない。", "平気": "「平気な努力」は努力の程度を表せず、不自然。", "無料": "「無料な努力」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "非常の合図があったら、すぐに校庭へ出てください。", "explanation": "ここは〈緊急〉の意味（非常時の意）。程度がはなはだしい意味の「非常な」とは別の語義。"}, {"text": "非常の警報が鳴り、人々は一斉に外へ出た。", "explanation": "ここは〈緊急〉の意味。程度がはなはだしい意味ではなく、非常時の意で使われている。"}, {"text": "非常の放送が流れ、人々は避難を始めた。", "explanation": "ここは〈緊急〉の意味。程度の大きさを表す「非常な」とは別の語義。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42964, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非常", "is_correct": true, "explanation": "「非常な速さ」で、速さの程度がはなはだしいことを表す。"}, {"text": "大切", "is_correct": false, "explanation": "「大切な速さ」は意味が通らない。"}, {"text": "派手", "is_correct": false, "explanation": "「派手な速さ」は程度の表現として不自然。"}, {"text": "不要", "is_correct": false, "explanation": "「不要な速さ」は意味が通らない。"}], "explanations": {"非常": "「非常な速さ」で、速さの程度がはなはだしいことを表す。", "大切": "「大切な速さ」は意味が通らない。", "派手": "「派手な速さ」は程度の表現として不自然。", "不要": "「不要な速さ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "非常のときの避難所は、この小学校の体育館だ。", "explanation": "ここは〈緊急〉の意味（非常時の意）。程度がはなはだしい意味とは別の語義。"}, {"text": "非常の場合に備えて、懐中電灯を用意した。", "explanation": "ここは〈緊急〉の意味。程度の大きさを表す「非常な」ではなく、非常時の意で使われている。"}, {"text": "非常の訓練で、生徒たちは静かに校庭へ並んだ。", "explanation": "ここは〈緊急〉の意味。程度がはなはだしい意味ではなく、非常時の意で使われている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42964, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は非常の集中力を持っている。", "corrected_sentence": "彼は非常な集中力を持っている。", "error_description": "程度を表す連体修飾は「非常な」。「非常の」は緊急の意味の形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "非常", "is_correct": true, "explanation": "文中の「非常な」は語幹「非常」に連体の「な」が付いた形で、語幹の「非常」が正しい。"}, {"text": "非常に", "is_correct": false, "explanation": "「非常に」は連用形で、名詞「喜び」を修飾する位置には使えない。"}, {"text": "非常だ", "is_correct": false, "explanation": "「非常だ」は終止形で、名詞「喜び」を直接修飾できず合わない。"}, {"text": "非常で", "is_correct": false, "explanation": "「非常で」は中止形で、名詞を直接修飾する位置には使えない。"}], "correct_form": "非常", "base_form": "非常だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"非常": "文中の「非常な」は語幹「非常」に連体の「な」が付いた形で、語幹の「非常」が正しい。", "非常に": "「非常に」は連用形で、名詞「喜び」を修飾する位置には使えない。", "非常だ": "「非常だ」は終止形で、名詞「喜び」を直接修飾できず合わない。", "非常で": "「非常で」は中止形で、名詞を直接修飾する位置には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
